-- =============================================================================
-- HubLabel — criação das tabelas (arquivo único)
-- Rode no Supabase: SQL Editor → cole tudo → Run.
-- Pode rodar de novo sem quebrar nada (cria o que falta e atualiza funções).
--
-- Conteúdo:
--   1. criar-tabelas-unificado.sql (base do sistema)
--   2. scripts/migracao-n8n-telas-acoes.sql do hublabel-disparador
--      (SAAS_Personalizacao, SAAS_PaginaVendas e funções f_hub_*)
--   3. scripts/pause-dispatch-on-last-disconnected-connection.sql do hublabel-disparador
--      (swap_connection: pausa o disparo quando cai a última conexão)
--   4. get_chat_lista (lista do chat numa chamada só) e índices de contatos
--   5. get_dashboard: tempo médio de abertura só com as mensagens da conta
--   6. Histórico de etapa dos cards (trigger) e vendas/agendamentos da dashboard
--      filtrados pela data em que o card entrou na etapa
--   7. Pixel da Meta: configuração por conta, fila de eventos e trigger de venda do CRM
-- =============================================================================

  -- =========================
  -- criar-tabelas-unificado.sql
  -- =========================
  -- Arquivo unificado: combina criar-tabelas-conta.sql (base) com adições
  -- de criar-tabelas.sql (realtime, índices extras, cron, coluna nota).
  -- Gerado em 2026-03-25.
  --
  -- Combina criar-tabelas + migração multi-usuários.
  -- Lógica:
  --   1. Tudo vazio (SAAS_Planos não existe) → cria direto no formato novo (SAAS_Contas + contaId)
  --   2. Tabelas existem mas SAAS_Contas não existe → executa migração
  --   3. SAAS_Contas existe ou contaId já presente → não migra, só ajustes (funções, RLS, views, grants)
  --
  -- IMPORTANTE: Faça backup do banco antes de executar!

  CREATE EXTENSION IF NOT EXISTS pgcrypto;

  DO $$
  DECLARE
    ext TEXT;
  BEGIN
    FOR ext IN SELECT unnest(ARRAY['http','pg_cron','pg_graphql','pg_stat_statements','pgcrypto','pgjwt','pgsodium','uuid-ossp','vector'])
    LOOP
      IF EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = ext) THEN
        BEGIN EXECUTE format('CREATE EXTENSION IF NOT EXISTS %I', ext); EXCEPTION WHEN OTHERS THEN RAISE NOTICE 'Ext %: %', ext, SQLERRM; END;
      END IF;
    END LOOP;
  END$$;

  -- =========================
  -- DETECÇÃO DE CENÁRIO
  -- =========================
  -- vazio: SAAS_Planos não existe
  -- migrar: SAAS_Planos existe, SAAS_Contas não existe
  -- ajustar: SAAS_Contas existe OU SAAS_Conexões tem contaId

  -- =========================
  -- CENÁRIO 1: VAZIO - Criar tudo no formato novo
  -- =========================
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Planos"') IS NOT NULL THEN RETURN; END IF;

    RAISE NOTICE 'Cenário VAZIO: criando todas as tabelas no formato novo (SAAS_Contas + contaId).';

    CREATE TABLE IF NOT EXISTS public."SAAS_Planos" (
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      nome TEXT, preco REAL,
      "diasValidade" INTEGER NOT NULL DEFAULT 30 CHECK ("diasValidade" > 0),
      "qntConexoes" BIGINT, "qntContatos" BIGINT, "qntDisparos" BIGINT, "qntUsuarios" BIGINT,
      "qntQuadros" BIGINT, "qntAgentesIa" BIGINT, "qntCreditosIa" BIGINT,
      menu_ocultar JSONB DEFAULT '[]'::jsonb,
      "apiNaoOficial" TEXT NOT NULL DEFAULT 'evolution',
      "liberarApiOficial" BOOLEAN NOT NULL DEFAULT false,
      "liberarEmail" BOOLEAN NOT NULL DEFAULT false,
      "iaChaveCliente" BOOLEAN NOT NULL DEFAULT false
    );

    CREATE TABLE IF NOT EXISTS public."SAAS_Contas" (
      id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      status BOOLEAN DEFAULT TRUE,
      "dataValidade" DATE,
      plano BIGINT REFERENCES public."SAAS_Planos"(id) ON UPDATE CASCADE,
      tokens NUMERIC,
      email TEXT
    );

    CREATE TABLE IF NOT EXISTS public."SAAS_Usuarios" (
      id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      "contaId" UUID CONSTRAINT "SAAS_Usuarios_contaId_fkey" REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE,
      nome TEXT, "Email" TEXT, telefone TEXT,
      auth_user_id UUID UNIQUE,
      funcao TEXT NOT NULL DEFAULT 'admin' CHECK (funcao IN ('admin', 'membro')),
      super_admin BOOLEAN NOT NULL DEFAULT false
    );
    CREATE INDEX IF NOT EXISTS idx_usuarios_contaId ON public."SAAS_Usuarios"("contaId");
    CREATE INDEX IF NOT EXISTS idx_usuarios_auth_user_id ON public."SAAS_Usuarios"(auth_user_id);

    CREATE TABLE IF NOT EXISTS public."SAAS_Conexões" (
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      "instanceName" TEXT, "NomeConexao" TEXT, "Telefone" TEXT, "FotoPerfil" TEXT, "Apikey" TEXT,
      "contaId" UUID REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE,
      "idAgente" BIGINT,
      "apiOficial" BOOLEAN NOT NULL DEFAULT false,
      "access_token" TEXT,
      "expires_in" BIGINT,
      "business_id" TEXT,
      "waba_id" TEXT,
      "phone_number_id" TEXT,
      "provedorApi" TEXT NOT NULL DEFAULT 'evolution',
      "urlApi" TEXT
    );

    CREATE TABLE IF NOT EXISTS public."SAAS_Listas" (
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      nome TEXT NOT NULL, descricao TEXT, tipo TEXT, campos JSONB, "idConexao" BIGINT,
      "contaId" UUID NOT NULL REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE
    );

    CREATE TABLE IF NOT EXISTS public."SAAS_Contatos" (
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      nome TEXT, telefone TEXT, email TEXT, "fotoPerfil" TEXT, "idLista" BIGINT,
      tipo TEXT NOT NULL DEFAULT 'contato' CHECK (tipo IN ('contato', 'grupo')),
      variaveis JSONB NOT NULL DEFAULT '{}', lid TEXT,
      validado BOOLEAN NOT NULL DEFAULT false,
      "contaId" UUID NOT NULL REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE
    );

    CREATE TABLE IF NOT EXISTS public."SAAS_Grupos" (
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      nome TEXT, "WhatsAppId" TEXT, "idLista" BIGINT NOT NULL, "idConexao" BIGINT,
      atributos JSONB NOT NULL DEFAULT '{}', participantes BIGINT,
      "contaId" UUID NOT NULL REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE
    );

    CREATE TABLE IF NOT EXISTS public."SAAS_Disparos" (
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      "NomeDisparo" TEXT,
      "Mensagens" JSONB[], "TipoDisparo" TEXT, "TotalDisparos" BIGINT, "MensagensDisparadas" BIGINT,
      "StatusDisparo" TEXT, "idExecution" TEXT, "idListas" BIGINT[], "idConexoes" BIGINT[],
      "intervaloMin" INTEGER, "intervaloMax" INTEGER, "PausaAposMensagens" INTEGER, "PausaMinutos" INTEGER,
      "StartTime" TIME, "EndTime" TIME, "DiasSelecionados" SMALLINT[], "DataAgendamento" TIMESTAMPTZ,
      "mostrarMensagem" BOOLEAN NOT NULL DEFAULT true,
      "contaId" UUID REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE
    );

    CREATE TABLE IF NOT EXISTS public."SAAS_Detalhes_Disparos" (
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
      "idDisparo" BIGINT, "idContato" BIGINT, "Mensagem" TEXT, "idConexao" BIGINT,
      "dataEnvio" TIMESTAMPTZ, "Status" TEXT, "statusHttp" TEXT, "mensagemErro" TEXT,
      "respostaHttp" JSONB, "Payload" JSONB, "KeyRedis" TEXT, "FakeCall" BOOLEAN, "idGrupo" BIGINT,
      "mensagemLida" BOOLEAN NOT NULL DEFAULT false,
      "dataMensagemLida" TIMESTAMPTZ
    );

    CREATE TABLE IF NOT EXISTS public."SAAS_Quadros" (
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      nome TEXT, descricao TEXT, cor TEXT, icone TEXT,
      "contaId" UUID REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE
    );

    CREATE TABLE IF NOT EXISTS public."SAAS_Etapas_Quadros" (
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      "quadroId" BIGINT, nome TEXT, ordem SMALLINT,
      "tipoEtapa" TEXT CHECK ("tipoEtapa" IS NULL OR "tipoEtapa" IN ('venda', 'perda', 'agendamento')),
      "contaId" UUID REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE
    );

    CREATE TABLE IF NOT EXISTS public."SAAS_Cards_Quadros" (
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      "quadroId" BIGINT, "contatoId" BIGINT, valor DOUBLE PRECISION, "etapaQuadroId" BIGINT,
      observacoes TEXT, tarefas JSONB[], ordem SMALLINT, nome TEXT, contato TEXT,
      "historicoCRM" JSONB NOT NULL DEFAULT '[]'::jsonb
    );

    CREATE TABLE IF NOT EXISTS public."SAAS_AgentesIA" (
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      nome TEXT, "conexaoId" BIGINT, instrucoes TEXT, modelo TEXT, criatividade REAL,
      "maxCreditos" BIGINT, ativo BOOLEAN, conhecimento JSONB, cor TEXT,
      "separarMensagens" BOOLEAN, "ouvirAudio" BOOLEAN, "analisarImagens" BOOLEAN,
      "aparecerDigitando" BOOLEAN, "pausarAtendimento" BOOLEAN, "qntMsgHistorico" INTEGER,
      "agruparMensagens" BOOLEAN, "intervaloEntreMensagens" INTEGER,
      "CRM" JSONB, "abrirAtendimento" JSONB, "notificarHumano" JSONB, "requisicaoHTTP" JSONB,
      produtos JSONB,
      followup JSONB NOT NULL DEFAULT '{}'::jsonb,
      "contaId" UUID REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE
    );

    CREATE TABLE IF NOT EXISTS public."SAAS_Conversas_Agentes" (
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      "idAgente" BIGINT REFERENCES public."SAAS_AgentesIA"(id) ON UPDATE CASCADE ON DELETE SET NULL, "idConexao" BIGINT REFERENCES public."SAAS_Conexões"(id) ON UPDATE CASCADE ON DELETE CASCADE, telefone TEXT, pausado BOOLEAN,
      "pausaAte" TIMESTAMPTZ, "ultimaMensagem" TIMESTAMPTZ,
      "contaId" UUID REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE,
      "contatoId" BIGINT, lida BOOLEAN NOT NULL DEFAULT false,
      "statusAtendimento" TEXT NOT NULL DEFAULT 'aguardando', "nomeConversa" TEXT, "fotoPerfil" TEXT,
      nota TEXT,
      "atendente" UUID DEFAULT null REFERENCES public."SAAS_Usuarios"(id) ON UPDATE CASCADE ON DELETE SET NULL
    );

    CREATE TABLE IF NOT EXISTS public."SAAS_Mensagens" (
      id BIGINT GENERATED ALWAYS AS IDENTITY NOT NULL PRIMARY KEY,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      "contaId" UUID NOT NULL REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE,
      "conexaoId" BIGINT, "conversaId" BIGINT NOT NULL REFERENCES public."SAAS_Conversas_Agentes"(id) ON UPDATE CASCADE ON DELETE CASCADE, mensagem TEXT,
      "tipoMensagem" TEXT NOT NULL, "arquivoUrl" TEXT, "fromMe" BOOLEAN NOT NULL DEFAULT false,
      apagada BOOLEAN NOT NULL DEFAULT false, "messageEvolutionId" TEXT, "mensagemRespondida" TEXT,
      enviada BOOLEAN, favorita BOOLEAN NOT NULL DEFAULT false, "IA" BOOLEAN
    );

    CREATE TABLE IF NOT EXISTS public."SAAS_Conhecimentos" (
      id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      content TEXT, metadata JSONB
    );

    CREATE TABLE IF NOT EXISTS public."SAAS_Webhook" (
      id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      "contaId" UUID REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE,
      "conexaoId" BIGINT, "tokenWebhook" UUID DEFAULT gen_random_uuid(), nome TEXT,
      status BOOLEAN, teste BOOLEAN, mapeamento JSONB, "ultimoPayload" JSONB, "idAgente" BIGINT, "mensagemPadrao" TEXT
    );

    CREATE TABLE IF NOT EXISTS public."SAAS_Resposta_Rapidas" (
      id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      "contaId" UUID REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE,
      nome TEXT, atalho TEXT, texto TEXT, arquivo TEXT, "tipoMedia" TEXT,
      rodape TEXT, botoes JSONB, "imagemBotao" TEXT
    );

    CREATE TABLE IF NOT EXISTS public."SAAS_Versao" (
      id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
      created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
      "versaoAtual" TEXT, "ultimaAtualizacao" TIMESTAMPTZ
    );

    RAISE NOTICE 'Tabelas criadas no formato novo.';
  END$$;

  -- =========================
  -- CENÁRIO 2: MIGRAR - Tabelas existem (formato antigo) mas SAAS_Contas não existe
  -- =========================
  -- Executa migração: SAAS_Usuarios → SAAS_Contas, cria nova SAAS_Usuarios, migra dados, renomeia userId/idUsuario → contaId
  -- Se SAAS_Contas já existir (ex: cenário VAZIO ou já migrado), os blocos abaixo fazem RETURN e não alteram nada.
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Contas"') IS NOT NULL THEN
      RAISE NOTICE 'Cenário AJUSTAR ou já migrado: SAAS_Contas existe. Pulando migração.';
      RETURN;
    END IF;
    IF to_regclass('public."SAAS_Usuarios"') IS NULL THEN
      RAISE EXCEPTION 'Para migrar: execute criar-tabelas.sql antes. SAAS_Usuarios não encontrada.';
    END IF;
    RAISE NOTICE 'Cenário MIGRAR: executando migração multi-usuários...';
  END$$;

  -- Drop FKs que referenciam SAAS_Usuarios (será renomeada para SAAS_Contas)
  DO $$
  DECLARE r RECORD;
  BEGIN
    IF to_regclass('public."SAAS_Contas"') IS NOT NULL THEN RETURN; END IF;
    FOR r IN
      SELECT c.conname, t.relname AS tabela
      FROM pg_constraint c JOIN pg_class t ON t.oid = c.conrelid
      WHERE c.confrelid = 'public."SAAS_Usuarios"'::regclass
    LOOP
      EXECUTE format('ALTER TABLE public.%I DROP CONSTRAINT IF EXISTS %I', r.tabela, r.conname);
    END LOOP;
  END$$;

  DROP TRIGGER IF EXISTS trg_usuarios_data_validade ON public."SAAS_Usuarios";

  DO $$ BEGIN
    IF to_regclass('public."SAAS_Contas"') IS NULL THEN
      ALTER TABLE public."SAAS_Usuarios" RENAME TO "SAAS_Contas";
    END IF;
  END$$;

  DO $$ BEGIN
    IF to_regclass('public."SAAS_Usuarios"') IS NULL THEN
      CREATE TABLE public."SAAS_Usuarios" (
        id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
        created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
        "contaId" UUID CONSTRAINT "SAAS_Usuarios_contaId_fkey" REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE,
        nome TEXT, "Email" TEXT, telefone TEXT, auth_user_id UUID UNIQUE,
        funcao TEXT NOT NULL DEFAULT 'admin' CHECK (funcao IN ('admin', 'membro')),
        super_admin BOOLEAN NOT NULL DEFAULT false
      );
      CREATE INDEX IF NOT EXISTS idx_usuarios_contaId ON public."SAAS_Usuarios"("contaId");
      CREATE INDEX IF NOT EXISTS idx_usuarios_auth_user_id ON public."SAAS_Usuarios"(auth_user_id);
    END IF;
  END$$;

  DO $$ BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='SAAS_Contas' AND column_name='nome') THEN
      INSERT INTO public."SAAS_Usuarios" ("contaId", nome, "Email", telefone, auth_user_id, funcao)
      SELECT id, nome, "Email", telefone, auth_user_id, 'admin' FROM public."SAAS_Contas";
    END IF;
  END$$;

  -- Uma FK só de SAAS_Usuarios.contaId → SAAS_Contas (PGRST201 se houver duplicata).
  -- Atenção: FKs invertidas (Contas.distribuicao*/redistribuicao*UsuarioFixoId → Usuarios)
  -- também contam para o PostgREST; o front deve embedar com SAAS_Contas!contaId(...).
  DO $$
  DECLARE
    r RECORD;
  BEGIN
    IF to_regclass('public."SAAS_Usuarios"') IS NULL OR to_regclass('public."SAAS_Contas"') IS NULL THEN
      RETURN;
    END IF;
    BEGIN
      ALTER TABLE public."SAAS_Usuarios" ALTER COLUMN "contaId" DROP NOT NULL;
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'SAAS_Usuarios.contaId DROP NOT NULL: %', SQLERRM;
    END;
    -- Remove qualquer FK de Usuarios.contaId → Contas (nomes antigos/duplicados)
    FOR r IN
      SELECT c.conname
      FROM pg_constraint c
      JOIN pg_class t ON t.oid = c.conrelid
      JOIN pg_namespace n ON n.oid = t.relnamespace
      JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey) AND NOT a.attisdropped
      WHERE c.contype = 'f'
        AND n.nspname = 'public'
        AND t.relname = 'SAAS_Usuarios'
        AND a.attname = 'contaId'
        AND c.confrelid = 'public."SAAS_Contas"'::regclass
    LOOP
      BEGIN
        EXECUTE format('ALTER TABLE public."SAAS_Usuarios" DROP CONSTRAINT IF EXISTS %I', r.conname);
      EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'drop %: %', r.conname, SQLERRM;
      END;
    END LOOP;
    BEGIN
      ALTER TABLE public."SAAS_Usuarios"
        ADD CONSTRAINT "SAAS_Usuarios_contaId_fkey"
        FOREIGN KEY ("contaId") REFERENCES public."SAAS_Contas"(id)
        ON UPDATE CASCADE ON DELETE CASCADE;
    EXCEPTION WHEN duplicate_object THEN
      NULL;
    WHEN OTHERS THEN
      RAISE NOTICE 'add SAAS_Usuarios_contaId_fkey: %', SQLERRM;
    END;
  END$$;

  DROP VIEW IF EXISTS public."vw_Usuarios_Com_Plano" CASCADE;
  DROP VIEW IF EXISTS public."vw_Contas_Com_Plano" CASCADE;
  DROP VIEW IF EXISTS public."vw_Planos_Usuarios_Count" CASCADE;
  DROP VIEW IF EXISTS public."vw_Detalhes_Completo" CASCADE;
  DROP VIEW IF EXISTS public."VW_SAAS_AgentesIA_Conversas" CASCADE;
  DROP VIEW IF EXISTS public."vw_SAAS_Quadros_CRM" CASCADE;
  DROP VIEW IF EXISTS public."VW_SAAS_Etapas_Quadros" CASCADE;
  DROP POLICY IF EXISTS "select_meu_usuario" ON public."SAAS_Contas";
  DROP POLICY IF EXISTS "update_meu_usuario" ON public."SAAS_Contas";
  DROP POLICY IF EXISTS "select_disparos_do_usuario" ON public."SAAS_Disparos";

  -- Adicionar coluna email (criador da conta) e popular a partir de "Email" antes de dropar (só se "Email" ainda existir)
  ALTER TABLE public."SAAS_Contas" ADD COLUMN IF NOT EXISTS email TEXT;
  DO $$
  BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Contas' AND column_name = 'Email') THEN
      UPDATE public."SAAS_Contas" SET email = "Email" WHERE email IS NULL AND "Email" IS NOT NULL;
    END IF;
  END$$;
  ALTER TABLE public."SAAS_Contas" DROP COLUMN IF EXISTS nome;
  ALTER TABLE public."SAAS_Contas" DROP COLUMN IF EXISTS "Email";
  ALTER TABLE public."SAAS_Contas" DROP COLUMN IF EXISTS telefone;
  ALTER TABLE public."SAAS_Contas" DROP COLUMN IF EXISTS auth_user_id;

  DO $$
  BEGIN
    IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Usuarios_plano_fkey') THEN
      ALTER TABLE public."SAAS_Contas" RENAME CONSTRAINT "SAAS_Usuarios_plano_fkey" TO "SAAS_Contas_plano_fkey";
    END IF;
  END$$;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Disparos"') IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='SAAS_Disparos' AND column_name='userId') THEN
      ALTER TABLE public."SAAS_Disparos" RENAME COLUMN "userId" TO "contaId";
    END IF;
    IF to_regclass('public."SAAS_Quadros"') IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='SAAS_Quadros' AND column_name='userId') THEN
      ALTER TABLE public."SAAS_Quadros" RENAME COLUMN "userId" TO "contaId";
    END IF;
    IF to_regclass('public."SAAS_Etapas_Quadros"') IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='SAAS_Etapas_Quadros' AND column_name='userId') THEN
      ALTER TABLE public."SAAS_Etapas_Quadros" RENAME COLUMN "userId" TO "contaId";
    END IF;
    IF to_regclass('public."SAAS_AgentesIA"') IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='SAAS_AgentesIA' AND column_name='userId') THEN
      ALTER TABLE public."SAAS_AgentesIA" RENAME COLUMN "userId" TO "contaId";
    END IF;
    IF to_regclass('public."SAAS_Conversas_Agentes"') IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='SAAS_Conversas_Agentes' AND column_name='userId') THEN
      ALTER TABLE public."SAAS_Conversas_Agentes" RENAME COLUMN "userId" TO "contaId";
    END IF;
    IF to_regclass('public."SAAS_Mensagens"') IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='SAAS_Mensagens' AND column_name='userId') THEN
      ALTER TABLE public."SAAS_Mensagens" RENAME COLUMN "userId" TO "contaId";
    END IF;
    IF to_regclass('public."SAAS_Webhook"') IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='SAAS_Webhook' AND column_name='userId') THEN
      ALTER TABLE public."SAAS_Webhook" RENAME COLUMN "userId" TO "contaId";
    END IF;
    IF to_regclass('public."SAAS_Resposta_Rapidas"') IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='SAAS_Resposta_Rapidas' AND column_name='userId') THEN
      ALTER TABLE public."SAAS_Resposta_Rapidas" RENAME COLUMN "userId" TO "contaId";
    END IF;
    IF to_regclass('public."SAAS_Conexões"') IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='SAAS_Conexões' AND column_name='idUsuario') THEN
      ALTER TABLE public."SAAS_Conexões" RENAME COLUMN "idUsuario" TO "contaId";
    END IF;
    IF to_regclass('public."SAAS_Listas"') IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='SAAS_Listas' AND column_name='idUsuario') THEN
      ALTER TABLE public."SAAS_Listas" RENAME COLUMN "idUsuario" TO "contaId";
    END IF;
    IF to_regclass('public."SAAS_Contatos"') IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='SAAS_Contatos' AND column_name='idUsuario') THEN
      ALTER TABLE public."SAAS_Contatos" RENAME COLUMN "idUsuario" TO "contaId";
    END IF;
    IF to_regclass('public."SAAS_Grupos"') IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='SAAS_Grupos' AND column_name='idUsuario') THEN
      ALTER TABLE public."SAAS_Grupos" RENAME COLUMN "idUsuario" TO "contaId";
    END IF;
  END$$;

  -- Normalizar colunas com camelCase em SAAS_Disparos
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Disparos"') IS NULL THEN RETURN; END IF;
    IF EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema='public' AND table_name='SAAS_Disparos' AND column_name='intervalomin'
    ) AND NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema='public' AND table_name='SAAS_Disparos' AND column_name='intervaloMin'
    ) THEN
      ALTER TABLE public."SAAS_Disparos" RENAME COLUMN intervalomin TO "intervaloMin";
    END IF;
    IF EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema='public' AND table_name='SAAS_Disparos' AND column_name='intervalomax'
    ) AND NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema='public' AND table_name='SAAS_Disparos' AND column_name='intervaloMax'
    ) THEN
      ALTER TABLE public."SAAS_Disparos" RENAME COLUMN intervalomax TO "intervaloMax";
    END IF;
  END$$;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Conexões"') IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = 'public'
          AND table_name = 'SAAS_Conexões'
          AND column_name = 'idAgente'
      ) THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "idAgente" BIGINT;
    END IF;
  END$$;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Conexões"') IS NULL THEN RETURN; END IF;

    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'apiOficial'
    ) THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "apiOficial" BOOLEAN NOT NULL DEFAULT false;
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'access_token'
    ) THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "access_token" TEXT;
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'expires_in'
    ) THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "expires_in" BIGINT;
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'business_id'
    ) THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "business_id" TEXT;
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'waba_id'
    ) THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "waba_id" TEXT;
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'phone_number_id'
    ) THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "phone_number_id" TEXT;
    END IF;

    -- provedorApi/urlApi: precisam existir antes das views/funções (vw_Detalhes_Completo, etc.)
    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'provedorApi'
    ) THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "provedorApi" TEXT NOT NULL DEFAULT 'evolution';
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'urlApi'
    ) THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "urlApi" TEXT;
    END IF;

    ALTER TABLE public."SAAS_Conexões" DROP CONSTRAINT IF EXISTS saas_conexoes_provedor_api_check;
    ALTER TABLE public."SAAS_Conexões"
      ADD CONSTRAINT saas_conexoes_provedor_api_check
      CHECK ("provedorApi" IN ('evolution', 'uazapi', 'oficial'));
  END$$;

  -- Plano: validade e opções de API antes de vw_Contas_Com_Plano
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Planos"') IS NULL THEN RETURN; END IF;
    ALTER TABLE public."SAAS_Planos" ADD COLUMN IF NOT EXISTS "diasValidade" INTEGER;
    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Planos' AND column_name = 'apiNaoOficial'
    ) THEN
      ALTER TABLE public."SAAS_Planos" ADD COLUMN "apiNaoOficial" TEXT NOT NULL DEFAULT 'evolution';
    END IF;
    ALTER TABLE public."SAAS_Planos" DROP CONSTRAINT IF EXISTS saas_planos_api_nao_oficial_check;
    ALTER TABLE public."SAAS_Planos"
      ADD CONSTRAINT saas_planos_api_nao_oficial_check
      CHECK ("apiNaoOficial" IN ('evolution', 'uazapi'));
    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Planos' AND column_name = 'liberarApiOficial'
    ) THEN
      ALTER TABLE public."SAAS_Planos" ADD COLUMN "liberarApiOficial" BOOLEAN NOT NULL DEFAULT false;
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Planos' AND column_name = 'liberarEmail'
    ) THEN
      ALTER TABLE public."SAAS_Planos" ADD COLUMN "liberarEmail" BOOLEAN NOT NULL DEFAULT false;
    END IF;
    -- true: a conta usa a própria chave de IA (Configurações) e não tem limite de créditos
    ALTER TABLE public."SAAS_Planos" ADD COLUMN IF NOT EXISTS "iaChaveCliente" BOOLEAN NOT NULL DEFAULT false;
  END$$;

  -- Planos existentes: mantém comportamento anterior (libera API oficial, exceto Free)
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Planos"') IS NULL THEN RETURN; END IF;
    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Planos' AND column_name = 'liberarApiOficial'
    ) THEN RETURN; END IF;
    UPDATE public."SAAS_Planos"
    SET "liberarApiOficial" = true
    WHERE COALESCE(lower(trim(nome)), '') <> 'free'
      AND "liberarApiOficial" IS NOT TRUE;
  END$$;

  -- Dados inválidos: detalhes/disparos com conta inexistente em SAAS_Contas, ou detalhe sem disparo correspondente
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Contas"') IS NULL OR to_regclass('public."SAAS_Disparos"') IS NULL THEN
      RETURN;
    END IF;
    IF to_regclass('public."SAAS_Detalhes_Disparos"') IS NOT NULL THEN
      DELETE FROM public."SAAS_Detalhes_Disparos" d
      WHERE d."idDisparo" IS NULL
        OR NOT EXISTS (SELECT 1 FROM public."SAAS_Disparos" h WHERE h.id = d."idDisparo");
      IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Disparos' AND column_name = 'contaId') THEN
        DELETE FROM public."SAAS_Detalhes_Disparos" d
        WHERE d."idDisparo" IN (
          SELECT h.id FROM public."SAAS_Disparos" h
          WHERE h."contaId" IS NOT NULL
            AND NOT EXISTS (SELECT 1 FROM public."SAAS_Contas" c WHERE c.id = h."contaId")
        );
      ELSIF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Disparos' AND column_name = 'userId') THEN
        DELETE FROM public."SAAS_Detalhes_Disparos" d
        WHERE d."idDisparo" IN (
          SELECT h.id FROM public."SAAS_Disparos" h
          WHERE h."userId" IS NOT NULL
            AND NOT EXISTS (SELECT 1 FROM public."SAAS_Contas" c WHERE c.id = h."userId")
        );
      END IF;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Disparos' AND column_name = 'contaId') THEN
      DELETE FROM public."SAAS_Disparos" d
      WHERE d."contaId" IS NOT NULL
        AND NOT EXISTS (SELECT 1 FROM public."SAAS_Contas" c WHERE c.id = d."contaId");
    ELSIF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Disparos' AND column_name = 'userId') THEN
      DELETE FROM public."SAAS_Disparos" d
      WHERE d."userId" IS NOT NULL
        AND NOT EXISTS (SELECT 1 FROM public."SAAS_Contas" c WHERE c.id = d."userId");
    END IF;
  END$$;

  -- Recriar FKs (apenas se ainda não existir contaId_fkey); só altera tabelas que existem
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Conexões"') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Conexões_contaId_fkey') THEN ALTER TABLE public."SAAS_Conexões" ADD CONSTRAINT "SAAS_Conexões_contaId_fkey" FOREIGN KEY ("contaId") REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE; END IF;
    IF to_regclass('public."SAAS_Listas"') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Listas_contaId_fkey') THEN ALTER TABLE public."SAAS_Listas" ADD CONSTRAINT "SAAS_Listas_contaId_fkey" FOREIGN KEY ("contaId") REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE; END IF;
    IF to_regclass('public."SAAS_Contatos"') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Contatos_contaId_fkey') THEN ALTER TABLE public."SAAS_Contatos" ADD CONSTRAINT "SAAS_Contatos_contaId_fkey" FOREIGN KEY ("contaId") REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE; END IF;
    IF to_regclass('public."SAAS_Grupos"') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Grupos_contaId_fkey') THEN ALTER TABLE public."SAAS_Grupos" ADD CONSTRAINT "SAAS_Grupos_contaId_fkey" FOREIGN KEY ("contaId") REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE; END IF;
    IF to_regclass('public."SAAS_Disparos"') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Disparos_contaId_fkey') THEN ALTER TABLE public."SAAS_Disparos" ADD CONSTRAINT "SAAS_Disparos_contaId_fkey" FOREIGN KEY ("contaId") REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE; END IF;
    IF to_regclass('public."SAAS_Quadros"') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Quadros_contaId_fkey') THEN ALTER TABLE public."SAAS_Quadros" ADD CONSTRAINT "SAAS_Quadros_contaId_fkey" FOREIGN KEY ("contaId") REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE; END IF;
    IF to_regclass('public."SAAS_Etapas_Quadros"') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Etapas_Quadros_contaId_fkey') THEN ALTER TABLE public."SAAS_Etapas_Quadros" ADD CONSTRAINT "SAAS_Etapas_Quadros_contaId_fkey" FOREIGN KEY ("contaId") REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE; END IF;
    IF to_regclass('public."SAAS_AgentesIA"') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_AgentesIA_contaId_fkey') THEN ALTER TABLE public."SAAS_AgentesIA" ADD CONSTRAINT "SAAS_AgentesIA_contaId_fkey" FOREIGN KEY ("contaId") REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE; END IF;
    IF to_regclass('public."SAAS_Conversas_Agentes"') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Conversas_Agentes_contaId_fkey') THEN ALTER TABLE public."SAAS_Conversas_Agentes" ADD CONSTRAINT "SAAS_Conversas_Agentes_contaId_fkey" FOREIGN KEY ("contaId") REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE; END IF;
    IF to_regclass('public."SAAS_Mensagens"') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'saas_mensagens_contaid_fkey') THEN ALTER TABLE public."SAAS_Mensagens" ADD CONSTRAINT "saas_mensagens_contaid_fkey" FOREIGN KEY ("contaId") REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE; END IF;
    IF to_regclass('public."SAAS_Webhook"') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Webhook_contaId_fkey') THEN ALTER TABLE public."SAAS_Webhook" ADD CONSTRAINT "SAAS_Webhook_contaId_fkey" FOREIGN KEY ("contaId") REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE; END IF;
    IF to_regclass('public."SAAS_Resposta_Rapidas"') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Resposta_Rapidas_contaId_fkey') THEN ALTER TABLE public."SAAS_Resposta_Rapidas" ADD CONSTRAINT "SAAS_Resposta_Rapidas_contaId_fkey" FOREIGN KEY ("contaId") REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE; END IF;
  END$$;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Conexões"') IS NOT NULL THEN CREATE INDEX IF NOT EXISTS idx_conexoes_contaId ON public."SAAS_Conexões"("contaId"); END IF;
    IF to_regclass('public."SAAS_Listas"') IS NOT NULL THEN CREATE INDEX IF NOT EXISTS "idx_Listas_contaId" ON public."SAAS_Listas"("contaId"); END IF;
    IF to_regclass('public."SAAS_Contatos"') IS NOT NULL THEN CREATE INDEX IF NOT EXISTS "idx_Contatos_contaId" ON public."SAAS_Contatos"("contaId"); END IF;
    IF to_regclass('public."SAAS_Grupos"') IS NOT NULL THEN CREATE INDEX IF NOT EXISTS "idx_Grupos_contaId" ON public."SAAS_Grupos"("contaId"); END IF;
    IF to_regclass('public."SAAS_Disparos"') IS NOT NULL THEN CREATE INDEX IF NOT EXISTS idx_disparos_contaId ON public."SAAS_Disparos"("contaId"); END IF;
    IF to_regclass('public."SAAS_Quadros"') IS NOT NULL THEN CREATE INDEX IF NOT EXISTS idx_Quadros_contaId ON public."SAAS_Quadros"("contaId"); END IF;
    IF to_regclass('public."SAAS_Etapas_Quadros"') IS NOT NULL THEN CREATE INDEX IF NOT EXISTS idx_Etapas_Quadros_contaId ON public."SAAS_Etapas_Quadros"("contaId"); END IF;
    IF to_regclass('public."SAAS_AgentesIA"') IS NOT NULL THEN CREATE INDEX IF NOT EXISTS idx_AgentesIA_contaId ON public."SAAS_AgentesIA"("contaId"); END IF;
    IF to_regclass('public."SAAS_Conversas_Agentes"') IS NOT NULL THEN CREATE INDEX IF NOT EXISTS saas_conversas_agentes_conta_idx ON public."SAAS_Conversas_Agentes"("contaId"); END IF;
    IF to_regclass('public."SAAS_Mensagens"') IS NOT NULL THEN CREATE INDEX IF NOT EXISTS saas_mensagens_conta_idx ON public."SAAS_Mensagens"("contaId"); END IF;
    IF to_regclass('public."SAAS_Webhook"') IS NOT NULL THEN CREATE INDEX IF NOT EXISTS idx_webhook_contaId ON public."SAAS_Webhook"("contaId"); END IF;
    IF to_regclass('public."SAAS_Resposta_Rapidas"') IS NOT NULL THEN CREATE INDEX IF NOT EXISTS idx_resposta_rapidas_contaId ON public."SAAS_Resposta_Rapidas"("contaId"); END IF;
  END$$;

  ALTER TABLE public."SAAS_Resposta_Rapidas" ADD COLUMN IF NOT EXISTS rodape TEXT;
  ALTER TABLE public."SAAS_Resposta_Rapidas" ADD COLUMN IF NOT EXISTS botoes JSONB;
  ALTER TABLE public."SAAS_Resposta_Rapidas" ADD COLUMN IF NOT EXISTS "imagemBotao" TEXT;

  DROP INDEX IF EXISTS saas_conversas_agentes_unique;
  DROP INDEX IF EXISTS saas_conversas_agentes_telefone_conexao_unique;
  CREATE UNIQUE INDEX IF NOT EXISTS saas_conversas_agentes_contato_conexao_unique
  ON public."SAAS_Conversas_Agentes"("contatoId", "idConexao")
  WHERE "contatoId" IS NOT NULL AND "idConexao" IS NOT NULL;

  -- Índices adicionais (de criar-tabelas.sql)
  CREATE INDEX IF NOT EXISTS idx_detalhes_idDisparo ON public."SAAS_Detalhes_Disparos"("idDisparo");
  CREATE INDEX IF NOT EXISTS idx_detalhes_dataEnvio ON public."SAAS_Detalhes_Disparos"("dataEnvio");
  CREATE INDEX IF NOT EXISTS idx_Etapas_Quadros_quadroId ON public."SAAS_Etapas_Quadros"("quadroId");

  -- Tipo especial da etapa CRM (venda / perda / agendamento): no máximo 1 de cada por quadro
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Etapas_Quadros"') IS NOT NULL THEN
      ALTER TABLE public."SAAS_Etapas_Quadros" ADD COLUMN IF NOT EXISTS "tipoEtapa" TEXT;
      IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'SAAS_Etapas_Quadros_tipoEtapa_check'
      ) THEN
        ALTER TABLE public."SAAS_Etapas_Quadros"
          ADD CONSTRAINT "SAAS_Etapas_Quadros_tipoEtapa_check"
          CHECK ("tipoEtapa" IS NULL OR "tipoEtapa" IN ('venda', 'perda', 'agendamento'));
      END IF;
    END IF;
  END$$;
  CREATE UNIQUE INDEX IF NOT EXISTS uq_etapas_quadro_tipo_venda
    ON public."SAAS_Etapas_Quadros" ("quadroId") WHERE "tipoEtapa" = 'venda';
  CREATE UNIQUE INDEX IF NOT EXISTS uq_etapas_quadro_tipo_perda
    ON public."SAAS_Etapas_Quadros" ("quadroId") WHERE "tipoEtapa" = 'perda';
  CREATE UNIQUE INDEX IF NOT EXISTS uq_etapas_quadro_tipo_agendamento
    ON public."SAAS_Etapas_Quadros" ("quadroId") WHERE "tipoEtapa" = 'agendamento';

  -- Normaliza contatos antes dos índices e funções que usam o schema novo.
  -- Necessário tanto em banco vazio quanto ao retomar uma execução interrompida.
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Contatos"') IS NULL THEN RETURN; END IF;
    IF EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Contatos' AND column_name = 'atributos'
    ) AND NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Contatos' AND column_name = 'variaveis'
    ) THEN
      ALTER TABLE public."SAAS_Contatos" RENAME COLUMN atributos TO variaveis;
    END IF;
  END$$;
  ALTER TABLE public."SAAS_Contatos" ADD COLUMN IF NOT EXISTS tipo TEXT NOT NULL DEFAULT 'contato' CHECK (tipo IN ('contato', 'grupo'));
  ALTER TABLE public."SAAS_Contatos" ADD COLUMN IF NOT EXISTS variaveis JSONB NOT NULL DEFAULT '{}';
  ALTER TABLE public."SAAS_Contatos" ADD COLUMN IF NOT EXISTS email TEXT;
  ALTER TABLE public."SAAS_Contatos" ADD COLUMN IF NOT EXISTS lid TEXT;
  ALTER TABLE public."SAAS_Contatos" ADD COLUMN IF NOT EXISTS validado BOOLEAN NOT NULL DEFAULT false;
  DO $$
  BEGIN
    IF EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Contatos'
        AND column_name = 'lid' AND data_type = 'boolean'
    ) THEN
      ALTER TABLE public."SAAS_Contatos"
        ALTER COLUMN lid TYPE TEXT USING CASE WHEN lid THEN 'true' ELSE 'false' END;
    END IF;
  END$$;
  ALTER TABLE public."SAAS_Contatos" ALTER COLUMN lid DROP NOT NULL;

  CREATE INDEX IF NOT EXISTS idx_Cards_Quadros_etapaQuadroId ON public."SAAS_Cards_Quadros"("etapaQuadroId");
  CREATE INDEX IF NOT EXISTS idx_Cards_Quadros_contatoId ON public."SAAS_Cards_Quadros"("contatoId");
  DROP INDEX IF EXISTS public.uq_cards_quadro_contato;
  CREATE INDEX IF NOT EXISTS idx_AgentesIA_conexaoId ON public."SAAS_AgentesIA"("conexaoId");
  CREATE INDEX IF NOT EXISTS idx_Conversas_Agentes_idAgente ON public."SAAS_Conversas_Agentes"("idAgente");
  CREATE INDEX IF NOT EXISTS idx_Conversas_Agentes_idConexao ON public."SAAS_Conversas_Agentes"("idConexao");
  CREATE EXTENSION IF NOT EXISTS pg_trgm;
  -- Busca textual usada no chat (ILIKE '%termo%').
  CREATE INDEX IF NOT EXISTS saas_conversas_telefone_trgm_idx
    ON public."SAAS_Conversas_Agentes" USING gin (telefone gin_trgm_ops);
  CREATE INDEX IF NOT EXISTS saas_contatos_nome_trgm_idx
    ON public."SAAS_Contatos" USING gin (nome gin_trgm_ops);
  -- Filtro por conta/status na mesma ordem de paginacao da lista.
  CREATE INDEX IF NOT EXISTS saas_conversas_conta_status_ultima_idx
    ON public."SAAS_Conversas_Agentes" (
      "contaId",
      (LOWER(BTRIM(COALESCE("statusAtendimento", '')))),
      "ultimaMensagem" DESC NULLS LAST,
      id DESC
    );
  -- Paginação da lista do chat por conta, na mesma ordem usada pelo frontend.
  CREATE INDEX IF NOT EXISTS saas_conversas_conta_ultima_mensagem_idx
    ON public."SAAS_Conversas_Agentes" ("contaId", "ultimaMensagem" DESC NULLS LAST, id DESC);
  CREATE INDEX IF NOT EXISTS saas_mensagens_conversa_idx ON public."SAAS_Mensagens"("conversaId");
  -- Histórico do agente: últimas N ativas por conversa (order id DESC / id > lastId)
  CREATE INDEX IF NOT EXISTS saas_mensagens_conversa_ativas_id_idx
    ON public."SAAS_Mensagens" ("conversaId", id DESC)
    WHERE apagada = false;
  -- Remove duplicatas (conversaId + messageEvolutionId) antes de garantir índice único
  DROP INDEX IF EXISTS public.saas_mensagens_conversa_evolution_unique;
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Mensagens"') IS NULL THEN
      RETURN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Mensagens' AND column_name = 'conversaId') THEN
      RETURN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Mensagens' AND column_name = 'messageEvolutionId') THEN
      RETURN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Mensagens' AND column_name = 'id') THEN
      RETURN;
    END IF;
    DELETE FROM public."SAAS_Mensagens" m
    USING (
      SELECT id,
        row_number() OVER (
          PARTITION BY "conversaId", "messageEvolutionId"
          ORDER BY id
        ) AS rn
      FROM public."SAAS_Mensagens"
      WHERE "messageEvolutionId" IS NOT NULL
        AND "messageEvolutionId" <> ''
    ) t
    WHERE m.id = t.id
      AND t.rn > 1;
  END$$;
  CREATE UNIQUE INDEX IF NOT EXISTS saas_mensagens_conversa_evolution_unique
  ON public."SAAS_Mensagens"("conversaId", "messageEvolutionId")
  WHERE "messageEvolutionId" IS NOT NULL AND "messageEvolutionId" <> '';

  -- Coluna favorita em mensagens (favoritar no chat)
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Mensagens"') IS NOT NULL THEN
      IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' AND LOWER(table_name) = 'saas_mensagens' AND column_name = 'favorita'
      ) THEN
        ALTER TABLE public."SAAS_Mensagens" ADD COLUMN favorita BOOLEAN NOT NULL DEFAULT false;
      END IF;
    END IF;
  END$$;
  -- Padrão: coluna de data em snake_case (alinhado ao restante do schema)
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Mensagens"') IS NULL THEN RETURN; END IF;
    IF EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND LOWER(table_name) = 'saas_mensagens' AND column_name = 'createdat'
    ) AND NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND LOWER(table_name) = 'saas_mensagens' AND column_name = 'created_at'
    ) THEN
      ALTER TABLE public."SAAS_Mensagens" RENAME COLUMN createdat TO created_at;
    END IF;
  END$$;
  -- Após RENAME createdat → created_at: regrava funções de trigger ligadas a SAAS_Mensagens que ainda usam NEW/OLD.createdat (evita 42703 no INSERT).
  DO $$
  DECLARE
    r RECORD;
    d text;
    d2 text;
  BEGIN
    IF to_regclass('public."SAAS_Mensagens"') IS NULL THEN RETURN; END IF;
    FOR r IN
      SELECT DISTINCT p.oid AS proid, p.proname
      FROM pg_trigger t
      JOIN pg_class c ON c.oid = t.tgrelid
      JOIN pg_namespace n ON n.oid = c.relnamespace
      JOIN pg_proc p ON p.oid = t.tgfoid
      WHERE n.nspname = 'public'
        AND c.relname = 'SAAS_Mensagens'
        AND NOT t.tgisinternal
    LOOP
      d := pg_get_functiondef(r.proid);
      IF d IS NULL THEN CONTINUE; END IF;
      IF position('createdat' IN lower(d)) = 0 THEN CONTINUE; END IF;
      d2 := replace(d, 'NEW."createdat"', 'NEW.created_at');
      d2 := replace(d2, 'OLD."createdat"', 'OLD.created_at');
      d2 := replace(d2, 'NEW.createdat', 'NEW.created_at');
      d2 := replace(d2, 'OLD.createdat', 'OLD.created_at');
      IF d2 IS DISTINCT FROM d THEN
        BEGIN
          EXECUTE d2;
        EXCEPTION WHEN OTHERS THEN
          RAISE NOTICE 'Reparo trigger SAAS_Mensagens: não foi possível regravar função %: %', r.proname, SQLERRM;
        END;
      END IF;
    END LOOP;
  END$$;
  CREATE INDEX IF NOT EXISTS saas_mensagens_conversa_favorita_idx
    ON public."SAAS_Mensagens"("conversaId") WHERE favorita = true;
  -- Após a normalização de createdat para created_at, atende a última mensagem e o histórico.
  CREATE INDEX IF NOT EXISTS saas_mensagens_conversa_created_idx
    ON public."SAAS_Mensagens" ("conversaId", created_at DESC, id DESC)
    WHERE apagada = false;
  CREATE INDEX IF NOT EXISTS saas_contatos_conta_lid_idx
    ON public."SAAS_Contatos" ("contaId", lid)
    WHERE lid IS NOT NULL AND lid <> '';
  -- Índice único: uq_SAAS_Usuarios_Email
  DO $$
  BEGIN
    IF NOT EXISTS (
      SELECT 1 FROM pg_indexes WHERE schemaname = 'public' AND tablename = 'SAAS_Usuarios' AND LOWER(indexname) = LOWER('uq_SAAS_Usuarios_Email')
    ) AND NOT EXISTS (
      SELECT 1 FROM pg_index i JOIN pg_class t ON t.oid = i.indrelid JOIN pg_class idx ON idx.oid = i.indexrelid JOIN pg_namespace n ON n.oid = t.relnamespace JOIN pg_attribute a ON a.attrelid = t.oid AND a.attnum = ANY(i.indkey)
      WHERE n.nspname = 'public' AND t.relname = 'SAAS_Usuarios' AND i.indisunique = true AND a.attname = 'Email' AND array_length(i.indkey, 1) = 1
    ) THEN
      BEGIN
        CREATE UNIQUE INDEX uq_SAAS_Usuarios_Email ON public."SAAS_Usuarios"("Email");
      EXCEPTION WHEN OTHERS THEN RAISE NOTICE 'Erro ao criar índice uq_SAAS_Usuarios_Email: %', SQLERRM; END;
    END IF;
  END$$;

  -- FKs: ON DELETE CASCADE: (1) Conexão→Conversas, (2) Conversa→Mensagens, (3) Conexão→Detalhes_Disparos, (4) Contato→Conversas (mensagens em cascata via conversa). Restante SET NULL onde aplicável.
  DO $$
  BEGIN
    -- (1) SAAS_Conversas_Agentes.idConexao → SAAS_Conexões: ON DELETE CASCADE
    IF to_regclass('public."SAAS_Conversas_Agentes"') IS NOT NULL AND to_regclass('public."SAAS_Conexões"') IS NOT NULL THEN
      IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Conversas_Agentes_idConexao_fkey') THEN
        ALTER TABLE public."SAAS_Conversas_Agentes" DROP CONSTRAINT "SAAS_Conversas_Agentes_idConexao_fkey";
      END IF;
      IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Conversas_Agentes_idConexao_fkey') THEN
        ALTER TABLE public."SAAS_Conversas_Agentes"
          ADD CONSTRAINT "SAAS_Conversas_Agentes_idConexao_fkey"
          FOREIGN KEY ("idConexao") REFERENCES public."SAAS_Conexões"(id) ON UPDATE CASCADE ON DELETE CASCADE;
      END IF;
    END IF;
    -- SAAS_Conversas_Agentes.contatoId → SAAS_Contatos: ON DELETE CASCADE (exclui conversa e, em cascata, SAAS_Mensagens)
    IF to_regclass('public."SAAS_Conversas_Agentes"') IS NOT NULL AND to_regclass('public."SAAS_Contatos"') IS NOT NULL THEN
      IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Conversas_Agentes_contatoId_fkey') THEN
        ALTER TABLE public."SAAS_Conversas_Agentes" DROP CONSTRAINT "SAAS_Conversas_Agentes_contatoId_fkey";
      END IF;
      IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'saas_conversas_agentes_contatoid_fkey') THEN
        ALTER TABLE public."SAAS_Conversas_Agentes" DROP CONSTRAINT "saas_conversas_agentes_contatoid_fkey";
      END IF;
      IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Conversas_Agentes_contatoId_fkey') THEN
        ALTER TABLE public."SAAS_Conversas_Agentes"
          ADD CONSTRAINT "SAAS_Conversas_Agentes_contatoId_fkey"
          FOREIGN KEY ("contatoId") REFERENCES public."SAAS_Contatos"(id) ON UPDATE CASCADE ON DELETE CASCADE;
      END IF;
    END IF;
    -- SAAS_Conversas_Agentes.idAgente → SAAS_AgentesIA: ON DELETE SET NULL (necessário para embed PostgREST no chat)
    IF to_regclass('public."SAAS_Conversas_Agentes"') IS NOT NULL AND to_regclass('public."SAAS_AgentesIA"') IS NOT NULL
      AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conversas_Agentes' AND column_name = 'idAgente') THEN
      UPDATE public."SAAS_Conversas_Agentes" c
      SET "idAgente" = NULL
      WHERE c."idAgente" IS NOT NULL
        AND NOT EXISTS (SELECT 1 FROM public."SAAS_AgentesIA" a WHERE a.id = c."idAgente");
      IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Conversas_Agentes_idAgente_fkey') THEN
        ALTER TABLE public."SAAS_Conversas_Agentes" DROP CONSTRAINT "SAAS_Conversas_Agentes_idAgente_fkey";
      END IF;
      IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Conversas_Agentes_idAgente_fkey') THEN
        ALTER TABLE public."SAAS_Conversas_Agentes"
          ADD CONSTRAINT "SAAS_Conversas_Agentes_idAgente_fkey"
          FOREIGN KEY ("idAgente") REFERENCES public."SAAS_AgentesIA"(id) ON UPDATE CASCADE ON DELETE SET NULL;
      END IF;
    END IF;
    -- (2) SAAS_Mensagens.conversaId → SAAS_Conversas_Agentes: ON DELETE CASCADE
    IF to_regclass('public."SAAS_Mensagens"') IS NOT NULL AND to_regclass('public."SAAS_Conversas_Agentes"') IS NOT NULL THEN
      -- Remove mensagens órfãs para permitir recriar FK de conversaId
      DELETE FROM public."SAAS_Mensagens" m
      WHERE m."conversaId" IS NOT NULL
        AND NOT EXISTS (
          SELECT 1
          FROM public."SAAS_Conversas_Agentes" c
          WHERE c.id = m."conversaId"
        );
      IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Mensagens_conversaId_fkey') THEN
        ALTER TABLE public."SAAS_Mensagens" DROP CONSTRAINT "SAAS_Mensagens_conversaId_fkey";
      END IF;
      IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Mensagens_conversaId_fkey') THEN
        ALTER TABLE public."SAAS_Mensagens"
          ADD CONSTRAINT "SAAS_Mensagens_conversaId_fkey"
          FOREIGN KEY ("conversaId") REFERENCES public."SAAS_Conversas_Agentes"(id) ON UPDATE CASCADE ON DELETE CASCADE;
      END IF;
    END IF;
    -- Remover FK SAAS_Mensagens.conexaoId → SAAS_Conexões (evita SET NULL ao excluir conexão; mensagens já são excluídas via CASCADE em conversaId)
    IF to_regclass('public."SAAS_Mensagens"') IS NOT NULL THEN
      IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Mensagens_conexaoId_fkey') THEN
        ALTER TABLE public."SAAS_Mensagens" DROP CONSTRAINT "SAAS_Mensagens_conexaoId_fkey";
      END IF;
      ALTER TABLE public."SAAS_Mensagens" ALTER COLUMN "conexaoId" DROP NOT NULL;
    END IF;
    -- (3) SAAS_Detalhes_Disparos.idConexao → SAAS_Conexões: ON DELETE CASCADE (ao excluir conexão, exclui linhas de disparo dessa conexão)
    IF to_regclass('public."SAAS_Detalhes_Disparos"') IS NOT NULL AND to_regclass('public."SAAS_Conexões"') IS NOT NULL THEN
      IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Detalhes_Disparos_idConexao_fkey') THEN
        ALTER TABLE public."SAAS_Detalhes_Disparos" DROP CONSTRAINT "SAAS_Detalhes_Disparos_idConexao_fkey";
      END IF;
      IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Detalhes_Disparos_idConexao_fkey') THEN
        ALTER TABLE public."SAAS_Detalhes_Disparos"
          ADD CONSTRAINT "SAAS_Detalhes_Disparos_idConexao_fkey"
          FOREIGN KEY ("idConexao") REFERENCES public."SAAS_Conexões"(id) ON UPDATE CASCADE ON DELETE CASCADE;
      END IF;
    END IF;
    -- SAAS_Detalhes_Disparos.idDisparo → SAAS_Disparos: ON DELETE CASCADE
    IF to_regclass('public."SAAS_Detalhes_Disparos"') IS NOT NULL AND to_regclass('public."SAAS_Disparos"') IS NOT NULL THEN
      DELETE FROM public."SAAS_Detalhes_Disparos" d
      WHERE d."idDisparo" IS NOT NULL
        AND NOT EXISTS (SELECT 1 FROM public."SAAS_Disparos" h WHERE h.id = d."idDisparo");
      IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Detalhes_Disparos_idDisparo_fkey') THEN
        ALTER TABLE public."SAAS_Detalhes_Disparos" DROP CONSTRAINT "SAAS_Detalhes_Disparos_idDisparo_fkey";
      END IF;
      IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Detalhes_Disparos_idDisparo_fkey') THEN
        ALTER TABLE public."SAAS_Detalhes_Disparos"
          ADD CONSTRAINT "SAAS_Detalhes_Disparos_idDisparo_fkey"
          FOREIGN KEY ("idDisparo") REFERENCES public."SAAS_Disparos"(id) ON UPDATE CASCADE ON DELETE CASCADE;
      END IF;
    END IF;
    -- SAAS_Detalhes_Disparos.idContato → SAAS_Contatos: ON DELETE SET NULL
    IF to_regclass('public."SAAS_Detalhes_Disparos"') IS NOT NULL AND to_regclass('public."SAAS_Contatos"') IS NOT NULL THEN
      DELETE FROM public."SAAS_Detalhes_Disparos" d
      WHERE d."idContato" IS NOT NULL
        AND NOT EXISTS (SELECT 1 FROM public."SAAS_Contatos" c WHERE c.id = d."idContato");
      IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Detalhes_Disparos_idContato_fkey') THEN
        ALTER TABLE public."SAAS_Detalhes_Disparos" DROP CONSTRAINT "SAAS_Detalhes_Disparos_idContato_fkey";
      END IF;
      IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Detalhes_Disparos_idContato_fkey') THEN
        ALTER TABLE public."SAAS_Detalhes_Disparos"
          ADD CONSTRAINT "SAAS_Detalhes_Disparos_idContato_fkey"
          FOREIGN KEY ("idContato") REFERENCES public."SAAS_Contatos"(id) ON UPDATE CASCADE ON DELETE SET NULL;
      END IF;
    END IF;
    -- SAAS_Etapas_Quadros.quadroId → SAAS_Quadros: ON DELETE CASCADE
    IF to_regclass('public."SAAS_Etapas_Quadros"') IS NOT NULL AND to_regclass('public."SAAS_Quadros"') IS NOT NULL THEN
      DELETE FROM public."SAAS_Etapas_Quadros" e
      WHERE e."quadroId" IS NOT NULL
        AND NOT EXISTS (SELECT 1 FROM public."SAAS_Quadros" q WHERE q.id = e."quadroId");
      IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Etapas_Quadros_quadroId_fkey') THEN
        ALTER TABLE public."SAAS_Etapas_Quadros" DROP CONSTRAINT "SAAS_Etapas_Quadros_quadroId_fkey";
      END IF;
      IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Etapas_Quadros_quadroId_fkey') THEN
        ALTER TABLE public."SAAS_Etapas_Quadros"
          ADD CONSTRAINT "SAAS_Etapas_Quadros_quadroId_fkey"
          FOREIGN KEY ("quadroId") REFERENCES public."SAAS_Quadros"(id) ON UPDATE CASCADE ON DELETE CASCADE;
      END IF;
    END IF;
    -- SAAS_Cards_Quadros.contatoId → SAAS_Contatos: ON DELETE SET NULL
    IF to_regclass('public."SAAS_Cards_Quadros"') IS NOT NULL AND to_regclass('public."SAAS_Contatos"') IS NOT NULL THEN
      DELETE FROM public."SAAS_Cards_Quadros" cq
      WHERE cq."contatoId" IS NOT NULL
        AND NOT EXISTS (SELECT 1 FROM public."SAAS_Contatos" c WHERE c.id = cq."contatoId");
      IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Cards_Quadros_contatoId_fkey') THEN
        ALTER TABLE public."SAAS_Cards_Quadros" DROP CONSTRAINT "SAAS_Cards_Quadros_contatoId_fkey";
      END IF;
      IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Cards_Quadros_contatoId_fkey') THEN
        ALTER TABLE public."SAAS_Cards_Quadros"
          ADD CONSTRAINT "SAAS_Cards_Quadros_contatoId_fkey"
          FOREIGN KEY ("contatoId") REFERENCES public."SAAS_Contatos"(id) ON UPDATE CASCADE ON DELETE SET NULL;
      END IF;
    END IF;
    -- SAAS_Cards_Quadros.etapaQuadroId → SAAS_Etapas_Quadros: ON DELETE CASCADE
    IF to_regclass('public."SAAS_Cards_Quadros"') IS NOT NULL AND to_regclass('public."SAAS_Etapas_Quadros"') IS NOT NULL THEN
      DELETE FROM public."SAAS_Cards_Quadros" cq
      WHERE cq."etapaQuadroId" IS NOT NULL
        AND NOT EXISTS (SELECT 1 FROM public."SAAS_Etapas_Quadros" e WHERE e.id = cq."etapaQuadroId");
      IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Cards_Quadros_etapaQuadroId_fkey') THEN
        ALTER TABLE public."SAAS_Cards_Quadros" DROP CONSTRAINT "SAAS_Cards_Quadros_etapaQuadroId_fkey";
      END IF;
      IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Cards_Quadros_etapaQuadroId_fkey') THEN
        ALTER TABLE public."SAAS_Cards_Quadros"
          ADD CONSTRAINT "SAAS_Cards_Quadros_etapaQuadroId_fkey"
          FOREIGN KEY ("etapaQuadroId") REFERENCES public."SAAS_Etapas_Quadros"(id) ON UPDATE CASCADE ON DELETE CASCADE;
      END IF;
    END IF;
    -- SAAS_Conexões.idAgente → SAAS_AgentesIA: ON DELETE SET NULL (excluir agente NÃO exclui conexão)
    IF to_regclass('public."SAAS_Conexões"') IS NOT NULL AND to_regclass('public."SAAS_AgentesIA"') IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'idAgente') THEN
      IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Conexões_idAgente_fkey') THEN
        ALTER TABLE public."SAAS_Conexões" DROP CONSTRAINT "SAAS_Conexões_idAgente_fkey";
      END IF;
      IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Conexões_idAgente_fkey') THEN
        ALTER TABLE public."SAAS_Conexões"
          ADD CONSTRAINT "SAAS_Conexões_idAgente_fkey"
          FOREIGN KEY ("idAgente") REFERENCES public."SAAS_AgentesIA"(id) ON UPDATE CASCADE ON DELETE SET NULL;
      END IF;
    END IF;
    -- SAAS_AgentesIA.conexaoId → SAAS_Conexões: ON DELETE SET NULL (excluir conexão NÃO exclui agente)
    IF to_regclass('public."SAAS_AgentesIA"') IS NOT NULL
      AND to_regclass('public."SAAS_Conexões"') IS NOT NULL
      AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_AgentesIA' AND column_name = 'conexaoId') THEN
      -- Limpa órfãos para permitir recriar a FK sem erro
      DELETE FROM public."SAAS_AgentesIA" a
      WHERE a."conexaoId" IS NOT NULL
        AND NOT EXISTS (
          SELECT 1
          FROM public."SAAS_Conexões" c
          WHERE c.id = a."conexaoId"
        );
      IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_AgentesIA_conexaoId_fkey') THEN
        ALTER TABLE public."SAAS_AgentesIA" DROP CONSTRAINT "SAAS_AgentesIA_conexaoId_fkey";
      END IF;
      IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_AgentesIA_conexaoId_fkey') THEN
        ALTER TABLE public."SAAS_AgentesIA"
          ADD CONSTRAINT "SAAS_AgentesIA_conexaoId_fkey"
          FOREIGN KEY ("conexaoId") REFERENCES public."SAAS_Conexões"(id) ON UPDATE CASCADE ON DELETE SET NULL;
      END IF;
    END IF;
    -- SAAS_Webhook.conexaoId → SAAS_Conexões: ON DELETE SET NULL
    IF to_regclass('public."SAAS_Webhook"') IS NOT NULL
      AND to_regclass('public."SAAS_Conexões"') IS NOT NULL
      AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Webhook' AND column_name = 'conexaoId') THEN
      DELETE FROM public."SAAS_Webhook" w
      WHERE w."conexaoId" IS NOT NULL
        AND NOT EXISTS (SELECT 1 FROM public."SAAS_Conexões" c WHERE c.id = w."conexaoId");
      IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Webhook_conexaoId_fkey') THEN
        ALTER TABLE public."SAAS_Webhook" DROP CONSTRAINT "SAAS_Webhook_conexaoId_fkey";
      END IF;
      IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Webhook_conexaoId_fkey') THEN
        ALTER TABLE public."SAAS_Webhook"
          ADD CONSTRAINT "SAAS_Webhook_conexaoId_fkey"
          FOREIGN KEY ("conexaoId") REFERENCES public."SAAS_Conexões"(id) ON UPDATE CASCADE ON DELETE SET NULL;
      END IF;
    END IF;
    -- SAAS_Webhook.idAgente → SAAS_AgentesIA: ON DELETE SET NULL
    IF to_regclass('public."SAAS_Webhook"') IS NOT NULL
      AND to_regclass('public."SAAS_AgentesIA"') IS NOT NULL
      AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Webhook' AND column_name = 'idAgente') THEN
      DELETE FROM public."SAAS_Webhook" w
      WHERE w."idAgente" IS NOT NULL
        AND NOT EXISTS (SELECT 1 FROM public."SAAS_AgentesIA" a WHERE a.id = w."idAgente");
      IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Webhook_idAgente_fkey') THEN
        ALTER TABLE public."SAAS_Webhook" DROP CONSTRAINT "SAAS_Webhook_idAgente_fkey";
      END IF;
      IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Webhook_idAgente_fkey') THEN
        ALTER TABLE public."SAAS_Webhook"
          ADD CONSTRAINT "SAAS_Webhook_idAgente_fkey"
          FOREIGN KEY ("idAgente") REFERENCES public."SAAS_AgentesIA"(id) ON UPDATE CASCADE ON DELETE SET NULL;
      END IF;
    END IF;
  END$$;

  -- Ao excluir conexão: excluir também os disparos (cabeçalho) que usam essa conexão em idConexoes
  CREATE OR REPLACE FUNCTION public.f_delete_disparos_on_delete_conexao()
  RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
  BEGIN
    -- Primeiro exclui detalhes dos disparos que referenciam esta conexão; depois exclui os disparos
    DELETE FROM public."SAAS_Detalhes_Disparos"
    WHERE "idDisparo" IN (SELECT id FROM public."SAAS_Disparos" WHERE OLD.id = ANY("idConexoes"));
    DELETE FROM public."SAAS_Disparos" WHERE OLD.id = ANY("idConexoes");
    RETURN OLD;
  END;
  $$;
  DROP TRIGGER IF EXISTS trg_delete_disparos_on_delete_conexao ON public."SAAS_Conexões";
  CREATE TRIGGER trg_delete_disparos_on_delete_conexao
    AFTER DELETE ON public."SAAS_Conexões"
    FOR EACH ROW EXECUTE FUNCTION public.f_delete_disparos_on_delete_conexao();

  -- =========================
  -- CENÁRIO 3: AJUSTES COMUNS (sempre executados)
  -- =========================
  -- Funções helper, RLS, views, triggers, grants. Idempotentes - podem rodar sempre.

  -- Criar SAAS_Webhook se não existir (mesmo quando SAAS_Contas ainda não existe — ex.: usuário sem tabela contas)
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Webhook"') IS NOT NULL THEN RETURN; END IF;
    IF to_regclass('public."SAAS_Contas"') IS NOT NULL THEN
      CREATE TABLE public."SAAS_Webhook" (
        id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
        created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
        "contaId" UUID REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE,
        "conexaoId" BIGINT, "tokenWebhook" UUID DEFAULT gen_random_uuid(), nome TEXT,
        status BOOLEAN, teste BOOLEAN, mapeamento JSONB, "ultimoPayload" JSONB, "idAgente" BIGINT, "mensagemPadrao" TEXT
      );
    ELSE
      CREATE TABLE public."SAAS_Webhook" (
        id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
        created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
        "contaId" UUID,
        "conexaoId" BIGINT, "tokenWebhook" UUID DEFAULT gen_random_uuid(), nome TEXT,
        status BOOLEAN, teste BOOLEAN, mapeamento JSONB, "ultimoPayload" JSONB, "idAgente" BIGINT, "mensagemPadrao" TEXT
      );
    END IF;
    CREATE INDEX IF NOT EXISTS idx_webhook_contaId ON public."SAAS_Webhook"("contaId");
  END$$;
  -- Adicionar FK contaId → SAAS_Contas quando a tabela contas existir (para webhook criado sem FK)
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Webhook"') IS NULL OR to_regclass('public."SAAS_Contas"') IS NULL THEN RETURN; END IF;
    IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Webhook_contaId_fkey') THEN RETURN; END IF;
    ALTER TABLE public."SAAS_Webhook" ADD CONSTRAINT "SAAS_Webhook_contaId_fkey"
      FOREIGN KEY ("contaId") REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE;
  END$$;

  -- Coluna email em SAAS_Contas (email do usuário criador da conta)
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Contas"') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Contas' AND column_name = 'email') THEN
      ALTER TABLE public."SAAS_Contas" ADD COLUMN email TEXT;
      UPDATE public."SAAS_Contas" c SET email = (SELECT u."Email" FROM public."SAAS_Usuarios" u WHERE u."contaId" = c.id AND u.funcao = 'admin' ORDER BY u.created_at LIMIT 1) WHERE c.email IS NULL;
    END IF;
  END$$;

  -- Coluna tokens: alterar BIGINT para NUMERIC quando já existir (permite valores decimais)
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Contas"') IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Contas' AND column_name = 'tokens' AND data_type = 'bigint') THEN
      ALTER TABLE public."SAAS_Contas" ALTER COLUMN tokens TYPE NUMERIC USING tokens::numeric;
    END IF;
  END$$;

  -- p_conta_id = contaId (multi-tenant: quem pode acessar a conta)
  CREATE OR REPLACE FUNCTION public.can_access_conta(p_conta_id uuid)
  RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER AS $$
    SELECT EXISTS (SELECT 1 FROM public."SAAS_Usuarios" u WHERE u."contaId" = p_conta_id AND u.auth_user_id = auth.uid());
  $$;

  -- p_conta_id = contaId
  CREATE OR REPLACE FUNCTION public.is_admin(p_conta_id uuid)
  RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
  BEGIN
    RETURN EXISTS (SELECT 1 FROM public."SAAS_Usuarios" u WHERE u."contaId" = p_conta_id AND u.auth_user_id = auth.uid() AND u.funcao = 'admin');
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.is_owner(p_user_id uuid)
  RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT public.can_access_conta(p_user_id); $$;

  -- Retorna os contaIds em que o usuário atual está vinculado (evita recursão no RLS de SAAS_Usuarios).
  -- Importante para Realtime do chat: NÃO usar set_config('row_security','off',...) aqui.
  CREATE OR REPLACE FUNCTION public.get_conta_ids_usuario()
  RETURNS uuid[] LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
  DECLARE arr uuid[];
  BEGIN
    SELECT array_agg("contaId") INTO arr FROM public."SAAS_Usuarios" WHERE auth_user_id = auth.uid();
    RETURN COALESCE(arr, ARRAY[]::uuid[]);
  END;
  $$;

  -- Super admin do sistema: usuário com super_admin = true tem acesso a tudo (apenas service_role pode editar a coluna).
  -- Importante para Realtime do chat: NÃO usar set_config('row_security','off',...) aqui.
  CREATE OR REPLACE FUNCTION public.is_super_admin()
  RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
  BEGIN
    RETURN EXISTS (SELECT 1 FROM public."SAAS_Usuarios" WHERE auth_user_id = auth.uid() AND super_admin = true);
  END;
  $$;


  -- Helpers RLS set-based: IN/SELECT avaliados 1x por query (nao por linha).
  CREATE OR REPLACE FUNCTION public.rls_conta_ids()
  RETURNS SETOF uuid
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
    SELECT u."contaId" FROM public."SAAS_Usuarios" u
    WHERE u.auth_user_id = (SELECT auth.uid());
  $$;

  CREATE OR REPLACE FUNCTION public.rls_conta_ids_admin()
  RETURNS SETOF uuid
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
    SELECT u."contaId" FROM public."SAAS_Usuarios" u
    WHERE u.auth_user_id = (SELECT auth.uid()) AND u.funcao = 'admin';
  $$;

  CREATE OR REPLACE FUNCTION public.rls_eh_super_admin()
  RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
    SELECT EXISTS (
      SELECT 1 FROM public."SAAS_Usuarios" u
      WHERE u.auth_user_id = (SELECT auth.uid()) AND u.super_admin = true
    );
  $$;

  GRANT EXECUTE ON FUNCTION public.rls_conta_ids() TO authenticated;
  GRANT EXECUTE ON FUNCTION public.rls_conta_ids_admin() TO authenticated;
  GRANT EXECUTE ON FUNCTION public.rls_eh_super_admin() TO authenticated;


  -- Coluna super_admin em SAAS_Usuarios (para instalações já existentes)
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Usuarios"') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Usuarios' AND column_name = 'super_admin') THEN
      ALTER TABLE public."SAAS_Usuarios" ADD COLUMN super_admin BOOLEAN NOT NULL DEFAULT false;
    END IF;
  END$$;

  -- Promover o usuário logado a primeiro super admin. Só funciona se não existir NENHUM super admin no sistema.
  CREATE OR REPLACE FUNCTION public.promover_primeiro_super_admin()
  RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
  DECLARE
    v_count_super integer;
    v_usuario_id uuid;
  BEGIN
    SELECT count(*) INTO v_count_super FROM public."SAAS_Usuarios" WHERE super_admin = true;
    IF v_count_super > 0 THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Já existe super admin no sistema.');
    END IF;

    UPDATE public."SAAS_Usuarios"
    SET super_admin = true
    WHERE auth_user_id = auth.uid()
    RETURNING id INTO v_usuario_id;

    IF v_usuario_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Usuário não encontrado em SAAS_Usuarios.');
    END IF;

    RETURN jsonb_build_object('ok', true);
  END;
  $$;

  -- Coluna atendente em SAAS_Conversas_Agentes (usuário vinculado à conversa; DEFAULT null)
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Conversas_Agentes"') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conversas_Agentes' AND column_name = 'atendente') THEN
      ALTER TABLE public."SAAS_Conversas_Agentes" ADD COLUMN "atendente" UUID DEFAULT null REFERENCES public."SAAS_Usuarios"(id) ON UPDATE CASCADE ON DELETE SET NULL;
    END IF;
    IF to_regclass('public."SAAS_Conversas_Agentes"') IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conversas_Agentes' AND column_name = 'atendente') THEN
      CREATE INDEX IF NOT EXISTS saas_conversas_agentes_atendente_idx ON public."SAAS_Conversas_Agentes"("atendente");
    END IF;
  END$$;

  -- Coluna dataFechamento em SAAS_Conversas_Agentes (para f_set_data_fechamento_conversa)
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Conversas_Agentes"') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conversas_Agentes' AND column_name = 'dataFechamento') THEN
      ALTER TABLE public."SAAS_Conversas_Agentes" ADD COLUMN "dataFechamento" TIMESTAMPTZ;
    END IF;
  END$$;

  -- Coluna nota em SAAS_Conversas_Agentes
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Conversas_Agentes"') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conversas_Agentes' AND column_name = 'nota') THEN
      ALTER TABLE public."SAAS_Conversas_Agentes" ADD COLUMN nota TEXT;
    END IF;
  END$$;

  -- Colunas de ferramentas em SAAS_AgentesIA (abrirAtendimento, notificarHumano, requisicaoHTTP, CRM) para bancos existentes
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_AgentesIA"') IS NULL THEN RETURN; END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_AgentesIA' AND column_name = 'abrirAtendimento') THEN
      ALTER TABLE public."SAAS_AgentesIA" ADD COLUMN "abrirAtendimento" JSONB;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_AgentesIA' AND column_name = 'notificarHumano') THEN
      ALTER TABLE public."SAAS_AgentesIA" ADD COLUMN "notificarHumano" JSONB;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_AgentesIA' AND column_name = 'requisicaoHTTP') THEN
      ALTER TABLE public."SAAS_AgentesIA" ADD COLUMN "requisicaoHTTP" JSONB;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_AgentesIA' AND column_name = 'CRM') THEN
      ALTER TABLE public."SAAS_AgentesIA" ADD COLUMN "CRM" JSONB;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_AgentesIA' AND column_name = 'produtos') THEN
      ALTER TABLE public."SAAS_AgentesIA" ADD COLUMN produtos JSONB DEFAULT '[]'::jsonb;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_AgentesIA' AND column_name = 'followup') THEN
      ALTER TABLE public."SAAS_AgentesIA" ADD COLUMN followup JSONB NOT NULL DEFAULT '{}'::jsonb;
    END IF;
    IF to_regclass('public."SAAS_Cards_Quadros"') IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Cards_Quadros' AND column_name = 'historicoCRM'
    ) THEN
      ALTER TABLE public."SAAS_Cards_Quadros" ADD COLUMN "historicoCRM" JSONB NOT NULL DEFAULT '[]'::jsonb;
    END IF;
    IF to_regclass('public."SAAS_Planos"') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Planos' AND column_name = 'menu_ocultar') THEN
      ALTER TABLE public."SAAS_Planos" ADD COLUMN menu_ocultar JSONB DEFAULT '[]'::jsonb;
    END IF;
    IF to_regclass('public."SAAS_Planos"') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Planos' AND column_name = 'qntUsuarios') THEN
      ALTER TABLE public."SAAS_Planos" ADD COLUMN "qntUsuarios" BIGINT;
    END IF;
  END$$;

  -- Retorna true se o usuário atual pode ver a conversa (atendente vinculado, setor ou admin da conta).
  -- Remove policies que referenciam assinaturas antigas antes de recriar a função.
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Conversas_Agentes"') IS NOT NULL THEN
      DROP POLICY IF EXISTS "select_conversas" ON public."SAAS_Conversas_Agentes";
      DROP POLICY IF EXISTS "update_conversas" ON public."SAAS_Conversas_Agentes";
      DROP POLICY IF EXISTS "usuario_crud_conversas_agentes" ON public."SAAS_Conversas_Agentes";
    END IF;
    IF to_regclass('public."SAAS_Mensagens"') IS NOT NULL THEN
      DROP POLICY IF EXISTS "select_mensagens" ON public."SAAS_Mensagens";
      DROP POLICY IF EXISTS "update_mensagens" ON public."SAAS_Mensagens";
      DROP POLICY IF EXISTS "usuario_crud_mensagens" ON public."SAAS_Mensagens";
    END IF;
  END$$;

  DROP FUNCTION IF EXISTS public.can_see_conversa(uuid, uuid);
  DROP FUNCTION IF EXISTS public.can_see_conversa(uuid, uuid, bigint);

  CREATE OR REPLACE FUNCTION public.usuario_pertence_setor(p_setor_id bigint)
  RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
    SELECT false;
  $$;

  CREATE OR REPLACE FUNCTION public.can_see_conversa(p_conta_id uuid, p_atendente uuid, p_setor_id bigint)
  RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
    SELECT public.is_admin(p_conta_id)
      OR (
        p_atendente IS NOT NULL
        AND EXISTS (
          SELECT 1 FROM public."SAAS_Usuarios" u
          WHERE u.auth_user_id = auth.uid() AND u.id = p_atendente
        )
      )
      OR (
        p_atendente IS NULL
        AND p_setor_id IS NOT NULL
        AND public.usuario_pertence_setor(p_setor_id)
      )
      OR (
        p_atendente IS NULL
        AND p_setor_id IS NULL
        AND public.can_access_conta(p_conta_id)
      );
  $$;

  -- Compatibilidade com ambientes que já usam can_see_mensagem nas policies de SAAS_Mensagens.
  -- Importante para Realtime: não usar set_config('row_security','off',...) aqui.
  CREATE OR REPLACE FUNCTION public.can_see_mensagem(p_conta_id uuid, p_conversa_id bigint, p_conexao_id bigint)
  RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
  DECLARE
    v_conv_conta_id uuid;
    v_conv_atendente uuid;
  BEGIN
    SELECT c."contaId", c.atendente
      INTO v_conv_conta_id, v_conv_atendente
      FROM public."SAAS_Conversas_Agentes" c
    WHERE c.id = p_conversa_id;

    IF v_conv_conta_id IS NULL THEN
      RETURN false;
    END IF;

    -- Regra principal: mesma regra de visualização da conversa.
    IF public.can_see_conversa(v_conv_conta_id, v_conv_atendente, NULL::bigint) THEN
      RETURN true;
    END IF;

    -- Regra compatível com políticas antigas baseadas em conta+conexão.
    IF p_conexao_id IS NOT NULL
      AND public.can_access_conta(p_conta_id)
      AND EXISTS (
        SELECT 1
          FROM public."SAAS_Conexões" co
          WHERE co.id = p_conexao_id
            AND co."contaId" = p_conta_id
      ) THEN
      RETURN true;
    END IF;

    RETURN false;
  END;
  $$;

  -- Transferência de atendente: o UPDATE direto falha no RLS para o membro atual (WITH CHECK exige ver a conversa já com o novo atendente).
  -- Esta função valida admin da conta OU atendente atual = usuário logado e atualiza atendente.
  CREATE OR REPLACE FUNCTION public.f_transferir_atendimento_conversa(
    p_conversa_id bigint,
    p_novo_atendente uuid
  )
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
  DECLARE
    v_conta uuid;
    v_atendente uuid;
  BEGIN
    IF p_conversa_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'conversa_id obrigatório');
    END IF;

    SELECT c."contaId", c.atendente INTO v_conta, v_atendente
    FROM public."SAAS_Conversas_Agentes" c
    WHERE c.id = p_conversa_id
    FOR UPDATE;

    IF v_conta IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Conversa não encontrada');
    END IF;

    IF NOT (
      public.is_admin(v_conta)
      OR (
        v_atendente IS NOT NULL
        AND EXISTS (
          SELECT 1 FROM public."SAAS_Usuarios" u
          WHERE u.id = v_atendente AND u.auth_user_id = auth.uid()
        )
      )
    ) THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Sem permissão para transferir este atendimento');
    END IF;

    IF p_novo_atendente IS NULL THEN
      IF NOT public.is_admin(v_conta) THEN
        RETURN jsonb_build_object('ok', false, 'erro', 'Apenas administradores podem remover a atribuição');
      END IF;
    ELSE
      IF NOT EXISTS (
        SELECT 1 FROM public."SAAS_Usuarios" u
        WHERE u.id = p_novo_atendente AND u."contaId" = v_conta
      ) THEN
        RETURN jsonb_build_object('ok', false, 'erro', 'Usuário não pertence a esta conta');
      END IF;
    END IF;

    UPDATE public."SAAS_Conversas_Agentes"
    SET atendente = p_novo_atendente
    WHERE id = p_conversa_id;

    RETURN jsonb_build_object('ok', true);
  END;
  $$;

  GRANT EXECUTE ON FUNCTION public.f_transferir_atendimento_conversa(bigint, uuid) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.f_transferir_atendimento_conversa(bigint, uuid) TO service_role;

  -- =========================
  -- Funções de apoio (templates de mensagem e agendamento de disparos)
  -- =========================
  CREATE OR REPLACE FUNCTION public.f_saudacao(p_ts timestamptz)
  RETURNS TEXT LANGUAGE sql IMMUTABLE AS $$
    SELECT CASE
            WHEN (p_ts AT TIME ZONE 'America/Sao_Paulo')::time BETWEEN TIME '05:00' AND TIME '11:59' THEN 'bom dia'
            WHEN (p_ts AT TIME ZONE 'America/Sao_Paulo')::time BETWEEN TIME '12:00' AND TIME '17:59' THEN 'boa tarde'
            ELSE 'boa noite'
          END
  $$;

  CREATE OR REPLACE FUNCTION public.f_next_valid_time(
    p_ts    timestamptz,
    p_start time,
    p_end   time,
    p_days  integer[]
  ) RETURNS timestamptz LANGUAGE plpgsql STABLE AS $$
  DECLARE v_local timestamp;
  BEGIN
    LOOP
      v_local := p_ts AT TIME ZONE 'America/Sao_Paulo';
      IF v_local::time < p_start THEN
        v_local := date_trunc('day', v_local) + p_start;
      ELSIF v_local::time > p_end THEN
        v_local := date_trunc('day', v_local + interval '1 day') + p_start;
      END IF;

      IF p_days IS NULL OR array_length(p_days,1) IS NULL
        OR extract(isodow FROM v_local) = ANY(p_days)
      THEN
        RETURN v_local AT TIME ZONE 'America/Sao_Paulo';
      END IF;

      v_local := date_trunc('day', v_local + interval '1 day') + p_start;
      p_ts    := v_local AT TIME ZONE 'America/Sao_Paulo';
    END LOOP;
  END
  $$;

  CREATE OR REPLACE FUNCTION public.f_render_message(
    p_template TEXT, p_nome TEXT, p_attrs JSONB, p_send_ts timestamptz
  ) RETURNS TEXT LANGUAGE plpgsql IMMUTABLE AS $$
  DECLARE v_msg TEXT := COALESCE(p_template,''); v_token TEXT; v_val TEXT; v_rec TEXT[];
  BEGIN
    FOR v_rec IN SELECT regexp_matches(v_msg, '<([^>]+)>', 'g') LOOP
      v_token := v_rec[1];
      IF v_token='nome' THEN v_val := COALESCE(p_nome,'');
      ELSIF v_token='data' THEN v_val := to_char(p_send_ts AT TIME ZONE 'America/Sao_Paulo','DD/MM/YYYY');
      ELSIF v_token='diadasemana' THEN
        v_val := lower(to_char(p_send_ts AT TIME ZONE 'America/Sao_Paulo','TMDay'));
        v_val := replace(replace(replace(replace(replace(replace(replace(
                v_val,'monday','segunda-feira'),'tuesday','terça-feira'),
                'wednesday','quarta-feira'),'thursday','quinta-feira'),
                'friday','sexta-feira'),'saturday','sábado'),'sunday','domingo');
      ELSIF v_token='hora' THEN v_val := to_char(p_send_ts AT TIME ZONE 'America/Sao_Paulo','HH24:MI');
      ELSIF v_token='mes' THEN v_val := lower(to_char(p_send_ts AT TIME ZONE 'America/Sao_Paulo','TMMonth'));
      ELSIF v_token='saudacao' THEN v_val := f_saudacao(p_send_ts);
      ELSE v_val := COALESCE(p_attrs ->> v_token,'');
      END IF;
      v_msg := replace(v_msg, '<'||v_token||'>', COALESCE(v_val,''));
    END LOOP;
    RETURN v_msg;
  END
  $$;

  -- match_documents (RAG) - cria apenas se tipo vector existir
  DO $$
  BEGIN
    IF EXISTS (SELECT 1 FROM pg_type WHERE typname = 'vector') THEN
      EXECUTE '
  CREATE OR REPLACE FUNCTION public.match_documents(
    query_embedding vector,
    match_count int DEFAULT 10,
    filter jsonb DEFAULT ''{}''
  ) RETURNS TABLE (
    id bigint,
    content text,
    metadata jsonb,
    similarity float
  )
  LANGUAGE plpgsql
  AS $func$
  BEGIN
    RETURN QUERY
    SELECT
      d.id,
      d.content,
      d.metadata,
      1 - (d.embedding <=> query_embedding) AS similarity
    FROM public."SAAS_Conhecimentos" d
    WHERE d.metadata @> filter
    ORDER BY d.embedding <=> query_embedding
    LIMIT match_count;
  END;
  $func$;';
    ELSE
      RAISE NOTICE 'Tipo vector não disponível. Função match_documents não será criada.';
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      RAISE NOTICE 'Erro ao criar função match_documents: %.', SQLERRM;
  END$$;

  -- f_excluir_conhecimento_por_idunico
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Conhecimentos"') IS NOT NULL THEN
      EXECUTE '
  CREATE OR REPLACE FUNCTION public.f_excluir_conhecimento_por_idunico(p_idunico text)
  RETURNS bigint
  LANGUAGE plpgsql
  AS $func$
  DECLARE
    v_deleted bigint;
  BEGIN
    DELETE FROM public."SAAS_Conhecimentos"
    WHERE metadata->>''idUnico'' = p_idunico;

    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    RETURN v_deleted;
  END;
  $func$;';
    ELSE
      RAISE NOTICE 'Tabela SAAS_Conhecimentos não existe. Função f_excluir_conhecimento_por_idunico não será criada.';
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      RAISE NOTICE 'Erro ao criar função f_excluir_conhecimento_por_idunico: %.', SQLERRM;
  END$$;

  -- RLS: permitir DELETE em SAAS_Conhecimentos apenas se o conhecimento estiver
  -- vinculado a um agente da mesma conta (SAAS_AgentesIA.conhecimento -> idUnico)
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Conhecimentos"') IS NOT NULL
      AND to_regclass('public."SAAS_AgentesIA"') IS NOT NULL THEN

      -- Habilitar RLS (idempotente)
      EXECUTE 'ALTER TABLE public."SAAS_Conhecimentos" ENABLE ROW LEVEL SECURITY';

      -- Criar policy de DELETE se ainda não existir
      IF NOT EXISTS (
        SELECT 1
        FROM pg_policies
        WHERE schemaname = 'public'
          AND tablename = 'SAAS_Conhecimentos'
          AND policyname = 'delete_knowledge_linked_to_own_agents'
      ) THEN
        EXECUTE $policy$
          CREATE POLICY delete_knowledge_linked_to_own_agents
          ON public."SAAS_Conhecimentos"
          FOR DELETE
          TO authenticated
          USING (
            EXISTS (
              SELECT 1
              FROM public."SAAS_AgentesIA" a
              CROSS JOIN LATERAL jsonb_array_elements(COALESCE(a.conhecimento, '[]'::jsonb)) AS c(elem)
              WHERE
                -- conta do agente deve ser a mesma do JWT
                a."contaId" = ((current_setting('request.jwt.claims', true)::jsonb->>'contaId')::uuid)
                -- idUnico do conhecimento deve aparecer no array conhecimento do agente
                AND c.elem->>'idUnico' = metadata->>'idUnico'
            )
          );
        $policy$;
      END IF;
    END IF;
  END$$;

  -- Coluna embedding em SAAS_Conhecimentos (RAG/vector) – só se o tipo vector existir
  DO $$
  BEGIN
    IF EXISTS (SELECT 1 FROM pg_type WHERE typname = 'vector') THEN
      IF to_regclass('public."SAAS_Conhecimentos"') IS NOT NULL
        AND NOT EXISTS (
          SELECT 1 FROM information_schema.columns
          WHERE table_schema = 'public' AND table_name = 'SAAS_Conhecimentos' AND column_name = 'embedding'
        ) THEN
        ALTER TABLE public."SAAS_Conhecimentos" ADD COLUMN embedding vector;
        RAISE NOTICE 'Coluna embedding adicionada à tabela SAAS_Conhecimentos.';
      END IF;
    ELSE
      RAISE NOTICE 'Tipo vector não disponível. Habilite a extensão vector no Supabase (Database > Extensions) e execute novamente ou adicione a coluna manualmente.';
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      RAISE NOTICE 'Erro ao adicionar coluna embedding: %.', SQLERRM;
  END$$;

  -- Índice ivfflat para busca por similaridade (embedding)
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Conhecimentos"') IS NOT NULL
      AND EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'SAAS_Conhecimentos' AND column_name = 'embedding'
      ) THEN
      IF NOT EXISTS (
        SELECT 1 FROM pg_indexes
        WHERE schemaname = 'public' AND tablename = 'SAAS_Conhecimentos' AND indexname = 'saas_conhecimentos_embedding_idx'
      ) THEN
        BEGIN
          EXECUTE 'CREATE INDEX saas_conhecimentos_embedding_idx ON public."SAAS_Conhecimentos" USING ivfflat (embedding vector_cosine_ops) WITH (lists = ''100'') TABLESPACE pg_default';
          RAISE NOTICE 'Índice saas_conhecimentos_embedding_idx criado com sucesso.';
        EXCEPTION
          WHEN OTHERS THEN
            RAISE NOTICE 'Não foi possível criar o índice IVFFlat agora: %. Crie manualmente depois de inserir dados com embeddings. Erro: %', SQLSTATE, SQLERRM;
        END;
      END IF;
    END IF;
  END$$;

  -- Data em que o card entrou na etapa: o último registro do historicoCRM com destino = etapa.
  -- Aceita os formatos já gravados no histórico: tela/trigger (etapaDestinoId + data),
  -- agente IA antigo (para + em) e criação do card (etapaId/etapa).
  -- Sem registro (cards de antes do histórico) → p_padrao (created_at do card).
  CREATE OR REPLACE FUNCTION public.f_crm_card_entrada_etapa(p_historico JSONB, p_etapa_id BIGINT, p_padrao TIMESTAMPTZ)
  RETURNS TIMESTAMPTZ LANGUAGE sql STABLE AS $$
    SELECT COALESCE(MAX(x.quando), p_padrao)
    FROM (
      SELECT (COALESCE(ev->>'data', ev->>'em'))::timestamptz AS quando
      FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_historico) = 'array' THEN p_historico ELSE '[]'::jsonb END) ev
      WHERE jsonb_typeof(ev) = 'object'
        AND COALESCE(ev->>'data', ev->>'em') ~ '^\d{4}-\d{2}-\d{2}'
        AND COALESCE(
          ev->>'etapaDestinoId',
          ev->>'para',
          CASE WHEN ev->>'tipo' = 'criacao' THEN COALESCE(ev->>'etapaId', ev->>'etapa') END
        ) = p_etapa_id::text
    ) x;
  $$;

  -- get_dashboard e get_dashboard_crm: ambas usam p_user_id (valor = contaId)
  -- Métricas: contatos no período; vendas/agendamentos = cards que entraram na etapa (tipoEtapa) dentro do período
  -- (data da entrada vem do historicoCRM, ver f_crm_card_entrada_etapa); faturamento = soma do valor dessas vendas
  CREATE OR REPLACE FUNCTION public.get_dashboard(
    p_user_id       UUID,
    p_data_inicial  TIMESTAMPTZ,
    p_data_final    TIMESTAMPTZ,
    p_conexao_ids   BIGINT[] DEFAULT NULL,
    p_quadro_id     BIGINT DEFAULT NULL
  )
  RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
  DECLARE
    v_conversas JSONB; v_crm JSONB; v_disparos JSONB; v_atendentes JSONB;
    v_vendas JSONB; v_agendamentos JSONB; v_contatos JSONB;
    v_total_conv BIGINT; v_respondidas_ia BIGINT; v_tempo_abrir NUMERIC; v_tempo_concl NUMERIC;
    v_em_aberto BIGINT; v_aguardando BIGINT; v_fechadas BIGINT; v_conv_por_dia JSONB;
    v_quadro_id BIGINT; v_etapas JSONB; v_conversao TEXT; v_valor_fechado TEXT;
    v_total_disp BIGINT; v_total_conex BIGINT; v_media_disp BIGINT; v_disp_por_dia JSONB;
    v_vendas_por_dia JSONB; v_agend_por_dia JSONB; v_contatos_por_dia JSONB;
    v_vendas_valor DOUBLE PRECISION; v_vendas_qtd BIGINT;
    v_agend_qtd BIGINT; v_contatos_total BIGINT;
  BEGIN
    IF NOT (public.can_access_conta(p_user_id) OR public.is_super_admin()) THEN
      RETURN jsonb_build_object(
        'conversas', jsonb_build_object('total', 0, 'respondidasIA', 0, 'tempoMedioAbrirMin', null, 'tempoMedioConclusaoHoras', null, 'emAberto', 0, 'aguardando', 0, 'fechadas', 0, 'conversasPorDia', '[]'::jsonb),
        'contatos', jsonb_build_object('total', 0, 'novos', 0, 'porDia', '[]'::jsonb),
        'crm', jsonb_build_object('etapas', '[]'::jsonb, 'conversaoTotal', '0%', 'valorFechado', 'R$ 0'),
        'vendas', jsonb_build_object('valorTotal', 0, 'quantidade', 0, 'porDia', '[]'::jsonb),
        'agendamentos', jsonb_build_object('quantidadeTotal', 0, 'porDia', '[]'::jsonb),
        'disparos', jsonb_build_object('totalDisparos', 0, 'conexoesAtivas', 0, 'totalConexoes', 0, 'mediaDisparosPorConexao', 0, 'disparosPorDia', '[]'::jsonb),
        'performanceAtendentes', '[]'::jsonb
      );
    END IF;

    SELECT COUNT(DISTINCT c.id) INTO v_total_conv
    FROM public."SAAS_Conversas_Agentes" c
    INNER JOIN public."SAAS_Mensagens" m ON m."conversaId" = c.id
    WHERE c."contaId" = p_user_id AND (p_conexao_ids IS NULL OR c."idConexao" = ANY(p_conexao_ids))
      AND m.created_at >= p_data_inicial AND m.created_at <= p_data_final;

    SELECT COUNT(DISTINCT c.id) INTO v_respondidas_ia
    FROM public."SAAS_Conversas_Agentes" c
    INNER JOIN public."SAAS_Mensagens" m ON m."conversaId" = c.id AND m."IA" = true
    WHERE c."contaId" = p_user_id AND (p_conexao_ids IS NULL OR c."idConexao" = ANY(p_conexao_ids))
      AND m.created_at >= p_data_inicial AND m.created_at <= p_data_final;

    -- Primeira mensagem enviada de cada conversa da conta, buscada conversa a conversa pelo
    -- índice de "conversaId" (antes agrupava as mensagens enviadas de todas as contas do banco).
    SELECT ROUND(AVG(EXTRACT(EPOCH FROM (prim.primeira_msg - c.created_at)) / 60.0)::numeric, 0) INTO v_tempo_abrir
    FROM public."SAAS_Conversas_Agentes" c
    CROSS JOIN LATERAL (
      SELECT MIN(m.created_at) AS primeira_msg
      FROM public."SAAS_Mensagens" m
      WHERE m."conversaId" = c.id AND m."fromMe" = true
    ) prim
    WHERE c."contaId" = p_user_id AND (p_conexao_ids IS NULL OR c."idConexao" = ANY(p_conexao_ids))
      AND prim.primeira_msg >= p_data_inicial AND prim.primeira_msg <= p_data_final;

    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='SAAS_Conversas_Agentes' AND column_name='dataFechamento') THEN
      SELECT ROUND(AVG(EXTRACT(EPOCH FROM (c."dataFechamento" - c.created_at)) / 3600.0)::numeric, 1) INTO v_tempo_concl
      FROM public."SAAS_Conversas_Agentes" c
      WHERE c."contaId" = p_user_id AND (p_conexao_ids IS NULL OR c."idConexao" = ANY(p_conexao_ids))
        AND c."dataFechamento" IS NOT NULL AND c."dataFechamento" >= p_data_inicial AND c."dataFechamento" <= p_data_final;
    END IF;

    SELECT COUNT(*) FILTER (WHERE LOWER(TRIM(COALESCE("statusAtendimento", ''))) = 'aberto') INTO v_em_aberto
    FROM public."SAAS_Conversas_Agentes" WHERE "contaId" = p_user_id AND (p_conexao_ids IS NULL OR "idConexao" = ANY(p_conexao_ids));

    SELECT COUNT(*) FILTER (WHERE LOWER(TRIM(COALESCE("statusAtendimento", ''))) = 'aguardando') INTO v_aguardando
    FROM public."SAAS_Conversas_Agentes" WHERE "contaId" = p_user_id AND (p_conexao_ids IS NULL OR "idConexao" = ANY(p_conexao_ids));

    SELECT COUNT(*) FILTER (WHERE LOWER(TRIM(COALESCE("statusAtendimento", ''))) = 'fechado') INTO v_fechadas
    FROM public."SAAS_Conversas_Agentes" WHERE "contaId" = p_user_id AND (p_conexao_ids IS NULL OR "idConexao" = ANY(p_conexao_ids));

    SELECT COALESCE(jsonb_agg(jsonb_build_object('data', to_char(d, 'YYYY-MM-DD'), 'dataFormatada', to_char(d, 'DD/MM'), 'total', cnt) ORDER BY d), '[]'::jsonb) INTO v_conv_por_dia
    FROM (SELECT (created_at AT TIME ZONE 'America/Sao_Paulo')::date AS d, COUNT(*) AS cnt
          FROM public."SAAS_Conversas_Agentes"
          WHERE "contaId" = p_user_id AND (p_conexao_ids IS NULL OR "idConexao" = ANY(p_conexao_ids))
            AND created_at >= p_data_inicial AND created_at <= p_data_final
          GROUP BY (created_at AT TIME ZONE 'America/Sao_Paulo')::date) sub;

    v_conversas := jsonb_build_object('total', COALESCE(v_total_conv, 0), 'respondidasIA', COALESCE(v_respondidas_ia, 0), 'tempoMedioAbrirMin', v_tempo_abrir, 'tempoMedioConclusaoHoras', v_tempo_concl, 'emAberto', COALESCE(v_em_aberto, 0), 'aguardando', COALESCE(v_aguardando, 0), 'fechadas', COALESCE(v_fechadas, 0), 'conversasPorDia', COALESCE(v_conv_por_dia, '[]'::jsonb));

    -- Contatos criados no período (tipo contato, não grupo)
    IF to_regclass('public."SAAS_Contatos"') IS NOT NULL THEN
      SELECT COUNT(*) INTO v_contatos_total
      FROM public."SAAS_Contatos" ct
      WHERE ct."contaId" = p_user_id
        AND ct.created_at >= p_data_inicial AND ct.created_at <= p_data_final
        AND (
          NOT EXISTS (
            SELECT 1 FROM information_schema.columns
            WHERE table_schema = 'public' AND table_name = 'SAAS_Contatos' AND column_name = 'tipo'
          )
          OR COALESCE(ct.tipo, 'contato') = 'contato'
        );

      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'data', to_char(d, 'YYYY-MM-DD'),
        'dataFormatada', to_char(d, 'DD/MM'),
        'quantidade', COALESCE(cnt, 0)
      ) ORDER BY d), '[]'::jsonb) INTO v_contatos_por_dia
      FROM (
        SELECT (ct.created_at AT TIME ZONE 'America/Sao_Paulo')::date AS d, COUNT(*)::bigint AS cnt
        FROM public."SAAS_Contatos" ct
        WHERE ct."contaId" = p_user_id
          AND ct.created_at >= p_data_inicial AND ct.created_at <= p_data_final
          AND (
            NOT EXISTS (
              SELECT 1 FROM information_schema.columns
              WHERE table_schema = 'public' AND table_name = 'SAAS_Contatos' AND column_name = 'tipo'
            )
            OR COALESCE(ct.tipo, 'contato') = 'contato'
          )
        GROUP BY (ct.created_at AT TIME ZONE 'America/Sao_Paulo')::date
      ) sub;
    ELSE
      v_contatos_total := 0;
      v_contatos_por_dia := '[]'::jsonb;
    END IF;

    v_contatos := jsonb_build_object(
      'total', COALESCE(v_contatos_total, 0),
      'novos', COALESCE(v_contatos_total, 0),
      'porDia', COALESCE(v_contatos_por_dia, '[]'::jsonb)
    );

    v_quadro_id := p_quadro_id;
    IF v_quadro_id IS NULL THEN SELECT id INTO v_quadro_id FROM public."SAAS_Quadros" WHERE "contaId" = p_user_id ORDER BY id LIMIT 1; END IF;

    IF v_quadro_id IS NOT NULL THEN
      WITH primeira AS (SELECT COUNT(*) AS total FROM public."SAAS_Cards_Quadros" c INNER JOIN public."SAAS_Etapas_Quadros" e ON e.id = c."etapaQuadroId" AND e."quadroId" = v_quadro_id WHERE c."quadroId" = v_quadro_id AND e.ordem = (SELECT MIN(ordem) FROM public."SAAS_Etapas_Quadros" WHERE "quadroId" = v_quadro_id)),
          por_etapa AS (SELECT e.nome, e.ordem, COUNT(c.id) AS qtd FROM public."SAAS_Etapas_Quadros" e LEFT JOIN public."SAAS_Cards_Quadros" c ON c."etapaQuadroId" = e.id AND c."quadroId" = e."quadroId" WHERE e."quadroId" = v_quadro_id GROUP BY e.id, e.nome, e.ordem)
      SELECT jsonb_agg(jsonb_build_object('nome', pe.nome, 'quantidade', pe.qtd, 'percentual', CASE WHEN prim.total > 0 THEN ROUND((pe.qtd::numeric / prim.total * 100)::numeric, 0) ELSE 0 END) ORDER BY pe.ordem) INTO v_etapas
      FROM por_etapa pe CROSS JOIN primeira prim;

      WITH ordens AS (SELECT ordem FROM public."SAAS_Etapas_Quadros" WHERE "quadroId" = v_quadro_id ORDER BY ordem),
          primeira_qtd AS (SELECT COUNT(c.id) AS q FROM public."SAAS_Cards_Quadros" c INNER JOIN public."SAAS_Etapas_Quadros" e ON e.id = c."etapaQuadroId" WHERE e."quadroId" = v_quadro_id AND e.ordem = (SELECT MIN(ordem) FROM ordens)),
          ultima_qtd AS (SELECT COUNT(c.id) AS q FROM public."SAAS_Cards_Quadros" c INNER JOIN public."SAAS_Etapas_Quadros" e ON e.id = c."etapaQuadroId" WHERE e."quadroId" = v_quadro_id AND e.ordem = (SELECT MAX(ordem) FROM ordens))
      SELECT TRIM(ROUND((u.q::numeric / NULLIF(p.q, 0) * 100)::numeric, 0)::text) || '%' INTO v_conversao FROM ultima_qtd u, primeira_qtd p;

      SELECT 'R$ ' || TRIM(TO_CHAR(COALESCE(SUM(c.valor), 0), 'FM999G999G990D00')) INTO v_valor_fechado
      FROM public."SAAS_Cards_Quadros" c INNER JOIN public."SAAS_Etapas_Quadros" e ON e.id = c."etapaQuadroId"
      WHERE e."quadroId" = v_quadro_id AND LOWER(TRIM(COALESCE(e."tipoEtapa", ''))) = 'venda';

      v_crm := jsonb_build_object('etapas', COALESCE(v_etapas, '[]'::jsonb), 'conversaoTotal', COALESCE(v_conversao, '0%'), 'valorFechado', COALESCE(v_valor_fechado, 'R$ 0'));
    ELSE
      v_crm := jsonb_build_object('etapas', '[]'::jsonb, 'conversaoTotal', '0%', 'valorFechado', 'R$ 0');
    END IF;

    -- Vendas / faturamento: cards em etapa tipo "venda" que entraram nela dentro do período
    WITH vendas AS (
      SELECT c.valor,
        public.f_crm_card_entrada_etapa(c."historicoCRM", c."etapaQuadroId", c.created_at) AS entrou_em
      FROM public."SAAS_Cards_Quadros" c
      INNER JOIN public."SAAS_Etapas_Quadros" e ON e.id = c."etapaQuadroId"
      INNER JOIN public."SAAS_Quadros" q ON q.id = c."quadroId"
      WHERE q."contaId" = p_user_id
        AND LOWER(TRIM(COALESCE(e."tipoEtapa", ''))) = 'venda'
        AND (p_quadro_id IS NULL OR c."quadroId" = p_quadro_id)
    ), no_periodo AS (
      SELECT valor, (entrou_em AT TIME ZONE 'America/Sao_Paulo')::date AS d
      FROM vendas
      WHERE entrou_em >= p_data_inicial AND entrou_em <= p_data_final
    )
    SELECT
      (SELECT COALESCE(SUM(valor), 0) FROM no_periodo),
      (SELECT COUNT(*) FROM no_periodo),
      (SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'data', to_char(d, 'YYYY-MM-DD'),
        'dataFormatada', to_char(d, 'DD/MM'),
        'valor', COALESCE(valor, 0),
        'quantidade', COALESCE(qtd, 0)
      ) ORDER BY d), '[]'::jsonb)
      FROM (SELECT d, SUM(valor) AS valor, COUNT(*)::bigint AS qtd FROM no_periodo GROUP BY d) sub)
    INTO v_vendas_valor, v_vendas_qtd, v_vendas_por_dia;

    v_vendas := jsonb_build_object(
      'valorTotal', COALESCE(v_vendas_valor, 0),
      'quantidade', COALESCE(v_vendas_qtd, 0),
      'porDia', COALESCE(v_vendas_por_dia, '[]'::jsonb)
    );

    -- Agendamentos: cards em etapa tipo "agendamento" que entraram nela dentro do período
    WITH agend AS (
      SELECT public.f_crm_card_entrada_etapa(c."historicoCRM", c."etapaQuadroId", c.created_at) AS entrou_em
      FROM public."SAAS_Cards_Quadros" c
      INNER JOIN public."SAAS_Etapas_Quadros" e ON e.id = c."etapaQuadroId"
      INNER JOIN public."SAAS_Quadros" q ON q.id = c."quadroId"
      WHERE q."contaId" = p_user_id
        AND LOWER(TRIM(COALESCE(e."tipoEtapa", ''))) = 'agendamento'
        AND (p_quadro_id IS NULL OR c."quadroId" = p_quadro_id)
    ), no_periodo AS (
      SELECT (entrou_em AT TIME ZONE 'America/Sao_Paulo')::date AS d
      FROM agend
      WHERE entrou_em >= p_data_inicial AND entrou_em <= p_data_final
    )
    SELECT
      (SELECT COUNT(*) FROM no_periodo),
      (SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'data', to_char(d, 'YYYY-MM-DD'),
        'dataFormatada', to_char(d, 'DD/MM'),
        'quantidade', COALESCE(qtd, 0)
      ) ORDER BY d), '[]'::jsonb)
      FROM (SELECT d, COUNT(*)::bigint AS qtd FROM no_periodo GROUP BY d) sub)
    INTO v_agend_qtd, v_agend_por_dia;

    v_agendamentos := jsonb_build_object(
      'quantidadeTotal', COALESCE(v_agend_qtd, 0),
      'porDia', COALESCE(v_agend_por_dia, '[]'::jsonb)
    );

    SELECT COUNT(*) INTO v_total_disp FROM public."SAAS_Detalhes_Disparos" d INNER JOIN public."SAAS_Disparos" h ON h.id = d."idDisparo"
    WHERE h."contaId" = p_user_id AND d."dataEnvio" >= p_data_inicial AND d."dataEnvio" <= p_data_final AND (p_conexao_ids IS NULL OR d."idConexao" = ANY(p_conexao_ids));

    SELECT COUNT(*) INTO v_total_conex FROM public."SAAS_Conexões" WHERE "contaId" = p_user_id;

    v_media_disp := CASE WHEN v_total_conex > 0 THEN (v_total_disp / v_total_conex)::BIGINT ELSE 0 END;

    SELECT COALESCE(jsonb_agg(jsonb_build_object('data', to_char(d, 'YYYY-MM-DD'), 'dataFormatada', to_char(d, 'DD/MM'), 'disparos', cnt) ORDER BY d), '[]'::jsonb) INTO v_disp_por_dia
    FROM (SELECT (d."dataEnvio" AT TIME ZONE 'America/Sao_Paulo')::date AS d, COUNT(*) AS cnt
          FROM public."SAAS_Detalhes_Disparos" d INNER JOIN public."SAAS_Disparos" h ON h.id = d."idDisparo"
          WHERE h."contaId" = p_user_id AND d."dataEnvio" >= p_data_inicial AND d."dataEnvio" <= p_data_final AND (p_conexao_ids IS NULL OR d."idConexao" = ANY(p_conexao_ids))
          GROUP BY (d."dataEnvio" AT TIME ZONE 'America/Sao_Paulo')::date) sub;

    v_disparos := jsonb_build_object('totalDisparos', COALESCE(v_total_disp, 0), 'conexoesAtivas', COALESCE(v_total_conex, 0), 'totalConexoes', COALESCE(v_total_conex, 0), 'mediaDisparosPorConexao', COALESCE(v_media_disp, 0), 'disparosPorDia', COALESCE(v_disp_por_dia, '[]'::jsonb));

    -- Performance por atendente: todos os usuários da conta com qtd atendimentos, tempo médio abertura e fechamento
    SELECT COALESCE(jsonb_agg(row ORDER BY row->>'nome'), '[]'::jsonb) INTO v_atendentes
    FROM (
      SELECT jsonb_build_object(
        'id', u.id,
        'nome', COALESCE(NULLIF(TRIM(COALESCE(u.nome, '')), ''), NULLIF(TRIM(COALESCE(u."Email", '')), ''), '—'),
        'email', u."Email",
        'quantidadeAtendimentos', COALESCE((s.stats->>'qtd')::bigint, 0),
        'tempoMedioAberturaMin', (s.stats->>'tempoMedioAberturaMin')::numeric,
        'tempoMedioFechamentoHoras', (s.stats->>'tempoMedioFechamentoHoras')::numeric
      ) AS row
      FROM public."SAAS_Usuarios" u
      LEFT JOIN (
        SELECT c.atendente,
          jsonb_build_object(
            'qtd', COUNT(*)::bigint,
            'tempoMedioAberturaMin', ROUND(AVG(EXTRACT(EPOCH FROM (prim.primeira_msg - c.created_at)) / 60.0))::numeric,
            'tempoMedioFechamentoHoras', ROUND((AVG(EXTRACT(EPOCH FROM (c."dataFechamento" - c.created_at)) / 3600.0) FILTER (WHERE c."dataFechamento" IS NOT NULL))::numeric, 1)
          ) AS stats
        FROM public."SAAS_Conversas_Agentes" c
        -- Igual ao tempo de abertura acima: só as conversas da conta, com pelo menos uma mensagem enviada.
        CROSS JOIN LATERAL (
          SELECT MIN(m.created_at) AS primeira_msg, COUNT(*) AS enviadas
          FROM public."SAAS_Mensagens" m
          WHERE m."conversaId" = c.id AND m."fromMe" = true
        ) prim
        WHERE c."contaId" = p_user_id AND (p_conexao_ids IS NULL OR c."idConexao" = ANY(p_conexao_ids))
          AND c.created_at >= p_data_inicial AND c.created_at <= p_data_final
          AND c.atendente IS NOT NULL
          AND prim.enviadas > 0
        GROUP BY c.atendente
      ) s ON s.atendente = u.id
      WHERE u."contaId" = p_user_id
    ) sub;

    RETURN jsonb_build_object(
      'conversas', v_conversas,
      'contatos', v_contatos,
      'crm', v_crm,
      'vendas', v_vendas,
      'agendamentos', v_agendamentos,
      'disparos', v_disparos,
      'performanceAtendentes', COALESCE(v_atendentes, '[]'::jsonb)
    );
  END;
  $$;
  GRANT EXECUTE ON FUNCTION public.get_dashboard(UUID, TIMESTAMPTZ, TIMESTAMPTZ, BIGINT[], BIGINT) TO authenticated, anon;

  -- get_chat_overview: payload único para sidebar do chat (contagens + lista paginada + última mensagem)
  CREATE OR REPLACE FUNCTION public.get_chat_overview(
    p_conta_id UUID,
    p_status TEXT DEFAULT 'aberto',
    p_limit INTEGER DEFAULT 20,
    p_offset INTEGER DEFAULT 0,
    p_conexao_ids BIGINT[] DEFAULT NULL,
    p_contato_ids BIGINT[] DEFAULT NULL,
    p_search TEXT DEFAULT NULL
  )
  RETURNS JSONB
  LANGUAGE plpgsql
  STABLE
  SECURITY INVOKER
  SET search_path = public
  AS $$
  DECLARE
    v_status TEXT := LOWER(TRIM(COALESCE(p_status, 'aberto')));
    v_limit INTEGER := GREATEST(1, LEAST(COALESCE(p_limit, 20), 200));
    v_offset INTEGER := GREATEST(0, COALESCE(p_offset, 0));
    v_search TEXT := NULLIF(TRIM(COALESCE(p_search, '')), '');
    v_aberto BIGINT := 0;
    v_aguardando BIGINT := 0;
    v_fechado BIGINT := 0;
    v_agente_ia BIGINT := 0;
    v_total_filtered BIGINT := 0;
    v_next_offset INTEGER := 0;
    v_has_more BOOLEAN := false;
    v_items JSONB := '[]'::jsonb;
  BEGIN
    IF p_conta_id IS NULL THEN
      RETURN jsonb_build_object(
        'counts', jsonb_build_object('aberto', 0, 'aguardando', 0, 'fechado', 0, 'agente_ia', 0),
        'total_filtered', 0,
        'next_offset', 0,
        'has_more', false,
        'conversations', '[]'::jsonb
      );
    END IF;

    -- Em chamadas via app (JWT presente), valida acesso à conta.
    -- Em execução administrativa sem JWT (ex.: SQL Editor), permite inspeção.
    IF auth.uid() IS NOT NULL
      AND NOT (public.can_access_conta(p_conta_id) OR public.is_super_admin()) THEN
      RETURN jsonb_build_object(
        'counts', jsonb_build_object('aberto', 0, 'aguardando', 0, 'fechado', 0, 'agente_ia', 0),
        'total_filtered', 0,
        'next_offset', 0,
        'has_more', false,
        'conversations', '[]'::jsonb
      );
    END IF;

    WITH base AS (
      SELECT
        c.*,
        cx."NomeConexao" AS conexao_nome,
        cx."Telefone" AS conexao_telefone,
        cx."idAgente" AS conexao_id_agente,
        c."idAgente" AS conversa_id_agente,
        ag.id AS agente_id,
        ag.nome AS agente_nome,
        ag."pausarAtendimento" AS agente_pausar,
        ag.ativo AS agente_ativo,
        ct.nome AS contato_nome,
        au.nome AS atendente_nome
      FROM public."SAAS_Conversas_Agentes" c
      LEFT JOIN public."SAAS_Conexões" cx ON cx.id = c."idConexao"
      LEFT JOIN public."SAAS_AgentesIA" ag ON ag.id = c."idAgente"
      LEFT JOIN public."SAAS_Contatos" ct ON ct.id = c."contatoId"
      LEFT JOIN public."SAAS_Usuarios" au ON au.id = c.atendente
      WHERE c."contaId" = p_conta_id
        AND (
          p_conexao_ids IS NULL
          OR cardinality(p_conexao_ids) = 0
          OR c."idConexao" = ANY(p_conexao_ids)
        )
        AND (
          p_contato_ids IS NULL
          OR cardinality(p_contato_ids) = 0
          OR c."contatoId" = ANY(p_contato_ids)
        )
        AND (
          v_search IS NULL
          OR c.telefone ILIKE ('%' || v_search || '%')
          OR COALESCE(ct.nome, '') ILIKE ('%' || v_search || '%')
        )
    ),
    flagged AS (
      SELECT
        b.*,
        (LOWER(TRIM(COALESCE(b."statusAtendimento", ''))) = 'aberto') AS is_aberto,
        (LOWER(TRIM(COALESCE(b."statusAtendimento", ''))) = 'fechado') AS is_fechado,
        (LOWER(TRIM(COALESCE(b."statusAtendimento", ''))) = 'aguardando') AS is_aguardando,
        (b.conversa_id_agente IS NOT NULL AND LOWER(TRIM(COALESCE(b."statusAtendimento", ''))) <> 'aberto') AS is_agente_ia
      FROM base b
    ),
    filtered AS (
      SELECT *
      FROM flagged f
      WHERE (
        (v_status = 'aberto' AND f.is_aberto AND NOT f.is_agente_ia)
        OR (v_status = 'fechado' AND f.is_fechado)
        OR (v_status = 'agente-ia' AND f.is_agente_ia)
        OR (v_status = 'aguardando' AND f.is_aguardando AND NOT f.is_agente_ia)
        OR (v_status NOT IN ('aberto', 'fechado', 'aguardando', 'agente-ia'))
      )
    ),
    enriched AS (
      SELECT
        f.*,
        lm.mensagem AS last_message_text,
        lm."tipoMensagem" AS last_message_tipo,
        lm.created_at AS last_message_created_at,
        lm."fromMe" AS last_message_from_me,
        COALESCE(lm.created_at, f."ultimaMensagem", f.created_at) AS sort_time
      FROM filtered f
      LEFT JOIN LATERAL (
        SELECT m.mensagem, m."tipoMensagem", m.created_at, m."fromMe"
        FROM public."SAAS_Mensagens" m
        WHERE m."conversaId" = f.id
          AND m.apagada = false
        ORDER BY m.created_at DESC, m.id DESC
        LIMIT 1
      ) lm ON true
    ),
    paged AS (
      SELECT *
      FROM enriched
      ORDER BY sort_time DESC NULLS LAST, id DESC
      LIMIT v_limit
      OFFSET v_offset
    )
    SELECT
      COALESCE(SUM(CASE WHEN is_aberto AND NOT is_agente_ia THEN 1 ELSE 0 END), 0),
      COALESCE(SUM(CASE WHEN is_aguardando AND NOT is_agente_ia THEN 1 ELSE 0 END), 0),
      COALESCE(SUM(CASE WHEN is_fechado THEN 1 ELSE 0 END), 0),
      COALESCE(SUM(CASE WHEN is_agente_ia THEN 1 ELSE 0 END), 0)
    INTO v_aberto, v_aguardando, v_fechado, v_agente_ia
    FROM flagged;

    WITH base AS (
      SELECT
        c.*,
        cx."NomeConexao" AS conexao_nome,
        cx."Telefone" AS conexao_telefone,
        cx."idAgente" AS conexao_id_agente,
        c."idAgente" AS conversa_id_agente,
        ag.id AS agente_id,
        ag.nome AS agente_nome,
        ag."pausarAtendimento" AS agente_pausar,
        ag.ativo AS agente_ativo,
        ct.nome AS contato_nome,
        au.nome AS atendente_nome
      FROM public."SAAS_Conversas_Agentes" c
      LEFT JOIN public."SAAS_Conexões" cx ON cx.id = c."idConexao"
      LEFT JOIN public."SAAS_AgentesIA" ag ON ag.id = c."idAgente"
      LEFT JOIN public."SAAS_Contatos" ct ON ct.id = c."contatoId"
      LEFT JOIN public."SAAS_Usuarios" au ON au.id = c.atendente
      WHERE c."contaId" = p_conta_id
        AND (
          p_conexao_ids IS NULL
          OR cardinality(p_conexao_ids) = 0
          OR c."idConexao" = ANY(p_conexao_ids)
        )
        AND (
          p_contato_ids IS NULL
          OR cardinality(p_contato_ids) = 0
          OR c."contatoId" = ANY(p_contato_ids)
        )
        AND (
          v_search IS NULL
          OR c.telefone ILIKE ('%' || v_search || '%')
          OR COALESCE(ct.nome, '') ILIKE ('%' || v_search || '%')
        )
    ),
    flagged AS (
      SELECT
        b.*,
        (LOWER(TRIM(COALESCE(b."statusAtendimento", ''))) = 'aberto') AS is_aberto,
        (LOWER(TRIM(COALESCE(b."statusAtendimento", ''))) = 'fechado') AS is_fechado,
        (LOWER(TRIM(COALESCE(b."statusAtendimento", ''))) = 'aguardando') AS is_aguardando,
        (b.conversa_id_agente IS NOT NULL AND LOWER(TRIM(COALESCE(b."statusAtendimento", ''))) <> 'aberto') AS is_agente_ia
      FROM base b
    ),
    filtered AS (
      SELECT *
      FROM flagged f
      WHERE (
        (v_status = 'aberto' AND f.is_aberto AND NOT f.is_agente_ia)
        OR (v_status = 'fechado' AND f.is_fechado)
        OR (v_status = 'agente-ia' AND f.is_agente_ia)
        OR (v_status = 'aguardando' AND f.is_aguardando AND NOT f.is_agente_ia)
        OR (v_status NOT IN ('aberto', 'fechado', 'aguardando', 'agente-ia'))
      )
    )
    SELECT COUNT(*) INTO v_total_filtered FROM filtered;
    v_next_offset := LEAST(v_offset::BIGINT + v_limit, 2147483647)::INTEGER;
    v_has_more := v_next_offset < v_total_filtered;
    IF NOT v_has_more THEN
      v_next_offset := v_total_filtered::INTEGER;
    END IF;

    WITH base AS (
      SELECT
        c.*,
        cx."NomeConexao" AS conexao_nome,
        cx."Telefone" AS conexao_telefone,
        cx."idAgente" AS conexao_id_agente,
        c."idAgente" AS conversa_id_agente,
        ag.id AS agente_id,
        ag.nome AS agente_nome,
        ag."pausarAtendimento" AS agente_pausar,
        ag.ativo AS agente_ativo,
        ct.nome AS contato_nome,
        au.nome AS atendente_nome
      FROM public."SAAS_Conversas_Agentes" c
      LEFT JOIN public."SAAS_Conexões" cx ON cx.id = c."idConexao"
      LEFT JOIN public."SAAS_AgentesIA" ag ON ag.id = c."idAgente"
      LEFT JOIN public."SAAS_Contatos" ct ON ct.id = c."contatoId"
      LEFT JOIN public."SAAS_Usuarios" au ON au.id = c.atendente
      WHERE c."contaId" = p_conta_id
        AND (
          p_conexao_ids IS NULL
          OR cardinality(p_conexao_ids) = 0
          OR c."idConexao" = ANY(p_conexao_ids)
        )
        AND (
          p_contato_ids IS NULL
          OR cardinality(p_contato_ids) = 0
          OR c."contatoId" = ANY(p_contato_ids)
        )
        AND (
          v_search IS NULL
          OR c.telefone ILIKE ('%' || v_search || '%')
          OR COALESCE(ct.nome, '') ILIKE ('%' || v_search || '%')
        )
    ),
    flagged AS (
      SELECT
        b.*,
        (LOWER(TRIM(COALESCE(b."statusAtendimento", ''))) = 'aberto') AS is_aberto,
        (LOWER(TRIM(COALESCE(b."statusAtendimento", ''))) = 'fechado') AS is_fechado,
        (LOWER(TRIM(COALESCE(b."statusAtendimento", ''))) = 'aguardando') AS is_aguardando,
        (b.conversa_id_agente IS NOT NULL AND LOWER(TRIM(COALESCE(b."statusAtendimento", ''))) <> 'aberto') AS is_agente_ia
      FROM base b
    ),
    filtered AS (
      SELECT *
      FROM flagged f
      WHERE (
        (v_status = 'aberto' AND f.is_aberto AND NOT f.is_agente_ia)
        OR (v_status = 'fechado' AND f.is_fechado)
        OR (v_status = 'agente-ia' AND f.is_agente_ia)
        OR (v_status = 'aguardando' AND f.is_aguardando AND NOT f.is_agente_ia)
        OR (v_status NOT IN ('aberto', 'fechado', 'aguardando', 'agente-ia'))
      )
    ),
    enriched AS (
      SELECT
        f.*,
        lm.mensagem AS last_message_text,
        lm."tipoMensagem" AS last_message_tipo,
        lm.created_at AS last_message_created_at,
        lm."fromMe" AS last_message_from_me,
        COALESCE(lm.created_at, f."ultimaMensagem", f.created_at) AS sort_time
      FROM filtered f
      LEFT JOIN LATERAL (
        SELECT m.mensagem, m."tipoMensagem", m.created_at, m."fromMe"
        FROM public."SAAS_Mensagens" m
        WHERE m."conversaId" = f.id
          AND m.apagada = false
        ORDER BY m.created_at DESC, m.id DESC
        LIMIT 1
      ) lm ON true
    ),
    paged AS (
      SELECT *
      FROM enriched
      ORDER BY sort_time DESC NULLS LAST, id DESC
      LIMIT v_limit
      OFFSET v_offset
    )
    SELECT COALESCE(
      jsonb_agg(
        (
          to_jsonb(p) - 'is_aberto' - 'is_fechado' - 'is_aguardando' - 'is_agente_ia'
          || jsonb_build_object(
            'contato', jsonb_build_object('nome', p.contato_nome),
            'atendente_usuario', jsonb_build_object('nome', p.atendente_nome),
            'idAgente', p.conversa_id_agente,
            'SAAS_AgentesIA', jsonb_build_object(
              'id', p.agente_id,
              'nome', p.agente_nome,
              'pausarAtendimento', p.agente_pausar,
              'ativo', p.agente_ativo
            ),
            'SAAS_Conexões', jsonb_build_object(
              'idAgente', p.conexao_id_agente,
              'NomeConexao', p.conexao_nome,
              'Telefone', p.conexao_telefone
            ),
            'ultimaMensagemTexto', p.last_message_text,
            'ultimaMensagemTipo', p.last_message_tipo,
            'ultimaMensagemData', p.last_message_created_at,
            'ultimaMensagemFromMe', p.last_message_from_me
          )
        )
        ORDER BY p.sort_time DESC NULLS LAST, p.id DESC
      ),
      '[]'::jsonb
    ) INTO v_items
    FROM paged p;

    RETURN jsonb_build_object(
      'counts', jsonb_build_object(
        'aberto', v_aberto,
        'aguardando', v_aguardando,
        'fechado', v_fechado,
        'agente_ia', v_agente_ia
      ),
      'total_filtered', v_total_filtered,
      'next_offset', v_next_offset,
      'has_more', v_has_more,
      'conversations', v_items
    );
  END;
  $$;
  GRANT EXECUTE ON FUNCTION public.get_chat_overview(UUID, TEXT, INTEGER, INTEGER, BIGINT[], BIGINT[], TEXT) TO authenticated;

  -- Versao otimizada: materializa candidatos uma vez e consulta mensagens apenas apos paginar.
  -- SECURITY INVOKER: a lista e as contagens seguem a RLS de SAAS_Conversas_Agentes
  -- (membro vê só as conversas dele, as do setor dele sem atendente e as sem setor e sem atendente).
  CREATE OR REPLACE FUNCTION public.get_chat_overview(
    p_conta_id UUID,
    p_status TEXT DEFAULT 'aberto',
    p_limit INTEGER DEFAULT 20,
    p_offset INTEGER DEFAULT 0,
    p_conexao_ids BIGINT[] DEFAULT NULL,
    p_contato_ids BIGINT[] DEFAULT NULL,
    p_search TEXT DEFAULT NULL
  )
  RETURNS JSONB
  LANGUAGE plpgsql
  STABLE
  SECURITY INVOKER
  SET search_path = public
  AS $$
  DECLARE
    v_status TEXT := LOWER(TRIM(COALESCE(p_status, 'aberto')));
    v_limit INTEGER := GREATEST(1, LEAST(COALESCE(p_limit, 20), 200));
    v_offset INTEGER := GREATEST(0, COALESCE(p_offset, 0));
    v_search TEXT := NULLIF(TRIM(COALESCE(p_search, '')), '');
    v_aberto BIGINT := 0;
    v_aguardando BIGINT := 0;
    v_fechado BIGINT := 0;
    v_agente_ia BIGINT := 0;
    v_total_filtered BIGINT := 0;
    v_next_offset INTEGER := 0;
    v_has_more BOOLEAN := false;
    v_items JSONB := '[]'::jsonb;
  BEGIN
    IF p_conta_id IS NULL THEN
      RETURN jsonb_build_object(
        'counts', jsonb_build_object('aberto', 0, 'aguardando', 0, 'fechado', 0, 'agente_ia', 0),
        'total_filtered', 0,
        'next_offset', 0,
        'has_more', false,
        'conversations', '[]'::jsonb
      );
    END IF;

    IF auth.uid() IS NOT NULL
      AND NOT (public.can_access_conta(p_conta_id) OR public.is_super_admin()) THEN
      RETURN jsonb_build_object(
        'counts', jsonb_build_object('aberto', 0, 'aguardando', 0, 'fechado', 0, 'agente_ia', 0),
        'total_filtered', 0,
        'next_offset', 0,
        'has_more', false,
        'conversations', '[]'::jsonb
      );
    END IF;

    WITH candidate AS MATERIALIZED (
      SELECT
        c.*,
        (LOWER(TRIM(COALESCE(c."statusAtendimento", ''))) = 'aberto') AS is_aberto,
        (LOWER(TRIM(COALESCE(c."statusAtendimento", ''))) = 'fechado') AS is_fechado,
        (LOWER(TRIM(COALESCE(c."statusAtendimento", ''))) = 'aguardando') AS is_aguardando,
        (
          c."idAgente" IS NOT NULL
          AND LOWER(TRIM(COALESCE(c."statusAtendimento", ''))) <> 'aberto'
        ) AS is_agente_ia
      FROM public."SAAS_Conversas_Agentes" c
      LEFT JOIN public."SAAS_Contatos" search_ct
        ON search_ct.id = c."contatoId"
       AND v_search IS NOT NULL
      WHERE c."contaId" = p_conta_id
        AND (
          p_conexao_ids IS NULL
          OR cardinality(p_conexao_ids) = 0
          OR c."idConexao" = ANY(p_conexao_ids)
        )
        AND (
          p_contato_ids IS NULL
          OR cardinality(p_contato_ids) = 0
          OR c."contatoId" = ANY(p_contato_ids)
        )
        AND (
          v_search IS NULL
          OR c.telefone ILIKE ('%' || v_search || '%')
          OR search_ct.nome ILIKE ('%' || v_search || '%')
        )
    ),
    filtered AS MATERIALIZED (
      SELECT *
      FROM candidate c
      WHERE
        (v_status = 'aberto' AND c.is_aberto AND NOT c.is_agente_ia)
        OR (v_status = 'fechado' AND c.is_fechado)
        OR (v_status = 'agente-ia' AND c.is_agente_ia)
        OR (v_status = 'aguardando' AND c.is_aguardando AND NOT c.is_agente_ia)
        OR (v_status NOT IN ('aberto', 'fechado', 'aguardando', 'agente-ia'))
    ),
    stats AS (
      SELECT
        COALESCE(SUM(CASE WHEN is_aberto AND NOT is_agente_ia THEN 1 ELSE 0 END), 0)::BIGINT AS aberto,
        COALESCE(SUM(CASE WHEN is_aguardando AND NOT is_agente_ia THEN 1 ELSE 0 END), 0)::BIGINT AS aguardando,
        COALESCE(SUM(CASE WHEN is_fechado THEN 1 ELSE 0 END), 0)::BIGINT AS fechado,
        COALESCE(SUM(CASE WHEN is_agente_ia THEN 1 ELSE 0 END), 0)::BIGINT AS agente_ia
      FROM candidate
    ),
    filtered_stats AS (
      SELECT COUNT(*)::BIGINT AS total_filtered FROM filtered
    ),
    paged AS MATERIALIZED (
      SELECT
        f.*,
        COALESCE(f."ultimaMensagem", f.created_at) AS page_sort_time
      FROM filtered f
      ORDER BY COALESCE(f."ultimaMensagem", f.created_at) DESC NULLS LAST, f.id DESC
      LIMIT v_limit
      OFFSET v_offset
    ),
    enriched AS (
      SELECT
        p.*,
        cx."NomeConexao" AS conexao_nome,
        cx."Telefone" AS conexao_telefone,
        cx."idAgente" AS conexao_id_agente,
        p."idAgente" AS conversa_id_agente,
        ag.id AS agente_id,
        ag.nome AS agente_nome,
        ag."pausarAtendimento" AS agente_pausar,
        ag.ativo AS agente_ativo,
        ct.nome AS contato_nome,
        au.nome AS atendente_nome,
        lm.mensagem AS last_message_text,
        lm."tipoMensagem" AS last_message_tipo,
        lm.created_at AS last_message_created_at,
        lm."fromMe" AS last_message_from_me,
        COALESCE(lm.created_at, p."ultimaMensagem", p.created_at) AS sort_time
      FROM paged p
      LEFT JOIN public."SAAS_Conexões" cx ON cx.id = p."idConexao"
      LEFT JOIN public."SAAS_AgentesIA" ag ON ag.id = p."idAgente"
      LEFT JOIN public."SAAS_Contatos" ct ON ct.id = p."contatoId"
      LEFT JOIN public."SAAS_Usuarios" au ON au.id = p.atendente
      LEFT JOIN LATERAL (
        SELECT m.mensagem, m."tipoMensagem", m.created_at, m."fromMe"
        FROM public."SAAS_Mensagens" m
        WHERE m."conversaId" = p.id
          AND m.apagada = false
        ORDER BY m.created_at DESC, m.id DESC
        LIMIT 1
      ) lm ON true
    ),
    payload AS (
      SELECT COALESCE(
        jsonb_agg(
          (
            to_jsonb(e)
            - 'is_aberto' - 'is_fechado' - 'is_aguardando' - 'is_agente_ia' - 'page_sort_time'
            || jsonb_build_object(
              'contato', jsonb_build_object('nome', e.contato_nome),
              'atendente_usuario', jsonb_build_object('nome', e.atendente_nome),
              'idAgente', e.conversa_id_agente,
              'SAAS_AgentesIA', jsonb_build_object(
                'id', e.agente_id,
                'nome', e.agente_nome,
                'pausarAtendimento', e.agente_pausar,
                'ativo', e.agente_ativo
              ),
              'SAAS_Conexões', jsonb_build_object(
                'idAgente', e.conexao_id_agente,
                'NomeConexao', e.conexao_nome,
                'Telefone', e.conexao_telefone
              ),
              'ultimaMensagemTexto', e.last_message_text,
              'ultimaMensagemTipo', e.last_message_tipo,
              'ultimaMensagemData', e.last_message_created_at,
              'ultimaMensagemFromMe', e.last_message_from_me
            )
          )
          ORDER BY e.page_sort_time DESC NULLS LAST, e.id DESC
        ),
        '[]'::jsonb
      ) AS items
      FROM enriched e
    )
    SELECT
      s.aberto,
      s.aguardando,
      s.fechado,
      s.agente_ia,
      fs.total_filtered,
      p.items
    INTO
      v_aberto,
      v_aguardando,
      v_fechado,
      v_agente_ia,
      v_total_filtered,
      v_items
    FROM stats s
    CROSS JOIN filtered_stats fs
    CROSS JOIN payload p;

    v_next_offset := LEAST(v_offset::BIGINT + v_limit, 2147483647)::INTEGER;
    v_has_more := v_next_offset < v_total_filtered;
    IF NOT v_has_more THEN
      v_next_offset := LEAST(v_total_filtered, 2147483647)::INTEGER;
    END IF;

    RETURN jsonb_build_object(
      'counts', jsonb_build_object(
        'aberto', v_aberto,
        'aguardando', v_aguardando,
        'fechado', v_fechado,
        'agente_ia', v_agente_ia
      ),
      'total_filtered', v_total_filtered,
      'next_offset', v_next_offset,
      'has_more', v_has_more,
      'conversations', v_items
    );
  END;
  $$;

  -- Retorna uma única mensagem ativa por conversa para as listas e filtros do chat.
  -- SECURITY INVOKER mantém as policies RLS de SAAS_Mensagens ativas.
  CREATE OR REPLACE FUNCTION public.get_chat_latest_messages(p_conversa_ids BIGINT[])
  RETURNS TABLE ("conversaId" BIGINT, mensagem TEXT, "tipoMensagem" TEXT, created_at TIMESTAMPTZ, "fromMe" BOOLEAN)
  LANGUAGE sql STABLE SECURITY INVOKER
  SET search_path = public
  AS $$
    SELECT ids.id, m.mensagem, m."tipoMensagem", m.created_at, m."fromMe"
    FROM (SELECT DISTINCT id FROM unnest(p_conversa_ids) AS input(id)) ids
    CROSS JOIN LATERAL (
      SELECT m.mensagem, m."tipoMensagem", m.created_at, m."fromMe"
      FROM public."SAAS_Mensagens" m
      WHERE m."conversaId" = ids.id AND m.apagada = false
      ORDER BY m.created_at DESC, m.id DESC
      LIMIT 1
    ) m;
  $$;
  REVOKE ALL ON FUNCTION public.get_chat_latest_messages(BIGINT[]) FROM PUBLIC, anon;
  GRANT EXECUTE ON FUNCTION public.get_chat_latest_messages(BIGINT[]) TO authenticated;

  -- get_dashboard_crm: p_user_id = contaId (igual get_dashboard)
  CREATE OR REPLACE FUNCTION public.get_dashboard_crm(p_user_id UUID, p_quadro_id BIGINT DEFAULT NULL)
  RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path = public AS $$
  DECLARE v_quadro_id BIGINT; v_etapas JSONB; v_conversao TEXT; v_valor_fechado TEXT;
  BEGIN
    v_quadro_id := p_quadro_id;
    IF v_quadro_id IS NULL THEN SELECT id INTO v_quadro_id FROM public."SAAS_Quadros" WHERE "contaId" = p_user_id ORDER BY id LIMIT 1; END IF;

    IF v_quadro_id IS NOT NULL THEN
      WITH primeira AS (SELECT COUNT(*) AS total FROM public."SAAS_Cards_Quadros" c INNER JOIN public."SAAS_Etapas_Quadros" e ON e.id = c."etapaQuadroId" AND e."quadroId" = v_quadro_id WHERE c."quadroId" = v_quadro_id AND e.ordem = (SELECT MIN(ordem) FROM public."SAAS_Etapas_Quadros" WHERE "quadroId" = v_quadro_id)),
          por_etapa AS (SELECT e.nome, e.ordem, COUNT(c.id) AS qtd FROM public."SAAS_Etapas_Quadros" e LEFT JOIN public."SAAS_Cards_Quadros" c ON c."etapaQuadroId" = e.id AND c."quadroId" = e."quadroId" WHERE e."quadroId" = v_quadro_id GROUP BY e.id, e.nome, e.ordem)
      SELECT jsonb_agg(jsonb_build_object('nome', pe.nome, 'quantidade', pe.qtd, 'percentual', CASE WHEN prim.total > 0 THEN ROUND((pe.qtd::numeric / prim.total * 100)::numeric, 0) ELSE 0 END) ORDER BY pe.ordem) INTO v_etapas FROM por_etapa pe CROSS JOIN primeira prim;

      WITH ordens AS (SELECT ordem FROM public."SAAS_Etapas_Quadros" WHERE "quadroId" = v_quadro_id ORDER BY ordem),
          primeira_qtd AS (SELECT COUNT(c.id) AS q FROM public."SAAS_Cards_Quadros" c INNER JOIN public."SAAS_Etapas_Quadros" e ON e.id = c."etapaQuadroId" WHERE e."quadroId" = v_quadro_id AND e.ordem = (SELECT MIN(ordem) FROM ordens)),
          ultima_qtd AS (SELECT COUNT(c.id) AS q FROM public."SAAS_Cards_Quadros" c INNER JOIN public."SAAS_Etapas_Quadros" e ON e.id = c."etapaQuadroId" WHERE e."quadroId" = v_quadro_id AND e.ordem = (SELECT MAX(ordem) FROM ordens))
      SELECT TRIM(ROUND((u.q::numeric / NULLIF(p.q, 0) * 100)::numeric, 0)::text) || '%' INTO v_conversao FROM ultima_qtd u, primeira_qtd p;

      SELECT 'R$ ' || TRIM(TO_CHAR(COALESCE(SUM(c.valor), 0), 'FM999G999G990D00')) INTO v_valor_fechado
      FROM public."SAAS_Cards_Quadros" c INNER JOIN public."SAAS_Etapas_Quadros" e ON e.id = c."etapaQuadroId"
      WHERE e."quadroId" = v_quadro_id AND e."tipoEtapa" = 'venda';

      RETURN jsonb_build_object('etapas', COALESCE(v_etapas, '[]'::jsonb), 'conversaoTotal', COALESCE(v_conversao, '0%'), 'valorFechado', COALESCE(v_valor_fechado, 'R$ 0'));
    ELSE
      RETURN jsonb_build_object('etapas', '[]'::jsonb, 'conversaoTotal', '0%', 'valorFechado', 'R$ 0');
    END IF;
  END;
  $$;
  GRANT EXECUTE ON FUNCTION public.get_dashboard_crm(UUID, BIGINT) TO authenticated, anon;

  -- Gráficos do dashboard: vendas (etapa venda) e agendamentos (etapa agendamento)
  -- Contam os cards que entraram na etapa dentro do período (data da entrada no historicoCRM);
  -- porDia agrupa pela mesma data.
  CREATE OR REPLACE FUNCTION public.get_dashboard_vendas(
    p_user_id UUID,
    p_data_inicial TIMESTAMPTZ,
    p_data_final TIMESTAMPTZ,
    p_quadro_id BIGINT DEFAULT NULL
  )
  RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
  DECLARE
    v_valor DOUBLE PRECISION; v_qtd BIGINT; v_por_dia JSONB;
  BEGIN
    IF NOT (public.can_access_conta(p_user_id) OR public.is_super_admin()) THEN
      RETURN jsonb_build_object('valorTotal', 0, 'quantidade', 0, 'porDia', '[]'::jsonb);
    END IF;

    -- Vendas / faturamento: cards em etapa tipo "venda" que entraram nela dentro do período
    WITH vendas AS (
      SELECT c.valor,
        public.f_crm_card_entrada_etapa(c."historicoCRM", c."etapaQuadroId", c.created_at) AS entrou_em
      FROM public."SAAS_Cards_Quadros" c
      INNER JOIN public."SAAS_Etapas_Quadros" e ON e.id = c."etapaQuadroId"
      INNER JOIN public."SAAS_Quadros" q ON q.id = c."quadroId"
      WHERE q."contaId" = p_user_id
        AND LOWER(TRIM(COALESCE(e."tipoEtapa", ''))) = 'venda'
        AND (p_quadro_id IS NULL OR c."quadroId" = p_quadro_id)
    ), no_periodo AS (
      SELECT valor, (entrou_em AT TIME ZONE 'America/Sao_Paulo')::date AS d
      FROM vendas
      WHERE entrou_em >= p_data_inicial AND entrou_em <= p_data_final
    )
    SELECT
      (SELECT COALESCE(SUM(valor), 0) FROM no_periodo),
      (SELECT COUNT(*) FROM no_periodo),
      (SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'data', to_char(d, 'YYYY-MM-DD'),
        'dataFormatada', to_char(d, 'DD/MM'),
        'valor', COALESCE(valor, 0),
        'quantidade', COALESCE(qtd, 0)
      ) ORDER BY d), '[]'::jsonb)
      FROM (SELECT d, SUM(valor) AS valor, COUNT(*)::bigint AS qtd FROM no_periodo GROUP BY d) sub)
    INTO v_valor, v_qtd, v_por_dia;

    RETURN jsonb_build_object(
      'valorTotal', COALESCE(v_valor, 0),
      'quantidade', COALESCE(v_qtd, 0),
      'porDia', COALESCE(v_por_dia, '[]'::jsonb)
    );
  END;
  $$;
  GRANT EXECUTE ON FUNCTION public.get_dashboard_vendas(UUID, TIMESTAMPTZ, TIMESTAMPTZ, BIGINT) TO authenticated, anon;

  CREATE OR REPLACE FUNCTION public.get_dashboard_agendamentos(
    p_user_id UUID,
    p_data_inicial TIMESTAMPTZ,
    p_data_final TIMESTAMPTZ,
    p_quadro_id BIGINT DEFAULT NULL
  )
  RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
  DECLARE v_qtd BIGINT; v_por_dia JSONB;
  BEGIN
    IF NOT (public.can_access_conta(p_user_id) OR public.is_super_admin()) THEN
      RETURN jsonb_build_object('quantidadeTotal', 0, 'porDia', '[]'::jsonb);
    END IF;

    -- Agendamentos: cards em etapa tipo "agendamento" que entraram nela dentro do período
    WITH agend AS (
      SELECT public.f_crm_card_entrada_etapa(c."historicoCRM", c."etapaQuadroId", c.created_at) AS entrou_em
      FROM public."SAAS_Cards_Quadros" c
      INNER JOIN public."SAAS_Etapas_Quadros" e ON e.id = c."etapaQuadroId"
      INNER JOIN public."SAAS_Quadros" q ON q.id = c."quadroId"
      WHERE q."contaId" = p_user_id
        AND LOWER(TRIM(COALESCE(e."tipoEtapa", ''))) = 'agendamento'
        AND (p_quadro_id IS NULL OR c."quadroId" = p_quadro_id)
    ), no_periodo AS (
      SELECT (entrou_em AT TIME ZONE 'America/Sao_Paulo')::date AS d
      FROM agend
      WHERE entrou_em >= p_data_inicial AND entrou_em <= p_data_final
    )
    SELECT
      (SELECT COUNT(*) FROM no_periodo),
      (SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'data', to_char(d, 'YYYY-MM-DD'),
        'dataFormatada', to_char(d, 'DD/MM'),
        'quantidade', COALESCE(qtd, 0)
      ) ORDER BY d), '[]'::jsonb)
      FROM (SELECT d, COUNT(*)::bigint AS qtd FROM no_periodo GROUP BY d) sub)
    INTO v_qtd, v_por_dia;

    RETURN jsonb_build_object(
      'quantidadeTotal', COALESCE(v_qtd, 0),
      'porDia', COALESCE(v_por_dia, '[]'::jsonb)
    );
  END;
  $$;
  GRANT EXECUTE ON FUNCTION public.get_dashboard_agendamentos(UUID, TIMESTAMPTZ, TIMESTAMPTZ, BIGINT) TO authenticated, anon;

  -- Resumo de métricas da página CRM (faturamento 30d, oportunidades, vendas e agendamentos)
  CREATE OR REPLACE FUNCTION public.get_crm_resumo_metricas(p_user_id UUID)
  RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
  DECLARE
    v_faturamento DOUBLE PRECISION;
    v_vendas_qtd BIGINT;
    v_agendamentos_qtd BIGINT;
    v_oportunidades BIGINT;
    v_ini TIMESTAMPTZ;
    v_fim TIMESTAMPTZ;
  BEGIN
    IF NOT (public.can_access_conta(p_user_id) OR public.is_super_admin()) THEN
      RETURN jsonb_build_object(
        'faturamento30d', 0,
        'quantidadeOportunidades', 0,
        'quantidadeVendas', 0,
        'quantidadeAgendamentos', 0
      );
    END IF;

    v_ini := (date_trunc('day', now() AT TIME ZONE 'America/Sao_Paulo') - interval '29 days') AT TIME ZONE 'America/Sao_Paulo';
    v_fim := ((date_trunc('day', now() AT TIME ZONE 'America/Sao_Paulo') + interval '1 day') AT TIME ZONE 'America/Sao_Paulo') - interval '1 microsecond';

    -- Vendas dos últimos 30 dias pela data em que o card entrou na etapa de venda
    SELECT COALESCE(SUM(v.valor), 0), COUNT(*)
    INTO v_faturamento, v_vendas_qtd
    FROM (
      SELECT c.valor, public.f_crm_card_entrada_etapa(c."historicoCRM", c."etapaQuadroId", c.created_at) AS entrou_em
      FROM public."SAAS_Cards_Quadros" c
      INNER JOIN public."SAAS_Etapas_Quadros" e ON e.id = c."etapaQuadroId"
      INNER JOIN public."SAAS_Quadros" q ON q.id = c."quadroId"
      WHERE q."contaId" = p_user_id
        AND e."tipoEtapa" = 'venda'
    ) v
    WHERE v.entrou_em >= v_ini AND v.entrou_em <= v_fim;

    SELECT COUNT(c.id) INTO v_agendamentos_qtd
    FROM public."SAAS_Cards_Quadros" c
    INNER JOIN public."SAAS_Etapas_Quadros" e ON e.id = c."etapaQuadroId"
    INNER JOIN public."SAAS_Quadros" q ON q.id = c."quadroId"
    WHERE q."contaId" = p_user_id
      AND e."tipoEtapa" = 'agendamento';

    SELECT COUNT(c.id) INTO v_oportunidades
    FROM public."SAAS_Cards_Quadros" c
    INNER JOIN public."SAAS_Etapas_Quadros" e ON e.id = c."etapaQuadroId"
    INNER JOIN public."SAAS_Quadros" q ON q.id = c."quadroId"
    WHERE q."contaId" = p_user_id
      AND (e."tipoEtapa" IS NULL OR e."tipoEtapa" NOT IN ('venda', 'perda', 'agendamento'));

    RETURN jsonb_build_object(
      'faturamento30d', COALESCE(v_faturamento, 0),
      'quantidadeOportunidades', COALESCE(v_oportunidades, 0),
      'quantidadeVendas', COALESCE(v_vendas_qtd, 0),
      'quantidadeAgendamentos', COALESCE(v_agendamentos_qtd, 0)
    );
  END;
  $$;
  GRANT EXECUTE ON FUNCTION public.get_crm_resumo_metricas(UUID) TO authenticated, anon;

  -- get_contatos_by_lista e get_grupos_by_lista: aliases para modelo etiquetas (idLista/SAAS_Grupos não existem mais)
  DROP FUNCTION IF EXISTS public.get_contatos_by_lista(bigint);
  DROP FUNCTION IF EXISTS public.get_grupos_by_lista(bigint);

  -- Criar get_contatos_by_etiqueta, get_grupos_by_etiqueta e aliases quando SAAS_Etiquetas existir
  DO $block$
  BEGIN
    IF to_regclass('public."SAAS_Etiquetas"') IS NOT NULL AND to_regclass('public."SAAS_Contatos_Etiquetas"') IS NOT NULL THEN
      CREATE OR REPLACE FUNCTION public.get_contatos_by_etiqueta(p_id_etiqueta bigint)
      RETURNS SETOF public."SAAS_Contatos" LANGUAGE sql STABLE AS $func$
        SELECT c.* FROM public."SAAS_Contatos" c JOIN public."SAAS_Contatos_Etiquetas" ce ON ce."contatoId" = c.id
        WHERE ce."etiquetaId" = p_id_etiqueta AND c.tipo = 'contato';
      $func$;
      CREATE OR REPLACE FUNCTION public.get_grupos_by_etiqueta(p_id_etiqueta bigint)
      RETURNS SETOF public."SAAS_Contatos" LANGUAGE sql STABLE AS $func$
        SELECT c.* FROM public."SAAS_Contatos" c JOIN public."SAAS_Contatos_Etiquetas" ce ON ce."contatoId" = c.id
        WHERE ce."etiquetaId" = p_id_etiqueta AND c.tipo = 'grupo';
      $func$;
      CREATE OR REPLACE FUNCTION public.get_contatos_by_lista(p_id bigint) RETURNS SETOF public."SAAS_Contatos" AS $func$ SELECT * FROM public.get_contatos_by_etiqueta(p_id); $func$ LANGUAGE sql STABLE;
      CREATE OR REPLACE FUNCTION public.get_grupos_by_lista(p_id bigint) RETURNS SETOF public."SAAS_Contatos" AS $func$ SELECT * FROM public.get_grupos_by_etiqueta(p_id); $func$ LANGUAGE sql STABLE;
    END IF;
  END$block$;

  -- Contas com plano (equivalente multi-tenant a f_usuarios_com_plano)
  DROP FUNCTION IF EXISTS public.f_contas_com_plano();
  CREATE OR REPLACE FUNCTION public.f_contas_com_plano()
  RETURNS TABLE (
    id UUID, created_at TIMESTAMPTZ, email TEXT, status BOOLEAN, "dataValidade" DATE,
    plano_id BIGINT, plano_nome TEXT, plano_preco REAL,
    "plano_qntConexoes" BIGINT, "plano_qntContatos" BIGINT, "plano_qntDisparos" BIGINT,
    "plano_qntQuadros" BIGINT, "plano_qntAgentesIa" BIGINT, "plano_qntCreditosIa" BIGINT
  ) LANGUAGE sql STABLE AS $$
    SELECT c.id, c.created_at, c.email, c.status, c."dataValidade",
      c.plano AS plano_id, p.nome AS plano_nome, p.preco AS plano_preco,
      p."qntConexoes" AS "plano_qntConexoes", p."qntContatos" AS "plano_qntContatos", p."qntDisparos" AS "plano_qntDisparos",
      p."qntQuadros" AS "plano_qntQuadros", p."qntAgentesIa" AS "plano_qntAgentesIa", p."qntCreditosIa" AS "plano_qntCreditosIa"
    FROM public."SAAS_Contas" c
    LEFT JOIN public."SAAS_Planos" p ON p.id = c.plano
    ORDER BY c.created_at DESC;
  $$;

  -- Reordenar etapas e cards de quadro
  CREATE OR REPLACE FUNCTION public.f_reordenar_etapas_quadro()
  RETURNS trigger LANGUAGE plpgsql AS $$
  DECLARE v_quadro_id bigint; v_old_pos smallint; v_new_pos smallint; v_flag text;
  BEGIN
    v_flag := current_setting('saas.reordering_etapas', true);
    IF v_flag = 'on' THEN RETURN NEW; END IF;
    IF NEW."quadroId" IS DISTINCT FROM OLD."quadroId" THEN RETURN NEW; END IF;
    IF NEW.ordem IS NULL OR OLD.ordem IS NULL THEN RETURN NEW; END IF;
    IF NEW.ordem = OLD.ordem THEN RETURN NEW; END IF;
    v_quadro_id := NEW."quadroId"; v_old_pos := OLD.ordem; v_new_pos := NEW.ordem;
    PERFORM set_config('saas.reordering_etapas', 'on', true);
    IF v_new_pos < v_old_pos THEN
      UPDATE public."SAAS_Etapas_Quadros" SET ordem = ordem + 1 WHERE "quadroId" = v_quadro_id AND id <> NEW.id AND ordem >= v_new_pos AND ordem < v_old_pos;
    ELSIF v_new_pos > v_old_pos THEN
      UPDATE public."SAAS_Etapas_Quadros" SET ordem = ordem - 1 WHERE "quadroId" = v_quadro_id AND id <> NEW.id AND ordem <= v_new_pos AND ordem > v_old_pos;
    END IF;
    PERFORM set_config('saas.reordering_etapas', 'off', true);
    RETURN NEW;
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_reordenar_cards_quadro()
  RETURNS trigger LANGUAGE plpgsql AS $$
  DECLARE v_quadro_id bigint; v_etapa_id bigint; v_old_pos smallint; v_new_pos smallint; v_flag text;
  BEGIN
    v_flag := current_setting('saas.reordering_cards', true);
    IF v_flag = 'on' THEN RETURN NEW; END IF;
    IF NEW."quadroId" IS DISTINCT FROM OLD."quadroId" OR NEW."etapaQuadroId" IS DISTINCT FROM OLD."etapaQuadroId" THEN RETURN NEW; END IF;
    IF NEW.ordem IS NULL OR OLD.ordem IS NULL THEN RETURN NEW; END IF;
    IF NEW.ordem = OLD.ordem THEN RETURN NEW; END IF;
    v_quadro_id := NEW."quadroId"; v_etapa_id := NEW."etapaQuadroId"; v_old_pos := OLD.ordem; v_new_pos := NEW.ordem;
    PERFORM set_config('saas.reordering_cards', 'on', true);
    IF v_new_pos < v_old_pos THEN
      UPDATE public."SAAS_Cards_Quadros" SET ordem = ordem + 1 WHERE "quadroId" = v_quadro_id AND "etapaQuadroId" = v_etapa_id AND id <> NEW.id AND ordem >= v_new_pos AND ordem < v_old_pos;
    ELSIF v_new_pos > v_old_pos THEN
      UPDATE public."SAAS_Cards_Quadros" SET ordem = ordem - 1 WHERE "quadroId" = v_quadro_id AND "etapaQuadroId" = v_etapa_id AND id <> NEW.id AND ordem <= v_new_pos AND ordem > v_old_pos;
    END IF;
    PERFORM set_config('saas.reordering_cards', 'off', true);
    RETURN NEW;
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_resetar_creditos_agentes_mes()
  RETURNS void LANGUAGE plpgsql AS $$
  BEGIN
    -- creditosGasto foi removido do modelo; saldo de créditos é mantido em SAAS_Contas.tokens
    RETURN;
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_sync_pausado_status_atendimento()
  RETURNS trigger LANGUAGE plpgsql AS $$
  BEGIN
    IF LOWER(TRIM(COALESCE(NEW."statusAtendimento", ''))) = 'aberto' THEN NEW.pausado := TRUE; ELSE NEW.pausado := FALSE; END IF;
    RETURN NEW;
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_set_data_fechamento_conversa()
  RETURNS trigger LANGUAGE plpgsql AS $$
  BEGIN
    IF LOWER(TRIM(COALESCE(NEW."statusAtendimento", ''))) = 'fechado' THEN
      NEW."dataFechamento" := COALESCE(NEW."dataFechamento", now());
      NEW."idAgente" := NULL;
    ELSE
      NEW."dataFechamento" := NULL;
    END IF;
    RETURN NEW;
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_pausar_atendimento_por_mensagem(p_mensagem_id BIGINT)
  RETURNS void LANGUAGE plpgsql AS $$
  DECLARE v_conversa_id BIGINT; v_conexao_id BIGINT; v_agente_id BIGINT; v_pausar BOOLEAN;
  BEGIN
    SELECT m."conversaId" INTO v_conversa_id FROM public."SAAS_Mensagens" m WHERE m.id = p_mensagem_id;
    IF v_conversa_id IS NULL THEN RETURN; END IF;
    SELECT c."idConexao" INTO v_conexao_id FROM public."SAAS_Conversas_Agentes" c WHERE c.id = v_conversa_id;
    IF v_conexao_id IS NULL THEN RETURN; END IF;
    SELECT c."idAgente" INTO v_agente_id FROM public."SAAS_Conversas_Agentes" c WHERE c.id = v_conversa_id;
    IF v_agente_id IS NULL THEN
      UPDATE public."SAAS_Conversas_Agentes" SET "statusAtendimento" = 'aberto', pausado = TRUE WHERE id = v_conversa_id;
      RETURN;
    END IF;
    SELECT a."pausarAtendimento" INTO v_pausar FROM public."SAAS_AgentesIA" a WHERE a.id = v_agente_id;
    IF v_pausar IS TRUE THEN
      UPDATE public."SAAS_Conversas_Agentes" SET "statusAtendimento" = 'aberto', pausado = TRUE WHERE id = v_conversa_id;
    END IF;
  END;
  $$;

  -- =========================
  -- Auth mirror: auth.users -> SAAS_Usuarios (ao criar/atualizar usuário no Auth)
  -- =========================
  CREATE OR REPLACE FUNCTION public.f_sync_auth_user_to_saas_usuarios()
  RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth AS $$
  DECLARE v_nome text; v_plano_id bigint; v_data_validade date; v_conta_id uuid; v_usuario_id uuid;
  BEGIN
    PERFORM set_config('row_security', 'off', true);
    v_nome := COALESCE(NEW.raw_user_meta_data->>'name', NEW.raw_user_meta_data->>'full_name', NEW.raw_user_meta_data->>'nome', NEW.raw_user_meta_data->>'first_name');
    v_plano_id := NULLIF(NEW.raw_user_meta_data->>'planoId', '')::bigint;
    v_data_validade := NULLIF(NEW.raw_user_meta_data->>'dataValidade', '')::date;

    IF TG_OP = 'UPDATE' THEN
      UPDATE public."SAAS_Usuarios" SET "Email" = NEW.email, telefone = COALESCE(NEW.phone, telefone), nome = COALESCE(v_nome, nome) WHERE auth_user_id = NEW.id;
      -- Atualizar plano/data/status da conta, mas não o email (conta mantém email do criador/primeiro admin)
      UPDATE public."SAAS_Contas" c SET plano = COALESCE(v_plano_id, plano), "dataValidade" = COALESCE(v_data_validade, "dataValidade"), status = COALESCE(status, true)
      FROM public."SAAS_Usuarios" u WHERE u."contaId" = c.id AND u.auth_user_id = NEW.id;
      RETURN NEW;
    END IF;

    -- Antes de criar qualquer coisa: se já existe SAAS_Usuarios com este email, só vincula auth_user_id (prioridade para linha com auth_user_id NULL = convite pendente)
    SELECT u.id INTO v_usuario_id FROM public."SAAS_Usuarios" u WHERE u."Email" = NEW.email ORDER BY (CASE WHEN u.auth_user_id IS NULL THEN 0 ELSE 1 END), u.created_at DESC LIMIT 1;
    IF v_usuario_id IS NOT NULL THEN
      UPDATE public."SAAS_Usuarios" SET auth_user_id = NEW.id, "Email" = NEW.email, telefone = COALESCE(NEW.phone, telefone), nome = COALESCE(v_nome, nome) WHERE id = v_usuario_id;
      SELECT "contaId" INTO v_conta_id FROM public."SAAS_Usuarios" WHERE id = v_usuario_id;
      IF v_conta_id IS NOT NULL THEN
        -- Não alterar email da conta ao vincular convidado: manter email do criador/primeiro admin
        UPDATE public."SAAS_Contas" SET plano = COALESCE(v_plano_id, plano), "dataValidade" = COALESCE(v_data_validade, "dataValidade"), status = COALESCE(status, true) WHERE id = v_conta_id;
      END IF;
      RETURN NEW;
    END IF;

    -- Convite por metadata: raw_user_meta_data tem contaId e invite (fallback quando o front não pré-criou a linha)
    v_conta_id := (NEW.raw_user_meta_data->>'contaId')::uuid;
    IF v_conta_id IS NOT NULL AND (NEW.raw_user_meta_data->>'invite') = 'true' THEN
      INSERT INTO public."SAAS_Usuarios" ("contaId", nome, "Email", telefone, auth_user_id, funcao)
      VALUES (v_conta_id, v_nome, NEW.email, NEW.phone, NEW.id, COALESCE(NULLIF(NEW.raw_user_meta_data->>'funcao', ''), 'membro'));
      RETURN NEW;
    END IF;

    -- Cadastro novo: cria conta e usuário admin
    INSERT INTO public."SAAS_Contas" (status, "dataValidade", plano, email) VALUES (true, v_data_validade, v_plano_id, NEW.email) RETURNING id INTO v_conta_id;
    INSERT INTO public."SAAS_Usuarios" ("contaId", nome, "Email", telefone, auth_user_id, funcao)
    VALUES (v_conta_id, v_nome, NEW.email, NEW.phone, NEW.id, 'admin');
    RETURN NEW;
  EXCEPTION WHEN OTHERS THEN RETURN NEW;
  END;
  $$;

  DROP TRIGGER IF EXISTS trg_sync_auth_user_to_saas_usuarios ON auth.users;
  CREATE TRIGGER trg_sync_auth_user_to_saas_usuarios
    AFTER INSERT OR UPDATE OF email, phone, raw_user_meta_data ON auth.users
    FOR EACH ROW EXECUTE FUNCTION public.f_sync_auth_user_to_saas_usuarios();

  -- Trigger: manter SAAS_Contas.email = email do usuário vinculado (criador = primeiro admin da conta)
  CREATE OR REPLACE FUNCTION public.f_sync_conta_email_from_usuario()
  RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
  BEGIN
    UPDATE public."SAAS_Contas" c
    SET email = (SELECT u."Email" FROM public."SAAS_Usuarios" u WHERE u."contaId" = COALESCE(NEW."contaId", OLD."contaId") AND u.funcao = 'admin' ORDER BY u.created_at ASC LIMIT 1)
    WHERE c.id = COALESCE(NEW."contaId", OLD."contaId");
    RETURN COALESCE(NEW, OLD);
  END;
  $$;
  DROP TRIGGER IF EXISTS trg_sync_conta_email_from_usuario ON public."SAAS_Usuarios";
  CREATE TRIGGER trg_sync_conta_email_from_usuario
    AFTER INSERT OR UPDATE OF "Email" ON public."SAAS_Usuarios"
    FOR EACH ROW EXECUTE FUNCTION public.f_sync_conta_email_from_usuario();

  -- Função: Pausar disparos de contas com status = false (executada 1x ao dia via cron)
  CREATE OR REPLACE FUNCTION public.f_cancelar_disparos_usuarios_inativos()
  RETURNS void LANGUAGE plpgsql AS $$
  BEGIN
    UPDATE public."SAAS_Disparos" d
    SET "StatusDisparo" = 'Pausado'
    FROM public."SAAS_Contas" c
    WHERE d."contaId" = c.id
      AND COALESCE(c.status, false) = false
      AND d."StatusDisparo" IN ('Aguardando', 'Em andamento', 'Pausado');
  END;
  $$;

  -- Trigger: dataValidade em SAAS_Contas (só ajusta status da conta; não lê/escreve em nenhuma outra tabela com RLS)
  -- Conta com super_admin nunca desativa. SECURITY DEFINER + row_security off só para o SELECT em Usuarios (evita 42501)
  CREATE OR REPLACE FUNCTION public.trg_contas_data_validade()
  RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
  BEGIN
    PERFORM set_config('row_security', 'off', true);
    IF EXISTS (SELECT 1 FROM public."SAAS_Usuarios" u WHERE u."contaId" = NEW.id AND u.super_admin = true) THEN
      NEW.status := true;
      RETURN NEW;
    END IF;
    IF NEW."dataValidade" IS NOT NULL AND NEW."dataValidade" < CURRENT_DATE AND COALESCE(NEW.status, true) IS NOT TRUE THEN
      NEW.status := false;
    END IF;
    RETURN NEW;
  END;
  $$;
  DROP TRIGGER IF EXISTS trg_usuarios_data_validade ON public."SAAS_Contas";
  DROP TRIGGER IF EXISTS trg_contas_data_validade ON public."SAAS_Contas";
  CREATE TRIGGER trg_contas_data_validade
    BEFORE INSERT OR UPDATE ON public."SAAS_Contas"
    FOR EACH ROW EXECUTE FUNCTION public.trg_contas_data_validade();

  -- Plano com "iaChaveCliente": a conta paga a própria OpenAI, então não acumula créditos.
  CREATE OR REPLACE FUNCTION public.f_conta_usa_chave_ia_cliente(p_conta_id uuid)
  RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
    SELECT COALESCE((
      SELECT p."iaChaveCliente"
      FROM public."SAAS_Contas" c
      JOIN public."SAAS_Planos" p ON p.id = c.plano
      WHERE c.id = p_conta_id
    ), false);
  $$;

  -- Funções de disparo (p_user_id = contaId)
  CREATE OR REPLACE FUNCTION public.f_add_tokens_usuario_por_agente(p_id_agente bigint, p_qnt_tokens numeric)
  RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
  DECLARE v_conta_id uuid; v_atual numeric; v_novo numeric;
  BEGIN
    SELECT a."contaId" INTO v_conta_id FROM public."SAAS_AgentesIA" a WHERE a.id = p_id_agente LIMIT 1;
    IF v_conta_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Agente não encontrado', 'id_agente_informado', p_id_agente);
    END IF;
    IF public.f_conta_usa_chave_ia_cliente(v_conta_id) THEN
      RETURN jsonb_build_object('ok', true, 'id_agente', p_id_agente, 'contaId', v_conta_id, 'ignorado', true, 'motivo', 'chave_ia_cliente');
    END IF;
    SELECT COALESCE(c.tokens, 0) INTO v_atual FROM public."SAAS_Contas" c WHERE c.id = v_conta_id;
    v_novo := v_atual + p_qnt_tokens;
    PERFORM set_config('saas.allow_tokens_update', '1', true);
    UPDATE public."SAAS_Contas" SET tokens = v_novo WHERE id = v_conta_id;
    RETURN jsonb_build_object('ok', true, 'id_agente', p_id_agente, 'contaId', v_conta_id, 'tokensAnterior', v_atual, 'tokensNovo', v_novo);
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'error', SQLERRM, 'id_agente_informado', p_id_agente);
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.swap_connection(p_disparo_id bigint, p_blocked_conn_id bigint)
  RETURNS void LANGUAGE plpgsql AS $$
  DECLARE hdr record; v_conn_ids bigint[]; v_new_conn_id bigint;
  BEGIN
    SELECT * INTO hdr FROM public."SAAS_Disparos" WHERE id=p_disparo_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Disparo % não existe', p_disparo_id; END IF;
    v_conn_ids := array_remove(hdr."idConexoes", p_blocked_conn_id);
    IF v_conn_ids IS NULL OR COALESCE(array_length(v_conn_ids,1),0)=0 THEN
      UPDATE public."SAAS_Disparos"
        SET "StatusDisparo"='Cancelado', "idConexoes"=NULL
        WHERE id=p_disparo_id;
      UPDATE public."SAAS_Detalhes_Disparos" SET "mensagemErro"='Whatsapp desconectado ou bloqueado'
        WHERE "idDisparo"=p_disparo_id AND "Status" IN ('pending','processing');
      RETURN;
    END IF;
    v_new_conn_id := v_conn_ids[1];
    UPDATE public."SAAS_Disparos" SET "idConexoes"=v_conn_ids WHERE id=p_disparo_id;
    UPDATE public."SAAS_Detalhes_Disparos" SET "idConexao"=v_new_conn_id
      WHERE "idDisparo"=p_disparo_id AND "Status"='pending' AND ("idConexao"=p_blocked_conn_id OR "idConexao" IS NULL);
    IF hdr."contaId" IS NOT NULL THEN
      PERFORM public.resume_disparo(p_disparo_id, hdr."contaId");
    END IF;
  END;
  $$;

  DROP FUNCTION IF EXISTS public.resume_disparo(bigint, text);
  CREATE OR REPLACE FUNCTION public.resume_disparo(p_disparo_id bigint, p_user_id uuid)
  RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
  DECLARE hdr record; v_base_ts timestamptz; v_cur_ts timestamptz; v_counter int := 0; v_gap int; v_days_arr int[]; rec_det record;
  BEGIN
    PERFORM set_config('row_security', 'off', true);
    SELECT * INTO hdr FROM public."SAAS_Disparos" WHERE id=p_disparo_id AND "contaId"=p_user_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Usuário inválido'; END IF;
    hdr."intervaloMin" := COALESCE(hdr."intervaloMin", 15);
    hdr."intervaloMax" := COALESCE(hdr."intervaloMax", 15);
    hdr."PausaAposMensagens" := COALESCE(hdr."PausaAposMensagens", 0);
    hdr."PausaMinutos" := COALESCE(hdr."PausaMinutos", 0);
    hdr."StartTime" := COALESCE(hdr."StartTime", time '00:00');
    hdr."EndTime" := COALESCE(hdr."EndTime", time '23:59:59');
    v_days_arr := COALESCE(hdr."DiasSelecionados", ARRAY[]::smallint[])::int[];
    UPDATE public."SAAS_Disparos" SET "StatusDisparo" = 'Em andamento' WHERE id=p_disparo_id AND "StatusDisparo" = 'Pausado';
    v_base_ts := now() + interval '1 minute';
    IF hdr."DataAgendamento" IS NOT NULL AND hdr."DataAgendamento" > v_base_ts THEN v_base_ts := hdr."DataAgendamento"; END IF;
    v_cur_ts := f_next_valid_time(v_base_ts, hdr."StartTime", hdr."EndTime", v_days_arr);
    FOR rec_det IN SELECT * FROM public."SAAS_Detalhes_Disparos" WHERE "idDisparo"=p_disparo_id AND "Status"='pending' ORDER BY id
    LOOP
      IF hdr."PausaAposMensagens" > 0 AND v_counter > 0 AND v_counter % hdr."PausaAposMensagens" = 0 THEN
        v_cur_ts := v_cur_ts + make_interval(mins => hdr."PausaMinutos");
        v_cur_ts := f_next_valid_time(v_cur_ts, hdr."StartTime", hdr."EndTime", v_days_arr);
      END IF;
      UPDATE public."SAAS_Detalhes_Disparos" SET "dataEnvio" = v_cur_ts WHERE id = rec_det.id;
      v_counter := v_counter + 1;
      v_gap := hdr."intervaloMin" + floor(random() * (hdr."intervaloMax" - hdr."intervaloMin" + 1))::int;
      v_cur_ts := f_next_valid_time(v_cur_ts + make_interval(secs => v_gap), hdr."StartTime", hdr."EndTime", v_days_arr);
    END LOOP;
  END;
  $$;

  DROP FUNCTION IF EXISTS public.pause_disparo(bigint, text);
  CREATE OR REPLACE FUNCTION public.pause_disparo(p_disparo_id bigint, p_user_id uuid)
  RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN
    PERFORM set_config('row_security', 'off', true);
    IF NOT EXISTS (SELECT 1 FROM public."SAAS_Disparos" WHERE id=p_disparo_id AND "contaId"=p_user_id) THEN RAISE EXCEPTION 'Usuário inválido'; END IF;
    UPDATE public."SAAS_Disparos" SET "StatusDisparo"='Pausado' WHERE id=p_disparo_id;
  END $$;

  DROP FUNCTION IF EXISTS public.delete_disparo(bigint, text);
  CREATE OR REPLACE FUNCTION public.delete_disparo(p_disparo_id bigint, p_user_id uuid)
  RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN
    PERFORM set_config('row_security', 'off', true);
    IF NOT EXISTS (SELECT 1 FROM public."SAAS_Disparos" WHERE id=p_disparo_id AND "contaId"=p_user_id) THEN RAISE EXCEPTION 'Usuário inválido'; END IF;
    DELETE FROM public."SAAS_Detalhes_Disparos" WHERE "idDisparo"=p_disparo_id;
    DELETE FROM public."SAAS_Disparos" WHERE id=p_disparo_id;
  END $$;

  CREATE OR REPLACE FUNCTION public.add_connections_disparo(p_disparo_id bigint, p_conn_ids bigint[], p_user_id uuid)
  RETURNS void LANGUAGE plpgsql AS $$
  DECLARE hdr record; v_all_conns bigint[]; v_conn_count int; v_idx_conn int := 1; v_cur_ts timestamptz; v_counter int := 0; v_gap int; rec_det record; v_first_ts timestamptz;
  BEGIN
    SELECT * INTO hdr FROM public."SAAS_Disparos" WHERE id=p_disparo_id AND "contaId"=p_user_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Usuário inválido ou disparo inexistente'; END IF;
    SELECT array_agg(DISTINCT conn)::bigint[] INTO v_all_conns FROM unnest(COALESCE(hdr."idConexoes", array[]::bigint[]) || COALESCE(p_conn_ids, array[]::bigint[])) AS conn;
    v_conn_count := COALESCE(array_length(v_all_conns, 1), 0);
    IF v_conn_count = 0 THEN RAISE EXCEPTION 'É necessário fornecer pelo menos 1 conexão válida'; END IF;
    UPDATE public."SAAS_Disparos" SET "idConexoes" = v_all_conns WHERE id = p_disparo_id;
    v_cur_ts := f_next_valid_time(now() + interval '1 minute', hdr."StartTime", hdr."EndTime", COALESCE(hdr."DiasSelecionados", ARRAY[]::smallint[])::int[]);
    FOR rec_det IN SELECT * FROM public."SAAS_Detalhes_Disparos" WHERE "idDisparo"=p_disparo_id AND "Status"='pending' ORDER BY id
    LOOP
      IF hdr."PausaAposMensagens" > 0 AND v_counter > 0 AND v_counter % hdr."PausaAposMensagens" = 0 THEN
        v_cur_ts := v_cur_ts + make_interval(mins => hdr."PausaMinutos");
        v_cur_ts := f_next_valid_time(v_cur_ts, hdr."StartTime", hdr."EndTime", COALESCE(hdr."DiasSelecionados", ARRAY[]::smallint[])::int[]);
      END IF;
      UPDATE public."SAAS_Detalhes_Disparos" SET "idConexao"=v_all_conns[v_idx_conn], "dataEnvio"=v_cur_ts, "mensagemErro"=NULL WHERE id=rec_det.id;
      IF v_counter = 0 THEN v_first_ts := v_cur_ts; END IF;
      v_counter := v_counter + 1; v_idx_conn := (v_idx_conn % v_conn_count) + 1;
      v_gap := hdr."intervaloMin" + floor(random() * (hdr."intervaloMax" - hdr."intervaloMin" + 1))::int;
      v_cur_ts := f_next_valid_time(v_cur_ts + make_interval(secs => v_gap), hdr."StartTime", hdr."EndTime", COALESCE(hdr."DiasSelecionados", ARRAY[]::smallint[])::int[]);
    END LOOP;
    IF v_counter > 0 THEN
      UPDATE public."SAAS_Disparos" SET "StatusDisparo" = CASE WHEN v_first_ts <= now() THEN 'Em andamento' ELSE 'Aguardando' END WHERE id = p_disparo_id;
    END IF;
  END;
  $$;

  -- Versões legadas de create_disparo / create_disparo_grupo (listas antigas) removidas.
  -- Implementação atual: ver "create_disparo e create_disparo_grupo (modelo etiquetas)" mais abaixo no arquivo.

  CREATE OR REPLACE FUNCTION public.f_upsert_conversas_agentes(p_items jsonb)
  RETURNS jsonb LANGUAGE plpgsql AS $$
  DECLARE v_item jsonb; v_inserted int := 0; v_skipped int := 0; v_exists boolean; v_telefone text; v_idconexao bigint; v_items jsonb;
  BEGIN
    IF p_items IS NULL THEN RETURN jsonb_build_object('inserted', 0, 'skipped', 0, 'error', 'payload null'); END IF;
    IF jsonb_typeof(p_items) = 'array' THEN v_items := p_items;
    ELSIF jsonb_typeof(p_items) = 'object' AND (p_items ? 'data') AND jsonb_typeof(p_items->'data') = 'array' THEN v_items := p_items->'data';
    ELSE RETURN jsonb_build_object('inserted', 0, 'skipped', 0, 'error', 'payload deve ser array ou {"data": [...]}', 'received_type', jsonb_typeof(p_items)); END IF;
    IF jsonb_array_length(v_items) = 0 THEN RETURN jsonb_build_object('inserted', 0, 'skipped', 0, 'error', 'array vazio'); END IF;
    FOR v_item IN SELECT * FROM jsonb_array_elements(v_items) LOOP
      v_telefone := NULLIF(trim(v_item->>'telefone'), ''); v_idconexao := (v_item->>'idConexao')::bigint;
      IF v_telefone IS NULL AND v_idconexao IS NULL THEN CONTINUE; END IF;
      SELECT EXISTS (SELECT 1 FROM public."SAAS_Conversas_Agentes" WHERE (telefone IS NOT DISTINCT FROM v_telefone) AND ("idConexao" IS NOT DISTINCT FROM v_idconexao)) INTO v_exists;
      IF v_exists THEN v_skipped := v_skipped + 1; CONTINUE; END IF;
      INSERT INTO public."SAAS_Conversas_Agentes" (telefone, "nomeConversa", "statusAtendimento", "idConexao", pausado, "contaId", lida, "fotoPerfil")
      VALUES (v_telefone, NULLIF(trim(v_item->>'nomeConversa'), ''), COALESCE(NULLIF(trim(lower(v_item->>'statusAtendimento')), ''), 'aberto'), v_idconexao,
              COALESCE((v_item->>'pausado')::boolean, false), (v_item->>'userId')::uuid, COALESCE((v_item->>'lida')::boolean, false), NULLIF(trim(v_item->>'fotoPerfil'), ''));
      v_inserted := v_inserted + 1;
    END LOOP;
    RETURN jsonb_build_object('inserted', v_inserted, 'skipped', v_skipped);
  EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('inserted', v_inserted, 'skipped', v_skipped, 'error', SQLERRM);
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_inserir_mensagens_conversa(p_mensagens jsonb, p_user_id uuid, p_conversa_id bigint, p_conexao_id bigint)
  RETURNS jsonb LANGUAGE plpgsql AS $$
  DECLARE v_item jsonb; v_items jsonb; v_inserted int := 0; v_skipped int := 0; v_msg_text text; v_tipo text; v_arquivo text; v_from_me boolean; v_ev_id text; v_respondida text; v_created timestamptz;
  BEGIN
    IF p_mensagens IS NULL THEN RETURN jsonb_build_object('inserted', 0, 'skipped', 0, 'error', 'payload null'); END IF;
    IF jsonb_typeof(p_mensagens) = 'array' THEN v_items := p_mensagens;
    ELSIF jsonb_typeof(p_mensagens) = 'object' AND (p_mensagens ? 'data') AND jsonb_typeof(p_mensagens->'data') = 'array' THEN v_items := p_mensagens->'data';
    ELSE RETURN jsonb_build_object('inserted', 0, 'skipped', 0, 'error', 'payload deve ser array ou {"data": [...]}'); END IF;
    IF jsonb_array_length(v_items) = 0 THEN RETURN jsonb_build_object('inserted', 0, 'skipped', 0, 'error', 'array vazio'); END IF;
    FOR v_item IN SELECT * FROM jsonb_array_elements(v_items) LOOP
      v_ev_id := NULLIF(trim(v_item->>'id'), '');
      IF v_ev_id IS NOT NULL AND EXISTS (SELECT 1 FROM public."SAAS_Mensagens" WHERE "messageEvolutionId" = v_ev_id AND "conversaId" = p_conversa_id) THEN v_skipped := v_skipped + 1; CONTINUE; END IF;
      v_tipo := COALESCE(NULLIF(trim(lower(v_item->>'messageType')), ''), 'conversation'); v_from_me := COALESCE((v_item->'key'->>'fromMe')::boolean, false);
      v_msg_text := v_item->'message'->>'conversation'; IF v_msg_text IS NULL THEN v_msg_text := v_item->'message'->'extendedTextMessage'->>'text'; END IF;
      IF v_msg_text IS NULL THEN v_msg_text := v_item->'message'->'imageMessage'->>'caption'; END IF;
      IF v_msg_text IS NULL THEN v_msg_text := v_item->'message'->'videoMessage'->>'caption'; END IF;
      IF v_msg_text IS NULL THEN v_msg_text := v_item->'message'->'documentMessage'->>'caption'; END IF;
      v_arquivo := v_item->'message'->'imageMessage'->>'url'; IF v_arquivo IS NULL THEN v_arquivo := v_item->'message'->'audioMessage'->>'url'; END IF;
      IF v_arquivo IS NULL THEN v_arquivo := v_item->'message'->'videoMessage'->>'url'; END IF;
      IF v_arquivo IS NULL THEN v_arquivo := v_item->'message'->'documentMessage'->>'url'; END IF;
      v_respondida := NULL; IF v_item->'contextInfo' IS NOT NULL AND v_item->'contextInfo' != 'null'::jsonb THEN
        v_respondida := v_item->'contextInfo'->>'stanzaId'; IF v_respondida IS NULL THEN v_respondida := v_item->'contextInfo'->>'quotedMessageId'; END IF;
      END IF;
      IF (v_item->>'messageTimestamp') IS NOT NULL AND (v_item->>'messageTimestamp') ~ '^\d+$' THEN v_created := to_timestamp((v_item->>'messageTimestamp')::numeric); ELSE v_created := now(); END IF;
      INSERT INTO public."SAAS_Mensagens" (created_at, "contaId", "conexaoId", "conversaId", mensagem, "tipoMensagem", "arquivoUrl", "fromMe", apagada, "messageEvolutionId", "mensagemRespondida", enviada, "IA")
      VALUES (v_created, p_user_id, p_conexao_id, p_conversa_id, NULLIF(trim(v_msg_text), ''), v_tipo, NULLIF(trim(v_arquivo), ''), v_from_me, false, v_ev_id, NULLIF(trim(v_respondida), ''), true, NULL);
      v_inserted := v_inserted + 1;
    END LOOP;
    RETURN jsonb_build_object('inserted', v_inserted, 'skipped', v_skipped);
  EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('inserted', v_inserted, 'skipped', v_skipped, 'error', SQLERRM);
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_conversa_ou_mensagem(p_telefone text, p_idconexao bigint, p_user_id uuid, p_mensagem text, p_message_evolution_id text DEFAULT NULL, p_id_agente bigint DEFAULT NULL)
  RETURNS jsonb LANGUAGE plpgsql AS $$
  DECLARE v_conversa_id bigint; v_mensagem_id bigint; v_created_conv boolean := false;
  BEGIN
    IF NULLIF(trim(p_telefone), '') IS NULL OR p_idconexao IS NULL OR p_user_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'telefone, idConexao e userId (contaId) são obrigatórios');
    END IF;
    SELECT id INTO v_conversa_id FROM public."SAAS_Conversas_Agentes" WHERE telefone = p_telefone AND "idConexao" = p_idconexao LIMIT 1;
    IF v_conversa_id IS NULL THEN
      INSERT INTO public."SAAS_Conversas_Agentes" (telefone, "idConexao", "contaId", "idAgente", "nomeConversa", "fotoPerfil", "statusAtendimento")
      VALUES (p_telefone, p_idconexao, p_user_id, p_id_agente, NULL, NULL, 'aberto') RETURNING id INTO v_conversa_id;
      v_created_conv := true;
    ELSE
      UPDATE public."SAAS_Conversas_Agentes" SET "idAgente" = p_id_agente WHERE id = v_conversa_id;
    END IF;
    INSERT INTO public."SAAS_Mensagens" ("contaId", "conexaoId", "conversaId", mensagem, "tipoMensagem", "fromMe", apagada, "messageEvolutionId", enviada, "IA")
    VALUES (p_user_id, p_conexao_id, v_conversa_id, NULLIF(trim(p_mensagem), ''), 'conversation', true, false, NULLIF(trim(p_message_evolution_id), ''), true, true)
    RETURNING id INTO v_mensagem_id;
    RETURN jsonb_build_object('ok', true, 'conversaId', v_conversa_id, 'mensagemId', v_mensagem_id, 'conversaCriada', v_created_conv);
  EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_mensagem_por_contato(
    p_contato_id bigint,
    p_id_conexao bigint,
    p_conta_id uuid,
    p_mensagem text DEFAULT NULL,
    p_url_arquivo text DEFAULT NULL,
    p_tipo_mensagem text DEFAULT 'conversation'
  )
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
  DECLARE
    v_conversa_id bigint;
    v_mensagem_id bigint;
    v_conversa_criada boolean := false;
    v_tipo_mensagem text;
    v_mensagem text;
    v_url_arquivo text;
    v_telefone text;
    v_nome_contato text;
    v_foto_contato text;
  BEGIN
    IF p_contato_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'contatoId é obrigatório');
    END IF;
    IF p_id_conexao IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'idConexao é obrigatório');
    END IF;
    IF p_conta_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'contaId é obrigatório');
    END IF;

    v_mensagem := NULLIF(trim(COALESCE(p_mensagem, '')), '');
    v_url_arquivo := NULLIF(trim(COALESCE(p_url_arquivo, '')), '');
    v_tipo_mensagem := COALESCE(NULLIF(trim(COALESCE(p_tipo_mensagem, '')), ''), 'conversation');

    IF v_mensagem IS NULL AND v_url_arquivo IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'mensagem ou urlArquivo é obrigatório');
    END IF;

    SELECT
      NULLIF(trim(COALESCE(c.telefone, '')), ''),
      NULLIF(trim(COALESCE(c.nome, '')), ''),
      NULLIF(trim(COALESCE(c."fotoPerfil", '')), '')
    INTO v_telefone, v_nome_contato, v_foto_contato
    FROM public."SAAS_Contatos" c
    WHERE c.id = p_contato_id
      AND c."contaId" = p_conta_id
    LIMIT 1;

    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'error', 'contatoId não encontrado para a conta informada');
    END IF;

    SELECT ca.id
    INTO v_conversa_id
    FROM public."SAAS_Conversas_Agentes" ca
    WHERE ca."contatoId" = p_contato_id
      AND ca."idConexao" = p_id_conexao
      AND ca."contaId" = p_conta_id
    ORDER BY ca.id DESC
    LIMIT 1;

    IF v_conversa_id IS NULL THEN
      BEGIN
        INSERT INTO public."SAAS_Conversas_Agentes" (
          "contaId", "idConexao", "contatoId", telefone, "nomeConversa", "fotoPerfil", lida, "statusAtendimento"
        )
        VALUES (
          p_conta_id, p_id_conexao, p_contato_id, v_telefone, v_nome_contato, v_foto_contato, false, 'aguardando'
        )
        RETURNING id INTO v_conversa_id;
        v_conversa_criada := true;
      EXCEPTION
        WHEN unique_violation THEN
          SELECT ca.id
          INTO v_conversa_id
          FROM public."SAAS_Conversas_Agentes" ca
          WHERE ca."contatoId" = p_contato_id
            AND ca."idConexao" = p_id_conexao
            AND ca."contaId" = p_conta_id
          ORDER BY ca.id DESC
          LIMIT 1;
      END;
    END IF;

    -- Mensagem enviada pelo usuário/atendente do sistema
    INSERT INTO public."SAAS_Mensagens" (
      "contaId", "conexaoId", "conversaId", mensagem, "tipoMensagem", "arquivoUrl", "fromMe", apagada, enviada, "IA"
    )
    VALUES (
      p_conta_id, p_id_conexao, v_conversa_id, v_mensagem, v_tipo_mensagem, v_url_arquivo, true, false, true, false
    )
    RETURNING id INTO v_mensagem_id;

    -- Conversa deve permanecer como não lida no fluxo solicitado
    UPDATE public."SAAS_Conversas_Agentes"
      SET lida = false
    WHERE id = v_conversa_id;

    RETURN jsonb_build_object(
      'ok', true,
      'conversaId', v_conversa_id,
      'mensagemId', v_mensagem_id,
      'conversaCriada', v_conversa_criada
    );
  EXCEPTION
    WHEN OTHERS THEN
      RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
  END;
  $$;

  -- Webhook: cria/atualiza contato, grava campos personalizados (cp_{id}) e vincula etiquetas (_idEtiquetas)
  CREATE OR REPLACE FUNCTION public.f_webhook_sincronizar_contato(
    p_conta_id uuid,
    p_telefone text,
    p_nome text DEFAULT NULL,
    p_campos jsonb DEFAULT '[]'::jsonb,
    p_id_etiquetas bigint[] DEFAULT NULL
  )
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
  DECLARE
    v_contato_id bigint;
    v_contato_criado boolean := false;
    v_telefone text;
    v_telefone_digits text;
    v_campo record;
    v_valor_raw text;
    v_valor_final text;
    v_campos_salvos int := 0;
    v_etiquetas_salvas int := 0;
    v_vars jsonb := '{}'::jsonb;
    v_etiqueta_id bigint;
  BEGIN
    IF p_conta_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'contaId é obrigatório');
    END IF;

    v_telefone := NULLIF(btrim(COALESCE(p_telefone, '')), '');
    IF v_telefone IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'telefone é obrigatório');
    END IF;

    v_telefone_digits := regexp_replace(v_telefone, '\D', '', 'g');

    SELECT c.id
      INTO v_contato_id
      FROM public."SAAS_Contatos" c
    WHERE c."contaId" = p_conta_id
      AND c.tipo = 'contato'
      AND (
        btrim(c.telefone) = v_telefone
        OR regexp_replace(COALESCE(c.telefone, ''), '\D', '', 'g') = v_telefone_digits
      )
    ORDER BY c.id
    LIMIT 1;

    IF v_contato_id IS NULL THEN
      INSERT INTO public."SAAS_Contatos" (nome, telefone, tipo, variaveis, "contaId", lid)
      VALUES (
        NULLIF(btrim(COALESCE(p_nome, '')), ''),
        v_telefone,
        'contato',
        '{}'::jsonb,
        p_conta_id,
        NULL
      )
      RETURNING id INTO v_contato_id;

      v_contato_criado := true;
    ELSE
      UPDATE public."SAAS_Contatos"
        SET nome = COALESCE(NULLIF(btrim(COALESCE(nome, '')), ''), NULLIF(btrim(COALESCE(p_nome, '')), ''), nome)
      WHERE id = v_contato_id;
    END IF;

    v_vars := jsonb_build_object(
      'nome', COALESCE(NULLIF(btrim(COALESCE(p_nome, '')), ''), ''),
      'telefone', v_telefone
    );

    FOR v_campo IN
      SELECT
        cp.id AS "idCampo",
        cp.nome,
        cp.tipo,
        NULLIF(btrim(elem->>'valor'), '') AS valor_raw
      FROM jsonb_array_elements(COALESCE(p_campos, '[]'::jsonb)) elem
      JOIN public."SAAS_Campos_Personalizados" cp
        ON cp.id = (elem->>'idCampo')::bigint
      AND cp."contaId" = p_conta_id
      WHERE NULLIF(btrim(elem->>'valor'), '') IS NOT NULL
    LOOP
      v_valor_raw := v_campo.valor_raw;

      IF v_campo.tipo = 'numero' THEN
        IF v_valor_raw !~ '^-?\d+(\.\d+)?$' AND replace(v_valor_raw, ',', '.') !~ '^-?\d+(\.\d+)?$' THEN
          CONTINUE;
        END IF;
        v_valor_final := replace(v_valor_raw, ',', '.');
      ELSIF v_campo.tipo = 'boolean' THEN
        IF lower(v_valor_raw) NOT IN ('true', 'false', '1', '0', 'sim', 'nao', 'não', 'yes', 'no', 's', 'n') THEN
          CONTINUE;
        END IF;
        v_valor_final := CASE
          WHEN lower(v_valor_raw) IN ('true', '1', 'sim', 'yes', 's') THEN 'sim'
          ELSE 'nao'
        END;
      ELSIF v_campo.tipo = 'data' THEN
        BEGIN
          v_valor_final := (v_valor_raw::timestamptz)::date::text;
        EXCEPTION WHEN OTHERS THEN
          CONTINUE;
        END;
      ELSE
        v_valor_final := v_valor_raw;
      END IF;

      INSERT INTO public."SAAS_Valores_Campos_Personalizados" ("idCampo", "idContato", "contaId", valor)
      VALUES (v_campo."idCampo", v_contato_id, p_conta_id, v_valor_final)
      ON CONFLICT ("idCampo", "idContato")
      DO UPDATE SET valor = EXCLUDED.valor;

      v_campos_salvos := v_campos_salvos + 1;

      v_vars := v_vars || jsonb_build_object(v_campo.nome, v_valor_final);
    END LOOP;

    IF p_id_etiquetas IS NOT NULL THEN
      FOREACH v_etiqueta_id IN ARRAY p_id_etiquetas
      LOOP
        IF v_etiqueta_id IS NULL THEN
          CONTINUE;
        END IF;

        INSERT INTO public."SAAS_Contatos_Etiquetas" ("contatoId", "etiquetaId", "contaId")
        SELECT v_contato_id, v_etiqueta_id, p_conta_id
        WHERE EXISTS (
          SELECT 1
            FROM public."SAAS_Etiquetas" e
            WHERE e.id = v_etiqueta_id
              AND e."contaId" = p_conta_id
        )
        ON CONFLICT ("contatoId", "etiquetaId") DO NOTHING;

        IF FOUND THEN
          v_etiquetas_salvas := v_etiquetas_salvas + 1;
        END IF;
      END LOOP;
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'contatoId', v_contato_id,
      'contatoCriado', v_contato_criado,
      'camposSalvos', v_campos_salvos,
      'etiquetasSalvas', v_etiquetas_salvas,
      'varsParaMensagem', v_vars
    );
  EXCEPTION
    WHEN OTHERS THEN
      RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
  END;
  $$;

  -- Avaliação unificada do fluxo do agente IA (Meta + Evolution)
  CREATE OR REPLACE FUNCTION public.f_avaliar_fluxo_agente_ia(
    p_conexao_id bigint,
    p_conta_id uuid,
    p_conversa_id bigint,
    p_contato_id bigint,
    p_contato_telefone text,
    p_telefone_input text,
    p_from_me boolean,
    p_nome_conversa text DEFAULT NULL,
    p_mensagem text DEFAULT NULL,
    p_eh_primeira_mensagem boolean DEFAULT false
  )
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
  DECLARE
    v_conexao jsonb;
    v_agente jsonb;
    v_agente_id bigint;
    v_conversa_agente_id bigint;
    v_setor_id bigint;
    v_resolver jsonb;
    v_motivo_ativacao text;
    v_agente_pausar boolean := false;
    v_conversa_pausada boolean := false;
    v_credito_esgotado boolean := false;
    v_segue_fluxo_ia boolean := false;
    v_parou_por_pausado boolean := false;
    v_abriu_atendimento_humano boolean := false;
    v_plano_qnt_creditos numeric;
    v_total_creditos numeric;
  BEGIN
    IF p_conexao_id IS NULL OR p_conta_id IS NULL OR p_conversa_id IS NULL OR p_contato_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'conexaoId, contaId, conversaId e contatoId obrigatorios');
    END IF;

    SELECT to_jsonb(c.*) INTO v_conexao
    FROM public."SAAS_Conexões" c
    WHERE c.id = p_conexao_id
    LIMIT 1;

    IF v_conexao IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'conexao invalida');
    END IF;

    SELECT ca."idAgente", ca."setorId", ca.pausado
      INTO v_conversa_agente_id, v_setor_id, v_conversa_pausada
      FROM public."SAAS_Conversas_Agentes" ca
    WHERE ca.id = p_conversa_id
    LIMIT 1;

    -- Conversa pausada (atendimento humano): não atribui agente nem pelo gatilho.
    IF COALESCE(v_conversa_pausada, false)
      AND NOT COALESCE(p_from_me, false)
    THEN
      UPDATE public."SAAS_Conversas_Agentes" SET lida = false WHERE id = p_conversa_id;

      IF v_conversa_agente_id IS NOT NULL THEN
        SELECT to_jsonb(a.*), a.id
          INTO v_agente, v_agente_id
          FROM public."SAAS_AgentesIA" a
        WHERE a.id = v_conversa_agente_id
        LIMIT 1;
      END IF;

      RETURN jsonb_build_object(
        'ok', true,
        'creditoEsgotado', false,
        'parouPorPausado', true,
        'abriuAtendimentoHumano', false,
        'segueFluxoIA', false,
        'conexao', v_conexao,
        'agente', v_agente,
        'agenteId', v_agente_id,
        'motivoAtivacao', 'conversa_pausada'
      );
    END IF;

    IF v_conversa_agente_id IS NOT NULL THEN
      SELECT to_jsonb(a.*), a.id, COALESCE(a."pausarAtendimento", false)
        INTO v_agente, v_agente_id, v_agente_pausar
        FROM public."SAAS_AgentesIA" a
      WHERE a.id = v_conversa_agente_id
        AND COALESCE(a.ativo, true) = true
      LIMIT 1;
      IF v_agente_id IS NOT NULL THEN
        v_motivo_ativacao := 'conversa_existente';
      END IF;
    END IF;

    IF v_agente_id IS NULL THEN
      v_resolver := public.f_resolver_agente_ativacao(
        p_conta_id,
        p_conexao_id,
        p_conversa_id,
        p_mensagem,
        p_contato_id,
        v_setor_id,
        COALESCE(p_eh_primeira_mensagem, false)
      );

      IF COALESCE(v_resolver->>'ok', 'false') = 'true'
        AND NULLIF(trim(COALESCE(v_resolver->>'idAgente', '')), '') IS NOT NULL
      THEN
        v_motivo_ativacao := v_resolver->>'motivo';
        SELECT to_jsonb(a.*), a.id, COALESCE(a."pausarAtendimento", false)
          INTO v_agente, v_agente_id, v_agente_pausar
          FROM public."SAAS_AgentesIA" a
        WHERE a.id = NULLIF(trim(v_resolver->>'idAgente'), '')::bigint
          AND COALESCE(a.ativo, true) = true
        LIMIT 1;
      END IF;
    END IF;

    IF v_agente_id IS NOT NULL THEN
      UPDATE public."SAAS_Conversas_Agentes"
        SET "idAgente" = v_agente_id
      WHERE id = p_conversa_id
        AND "idAgente" IS NULL;
    END IF;

    SELECT v."planoQntCreditos", v.total_creditos
      INTO v_plano_qnt_creditos, v_total_creditos
      FROM public."vw_Contas_Com_Plano" v
    WHERE v.id = p_conta_id
    LIMIT 1;

    IF v_plano_qnt_creditos IS NOT NULL THEN
      v_credito_esgotado := COALESCE(v_total_creditos, 0) >= COALESCE(v_plano_qnt_creditos, 0);
    END IF;

    IF NOT v_credito_esgotado AND v_agente_id IS NOT NULL THEN
      IF COALESCE(p_from_me, false) THEN
        IF v_agente_pausar THEN
          UPDATE public."SAAS_Conversas_Agentes"
            SET "statusAtendimento" = 'aberto',
                pausado = true
          WHERE id = p_conversa_id;
          v_abriu_atendimento_humano := true;
        END IF;
        v_segue_fluxo_ia := false;
      ELSE
        v_segue_fluxo_ia := true;
      END IF;
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'creditoEsgotado', v_credito_esgotado,
      'parouPorPausado', v_parou_por_pausado,
      'abriuAtendimentoHumano', v_abriu_atendimento_humano,
      'segueFluxoIA', v_segue_fluxo_ia,
      'conexao', v_conexao,
      'agente', v_agente,
      'agenteId', v_agente_id,
      'motivoAtivacao', v_motivo_ativacao
    );
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_ingestao_mensagem_internal(
    p_conexao_id bigint,
    p_telefone text,
    p_mensagem text,
    p_tipo_mensagem text,
    p_from_me boolean,
    p_arquivo_url text DEFAULT NULL,
    p_nome_conversa text DEFAULT NULL,
    p_foto_perfil text DEFAULT NULL,
    p_message_evolution_id text DEFAULT NULL,
    p_apagada boolean DEFAULT false,
    p_mensagem_respondida text DEFAULT NULL,
    p_lid text DEFAULT NULL
  )
  RETURNS jsonb
  LANGUAGE plpgsql
  AS $$
  DECLARE
    v_conta_id uuid;
    v_telefone_input text;
    v_lid_input text;
    v_is_lid boolean := false;
    v_telefone_sem_sufixo text;
    v_telefone_base text;
    v_telefone_alt text;
    v_candidatos_telefone text[] := ARRAY[]::text[];
    v_ingest_lock_key text;
    v_contato_telefone text;
    v_contato_id bigint;
    v_conversa_id bigint;
    v_mensagem_id bigint;
    v_conexao jsonb;
    v_agente jsonb;
    v_agente_id bigint;
    v_agente_pausar boolean := false;
    v_conversa_pausada boolean := false;
    v_status_atual text;
    v_conversa_criada boolean := false;
    v_contato_criado boolean := false;
    v_card_criado boolean := false;
    v_card_id bigint;
    v_mensagem_criada boolean := false;
    v_credito_esgotado boolean := false;
    v_segue_fluxo_ia boolean := false;
    v_parou_por_pausado boolean := false;
    v_abriu_atendimento_humano boolean := false;
    v_quadro_id bigint;
    v_etapa_id bigint;
    v_plano_qnt_creditos numeric;
    v_total_creditos numeric;
    v_agente_fluxo jsonb;
    v_eh_primeira_mensagem boolean := false;
  BEGIN
    IF p_conexao_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'conexaoId é obrigatório');
    END IF;
    IF NULLIF(trim(COALESCE(p_telefone, '')), '') IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'telefone é obrigatório');
    END IF;
    IF NULLIF(trim(COALESCE(p_tipo_mensagem, '')), '') IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'tipoMensagem é obrigatório');
    END IF;

    SELECT c."contaId", to_jsonb(c.*)
      INTO v_conta_id, v_conexao
      FROM public."SAAS_Conexões" c
    WHERE c.id = p_conexao_id
    LIMIT 1;

    IF v_conta_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'conexaoId inválido ou sem conta vinculada');
    END IF;

    v_telefone_input := trim(p_telefone);
    v_is_lid := lower(v_telefone_input) LIKE '%@lid';
    v_lid_input := NULLIF(trim(COALESCE(p_lid, '')), '');
    IF v_is_lid AND v_lid_input IS NULL THEN
      v_lid_input := v_telefone_input;
    END IF;

    IF NOT v_is_lid THEN
      v_telefone_sem_sufixo := regexp_replace(v_telefone_input, '@s\.whatsapp\.net$', '', 'i');
      v_telefone_base := regexp_replace(v_telefone_sem_sufixo, '\D', '', 'g');

      IF v_telefone_base ~ '^55\d{10,11}$' THEN
        -- Regra do nono dígito para BR (DDI 55 + DDD + número local)
        IF length(v_telefone_base) = 13 AND substring(v_telefone_base from 5 for 1) = '9' THEN
          v_telefone_alt := substring(v_telefone_base from 1 for 4) || substring(v_telefone_base from 6);
        ELSIF length(v_telefone_base) = 12 THEN
          v_telefone_alt := substring(v_telefone_base from 1 for 4) || '9' || substring(v_telefone_base from 5);
        END IF;
      END IF;
    END IF;

    -- Serializa apenas o mesmo contato dentro da mesma conta. As variantes brasileiras
    -- com e sem nono digito produzem a mesma chave, evitando corridas entre webhooks.
    v_ingest_lock_key := CASE
      WHEN v_is_lid THEN lower(COALESCE(v_lid_input, v_telefone_input))
      ELSE COALESCE(
        LEAST(NULLIF(v_telefone_base, ''), NULLIF(v_telefone_alt, '')),
        NULLIF(v_telefone_base, ''),
        lower(v_telefone_input)
      )
    END;
    PERFORM pg_advisory_xact_lock(
      hashtextextended(v_conta_id::text || ':' || v_ingest_lock_key, 0)
    );

    IF v_is_lid THEN
      -- Para @lid: 1) tenta por coluna lid
      SELECT c.id, c.telefone
        INTO v_contato_id, v_contato_telefone
        FROM public."SAAS_Contatos" c
      WHERE c."contaId" = v_conta_id
        AND c.lid = v_lid_input
      LIMIT 1;

      -- Para @lid: 2) se não achou, tenta por coluna telefone
      IF v_contato_id IS NULL THEN
        SELECT c.id, c.telefone
          INTO v_contato_id, v_contato_telefone
          FROM public."SAAS_Contatos" c
        WHERE c."contaId" = v_conta_id
          AND c.telefone = v_telefone_input
        LIMIT 1;
      END IF;
    ELSE
      v_candidatos_telefone := array_remove(ARRAY[
        v_telefone_input,
        v_telefone_sem_sufixo,
        CASE WHEN v_telefone_sem_sufixo <> '' THEN v_telefone_sem_sufixo || '@s.whatsapp.net' END,
        v_telefone_base,
        CASE WHEN v_telefone_base <> '' THEN v_telefone_base || '@s.whatsapp.net' END,
        v_telefone_alt,
        CASE WHEN NULLIF(trim(COALESCE(v_telefone_alt, '')), '') IS NOT NULL THEN v_telefone_alt || '@s.whatsapp.net' END
      ], NULL);

      SELECT c.id, c.telefone
        INTO v_contato_id, v_contato_telefone
        FROM public."SAAS_Contatos" c
      WHERE c."contaId" = v_conta_id
        AND c.telefone = ANY(v_candidatos_telefone)
      ORDER BY CASE c.telefone
        WHEN v_telefone_input THEN 1
        WHEN v_telefone_sem_sufixo THEN 2
        WHEN v_telefone_base THEN 3
        WHEN v_telefone_alt THEN 4
        WHEN COALESCE(v_telefone_alt, '') || '@s.whatsapp.net' THEN 5
        ELSE 99
      END
      LIMIT 1;
    END IF;

    IF v_contato_id IS NULL THEN
      BEGIN
        INSERT INTO public."SAAS_Contatos" (nome, telefone, "fotoPerfil", tipo, variaveis, "contaId", lid, validado)
        VALUES (
          NULLIF(trim(COALESCE(p_nome_conversa, '')), ''),
          v_telefone_input,
          NULLIF(trim(COALESCE(p_foto_perfil, '')), ''),
          'contato',
          '{}'::jsonb,
          v_conta_id,
          v_lid_input,
          true
        )
        RETURNING id, telefone INTO v_contato_id, v_contato_telefone;
        v_contato_criado := true;
      EXCEPTION
        WHEN unique_violation OR raise_exception THEN
          -- Outro escritor pode ter criado o contato entre a busca e o INSERT.
          v_contato_id := NULL;
          SELECT c.id, c.telefone
            INTO v_contato_id, v_contato_telefone
          FROM public."SAAS_Contatos" c
          WHERE c."contaId" = v_conta_id
            AND c.telefone = v_telefone_input
          LIMIT 1;

          IF v_contato_id IS NULL THEN
            RAISE;
          END IF;
      END;
    ELSIF v_lid_input IS NOT NULL THEN
      UPDATE public."SAAS_Contatos"
        SET lid = COALESCE(NULLIF(trim(COALESCE(lid, '')), ''), v_lid_input, lid),
            nome = COALESCE(NULLIF(trim(COALESCE(nome, '')), ''), NULLIF(trim(COALESCE(p_nome_conversa, '')), ''), nome),
            "fotoPerfil" = COALESCE(NULLIF(trim(COALESCE("fotoPerfil", '')), ''), NULLIF(trim(COALESCE(p_foto_perfil, '')), ''), "fotoPerfil"),
            validado = true
      WHERE id = v_contato_id
      RETURNING telefone INTO v_contato_telefone;
    ELSE
      UPDATE public."SAAS_Contatos"
        SET nome = COALESCE(NULLIF(trim(COALESCE(nome, '')), ''), NULLIF(trim(COALESCE(p_nome_conversa, '')), ''), nome),
            "fotoPerfil" = COALESCE(NULLIF(trim(COALESCE("fotoPerfil", '')), ''), NULLIF(trim(COALESCE(p_foto_perfil, '')), ''), "fotoPerfil"),
            validado = true
      WHERE id = v_contato_id
      RETURNING telefone INTO v_contato_telefone;
    END IF;

    SELECT c.id
      INTO v_conversa_id
    FROM public."SAAS_Conversas_Agentes" c
    WHERE c."contatoId" = v_contato_id
      AND c."idConexao" = p_conexao_id
    LIMIT 1;

    IF v_conversa_id IS NULL THEN
      INSERT INTO public."SAAS_Conversas_Agentes" (
        "contaId", "idConexao", "contatoId", telefone, pausado, "ultimaMensagem", lida, "statusAtendimento"
      )
      VALUES (
        v_conta_id,
        p_conexao_id,
        v_contato_id,
        COALESCE(v_contato_telefone, v_telefone_input),
        false,
        now(),
        COALESCE(p_from_me, false),
        'aguardando'
      )
      ON CONFLICT DO NOTHING
      RETURNING id INTO v_conversa_id;

      IF v_conversa_id IS NOT NULL THEN
        v_conversa_criada := true;
      ELSE
        SELECT c.id
          INTO v_conversa_id
        FROM public."SAAS_Conversas_Agentes" c
        WHERE c."contatoId" = v_contato_id
          AND c."idConexao" = p_conexao_id
        LIMIT 1;
      END IF;
    END IF;

    IF v_conversa_id IS NULL THEN
      RAISE EXCEPTION 'Não foi possível localizar ou criar a conversa para contato % e conexão %',
        v_contato_id, p_conexao_id;
    END IF;

    INSERT INTO public."SAAS_Mensagens" (
      "contaId", "conexaoId", "conversaId", mensagem, "tipoMensagem", "arquivoUrl",
      "fromMe", apagada, "messageEvolutionId", "mensagemRespondida", enviada, "IA"
    )
    VALUES (
      v_conta_id, p_conexao_id, v_conversa_id, NULLIF(trim(COALESCE(p_mensagem, '')), ''),
      trim(p_tipo_mensagem), NULLIF(trim(COALESCE(p_arquivo_url, '')), ''),
      COALESCE(p_from_me, false), COALESCE(p_apagada, false), NULLIF(trim(COALESCE(p_message_evolution_id, '')), ''),
      NULLIF(trim(COALESCE(p_mensagem_respondida, '')), ''), true, NULL
    )
    ON CONFLICT DO NOTHING
    RETURNING id INTO v_mensagem_id;

    IF v_mensagem_id IS NOT NULL THEN
      v_mensagem_criada := true;
    ELSIF NULLIF(trim(COALESCE(p_message_evolution_id, '')), '') IS NOT NULL THEN
      SELECT m.id
        INTO v_mensagem_id
      FROM public."SAAS_Mensagens" m
      WHERE m."conversaId" = v_conversa_id
        AND m."messageEvolutionId" = trim(p_message_evolution_id)
      LIMIT 1;
    END IF;

    IF v_mensagem_id IS NULL THEN
      RAISE EXCEPTION 'Não foi possível localizar ou criar a mensagem na conversa %', v_conversa_id;
    END IF;

    -- Uma entrega repetida retorna sucesso sem reabrir a conversa nem disparar a IA novamente.
    IF v_mensagem_criada THEN
      IF NOT v_conversa_criada THEN
        UPDATE public."SAAS_Conversas_Agentes"
          SET "ultimaMensagem" = now(),
              lida = CASE WHEN COALESCE(p_from_me, false) THEN true ELSE false END,
              "statusAtendimento" = CASE
                WHEN lower(trim(COALESCE("statusAtendimento", ''))) = 'fechado' THEN 'aguardando'
                ELSE "statusAtendimento"
              END
        WHERE id = v_conversa_id;
      END IF;

      IF NOT COALESCE(p_from_me, false) THEN
        -- Só importa saber se existe uma segunda mensagem recebida; evita contar o histórico inteiro.
        SELECT NOT EXISTS (
          SELECT 1 FROM public."SAAS_Mensagens" m
          WHERE m."conversaId" = v_conversa_id
            AND m."fromMe" = false
            AND m.apagada = false
          OFFSET 1 LIMIT 1
        ) INTO v_eh_primeira_mensagem;
      END IF;

      v_agente_fluxo := public.f_avaliar_fluxo_agente_ia(
        p_conexao_id,
        v_conta_id,
        v_conversa_id,
        v_contato_id,
        v_contato_telefone,
        v_telefone_input,
        COALESCE(p_from_me, false),
        p_nome_conversa,
        NULLIF(trim(COALESCE(p_mensagem, '')), ''),
        v_eh_primeira_mensagem
      );
    ELSE
      v_agente_fluxo := '{}'::jsonb;
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'contaId', v_conta_id,
      'conexaoId', p_conexao_id,
      'contatoId', v_contato_id,
      'conversaId', v_conversa_id,
      'mensagemId', v_mensagem_id,
      'contatoCriado', v_contato_criado,
      'conversaCriada', v_conversa_criada,
      'mensagemCriada', v_mensagem_criada
    ) || COALESCE(v_agente_fluxo - 'ok', '{}'::jsonb);
  EXCEPTION
    WHEN OTHERS THEN
      RETURN jsonb_build_object('ok', false, 'error', SQLERRM, 'sqlstate', SQLSTATE);
  END;
  $$;

  -- Mantém apenas a função pública JSONB; remove assinatura antiga para evitar overload.
  DROP FUNCTION IF EXISTS public.f_ingestao_mensagem(
    bigint, text, text, text, boolean, text, text, text, text, boolean, text, text
  );

  -- Overload: aceita JSONB (array com 1 objeto)
  CREATE OR REPLACE FUNCTION public.f_ingestao_mensagem(p_input jsonb)
  RETURNS jsonb
  LANGUAGE plpgsql
  AS $$
  DECLARE
    v_item jsonb;
    v_data jsonb;
    v_evolu jsonb;
    v_conexao_id bigint;
    v_telefone text;
    v_mensagem text;
    v_tipo_mensagem text;
    v_from_me boolean;
    v_arquivo_url text;
    v_nome_conversa text;
    v_foto_perfil text;
    v_message_evolution_id text;
    v_apagada boolean;
    v_mensagem_respondida text;
    v_lid text;
    v_resultado jsonb;
    v_contato_id bigint;
    v_contato_criado boolean;
    v_foto_atual text;
    v_foto_url text;
    v_evolu_url text;
    v_http_body jsonb;
  BEGIN
    -- Aceita array ou objeto único
    IF jsonb_typeof(p_input) = 'array' THEN
      v_item := p_input->0;
    ELSE
      v_item := p_input;
    END IF;

    v_data := v_item->'data';
    v_evolu := v_item->'evolu';

    -- Campos obrigatórios
    v_conexao_id := (v_item->'conexao'->>'id')::bigint;
    v_telefone := v_data->>'remoteJid';
    v_mensagem := v_data->>'conversation';
    v_tipo_mensagem := v_data->>'messageType';
    v_from_me := COALESCE((v_data->>'fromMe')::boolean, false);

    -- Campos opcionais
    v_arquivo_url := v_data->>'arquivoUrl';
    v_nome_conversa := v_data->>'pushName';
    v_foto_perfil := v_data->>'fotoPerfil';
    v_message_evolution_id := v_data->>'id';
    v_apagada := COALESCE((v_data->>'apagada')::boolean, false);
    v_mensagem_respondida := v_data->>'mensagemRespondida';
    v_lid := NULLIF(COALESCE(v_data->>'lid', ''), '');

    -- Chama a função original
    v_resultado := public.f_ingestao_mensagem_internal(
      v_conexao_id,
      v_telefone,
      v_mensagem,
      v_tipo_mensagem,
      v_from_me,
      v_arquivo_url,
      v_nome_conversa,
      v_foto_perfil,
      v_message_evolution_id,
      v_apagada,
      v_mensagem_respondida,
      v_lid
    );

    RETURN v_resultado;
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_vincular_contatos_conversas_por_telefone()
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
  DECLARE
    v_novos_contatos bigint := 0;
    v_conversas_vinculadas bigint := 0;
  BEGIN
    -- 1) Contatos que já existem com número sem sufixo: atualiza telefone para incluir @s.whatsapp.net
    UPDATE public."SAAS_Contatos" ct
      SET telefone = ct.telefone || '@s.whatsapp.net'
      FROM (
        SELECT DISTINCT c."contaId" AS conta_id, c.telefone AS tel_conversa
          FROM public."SAAS_Conversas_Agentes" c
        WHERE c."contaId" IS NOT NULL
          AND c.telefone IS NOT NULL
          AND trim(c.telefone) <> ''
          AND c.telefone LIKE '%@s.whatsapp.net'
      ) src
    WHERE ct."contaId" = src.conta_id
      AND ct.telefone = replace(src.tel_conversa, '@s.whatsapp.net', '')
      AND ct.telefone NOT LIKE '%@s.whatsapp.net';

    -- 2) Garante que todos os telefones de conversas tenham contato correspondente,
    -- aproveitando nomeConversa/fotoPerfil da conversa para preencher contato.
    WITH src AS (
      SELECT
        c.id AS conversa_id,
        c."contaId" AS conta_id,
        c.telefone AS telefone,
        NULLIF(trim(COALESCE(c."nomeConversa", '')), '') AS nome_conversa,
        NULLIF(trim(COALESCE(c."fotoPerfil", '')), '') AS foto_perfil
      FROM public."SAAS_Conversas_Agentes" c
      WHERE c."contaId" IS NOT NULL
        AND c.telefone IS NOT NULL
        AND trim(c.telefone) <> ''
    ),
    src_dedup AS (
      SELECT DISTINCT ON (s.conta_id, s.telefone)
        s.conta_id, s.telefone, s.nome_conversa, s.foto_perfil
      FROM src s
      ORDER BY s.conta_id, s.telefone, s.conversa_id
    ),
    to_insert AS (
      SELECT d.*
      FROM src_dedup d
      LEFT JOIN public."SAAS_Contatos" ct
        ON ct."contaId" = d.conta_id
      AND ct.telefone = d.telefone
      WHERE ct.id IS NULL
    ),
    ins AS (
      INSERT INTO public."SAAS_Contatos" (nome, telefone, "fotoPerfil", tipo, variaveis, "contaId")
      SELECT
        t.nome_conversa,
        t.telefone,
        t.foto_perfil,
        'contato',
        '{}'::jsonb,
        t.conta_id
      FROM to_insert t
      RETURNING id
    )
    SELECT COUNT(*) INTO v_novos_contatos FROM ins;

    -- 3) Atualiza dados faltantes (nome/foto) no contato a partir da conversa
    WITH src AS (
      SELECT
        c."contaId" AS conta_id,
        c.telefone AS telefone,
        NULLIF(trim(COALESCE(c."nomeConversa", '')), '') AS nome_conversa,
        NULLIF(trim(COALESCE(c."fotoPerfil", '')), '') AS foto_perfil
      FROM public."SAAS_Conversas_Agentes" c
      WHERE c."contaId" IS NOT NULL
        AND c.telefone IS NOT NULL
        AND trim(c.telefone) <> ''
    )
    UPDATE public."SAAS_Contatos" ct
      SET nome = COALESCE(NULLIF(trim(COALESCE(ct.nome, '')), ''), src.nome_conversa, ct.nome),
          "fotoPerfil" = COALESCE(NULLIF(trim(COALESCE(ct."fotoPerfil", '')), ''), src.foto_perfil, ct."fotoPerfil")
      FROM src
    WHERE ct."contaId" = src.conta_id
      AND ct.telefone = src.telefone
      AND (
        (NULLIF(trim(COALESCE(ct.nome, '')), '') IS NULL AND src.nome_conversa IS NOT NULL)
        OR (NULLIF(trim(COALESCE(ct."fotoPerfil", '')), '') IS NULL AND src.foto_perfil IS NOT NULL)
      );

    -- 4) Vincula contatoId em todas as conversas pelo par contaId+telefone
    WITH upd AS (
      UPDATE public."SAAS_Conversas_Agentes" c
        SET "contatoId" = ct.id
        FROM public."SAAS_Contatos" ct
      WHERE c."contaId" = ct."contaId"
        AND c.telefone = ct.telefone
        AND c.telefone IS NOT NULL
        AND trim(c.telefone) <> ''
        AND (c."contatoId" IS DISTINCT FROM ct.id)
      RETURNING c.id
    )
    SELECT COUNT(*) INTO v_conversas_vinculadas FROM upd;

    RETURN jsonb_build_object(
      'ok', true,
      'contatosCriados', v_novos_contatos,
      'conversasVinculadas', v_conversas_vinculadas
    );
  EXCEPTION
    WHEN OTHERS THEN
      RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
  END;
  $$;

  -- Triggers de disparo (start/finalize)
  CREATE OR REPLACE FUNCTION public.f_start_disparo()
  RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
    IF OLD."Status"='pending' AND NEW."Status" IN ('processing','sent','failed') THEN
      UPDATE public."SAAS_Disparos" SET "StatusDisparo"='Em andamento' WHERE id=NEW."idDisparo" AND "StatusDisparo"='Aguardando';
    END IF;
    RETURN NEW;
  END $$;

  CREATE OR REPLACE FUNCTION public.f_finalize_disparo()
  RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
    IF NEW."Status" IN ('sent','failed') AND OLD."Status" IS DISTINCT FROM NEW."Status" THEN
      UPDATE public."SAAS_Disparos" SET "MensagensDisparadas" = COALESCE("MensagensDisparadas",0) + 1 WHERE id = NEW."idDisparo";
      PERFORM 1 FROM public."SAAS_Detalhes_Disparos" WHERE "idDisparo"=NEW."idDisparo" AND "Status" IN ('pending','processing');
      IF NOT FOUND THEN
        UPDATE public."SAAS_Disparos" SET "StatusDisparo"='Finalizado' WHERE id=NEW."idDisparo";
      END IF;
    END IF;
    RETURN NEW;
  END $$;

  -- Overload f_add_tokens com JSONB
  CREATE OR REPLACE FUNCTION public.f_add_tokens_usuario_por_agente(p_params JSONB)
  RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
  BEGIN
    RETURN public.f_add_tokens_usuario_por_agente((p_params->>'id_agente')::bigint, (p_params->>'qnt_tokens')::numeric);
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_add_tokens_conta(p_conta_id uuid, p_qnt_tokens numeric)
  RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
  DECLARE v_atual numeric; v_novo numeric;
  BEGIN
    IF p_conta_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'contaId é obrigatório');
    END IF;
    IF p_qnt_tokens IS NULL OR p_qnt_tokens <= 0 THEN
      RETURN jsonb_build_object('ok', true, 'contaId', p_conta_id, 'ignorado', true);
    END IF;
    IF public.f_conta_usa_chave_ia_cliente(p_conta_id) THEN
      RETURN jsonb_build_object('ok', true, 'contaId', p_conta_id, 'ignorado', true, 'motivo', 'chave_ia_cliente');
    END IF;
    SELECT COALESCE(c.tokens, 0) INTO v_atual FROM public."SAAS_Contas" c WHERE c.id = p_conta_id;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Conta não encontrada', 'contaId', p_conta_id);
    END IF;
    v_novo := v_atual + p_qnt_tokens;
    PERFORM set_config('saas.allow_tokens_update', '1', true);
    UPDATE public."SAAS_Contas" SET tokens = v_novo WHERE id = p_conta_id;
    RETURN jsonb_build_object('ok', true, 'contaId', p_conta_id, 'tokensAnterior', v_atual, 'tokensNovo', v_novo);
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'error', SQLERRM, 'contaId', p_conta_id);
  END;
  $$;
  GRANT EXECUTE ON FUNCTION public.f_add_tokens_conta(uuid, numeric) TO service_role;

  CREATE OR REPLACE FUNCTION public.f_block_delete_lista_if_active()
  RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $function$
  BEGIN
    -- Desativar RLS apenas dentro desta função para validar disparos vinculados à lista
    PERFORM set_config('row_security', 'off', true);
    IF EXISTS (
      SELECT 1 FROM public."SAAS_Disparos" h
      WHERE h."StatusDisparo" IN ('Aguardando','Em andamento','Pausado')
        AND (OLD.id = ANY(h."idListas")
            OR EXISTS (SELECT 1 FROM public."SAAS_Detalhes_Disparos" d LEFT JOIN public."SAAS_Contatos" c ON c.id = d."idContato" LEFT JOIN public."SAAS_Grupos" g ON g.id = d."idGrupo"
                        WHERE d."idDisparo" = h.id AND (c."idLista" = OLD.id OR g."idLista" = OLD.id)))
    ) THEN
      RAISE EXCEPTION 'Não é possível excluir a lista %: há disparos não finalizados vinculados.', OLD.id;
    END IF;
    RETURN OLD;
  END $function$;

  CREATE OR REPLACE FUNCTION public.f_block_delete_contato_if_active()
  RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $function$
  BEGIN
    -- Permite limpeza dos vínculos mesmo quando houver RLS ativo nas tabelas relacionadas.
    PERFORM set_config('row_security', 'off', true);

    -- Disparos: remove detalhes vinculados ao contato (inclusive ativos/pending).
    IF to_regclass('public."SAAS_Detalhes_Disparos"') IS NOT NULL THEN
      DELETE FROM public."SAAS_Detalhes_Disparos"
      WHERE "idContato" = OLD.id;
    END IF;

    -- CRM: remove cards vinculados ao contato.
    IF to_regclass('public."SAAS_Cards_Quadros"') IS NOT NULL THEN
      DELETE FROM public."SAAS_Cards_Quadros"
      WHERE "contatoId" = OLD.id;
    END IF;

    -- Chat: remove conversas vinculadas; mensagens caem em cascata quando FK existir.
    IF to_regclass('public."SAAS_Conversas_Agentes"') IS NOT NULL THEN
      DELETE FROM public."SAAS_Conversas_Agentes"
      WHERE "contatoId" = OLD.id;
    END IF;

    -- Etiquetas e campos personalizados vinculados ao contato.
    IF to_regclass('public."SAAS_Contatos_Etiquetas"') IS NOT NULL THEN
      DELETE FROM public."SAAS_Contatos_Etiquetas"
      WHERE "contatoId" = OLD.id;
    END IF;

    IF to_regclass('public."SAAS_Valores_Campos_Personalizados"') IS NOT NULL THEN
      DELETE FROM public."SAAS_Valores_Campos_Personalizados"
      WHERE "idContato" = OLD.id;
    END IF;

    RETURN OLD;
  END $function$;

  CREATE OR REPLACE FUNCTION public.f_block_delete_grupo_if_active()
  RETURNS trigger LANGUAGE plpgsql AS $func$
  BEGIN
    IF EXISTS (
      SELECT 1 FROM public."SAAS_Detalhes_Disparos" d JOIN public."SAAS_Disparos" h ON h.id = d."idDisparo"
      WHERE d."idGrupo" = OLD.id AND h."StatusDisparo" IN ('Aguardando','Em andamento','Pausado')
    ) THEN
      RAISE EXCEPTION 'Não é possível excluir o grupo %: há disparos não finalizados vinculados.', OLD.id;
    END IF;
    RETURN OLD;
  END $func$;

  -- Expirar contas (dataValidade vencida); contas com super_admin nunca expiram
  CREATE OR REPLACE FUNCTION public.p_expire_contas_daily()
  RETURNS void LANGUAGE plpgsql AS $$
  BEGIN
    UPDATE public."SAAS_Contas" c SET status = FALSE
    WHERE c.status IS DISTINCT FROM FALSE AND c."dataValidade" IS NOT NULL AND CURRENT_DATE > c."dataValidade"
      AND NOT EXISTS (SELECT 1 FROM public."SAAS_Usuarios" u WHERE u."contaId" = c.id AND u.super_admin = true);
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.p_expire_contas_now()
  RETURNS void LANGUAGE plpgsql AS $$
  BEGIN
    UPDATE public."SAAS_Contas" c SET status = false
    WHERE c."dataValidade" IS NOT NULL AND c."dataValidade" < CURRENT_DATE AND c.status IS DISTINCT FROM false
      AND NOT EXISTS (SELECT 1 FROM public."SAAS_Usuarios" u WHERE u."contaId" = c.id AND u.super_admin = true);
  END;
  $$;

  -- Mirror auth → SAAS_Usuarios (alternativa; em conta o sync principal já cria Conta+Usuario)
  CREATE OR REPLACE FUNCTION public.f_auth_to_saas_usuarios_mirror()
  RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth AS $$
  DECLARE v_existing_id uuid; v_nome text; v_telefone text;
  BEGIN
    PERFORM set_config('row_security', 'off', true);
    v_nome := COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.raw_user_meta_data->>'name', NEW.raw_user_meta_data->>'nome');
    v_telefone := COALESCE(NEW.phone, NEW.raw_user_meta_data->>'phone', NEW.raw_user_meta_data->>'telefone');
    SELECT id INTO v_existing_id FROM public."SAAS_Usuarios" WHERE "Email" = NEW.email LIMIT 1;
    IF v_existing_id IS NOT NULL THEN
      UPDATE public."SAAS_Usuarios" SET auth_user_id = NEW.id, "Email" = NEW.email, nome = COALESCE(v_nome, nome), telefone = COALESCE(v_telefone, telefone) WHERE id = v_existing_id;
    END IF;
    RETURN NEW;
  EXCEPTION WHEN OTHERS THEN RETURN NEW;
  END;
  $$;

  -- RLS SAAS_Usuarios: usuário vê a si e os demais da mesma conta (só leitura nos outros); edita apenas o próprio; admin pode inserir convites.
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Usuarios"') IS NOT NULL THEN
      ALTER TABLE public."SAAS_Usuarios" ENABLE ROW LEVEL SECURITY;
      DROP POLICY IF EXISTS "service_role_full_access" ON public."SAAS_Usuarios";
      CREATE POLICY "service_role_full_access" ON public."SAAS_Usuarios" TO service_role USING (true) WITH CHECK (true);
      DROP POLICY IF EXISTS "insert_usuario_admin" ON public."SAAS_Usuarios";
      -- Inserir: apenas admin da conta pode adicionar usuários (convite) na mesma conta
      CREATE POLICY "insert_usuario_admin" ON public."SAAS_Usuarios" FOR INSERT TO authenticated
        WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids_admin()) OR (SELECT public.rls_eh_super_admin()));
      DROP POLICY IF EXISTS "select_meu_usuario" ON public."SAAS_Usuarios";
      DROP POLICY IF EXISTS "select_usuarios_da_conta" ON public."SAAS_Usuarios";
      DROP POLICY IF EXISTS "select_usuarios_mesma_conta" ON public."SAAS_Usuarios";
      -- Ver: próprio usuário ou outros da mesma conta (apenas visualizar); super_admin vê todos
      CREATE POLICY "select_usuarios_mesma_conta" ON public."SAAS_Usuarios" FOR SELECT TO authenticated
        USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
      DROP POLICY IF EXISTS "update_meu_usuario" ON public."SAAS_Usuarios";
      -- Atualizar: apenas o próprio registro (auth_user_id = auth.uid()); super_admin pode atualizar qualquer
      CREATE POLICY "update_meu_usuario" ON public."SAAS_Usuarios" FOR UPDATE TO authenticated
        USING ("auth_user_id" = (SELECT auth.uid()) OR (SELECT public.rls_eh_super_admin())) WITH CHECK ("auth_user_id" = (SELECT auth.uid()) OR (SELECT public.rls_eh_super_admin()));
      -- Excluir: apenas admin da conta pode excluir outros usuários da mesma conta (não pode excluir a si mesmo)
      DROP POLICY IF EXISTS "delete_usuario_admin" ON public."SAAS_Usuarios";
      CREATE POLICY "delete_usuario_admin" ON public."SAAS_Usuarios" FOR DELETE TO authenticated
        USING (("contaId" IN (SELECT public.rls_conta_ids_admin()) OR (SELECT public.rls_eh_super_admin())) AND ("auth_user_id" IS DISTINCT FROM (SELECT auth.uid())));
      -- Autenticado não pode editar contaId nem super_admin: apenas Email, nome, telefone
      REVOKE UPDATE ON public."SAAS_Usuarios" FROM authenticated;
      GRANT SELECT, INSERT, UPDATE ("Email", nome, telefone) ON public."SAAS_Usuarios" TO authenticated;
    END IF;
  END$$;

  -- Super admin: ler nome/telefone de contato de todas as contas (bypassa RLS de SAAS_Usuarios)
  CREATE OR REPLACE FUNCTION public.f_admin_contatos_clientes()
  RETURNS TABLE (conta_id uuid, nome text, telefone text, email text)
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path = public
  AS $$
  BEGIN
    IF NOT public.is_super_admin() THEN
      RAISE EXCEPTION 'Apenas super admin';
    END IF;
    RETURN QUERY
    SELECT DISTINCT ON (c.id)
      c.id AS conta_id,
      u.nome,
      u.telefone,
      u."Email" AS email
    FROM public."SAAS_Contas" c
    LEFT JOIN public."SAAS_Usuarios" u ON u."contaId" = c.id
    ORDER BY
      c.id,
      CASE WHEN u."Email" IS NOT NULL AND lower(u."Email") = lower(COALESCE(c.email, '')) THEN 0 ELSE 1 END,
      CASE WHEN u.funcao = 'admin' THEN 0 ELSE 1 END,
      CASE WHEN NULLIF(trim(COALESCE(u.nome, '')), '') IS NOT NULL THEN 0 ELSE 1 END,
      u.created_at ASC NULLS LAST;
  END;
  $$;

  -- Super admin: atualizar status/validade da conta + nome/telefone do usuário de contato
  CREATE OR REPLACE FUNCTION public.f_admin_atualizar_cliente_contato(
    p_conta_id uuid,
    p_nome text DEFAULT NULL,
    p_telefone text DEFAULT NULL,
    p_status boolean DEFAULT NULL,
    p_data_validade date DEFAULT NULL
  )
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
  DECLARE
    v_email text;
    v_usuario_id uuid;
  BEGIN
    IF NOT public.is_super_admin() THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Apenas super admin');
    END IF;
    IF p_conta_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'contaId obrigatório');
    END IF;

    UPDATE public."SAAS_Contas"
    SET
      status = COALESCE(p_status, status),
      "dataValidade" = p_data_validade
    WHERE id = p_conta_id;

    IF p_nome IS NOT NULL OR p_telefone IS NOT NULL THEN
      SELECT c.email INTO v_email FROM public."SAAS_Contas" c WHERE c.id = p_conta_id;

      SELECT u.id INTO v_usuario_id
      FROM public."SAAS_Usuarios" u
      WHERE u."contaId" = p_conta_id
      ORDER BY
        CASE WHEN v_email IS NOT NULL AND lower(COALESCE(u."Email", '')) = lower(v_email) THEN 0 ELSE 1 END,
        CASE WHEN u.funcao = 'admin' THEN 0 ELSE 1 END,
        CASE WHEN NULLIF(trim(COALESCE(u.nome, '')), '') IS NOT NULL THEN 0 ELSE 1 END,
        u.created_at ASC NULLS LAST
      LIMIT 1;

      IF v_usuario_id IS NULL THEN
        RETURN jsonb_build_object('ok', false, 'erro', 'Usuário da conta não encontrado');
      END IF;

      UPDATE public."SAAS_Usuarios"
      SET
        nome = COALESCE(p_nome, nome),
        telefone = COALESCE(p_telefone, telefone)
      WHERE id = v_usuario_id;
    END IF;

    RETURN jsonb_build_object('ok', true, 'contaId', p_conta_id, 'usuarioId', v_usuario_id);
  END;
  $$;

  GRANT EXECUTE ON FUNCTION public.f_admin_contatos_clientes() TO authenticated;
  GRANT EXECUTE ON FUNCTION public.f_admin_atualizar_cliente_contato(uuid, text, text, boolean, date) TO authenticated;

  -- FKs para SAAS_Contas: ON DELETE CASCADE (instalações já existentes)
  DO $$
  DECLARE
    r record;
  BEGIN
    FOR r IN
      SELECT
        tc.table_name,
        tc.constraint_name,
        kcu.column_name
      FROM information_schema.table_constraints tc
      JOIN information_schema.key_column_usage kcu
        ON tc.constraint_name = kcu.constraint_name
       AND tc.table_schema = kcu.table_schema
      JOIN information_schema.constraint_column_usage ccu
        ON ccu.constraint_name = tc.constraint_name
       AND ccu.table_schema = tc.table_schema
      JOIN information_schema.referential_constraints rc
        ON rc.constraint_name = tc.constraint_name
       AND rc.constraint_schema = tc.table_schema
      WHERE tc.constraint_type = 'FOREIGN KEY'
        AND tc.table_schema = 'public'
        AND ccu.table_schema = 'public'
        AND ccu.table_name = 'SAAS_Contas'
        AND rc.delete_rule IS DISTINCT FROM 'CASCADE'
    LOOP
      EXECUTE format('ALTER TABLE public.%I DROP CONSTRAINT %I', r.table_name, r.constraint_name);
      EXECUTE format(
        'ALTER TABLE public.%I ADD CONSTRAINT %I FOREIGN KEY (%I) REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE',
        r.table_name, r.constraint_name, r.column_name
      );
    END LOOP;
  END $$;

  CREATE OR REPLACE FUNCTION public.f_admin_excluir_conta_validar(p_conta_id uuid)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
  DECLARE
    v_auth_ids uuid[];
    v_conexoes jsonb;
  BEGIN
    PERFORM set_config('row_security', 'off', true);

    IF NOT public.is_super_admin() THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Apenas super admin');
    END IF;

    IF p_conta_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'contaId obrigatório');
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public."SAAS_Contas" WHERE id = p_conta_id) THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Conta não encontrada');
    END IF;

    IF EXISTS (
      SELECT 1 FROM public."SAAS_Usuarios"
      WHERE "contaId" = p_conta_id AND auth_user_id = auth.uid()
    ) THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Você não pode excluir a própria conta');
    END IF;

    IF EXISTS (
      SELECT 1 FROM public."SAAS_Usuarios"
      WHERE "contaId" = p_conta_id AND super_admin IS TRUE
    ) THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Não é possível excluir uma conta de super admin');
    END IF;

    SELECT COALESCE(array_agg(DISTINCT uid), '{}')
    INTO v_auth_ids
    FROM (
      SELECT u.auth_user_id AS uid
      FROM public."SAAS_Usuarios" u
      WHERE u."contaId" = p_conta_id AND u.auth_user_id IS NOT NULL
      UNION
      SELECT u.id
      FROM public."SAAS_Usuarios" u
      JOIN auth.users au ON au.id = u.id
      WHERE u."contaId" = p_conta_id
      UNION
      SELECT au.id
      FROM public."SAAS_Usuarios" u
      JOIN auth.users au ON lower(au.email) = lower(u."Email")
      WHERE u."contaId" = p_conta_id AND u."Email" IS NOT NULL
      UNION
      SELECT au.id
      FROM public."SAAS_Contas" c
      JOIN auth.users au ON lower(au.email) = lower(c.email)
      WHERE c.id = p_conta_id AND c.email IS NOT NULL
    ) s;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', cx.id,
      'instanceName', cx."instanceName",
      'apikey', cx."Apikey",
      'apiOficial', COALESCE(cx."apiOficial", false),
      'provedorApi', COALESCE(cx."provedorApi", 'evolution'),
      'urlApi', cx."urlApi"
    )), '[]'::jsonb)
    INTO v_conexoes
    FROM public."SAAS_Conexões" cx
    WHERE cx."contaId" = p_conta_id;

    RETURN jsonb_build_object(
      'ok', true,
      'contaId', p_conta_id,
      'auth_ids', to_jsonb(v_auth_ids),
      'conexoes', v_conexoes
    );
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_admin_excluir_conta_cascade(p_conta_id uuid)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
  DECLARE
    r record;
    i int;
    conv_ids bigint[];
    disp_ids bigint[];
    quadro_ids bigint[];
    etiqueta_ids bigint[];
  BEGIN
    PERFORM set_config('row_security', 'off', true);

    IF NOT public.is_super_admin() THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Apenas super admin');
    END IF;

    IF p_conta_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'contaId obrigatório');
    END IF;

    BEGIN
      EXECUTE 'SET LOCAL session_replication_role = replica';
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;

    -- SAAS_Grupos / idLista foram migrados: grupos vivem em SAAS_Contatos (tipo=grupo) e vínculos em SAAS_Contatos_Etiquetas
    SELECT COALESCE(array_agg(DISTINCT eid), '{}') INTO etiqueta_ids
    FROM (
      SELECT e.id AS eid FROM public."SAAS_Etiquetas" e WHERE e."contaId" = p_conta_id
      UNION
      SELECT e.id FROM public."SAAS_Etiquetas" e
      WHERE e."contaId" IS NULL
        AND EXISTS (
          SELECT 1 FROM public."SAAS_Contatos_Etiquetas" ce
          WHERE ce."etiquetaId" = e.id
            AND (ce."contaId" = p_conta_id OR ce."contatoId" IN (SELECT c.id FROM public."SAAS_Contatos" c WHERE c."contaId" = p_conta_id))
        )
    ) s;

    IF to_regclass('public."SAAS_Contatos_Etiquetas"') IS NOT NULL THEN
      DELETE FROM public."SAAS_Contatos_Etiquetas"
      WHERE "contaId" = p_conta_id
         OR "contatoId" IN (SELECT id FROM public."SAAS_Contatos" WHERE "contaId" = p_conta_id)
         OR "etiquetaId" = ANY (etiqueta_ids);
    END IF;

    IF to_regclass('public."SAAS_Valores_Campos_Personalizados"') IS NOT NULL THEN
      DELETE FROM public."SAAS_Valores_Campos_Personalizados"
      WHERE "contaId" = p_conta_id
         OR "idContato" IN (SELECT id FROM public."SAAS_Contatos" WHERE "contaId" = p_conta_id)
         OR "idCampo" IN (SELECT id FROM public."SAAS_Campos_Personalizados" WHERE "contaId" = p_conta_id);
    END IF;

    IF to_regclass('public."SAAS_Campos_Personalizados"') IS NOT NULL THEN
      DELETE FROM public."SAAS_Campos_Personalizados" WHERE "contaId" = p_conta_id;
    END IF;

    SELECT array_agg(id) INTO conv_ids FROM public."SAAS_Conversas_Agentes" WHERE "contaId" = p_conta_id;
    IF conv_ids IS NOT NULL THEN
      DELETE FROM public."SAAS_Mensagens" WHERE "conversaId" = ANY (conv_ids) OR "contaId" = p_conta_id;
    ELSE
      DELETE FROM public."SAAS_Mensagens" WHERE "contaId" = p_conta_id;
    END IF;
    DELETE FROM public."SAAS_Conversas_Agentes" WHERE "contaId" = p_conta_id;

    SELECT array_agg(id) INTO disp_ids FROM public."SAAS_Disparos" WHERE "contaId" = p_conta_id;
    IF disp_ids IS NOT NULL AND to_regclass('public."SAAS_Detalhes_Disparos"') IS NOT NULL THEN
      DELETE FROM public."SAAS_Detalhes_Disparos" WHERE "idDisparo" = ANY (disp_ids);
    END IF;
    DELETE FROM public."SAAS_Disparos" WHERE "contaId" = p_conta_id;

    DELETE FROM public."SAAS_Contatos" WHERE "contaId" = p_conta_id;
    IF to_regclass('public."SAAS_Grupos"') IS NOT NULL THEN
      DELETE FROM public."SAAS_Grupos" WHERE "contaId" = p_conta_id;
    END IF;
    IF to_regclass('public."SAAS_Listas"') IS NOT NULL THEN
      DELETE FROM public."SAAS_Listas" WHERE "contaId" = p_conta_id;
    END IF;

    IF etiqueta_ids IS NOT NULL AND array_length(etiqueta_ids, 1) > 0 THEN
      DELETE FROM public."SAAS_Etiquetas" WHERE id = ANY (etiqueta_ids);
    END IF;
    DELETE FROM public."SAAS_Etiquetas" WHERE "contaId" = p_conta_id;

    SELECT array_agg(id) INTO quadro_ids FROM public."SAAS_Quadros" WHERE "contaId" = p_conta_id;
    IF quadro_ids IS NOT NULL THEN
      DELETE FROM public."SAAS_Cards_Quadros" WHERE "quadroId" = ANY (quadro_ids);
    END IF;
    DELETE FROM public."SAAS_Etapas_Quadros" WHERE "contaId" = p_conta_id;
    DELETE FROM public."SAAS_Quadros" WHERE "contaId" = p_conta_id;

    DELETE FROM public."SAAS_Conexões" WHERE "contaId" = p_conta_id;
    DELETE FROM public."SAAS_AgentesIA" WHERE "contaId" = p_conta_id;
    DELETE FROM public."SAAS_Webhook" WHERE "contaId" = p_conta_id;
    DELETE FROM public."SAAS_Resposta_Rapidas" WHERE "contaId" = p_conta_id;
    IF to_regclass('public."SAAS_Setores_Gerentes"') IS NOT NULL THEN
      DELETE FROM public."SAAS_Setores_Gerentes" WHERE "contaId" = p_conta_id;
    END IF;
    IF to_regclass('public."SAAS_Setores_Usuarios"') IS NOT NULL THEN
      DELETE FROM public."SAAS_Setores_Usuarios" WHERE "contaId" = p_conta_id;
    END IF;
    IF to_regclass('public."SAAS_Setores"') IS NOT NULL THEN
      DELETE FROM public."SAAS_Setores" WHERE "contaId" = p_conta_id;
    END IF;

    DELETE FROM public."SAAS_Usuarios" WHERE "contaId" = p_conta_id;

    FOR i IN 1..12 LOOP
      FOR r IN
        SELECT c.table_name, c.column_name
        FROM information_schema.columns c
        WHERE c.table_schema = 'public'
          AND c.column_name IN ('contaId', 'conta_id')
          AND c.table_name IS DISTINCT FROM 'SAAS_Contas'
      LOOP
        BEGIN
          EXECUTE format('DELETE FROM public.%I WHERE %I = $1', r.table_name, r.column_name)
          USING p_conta_id;
        EXCEPTION WHEN OTHERS THEN
          NULL;
        END;
      END LOOP;
    END LOOP;

    DELETE FROM public."SAAS_Contas" WHERE id = p_conta_id;

    RETURN jsonb_build_object('ok', true, 'contaId', p_conta_id);
  END;
  $$;

  DROP FUNCTION IF EXISTS public.f_admin_excluir_conta(uuid);

  REVOKE ALL ON FUNCTION public.f_admin_excluir_conta_validar(uuid) FROM PUBLIC;
  REVOKE ALL ON FUNCTION public.f_admin_excluir_conta_cascade(uuid) FROM PUBLIC;
  GRANT EXECUTE ON FUNCTION public.f_admin_excluir_conta_validar(uuid) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.f_admin_excluir_conta_cascade(uuid) TO authenticated;

  -- RLS SAAS_Contas: membros leem; super_admin vê/edita/cria/exclui tudo
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Contas"') IS NOT NULL THEN
      ALTER TABLE public."SAAS_Contas" ENABLE ROW LEVEL SECURITY;
      DROP POLICY IF EXISTS "authenticated_select_contas_membro" ON public."SAAS_Contas";
      CREATE POLICY "authenticated_select_contas_membro" ON public."SAAS_Contas" FOR SELECT TO authenticated USING (id IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
      DROP POLICY IF EXISTS "admin_update_conta" ON public."SAAS_Contas";
      DROP POLICY IF EXISTS "super_admin_all_contas" ON public."SAAS_Contas";
      CREATE POLICY "super_admin_all_contas" ON public."SAAS_Contas" FOR ALL TO authenticated USING ((SELECT public.rls_eh_super_admin())) WITH CHECK ((SELECT public.rls_eh_super_admin()));
      REVOKE INSERT, UPDATE, DELETE ON public."SAAS_Contas" FROM authenticated;
      GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_Contas" TO authenticated;
    END IF;
  END$$;

  -- RLS: tabelas com contaId (admin=CRUD, membro=sem DELETE). Execute migracao-multi-usuarios.sql para RLS completo.
  -- Aqui aplicamos policies nas principais tabelas:
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Conexões"') IS NULL THEN RETURN; END IF;
    ALTER TABLE public."SAAS_Conexões" ENABLE ROW LEVEL SECURITY;
    DROP POLICY IF EXISTS "usuario_crud_conexoes" ON public."SAAS_Conexões";
    DROP POLICY IF EXISTS "select_conexoes" ON public."SAAS_Conexões";
    DROP POLICY IF EXISTS "insert_conexoes" ON public."SAAS_Conexões";
    DROP POLICY IF EXISTS "update_conexoes" ON public."SAAS_Conexões";
    DROP POLICY IF EXISTS "delete_conexoes_admin" ON public."SAAS_Conexões";
    CREATE POLICY "select_conexoes" ON public."SAAS_Conexões" FOR SELECT TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
    CREATE POLICY "insert_conexoes" ON public."SAAS_Conexões" FOR INSERT TO authenticated WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
    CREATE POLICY "update_conexoes" ON public."SAAS_Conexões" FOR UPDATE TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin())) WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
    CREATE POLICY "delete_conexoes_admin" ON public."SAAS_Conexões" FOR DELETE TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids_admin()) OR (SELECT public.rls_eh_super_admin()));
  END$$;

  -- SAAS_Listas foi renomeada para SAAS_Etiquetas. RLS dessa tabela fica no bloco de etiquetas.
  -- Não aplicar policy em SAAS_Listas: em clientes já migrados a relação não existe (42P01).

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Contatos"') IS NULL THEN RETURN; END IF;
    ALTER TABLE public."SAAS_Contatos" ENABLE ROW LEVEL SECURITY;
    DROP POLICY IF EXISTS "usuario_crud_contatos" ON public."SAAS_Contatos";
    DROP POLICY IF EXISTS "select_contatos" ON public."SAAS_Contatos";
    DROP POLICY IF EXISTS "insert_contatos" ON public."SAAS_Contatos";
    DROP POLICY IF EXISTS "update_contatos" ON public."SAAS_Contatos";
    DROP POLICY IF EXISTS "delete_contatos_admin" ON public."SAAS_Contatos";
    CREATE POLICY "select_contatos" ON public."SAAS_Contatos" FOR SELECT TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
    CREATE POLICY "insert_contatos" ON public."SAAS_Contatos" FOR INSERT TO authenticated WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
    CREATE POLICY "update_contatos" ON public."SAAS_Contatos" FOR UPDATE TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin())) WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
    CREATE POLICY "delete_contatos_admin" ON public."SAAS_Contatos" FOR DELETE TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids_admin()) OR (SELECT public.rls_eh_super_admin()));
  END$$;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Grupos"') IS NULL THEN RETURN; END IF;
    ALTER TABLE public."SAAS_Grupos" ENABLE ROW LEVEL SECURITY;
    DROP POLICY IF EXISTS "usuario_crud_grupos" ON public."SAAS_Grupos";
    DROP POLICY IF EXISTS "select_grupos" ON public."SAAS_Grupos";
    DROP POLICY IF EXISTS "insert_grupos" ON public."SAAS_Grupos";
    DROP POLICY IF EXISTS "update_grupos" ON public."SAAS_Grupos";
    DROP POLICY IF EXISTS "delete_grupos_admin" ON public."SAAS_Grupos";
    CREATE POLICY "select_grupos" ON public."SAAS_Grupos" FOR SELECT TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
    CREATE POLICY "insert_grupos" ON public."SAAS_Grupos" FOR INSERT TO authenticated WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
    CREATE POLICY "update_grupos" ON public."SAAS_Grupos" FOR UPDATE TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin())) WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
    CREATE POLICY "delete_grupos_admin" ON public."SAAS_Grupos" FOR DELETE TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids_admin()) OR (SELECT public.rls_eh_super_admin()));
  END$$;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Disparos"') IS NULL THEN RETURN; END IF;
    -- Manter RLS ativa em SAAS_Disparos (multi-tenant por contaId)
    ALTER TABLE public."SAAS_Disparos" ENABLE ROW LEVEL SECURITY;
    DROP POLICY IF EXISTS "usuario_crud_disparos" ON public."SAAS_Disparos";
    DROP POLICY IF EXISTS "select_disparos_do_usuario" ON public."SAAS_Disparos";
    DROP POLICY IF EXISTS "select_disparos" ON public."SAAS_Disparos";
    DROP POLICY IF EXISTS "insert_disparos" ON public."SAAS_Disparos";
    DROP POLICY IF EXISTS "update_disparos" ON public."SAAS_Disparos";
    DROP POLICY IF EXISTS "delete_disparos_admin" ON public."SAAS_Disparos";
    DROP POLICY IF EXISTS "delete_disparos" ON public."SAAS_Disparos";
    DROP POLICY IF EXISTS "delete_disparos_trigger_owner" ON public."SAAS_Disparos";
    CREATE POLICY "select_disparos" ON public."SAAS_Disparos" FOR SELECT TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
    CREATE POLICY "insert_disparos" ON public."SAAS_Disparos" FOR INSERT TO authenticated WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
    CREATE POLICY "update_disparos" ON public."SAAS_Disparos" FOR UPDATE TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin())) WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
    -- DELETE: alinhado a SELECT/UPDATE (membro em SAAS_Usuarios). JWT contaId sozinho bloqueava quem vê o disparo com outra conta ativa no claim.
    CREATE POLICY "delete_disparos" ON public."SAAS_Disparos" FOR DELETE
      USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
    -- Permite cascade do trigger (SECURITY DEFINER) ao excluir conexão (dono da função no Supabase pode ser postgres ou supabase_admin)
    CREATE POLICY "delete_disparos_trigger_owner" ON public."SAAS_Disparos" FOR DELETE TO postgres, supabase_admin USING (true);
  END$$;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Quadros"') IS NULL THEN RETURN; END IF;
    ALTER TABLE public."SAAS_Quadros" ENABLE ROW LEVEL SECURITY;
    DROP POLICY IF EXISTS "usuario_crud_quadros" ON public."SAAS_Quadros";
    DROP POLICY IF EXISTS "select_quadros" ON public."SAAS_Quadros";
    DROP POLICY IF EXISTS "insert_quadros" ON public."SAAS_Quadros";
    DROP POLICY IF EXISTS "update_quadros" ON public."SAAS_Quadros";
    DROP POLICY IF EXISTS "delete_quadros_admin" ON public."SAAS_Quadros";
    CREATE POLICY "select_quadros" ON public."SAAS_Quadros" FOR SELECT TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
    CREATE POLICY "insert_quadros" ON public."SAAS_Quadros" FOR INSERT TO authenticated WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
    CREATE POLICY "update_quadros" ON public."SAAS_Quadros" FOR UPDATE TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin())) WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
    CREATE POLICY "delete_quadros_admin" ON public."SAAS_Quadros" FOR DELETE TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids_admin()) OR (SELECT public.rls_eh_super_admin()));
  END$$;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Etapas_Quadros"') IS NULL THEN RETURN; END IF;
    ALTER TABLE public."SAAS_Etapas_Quadros" ENABLE ROW LEVEL SECURITY;
    DROP POLICY IF EXISTS "usuario_crud_etapas_quadros" ON public."SAAS_Etapas_Quadros";
    DROP POLICY IF EXISTS "select_etapas_quadros" ON public."SAAS_Etapas_Quadros";
    DROP POLICY IF EXISTS "insert_etapas_quadros" ON public."SAAS_Etapas_Quadros";
    DROP POLICY IF EXISTS "update_etapas_quadros" ON public."SAAS_Etapas_Quadros";
    DROP POLICY IF EXISTS "delete_etapas_quadros_admin" ON public."SAAS_Etapas_Quadros";
    CREATE POLICY "select_etapas_quadros" ON public."SAAS_Etapas_Quadros" FOR SELECT TO authenticated
      USING ("contaId" IN (SELECT public.rls_conta_ids()) OR EXISTS (SELECT 1 FROM public."SAAS_Quadros" q WHERE q.id = "quadroId" AND q."contaId" IN (SELECT public.rls_conta_ids())) OR (SELECT public.rls_eh_super_admin()));
    CREATE POLICY "insert_etapas_quadros" ON public."SAAS_Etapas_Quadros" FOR INSERT TO authenticated
      WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR EXISTS (SELECT 1 FROM public."SAAS_Quadros" q WHERE q.id = "quadroId" AND q."contaId" IN (SELECT public.rls_conta_ids())) OR (SELECT public.rls_eh_super_admin()));
    CREATE POLICY "update_etapas_quadros" ON public."SAAS_Etapas_Quadros" FOR UPDATE TO authenticated
      USING ("contaId" IN (SELECT public.rls_conta_ids()) OR EXISTS (SELECT 1 FROM public."SAAS_Quadros" q WHERE q.id = "quadroId" AND q."contaId" IN (SELECT public.rls_conta_ids())) OR (SELECT public.rls_eh_super_admin()))
      WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR EXISTS (SELECT 1 FROM public."SAAS_Quadros" q WHERE q.id = "quadroId" AND q."contaId" IN (SELECT public.rls_conta_ids())) OR (SELECT public.rls_eh_super_admin()));
    CREATE POLICY "delete_etapas_quadros_admin" ON public."SAAS_Etapas_Quadros" FOR DELETE TO authenticated
      USING ("contaId" IN (SELECT public.rls_conta_ids_admin()) OR EXISTS (SELECT 1 FROM public."SAAS_Quadros" q WHERE q.id = "quadroId" AND q."contaId" IN (SELECT public.rls_conta_ids_admin())) OR (SELECT public.rls_eh_super_admin()));
  END$$;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_AgentesIA"') IS NULL THEN RETURN; END IF;
    ALTER TABLE public."SAAS_AgentesIA" ENABLE ROW LEVEL SECURITY;
    DROP POLICY IF EXISTS "usuario_crud_agentes_ia" ON public."SAAS_AgentesIA";
    DROP POLICY IF EXISTS "super_admin_all_agentes_ia" ON public."SAAS_AgentesIA";
    DROP POLICY IF EXISTS "select_agentes_ia" ON public."SAAS_AgentesIA";
    DROP POLICY IF EXISTS "insert_agentes_ia" ON public."SAAS_AgentesIA";
    DROP POLICY IF EXISTS "update_agentes_ia" ON public."SAAS_AgentesIA";
    DROP POLICY IF EXISTS "delete_agentes_ia_admin" ON public."SAAS_AgentesIA";
    -- RLS set-based: mesma regra de can_access_conta / is_admin / is_super_admin.
    CREATE POLICY "super_admin_all_agentes_ia" ON public."SAAS_AgentesIA" FOR ALL TO authenticated
      USING (
        EXISTS (
          SELECT 1 FROM public."SAAS_Usuarios" u
          WHERE u.auth_user_id = (SELECT auth.uid()) AND u.super_admin = true
        )
      )
      WITH CHECK (
        EXISTS (
          SELECT 1 FROM public."SAAS_Usuarios" u
          WHERE u.auth_user_id = (SELECT auth.uid()) AND u.super_admin = true
        )
      );
    CREATE POLICY "select_agentes_ia" ON public."SAAS_AgentesIA" FOR SELECT TO authenticated
      USING (
        "contaId" IN (
          SELECT u."contaId" FROM public."SAAS_Usuarios" u
          WHERE u.auth_user_id = (SELECT auth.uid())
        )
        OR EXISTS (
          SELECT 1 FROM public."SAAS_Usuarios" u
          WHERE u.auth_user_id = (SELECT auth.uid()) AND u.super_admin = true
        )
      );
    CREATE POLICY "insert_agentes_ia" ON public."SAAS_AgentesIA" FOR INSERT TO authenticated
      WITH CHECK (
        "contaId" IN (
          SELECT u."contaId" FROM public."SAAS_Usuarios" u
          WHERE u.auth_user_id = (SELECT auth.uid())
        )
        OR EXISTS (
          SELECT 1 FROM public."SAAS_Usuarios" u
          WHERE u.auth_user_id = (SELECT auth.uid()) AND u.super_admin = true
        )
      );
    CREATE POLICY "update_agentes_ia" ON public."SAAS_AgentesIA" FOR UPDATE TO authenticated
      USING (
        "contaId" IN (
          SELECT u."contaId" FROM public."SAAS_Usuarios" u
          WHERE u.auth_user_id = (SELECT auth.uid())
        )
        OR EXISTS (
          SELECT 1 FROM public."SAAS_Usuarios" u
          WHERE u.auth_user_id = (SELECT auth.uid()) AND u.super_admin = true
        )
      )
      WITH CHECK (
        "contaId" IN (
          SELECT u."contaId" FROM public."SAAS_Usuarios" u
          WHERE u.auth_user_id = (SELECT auth.uid())
        )
        OR EXISTS (
          SELECT 1 FROM public."SAAS_Usuarios" u
          WHERE u.auth_user_id = (SELECT auth.uid()) AND u.super_admin = true
        )
      );
    CREATE POLICY "delete_agentes_ia_admin" ON public."SAAS_AgentesIA" FOR DELETE TO authenticated
      USING (
        "contaId" IN (
          SELECT u."contaId" FROM public."SAAS_Usuarios" u
          WHERE u.auth_user_id = (SELECT auth.uid()) AND u.funcao = 'admin'
        )
        OR EXISTS (
          SELECT 1 FROM public."SAAS_Usuarios" u
          WHERE u.auth_user_id = (SELECT auth.uid()) AND u.super_admin = true
        )
      );
  END$$;

