    CREATE POLICY "update_webhook" ON public."SAAS_Webhook" FOR UPDATE TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin())) WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
    CREATE POLICY "delete_webhook_admin" ON public."SAAS_Webhook" FOR DELETE TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids_admin()) OR (SELECT public.rls_eh_super_admin()));
  END$$;

