    ALTER TABLE public."SAAS_Resposta_Rapidas" ENABLE ROW LEVEL SECURITY;
    DROP POLICY IF EXISTS "usuario_crud_resposta_rapidas" ON public."SAAS_Resposta_Rapidas";
    DROP POLICY IF EXISTS "select_resposta_rapidas" ON public."SAAS_Resposta_Rapidas";
