    DROP POLICY IF EXISTS "update_resposta_rapidas" ON public."SAAS_Resposta_Rapidas";
    DROP POLICY IF EXISTS "delete_resposta_rapidas_admin" ON public."SAAS_Resposta_Rapidas";
    CREATE POLICY "select_resposta_rapidas" ON public."SAAS_Resposta_Rapidas" FOR SELECT TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
    CREATE POLICY "insert_resposta_rapidas" ON public."SAAS_Resposta_Rapidas" FOR INSERT TO authenticated WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
    CREATE POLICY "update_resposta_rapidas" ON public."SAAS_Resposta_Rapidas" FOR UPDATE TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin())) WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
    CREATE POLICY "delete_resposta_rapidas_admin" ON public."SAAS_Resposta_Rapidas" FOR DELETE TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids_admin()) OR (SELECT public.rls_eh_super_admin()));
