  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Detalhes_Disparos"') IS NULL THEN RETURN; END IF;
    -- Manter RLS ativa em SAAS_Detalhes_Disparos (multi-tenant via disparo pai)
    ALTER TABLE public."SAAS_Detalhes_Disparos" ENABLE ROW LEVEL SECURITY;
    DROP POLICY IF EXISTS "authenticated_select_detalhes_do_disparo" ON public."SAAS_Detalhes_Disparos";
    DROP POLICY IF EXISTS "select_detalhes_disparos" ON public."SAAS_Detalhes_Disparos";
    DROP POLICY IF EXISTS "insert_detalhes_disparos" ON public."SAAS_Detalhes_Disparos";
    DROP POLICY IF EXISTS "update_detalhes_disparos" ON public."SAAS_Detalhes_Disparos";
    DROP POLICY IF EXISTS "delete_detalhes_disparos_admin" ON public."SAAS_Detalhes_Disparos";
    DROP POLICY IF EXISTS "delete_detalhes_disparos" ON public."SAAS_Detalhes_Disparos";
    DROP POLICY IF EXISTS "delete_detalhes_disparos_trigger_owner" ON public."SAAS_Detalhes_Disparos";
    CREATE POLICY "select_detalhes_disparos" ON public."SAAS_Detalhes_Disparos" FOR SELECT TO authenticated
      USING (EXISTS (SELECT 1 FROM public."SAAS_Disparos" h WHERE h.id = "SAAS_Detalhes_Disparos"."idDisparo" AND (h."contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()))));
    CREATE POLICY "insert_detalhes_disparos" ON public."SAAS_Detalhes_Disparos" FOR INSERT TO authenticated
      WITH CHECK (EXISTS (SELECT 1 FROM public."SAAS_Disparos" h WHERE h.id = "SAAS_Detalhes_Disparos"."idDisparo" AND (h."contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()))));
    CREATE POLICY "update_detalhes_disparos" ON public."SAAS_Detalhes_Disparos" FOR UPDATE TO authenticated
      USING (EXISTS (SELECT 1 FROM public."SAAS_Disparos" h WHERE h.id = "SAAS_Detalhes_Disparos"."idDisparo" AND (h."contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()))))
      WITH CHECK (EXISTS (SELECT 1 FROM public."SAAS_Disparos" h WHERE h.id = "SAAS_Detalhes_Disparos"."idDisparo" AND (h."contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()))));
    -- DELETE: mesmo critério do SELECT (can_access_conta no disparo pai)
    CREATE POLICY "delete_detalhes_disparos" ON public."SAAS_Detalhes_Disparos" FOR DELETE
      USING (
        EXISTS (
          SELECT 1
          FROM public."SAAS_Disparos" h
          WHERE h.id = "SAAS_Detalhes_Disparos"."idDisparo"
            AND (h."contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()))
        )
      );
    -- Permite cascade do trigger (SECURITY DEFINER) ao excluir conexão (dono da função no Supabase pode ser postgres ou supabase_admin)
    CREATE POLICY "delete_detalhes_disparos_trigger_owner" ON public."SAAS_Detalhes_Disparos" FOR DELETE TO postgres, supabase_admin USING (true);
  END$$;

