    CREATE POLICY "insert_cards_quadros" ON public."SAAS_Cards_Quadros" FOR INSERT TO authenticated
      WITH CHECK (EXISTS (SELECT 1 FROM public."SAAS_Quadros" q WHERE q.id = "quadroId" AND (q."contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()))));
    CREATE POLICY "update_cards_quadros" ON public."SAAS_Cards_Quadros" FOR UPDATE TO authenticated
      USING (EXISTS (SELECT 1 FROM public."SAAS_Quadros" q WHERE q.id = "quadroId" AND (q."contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()))))
      WITH CHECK (EXISTS (SELECT 1 FROM public."SAAS_Quadros" q WHERE q.id = "quadroId" AND (q."contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()))));
    CREATE POLICY "delete_cards_quadros_admin" ON public."SAAS_Cards_Quadros" FOR DELETE TO authenticated
      USING (EXISTS (SELECT 1 FROM public."SAAS_Quadros" q WHERE q.id = "quadroId" AND (q."contaId" IN (SELECT public.rls_conta_ids_admin()) OR (SELECT public.rls_eh_super_admin()))));
