  -- RLS SAAS_Conversas_Agentes: se atendente vinculado, só ele ou admin da conta vê; senão, membros da conta
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Conversas_Agentes"') IS NULL THEN RETURN; END IF;
    ALTER TABLE public."SAAS_Conversas_Agentes" ENABLE ROW LEVEL SECURITY;
    DROP POLICY IF EXISTS "service_role_full_access" ON public."SAAS_Conversas_Agentes";
    DROP POLICY IF EXISTS "select_conversas" ON public."SAAS_Conversas_Agentes";
    DROP POLICY IF EXISTS "insert_conversas" ON public."SAAS_Conversas_Agentes";
    DROP POLICY IF EXISTS "update_conversas" ON public."SAAS_Conversas_Agentes";
    DROP POLICY IF EXISTS "delete_conversas_admin" ON public."SAAS_Conversas_Agentes";
    DROP POLICY IF EXISTS "usuario_crud_conversas_agentes" ON public."SAAS_Conversas_Agentes";
    CREATE POLICY "service_role_full_access" ON public."SAAS_Conversas_Agentes" TO service_role USING (true) WITH CHECK (true);
    CREATE POLICY "select_conversas" ON public."SAAS_Conversas_Agentes" FOR SELECT TO authenticated
      USING ((
        "contaId" IN (SELECT public.rls_conta_ids_admin())
        OR atendente IN (SELECT u.id FROM public."SAAS_Usuarios" u WHERE u.auth_user_id = (SELECT auth.uid()))
        OR (atendente IS NULL AND "contaId" IN (SELECT public.rls_conta_ids()))
      ));
    CREATE POLICY "insert_conversas" ON public."SAAS_Conversas_Agentes" FOR INSERT TO authenticated
      WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()));
    CREATE POLICY "update_conversas" ON public."SAAS_Conversas_Agentes" FOR UPDATE TO authenticated
      USING ((
        "contaId" IN (SELECT public.rls_conta_ids_admin())
        OR atendente IN (SELECT u.id FROM public."SAAS_Usuarios" u WHERE u.auth_user_id = (SELECT auth.uid()))
        OR (atendente IS NULL AND "contaId" IN (SELECT public.rls_conta_ids()))
      )) WITH CHECK ((
        "contaId" IN (SELECT public.rls_conta_ids_admin())
        OR atendente IN (SELECT u.id FROM public."SAAS_Usuarios" u WHERE u.auth_user_id = (SELECT auth.uid()))
        OR (atendente IS NULL AND "contaId" IN (SELECT public.rls_conta_ids()))
      ));
    CREATE POLICY "delete_conversas_admin" ON public."SAAS_Conversas_Agentes" FOR DELETE TO authenticated
      USING ("contaId" IN (SELECT public.rls_conta_ids_admin()));
    GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_Conversas_Agentes" TO authenticated;
  END$$;

  -- RLS SAAS_Mensagens: vê mensagens apenas das conversas que pode ver (regra atendente/admin)
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Mensagens"') IS NULL THEN RETURN; END IF;
    ALTER TABLE public."SAAS_Mensagens" ENABLE ROW LEVEL SECURITY;
    DROP POLICY IF EXISTS "service_role_full_access" ON public."SAAS_Mensagens";
    DROP POLICY IF EXISTS "select_mensagens" ON public."SAAS_Mensagens";
