    DROP POLICY IF EXISTS "update_mensagens" ON public."SAAS_Mensagens";
    DROP POLICY IF EXISTS "delete_mensagens" ON public."SAAS_Mensagens";
    DROP POLICY IF EXISTS "usuario_crud_mensagens" ON public."SAAS_Mensagens";
    CREATE POLICY "service_role_full_access" ON public."SAAS_Mensagens" TO service_role USING (true) WITH CHECK (true);
    CREATE POLICY "select_mensagens" ON public."SAAS_Mensagens" FOR SELECT TO authenticated
      USING (EXISTS (
        SELECT 1 FROM public."SAAS_Conversas_Agentes" c
        WHERE c.id = "SAAS_Mensagens"."conversaId"
          AND (
              c."contaId" IN (SELECT public.rls_conta_ids_admin())
              OR c.atendente IN (SELECT u.id FROM public."SAAS_Usuarios" u WHERE u.auth_user_id = (SELECT auth.uid()))
              OR (c.atendente IS NULL AND c."contaId" IN (SELECT public.rls_conta_ids()))
            )
      ));
    CREATE POLICY "insert_mensagens" ON public."SAAS_Mensagens" FOR INSERT TO authenticated
      WITH CHECK (EXISTS (
        SELECT 1 FROM public."SAAS_Conversas_Agentes" c
        WHERE c.id = "SAAS_Mensagens"."conversaId"
          AND c."contaId" IN (SELECT public.rls_conta_ids())
      ));
    CREATE POLICY "update_mensagens" ON public."SAAS_Mensagens" FOR UPDATE TO authenticated
      USING (EXISTS (
        SELECT 1 FROM public."SAAS_Conversas_Agentes" c
        WHERE c.id = "SAAS_Mensagens"."conversaId"
          AND (
              c."contaId" IN (SELECT public.rls_conta_ids_admin())
              OR c.atendente IN (SELECT u.id FROM public."SAAS_Usuarios" u WHERE u.auth_user_id = (SELECT auth.uid()))
              OR (c.atendente IS NULL AND c."contaId" IN (SELECT public.rls_conta_ids()))
            )
      ));
    CREATE POLICY "delete_mensagens" ON public."SAAS_Mensagens" FOR DELETE TO authenticated
      USING (EXISTS (
        SELECT 1 FROM public."SAAS_Conversas_Agentes" c
        WHERE c.id = "SAAS_Mensagens"."conversaId"
          AND c."contaId" IN (SELECT public.rls_conta_ids_admin())
      ));
    GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_Mensagens" TO authenticated;
  END$$;

  DO $$
  BEGIN
    -- SAAS_Planos: todos autenticados podem apenas visualizar; só super_admin pode criar/editar/excluir
    IF to_regclass('public."SAAS_Planos"') IS NOT NULL THEN
      ALTER TABLE public."SAAS_Planos" ENABLE ROW LEVEL SECURITY;
      DROP POLICY IF EXISTS "service_role_full_access" ON public."SAAS_Planos";
      CREATE POLICY "service_role_full_access" ON public."SAAS_Planos" TO service_role USING (true) WITH CHECK (true);
      DROP POLICY IF EXISTS "authenticated_select_planos" ON public."SAAS_Planos";
      CREATE POLICY "authenticated_select_planos" ON public."SAAS_Planos" FOR SELECT TO authenticated USING (true);
      DROP POLICY IF EXISTS "super_admin_planos" ON public."SAAS_Planos";
      CREATE POLICY "super_admin_planos" ON public."SAAS_Planos" FOR ALL TO authenticated USING ((SELECT public.rls_eh_super_admin())) WITH CHECK ((SELECT public.rls_eh_super_admin()));
      GRANT SELECT ON public."SAAS_Planos" TO authenticated;
      GRANT INSERT, UPDATE, DELETE ON public."SAAS_Planos" TO authenticated;
    END IF;
    -- SAAS_Versao: authenticated apenas SELECT
    IF to_regclass('public."SAAS_Versao"') IS NOT NULL THEN
      ALTER TABLE public."SAAS_Versao" ENABLE ROW LEVEL SECURITY;
      DROP POLICY IF EXISTS "versao_select_authenticated" ON public."SAAS_Versao";
      CREATE POLICY "versao_select_authenticated" ON public."SAAS_Versao"
        FOR SELECT TO authenticated USING (true);
      REVOKE INSERT, UPDATE, DELETE ON public."SAAS_Versao" FROM authenticated;
      GRANT SELECT ON public."SAAS_Versao" TO authenticated;
    END IF;
  END$$;

  -- =========================
  -- Triggers (disparos, bloqueios, reordenação, conversas, auth)
  -- =========================
  DROP TRIGGER IF EXISTS trg_start_disparo ON public."SAAS_Detalhes_Disparos";
  CREATE TRIGGER trg_start_disparo AFTER UPDATE ON public."SAAS_Detalhes_Disparos"
  FOR EACH ROW EXECUTE FUNCTION public.f_start_disparo();

  DROP TRIGGER IF EXISTS trg_finalize_disparo ON public."SAAS_Detalhes_Disparos";
  CREATE TRIGGER trg_finalize_disparo AFTER UPDATE ON public."SAAS_Detalhes_Disparos"
  FOR EACH ROW EXECUTE FUNCTION public.f_finalize_disparo();

  -- Trigger de bloqueio em SAAS_Listas omitido: tabela vira SAAS_Etiquetas; exclusão usa f_excluir_etiqueta.

  DROP TRIGGER IF EXISTS trg_block_delete_contato_if_active ON public."SAAS_Contatos";
  CREATE TRIGGER trg_block_delete_contato_if_active BEFORE DELETE ON public."SAAS_Contatos"
  FOR EACH ROW EXECUTE FUNCTION public.f_block_delete_contato_if_active();

  DO $$ BEGIN IF to_regclass('public."SAAS_Grupos"') IS NOT NULL THEN DROP TRIGGER IF EXISTS trg_block_delete_grupo_if_active ON public."SAAS_Grupos"; CREATE TRIGGER trg_block_delete_grupo_if_active BEFORE DELETE ON public."SAAS_Grupos" FOR EACH ROW EXECUTE FUNCTION public.f_block_delete_grupo_if_active(); END IF; END $$;

  -- Plano Free não pode ser excluído (nem por super_admin)
  CREATE OR REPLACE FUNCTION public.f_block_delete_plano_free()
  RETURNS trigger LANGUAGE plpgsql AS $$
  BEGIN
    IF OLD.nome = 'Free' THEN
      RAISE EXCEPTION 'O plano Free não pode ser excluído.';
    END IF;
    RETURN OLD;
  END;
  $$;
  DROP TRIGGER IF EXISTS trg_block_delete_plano_free ON public."SAAS_Planos";
  CREATE TRIGGER trg_block_delete_plano_free BEFORE DELETE ON public."SAAS_Planos"
  FOR EACH ROW EXECUTE FUNCTION public.f_block_delete_plano_free();

  DROP TRIGGER IF EXISTS trg_reordenar_etapas_quadro ON public."SAAS_Etapas_Quadros";
  CREATE TRIGGER trg_reordenar_etapas_quadro BEFORE UPDATE OF ordem ON public."SAAS_Etapas_Quadros"
  FOR EACH ROW WHEN (OLD.ordem IS DISTINCT FROM NEW.ordem) EXECUTE FUNCTION public.f_reordenar_etapas_quadro();

  -- Toda mudança de etapa do card (arrastar no Kanban, chat, contatos, agente IA, API) entra no
  -- historicoCRM com a data. É dessa data que a dashboard tira quando a venda/agendamento aconteceu.
  -- Se quem moveu já gravou a movimentação na mesma escrita (ex.: agente IA), não duplica.
  CREATE OR REPLACE FUNCTION public.f_cards_historico_etapa()
  RETURNS TRIGGER LANGUAGE plpgsql SET search_path = public AS $$
  DECLARE
    v_hist JSONB; v_ult JSONB; v_qtd_antes INT := 0; v_origem_nome TEXT; v_destino_nome TEXT;
  BEGIN
    IF NEW."etapaQuadroId" IS NULL THEN RETURN NEW; END IF;
    IF TG_OP = 'UPDATE' AND NEW."etapaQuadroId" IS NOT DISTINCT FROM OLD."etapaQuadroId" THEN RETURN NEW; END IF;

    v_hist := CASE WHEN jsonb_typeof(NEW."historicoCRM") = 'array' THEN NEW."historicoCRM" ELSE '[]'::jsonb END;
    IF TG_OP = 'UPDATE' AND jsonb_typeof(OLD."historicoCRM") = 'array' THEN
      v_qtd_antes := jsonb_array_length(OLD."historicoCRM");
    END IF;
    SELECT nome INTO v_destino_nome FROM public."SAAS_Etapas_Quadros" WHERE id = NEW."etapaQuadroId";
    IF TG_OP = 'UPDATE' AND OLD."etapaQuadroId" IS NOT NULL THEN
      SELECT nome INTO v_origem_nome FROM public."SAAS_Etapas_Quadros" WHERE id = OLD."etapaQuadroId";
    END IF;

    IF jsonb_array_length(v_hist) > v_qtd_antes THEN
      v_ult := v_hist -> -1;
      IF COALESCE(v_ult->>'etapaDestinoId', v_ult->>'para', v_ult->>'etapaId', v_ult->>'etapa') = NEW."etapaQuadroId"::text THEN
        -- Já registrado por quem moveu: só completa os nomes das etapas (o que já veio prevalece).
        NEW."historicoCRM" := (v_hist - -1) || jsonb_build_array(
          jsonb_strip_nulls(jsonb_build_object('etapaOrigemNome', v_origem_nome, 'etapaDestinoNome', v_destino_nome)) || v_ult
        );
        RETURN NEW;
      END IF;
    END IF;

    NEW."historicoCRM" := v_hist || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'tipo', CASE WHEN TG_OP = 'INSERT' THEN 'criacao' ELSE 'movimentacao' END,
      'titulo', CASE WHEN TG_OP = 'INSERT' THEN 'Card criado em ' || COALESCE(v_destino_nome, 'etapa ' || NEW."etapaQuadroId") END,
      'etapaOrigemId', CASE WHEN TG_OP = 'UPDATE' THEN OLD."etapaQuadroId" END,
      'etapaOrigemNome', v_origem_nome,
      'etapaDestinoId', NEW."etapaQuadroId",
      'etapaDestinoNome', v_destino_nome,
      'data', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
    )));
    RETURN NEW;
  END;
  $$;

  DROP TRIGGER IF EXISTS trg_cards_historico_etapa ON public."SAAS_Cards_Quadros";
  CREATE TRIGGER trg_cards_historico_etapa BEFORE INSERT OR UPDATE OF "etapaQuadroId" ON public."SAAS_Cards_Quadros"
  FOR EACH ROW EXECUTE FUNCTION public.f_cards_historico_etapa();

  DROP TRIGGER IF EXISTS trg_reordenar_cards_quadro ON public."SAAS_Cards_Quadros";
  CREATE TRIGGER trg_reordenar_cards_quadro BEFORE UPDATE OF ordem ON public."SAAS_Cards_Quadros"
  FOR EACH ROW WHEN (OLD.ordem IS DISTINCT FROM NEW.ordem) EXECUTE FUNCTION public.f_reordenar_cards_quadro();

  DROP TRIGGER IF EXISTS trg_sync_pausado_status_atendimento ON public."SAAS_Conversas_Agentes";
  CREATE TRIGGER trg_sync_pausado_status_atendimento BEFORE INSERT OR UPDATE ON public."SAAS_Conversas_Agentes"
  FOR EACH ROW EXECUTE FUNCTION public.f_sync_pausado_status_atendimento();

  DROP TRIGGER IF EXISTS trg_set_data_fechamento_conversa ON public."SAAS_Conversas_Agentes";
  CREATE TRIGGER trg_set_data_fechamento_conversa BEFORE INSERT OR UPDATE OF "statusAtendimento" ON public."SAAS_Conversas_Agentes"
  FOR EACH ROW EXECUTE FUNCTION public.f_set_data_fechamento_conversa();

  DROP TRIGGER IF EXISTS trg_auth_to_saas_usuarios_mirror ON auth.users;
  CREATE TRIGGER trg_auth_to_saas_usuarios_mirror AFTER INSERT OR UPDATE OF email, phone, raw_user_meta_data ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.f_auth_to_saas_usuarios_mirror();

  -- =========================
  -- REALTIME (Supabase) – Conversas e Mensagens (chat: sidebar + mensagens)
  -- Bancos novos e antigos: reaplica funções RLS compatíveis com Realtime e republica as tabelas.
  -- Sintoma corrigido: mensagens em tempo real OK, mas nova conversa só aparecia após F5.
  -- =========================

  -- Reaplica funções da cadeia RLS (instalações antigas podem ainda ter row_security off).
  CREATE OR REPLACE FUNCTION public.get_conta_ids_usuario()
  RETURNS uuid[] LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
  DECLARE arr uuid[];
  BEGIN
    SELECT array_agg("contaId") INTO arr FROM public."SAAS_Usuarios" WHERE auth_user_id = auth.uid();
    RETURN COALESCE(arr, ARRAY[]::uuid[]);
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.is_super_admin()
  RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
  BEGIN
    RETURN EXISTS (SELECT 1 FROM public."SAAS_Usuarios" WHERE auth_user_id = auth.uid() AND super_admin = true);
  END;
  $$;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Conversas_Agentes"') IS NOT NULL THEN
      DROP POLICY IF EXISTS "usuario_crud_conversas_agentes" ON public."SAAS_Conversas_Agentes";
    END IF;
    IF to_regclass('public."SAAS_Mensagens"') IS NOT NULL THEN
      DROP POLICY IF EXISTS "usuario_crud_mensagens" ON public."SAAS_Mensagens";
    END IF;
  END$$;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Conversas_Agentes"') IS NULL THEN RETURN; END IF;
    BEGIN
      ALTER PUBLICATION supabase_realtime DROP TABLE public."SAAS_Conversas_Agentes";
    EXCEPTION
      WHEN undefined_object THEN NULL;
      WHEN OTHERS THEN NULL;
    END;
    ALTER PUBLICATION supabase_realtime ADD TABLE public."SAAS_Conversas_Agentes";
  EXCEPTION
    WHEN duplicate_object THEN NULL;
    WHEN undefined_object THEN NULL;
  END$$;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Mensagens"') IS NULL THEN RETURN; END IF;
    BEGIN
      ALTER PUBLICATION supabase_realtime DROP TABLE public."SAAS_Mensagens";
    EXCEPTION
      WHEN undefined_object THEN NULL;
      WHEN OTHERS THEN NULL;
    END;
    ALTER PUBLICATION supabase_realtime ADD TABLE public."SAAS_Mensagens";
  EXCEPTION
    WHEN duplicate_object THEN NULL;
    WHEN undefined_object THEN NULL;
  END$$;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Contatos_Etiquetas"') IS NULL THEN RETURN; END IF;
    BEGIN
      ALTER PUBLICATION supabase_realtime DROP TABLE public."SAAS_Contatos_Etiquetas";
    EXCEPTION
      WHEN undefined_object THEN NULL;
      WHEN OTHERS THEN NULL;
    END;
    ALTER PUBLICATION supabase_realtime ADD TABLE public."SAAS_Contatos_Etiquetas";
  EXCEPTION
    WHEN duplicate_object THEN NULL;
    WHEN undefined_object THEN NULL;
  END$$;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Conversas_Agentes"') IS NOT NULL THEN
      ALTER TABLE public."SAAS_Conversas_Agentes" REPLICA IDENTITY FULL;
    END IF;
    IF to_regclass('public."SAAS_Mensagens"') IS NOT NULL THEN
      ALTER TABLE public."SAAS_Mensagens" REPLICA IDENTITY FULL;
    END IF;
    IF to_regclass('public."SAAS_Contatos_Etiquetas"') IS NOT NULL THEN
      ALTER TABLE public."SAAS_Contatos_Etiquetas" REPLICA IDENTITY FULL;
    END IF;
  END$$;

  -- SAAS_Contatos (schema legado do CREATE TABLE inicial): views abaixo usam tipo/variaveis antes do bloco de migração etiquetas
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Contatos"') IS NULL THEN RETURN; END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Contatos' AND column_name = 'atributos')
      AND NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Contatos' AND column_name = 'variaveis') THEN
      ALTER TABLE public."SAAS_Contatos" RENAME COLUMN atributos TO variaveis;
    END IF;
  END $$;
  ALTER TABLE public."SAAS_Contatos" ADD COLUMN IF NOT EXISTS tipo TEXT NOT NULL DEFAULT 'contato' CHECK (tipo IN ('contato', 'grupo'));
  ALTER TABLE public."SAAS_Contatos" ADD COLUMN IF NOT EXISTS variaveis JSONB NOT NULL DEFAULT '{}';

  -- Views (formato multi-usuários)
  CREATE OR REPLACE VIEW public."vw_Planos_Usuarios_Count" WITH (security_invoker = true) AS
  SELECT p.id, p.created_at, p.nome, p.preco, p."qntConexoes", p."qntContatos", p."qntDisparos",
    COUNT(c.id) AS total_usuarios, p."qntUsuarios", p."qntQuadros", p."qntAgentesIa", p."qntCreditosIa", p.menu_ocultar,
    p."apiNaoOficial", p."liberarApiOficial", p."liberarEmail", p."diasValidade", p."iaChaveCliente"
  FROM public."SAAS_Planos" p
  LEFT JOIN public."SAAS_Contas" c ON c.plano = p.id
  GROUP BY p.id, p.created_at, p.nome, p.preco, p."qntConexoes", p."qntContatos", p."qntDisparos", p."qntUsuarios", p."qntQuadros", p."qntAgentesIa", p."qntCreditosIa", p.menu_ocultar, p."apiNaoOficial", p."liberarApiOficial", p."liberarEmail", p."diasValidade", p."iaChaveCliente";

  -- vw_Detalhes_Completo: modelo novo (etiquetas) - grupos são contatos com tipo='grupo'
  DROP VIEW IF EXISTS public."vw_Detalhes_Completo" CASCADE;
  CREATE OR REPLACE VIEW public."vw_Detalhes_Completo" WITH (security_invoker = true) AS
  SELECT d.id, d."idDisparo", d."idContato", d."Mensagem", d."idConexao", d."dataEnvio", d."Status", d."statusHttp", d."mensagemErro", d."respostaHttp", d."Payload", d."KeyRedis", d."FakeCall",
    disp."StatusDisparo",
    CASE WHEN c.tipo = 'contato' THEN c.telefone ELSE NULL END AS "TelefoneContato",
    c.variaveis->>'whatsappId' AS "WhatsAppIdGrupo",
    c.nome AS "NomeGrupo",
    cx."instanceName" AS "InstanceName", cx."Apikey" AS "ApikeyConexao",
    COALESCE(cx."provedorApi", 'evolution') AS "provedorApi",
    cx."urlApi" AS "urlApi",
    disp."contaId" AS "UserId", cx."NomeConexao", disp."TipoDisparo"
  FROM public."SAAS_Detalhes_Disparos" d
  LEFT JOIN public."SAAS_Disparos" disp ON disp.id = d."idDisparo"
  LEFT JOIN public."SAAS_Contatos" c ON c.id = d."idContato"
  LEFT JOIN public."SAAS_Conexões" cx ON cx.id = d."idConexao";

  CREATE OR REPLACE VIEW public."vw_Contas_Com_Plano" WITH (security_invoker = true) AS
  SELECT c.id, c.status, c."dataValidade", c.plano AS plano_id, p.nome AS plano_nome, p.preco AS plano_preco, p.created_at AS plano_created_at,
    CASE WHEN COALESCE(c.status, false) THEN p."qntConexoes" ELSE 0 END AS "plano_qntConexoes",
    CASE WHEN COALESCE(c.status, false) THEN p."qntContatos" ELSE 0 END AS "plano_qntContatos",
    CASE WHEN COALESCE(c.status, false) THEN p."qntDisparos" ELSE 0 END AS "plano_qntDisparos",
    CASE WHEN COALESCE(c.status, false) THEN p."qntQuadros" ELSE 0 END AS "plano_qntQuadros",
    CASE WHEN COALESCE(c.status, false) THEN p."qntAgentesIa" ELSE 0 END AS "planoQntAgentes",
    CASE WHEN NOT COALESCE(c.status, false) THEN 0
         WHEN COALESCE(p."iaChaveCliente", false) THEN NULL
         ELSE p."qntCreditosIa" END AS "planoQntCreditos",
    COALESCE(p."apiNaoOficial", 'evolution') AS "apiNaoOficial",
    COALESCE(p."liberarApiOficial", false) AS "liberarApiOficial",
    COALESCE(p."liberarEmail", false) AS "liberarEmail",
    COALESCE(p."iaChaveCliente", false) AS "iaChaveCliente",
    COALESCE(cx.total_conexoes, 0::bigint) AS total_conexoes,
    COALESCE(ct.total_contatos, 0::bigint) AS total_contatos, COALESCE(dd.total_disparos, 0::bigint) AS total_disparos,
    COALESCE(qd.total_quadros, 0::bigint) AS total_quadros,
    COALESCE(ag.total_agentes, 0::bigint) AS total_agentes,
    COALESCE(uc.total_creditos, 0::numeric) AS total_creditos,
    CASE WHEN COALESCE(c.status, false) THEN p."qntUsuarios" ELSE 0 END AS "planoQntUsuarios",
    COALESCE(us.total_usuarios, 0::bigint) AS total_usuarios
  FROM public."SAAS_Contas" c
  LEFT JOIN public."SAAS_Planos" p ON p.id = c.plano
  LEFT JOIN (SELECT "contaId", COUNT(*) AS total_conexoes FROM public."SAAS_Conexões" GROUP BY "contaId") cx ON cx."contaId" = c.id
  LEFT JOIN (SELECT "contaId", COUNT(*) AS total_contatos FROM public."SAAS_Contatos" GROUP BY "contaId") ct ON ct."contaId" = c.id
  LEFT JOIN (SELECT h."contaId" AS uid, COUNT(*) AS total_disparos FROM public."SAAS_Detalhes_Disparos" d JOIN public."SAAS_Disparos" h ON h.id = d."idDisparo"
    WHERE d."dataEnvio" >= date_trunc('month', now() AT TIME ZONE 'America/Sao_Paulo') AND d."dataEnvio" < (date_trunc('month', now() AT TIME ZONE 'America/Sao_Paulo') + '1 mon'::interval)
    GROUP BY h."contaId") dd ON dd.uid = c.id
  LEFT JOIN (SELECT q."contaId" AS uid, COUNT(*) AS total_quadros FROM public."SAAS_Quadros" q GROUP BY q."contaId") qd ON qd.uid = c.id
  LEFT JOIN (SELECT "SAAS_AgentesIA"."contaId" AS uid, COUNT(*) AS total_agentes FROM public."SAAS_AgentesIA" GROUP BY "contaId") ag ON ag.uid = c.id
  LEFT JOIN (SELECT "contaId", COUNT(*) AS total_usuarios FROM public."SAAS_Usuarios" GROUP BY "contaId") us ON us."contaId" = c.id
  LEFT JOIN (
    SELECT c2.id AS uid, COALESCE(c2.tokens, 0::numeric) AS total_creditos
    FROM public."SAAS_Contas" c2
  ) uc ON uc.uid = c.id;

  CREATE OR REPLACE VIEW public."VW_SAAS_Etapas_Quadros"
  WITH (security_invoker = true)
  AS
  SELECT
    q.id AS "quadroId",
    q.nome AS "nomeQuadro",
    e.id AS "etapaId",
    e.nome AS "nomeEtapa",
    e.ordem AS "ordemEtapa",
    e."tipoEtapa" AS "tipoEtapa",
    COALESCE(
      (
        SELECT
          jsonb_agg(
            to_jsonb(c.*) || jsonb_build_object('ordemCard', c.ordem)
            ORDER BY c.ordem
          ) AS jsonb_agg
        FROM public."SAAS_Cards_Quadros" c
        WHERE c."quadroId" = q.id
          AND c."etapaQuadroId" = e.id
      ),
      '[]'::jsonb
    ) AS cards
  FROM public."SAAS_Etapas_Quadros" e
  JOIN public."SAAS_Quadros" q ON q.id = e."quadroId";

  CREATE OR REPLACE VIEW public."VW_SAAS_AgentesIA_Conversas"
  WITH (security_invoker = true)
  AS
  SELECT
    a.id, a.created_at, a."contaId", a.nome, a."conexaoId", a.instrucoes, a.modelo, a.criatividade,
    a."maxCreditos", a.ativo, a.conhecimento, a.cor, a."separarMensagens", a."ouvirAudio", a."analisarImagens",
    a."aparecerDigitando", a."pausarAtendimento", a."qntMsgHistorico", a."agruparMensagens", a."intervaloEntreMensagens",
    COALESCE(cnv.conversas_atendimento, 0::bigint) AS "conversasAtendimento",
    COALESCE(cnv.conversas_pausadas, 0::bigint) AS "ConversasPausadas",
    CASE WHEN p."qntCreditosIa" IS NULL OR COALESCE(p."iaChaveCliente", false) THEN false
        ELSE COALESCE(uc.total_creditos, 0::bigint) >= p."qntCreditosIa"
    END AS "limiteAtingido",
    a."CRM"
  FROM public."SAAS_AgentesIA" a
  LEFT JOIN (
    SELECT "SAAS_Conversas_Agentes"."idAgente",
      COUNT(*) FILTER (WHERE "SAAS_Conversas_Agentes".pausado IS false) AS conversas_atendimento,
      COUNT(*) FILTER (WHERE "SAAS_Conversas_Agentes".pausado IS true) AS conversas_pausadas
    FROM public."SAAS_Conversas_Agentes" GROUP BY "idAgente"
  ) cnv ON cnv."idAgente" = a.id
  LEFT JOIN public."SAAS_Contas" c ON c.id = a."contaId"
  LEFT JOIN public."SAAS_Planos" p ON p.id = c.plano
  LEFT JOIN (
    SELECT c3.id AS "contaId", COALESCE(c3.tokens, 0::numeric)::bigint AS total_creditos
    FROM public."SAAS_Contas" c3
  ) uc ON uc."contaId" = a."contaId";

  CREATE OR REPLACE VIEW public."vw_SAAS_Quadros_CRM"
  WITH (security_invoker = true)
  AS
  SELECT
    q.id, q.created_at, q.nome, q.descricao, q.cor, q."contaId", q.icone,
    COALESCE(c.total_cards, 0::bigint) AS total_cards,
    COALESCE(c.valor_total, 0::double precision) AS valor_total,
    COALESCE(c.qtd_oportunidades, 0::bigint) AS qtd_oportunidades,
    COALESCE(c.qtd_vendas_30d, 0::bigint) AS qtd_vendas_30d,
    COALESCE(c.qtd_agendamentos, 0::bigint) AS qtd_agendamentos,
    COALESCE(c.faturamento_30d, 0::double precision) AS faturamento_30d
  FROM public."SAAS_Quadros" q
  LEFT JOIN (
    SELECT c."quadroId" AS quadro_id,
      COUNT(*) AS total_cards,
      COALESCE(SUM(c.valor) FILTER (WHERE e."tipoEtapa" = 'venda'), 0::double precision) AS valor_total,
      COUNT(*) FILTER (
        WHERE e."tipoEtapa" IS NULL OR e."tipoEtapa" NOT IN ('venda', 'perda', 'agendamento')
      ) AS qtd_oportunidades,
      COUNT(*) FILTER (
        WHERE e."tipoEtapa" = 'venda'
          AND c.created_at >= (date_trunc('day', now() AT TIME ZONE 'America/Sao_Paulo') - interval '29 days') AT TIME ZONE 'America/Sao_Paulo'
          AND c.created_at <= ((date_trunc('day', now() AT TIME ZONE 'America/Sao_Paulo') + interval '1 day') AT TIME ZONE 'America/Sao_Paulo') - interval '1 microsecond'
      ) AS qtd_vendas_30d,
      COUNT(*) FILTER (WHERE e."tipoEtapa" = 'agendamento') AS qtd_agendamentos,
      COALESCE(SUM(c.valor) FILTER (
        WHERE e."tipoEtapa" = 'venda'
          AND c.created_at >= (date_trunc('day', now() AT TIME ZONE 'America/Sao_Paulo') - interval '29 days') AT TIME ZONE 'America/Sao_Paulo'
          AND c.created_at <= ((date_trunc('day', now() AT TIME ZONE 'America/Sao_Paulo') + interval '1 day') AT TIME ZONE 'America/Sao_Paulo') - interval '1 microsecond'
      ), 0::double precision) AS faturamento_30d
    FROM public."SAAS_Cards_Quadros" c
    LEFT JOIN public."SAAS_Etapas_Quadros" e ON e.id = c."etapaQuadroId"
    GROUP BY c."quadroId"
  ) c ON c.quadro_id = q.id;

  GRANT SELECT ON public."vw_Detalhes_Completo" TO anon, authenticated;
  GRANT SELECT ON public."vw_Planos_Usuarios_Count" TO anon, authenticated;
  GRANT SELECT ON public."vw_Contas_Com_Plano" TO anon, authenticated;
  GRANT SELECT ON public."VW_SAAS_Etapas_Quadros" TO anon, authenticated;
  GRANT SELECT ON public."VW_SAAS_AgentesIA_Conversas" TO anon, authenticated;
  GRANT SELECT ON public."vw_SAAS_Quadros_CRM" TO anon, authenticated;

  -- GRANT em tabelas SAAS (necessário para RLS aplicar; sem GRANT = permission denied for table)
  GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_Conexões" TO authenticated;
  DO $$ BEGIN IF to_regclass('public."SAAS_Grupos"') IS NOT NULL THEN GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_Grupos" TO authenticated; END IF; END $$;
  GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_Contatos" TO authenticated;
  GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_Disparos" TO authenticated;
  GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_Detalhes_Disparos" TO authenticated;
  GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_Quadros" TO authenticated;
  GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_Etapas_Quadros" TO authenticated;
  GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_Cards_Quadros" TO authenticated;
  GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_AgentesIA" TO authenticated;
  GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_Conhecimentos" TO authenticated;
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Webhook"') IS NOT NULL THEN GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_Webhook" TO authenticated; END IF;
    IF to_regclass('public."SAAS_IntegracaoPagamento"') IS NOT NULL THEN GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_IntegracaoPagamento" TO authenticated; END IF;
    IF to_regclass('public."SAAS_Resposta_Rapidas"') IS NOT NULL THEN GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_Resposta_Rapidas" TO authenticated; END IF;
  END$$;
  GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_Versao" TO authenticated;

  GRANT SELECT, INSERT, DELETE ON public."SAAS_Usuarios" TO authenticated;
  REVOKE UPDATE ON public."SAAS_Usuarios" FROM authenticated;
  GRANT UPDATE ("Email", nome, telefone) ON public."SAAS_Usuarios" TO authenticated;
  GRANT SELECT ON public."SAAS_Usuarios" TO anon;

  -- =========================
  -- Config E-mails e SMTP (admin)
  -- =========================
  -- Uma única linha (id=1): supabase_pat (PAT), templates (novo utilizador + recovery) e colunas smtp_*.
  -- O painel admin grava PAT e SMTP nesta tabela; RLS: apenas super_admin (authenticated); service_role ignora RLS.
  CREATE TABLE IF NOT EXISTS public."SAAS_Config_Emails" (
    id INT PRIMARY KEY DEFAULT 1,
    supabase_pat TEXT,
    assunto_email_novousuario TEXT,
    html_email_novousuario TEXT,
    assunto_email_redefinirsenha TEXT,
    html_email_redefinirsenha TEXT,
    smtp_email TEXT,
    smtp_name TEXT,
    smtp_host TEXT,
    smtp_port INT,
    smtp_user TEXT,
    smtp_apikey TEXT,
    updated_at TIMESTAMPTZ DEFAULT now(),
    CONSTRAINT single_row CHECK (id = 1)
  );


  -- Migração de nomes legados templates -> padrão atual
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Config_Emails"') IS NULL THEN RETURN; END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Config_Emails' AND column_name = 'mailer_subjects_confirmation')
      AND NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Config_Emails' AND column_name = 'assunto_email_novousuario') THEN
      ALTER TABLE public."SAAS_Config_Emails" RENAME COLUMN mailer_subjects_confirmation TO assunto_email_novousuario;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Config_Emails' AND column_name = 'mailer_templates_confirmation_content')
      AND NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Config_Emails' AND column_name = 'html_email_novousuario') THEN
      ALTER TABLE public."SAAS_Config_Emails" RENAME COLUMN mailer_templates_confirmation_content TO html_email_novousuario;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Config_Emails' AND column_name = 'mailer_subjects_recovery')
      AND NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Config_Emails' AND column_name = 'assunto_email_redefinirsenha') THEN
      ALTER TABLE public."SAAS_Config_Emails" RENAME COLUMN mailer_subjects_recovery TO assunto_email_redefinirsenha;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Config_Emails' AND column_name = 'mailer_templates_recovery_content')
      AND NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Config_Emails' AND column_name = 'html_email_redefinirsenha') THEN
      ALTER TABLE public."SAAS_Config_Emails" RENAME COLUMN mailer_templates_recovery_content TO html_email_redefinirsenha;
    END IF;
  END$$;

  -- Migração de nomes legados SMTP -> padrão atual
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Config_Emails"') IS NULL THEN RETURN; END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Config_Emails' AND column_name = 'smtp_admin_email')
      AND NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Config_Emails' AND column_name = 'smtp_email') THEN
      ALTER TABLE public."SAAS_Config_Emails" RENAME COLUMN smtp_admin_email TO smtp_email;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Config_Emails' AND column_name = 'smtp_sender_name')
      AND NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Config_Emails' AND column_name = 'smtp_name') THEN
      ALTER TABLE public."SAAS_Config_Emails" RENAME COLUMN smtp_sender_name TO smtp_name;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Config_Emails' AND column_name = 'smtp_pass')
      AND NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Config_Emails' AND column_name = 'smtp_apikey') THEN
      ALTER TABLE public."SAAS_Config_Emails" RENAME COLUMN smtp_pass TO smtp_apikey;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Config_Emails' AND column_name = 'smtp_admin_email')
      AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Config_Emails' AND column_name = 'smtp_email') THEN
      ALTER TABLE public."SAAS_Config_Emails" DROP COLUMN smtp_admin_email;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Config_Emails' AND column_name = 'smtp_sender_name')
      AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Config_Emails' AND column_name = 'smtp_name') THEN
      ALTER TABLE public."SAAS_Config_Emails" DROP COLUMN smtp_sender_name;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Config_Emails' AND column_name = 'smtp_pass')
      AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Config_Emails' AND column_name = 'smtp_apikey') THEN
      ALTER TABLE public."SAAS_Config_Emails" DROP COLUMN smtp_pass;
    END IF;
  END$$;

