  -- Status SMTP para usuários autenticados: expõe apenas se está configurado e o e-mail remetente (sem credenciais).
  CREATE OR REPLACE FUNCTION public.obter_status_smtp()
  RETURNS TABLE (smtp_configurado BOOLEAN, smtp_email TEXT)
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path = public
  AS $$
    SELECT
      (
        COALESCE(NULLIF(trim(c.smtp_host), ''), NULL) IS NOT NULL
        AND COALESCE(NULLIF(trim(c.smtp_user), ''), NULL) IS NOT NULL
        AND COALESCE(NULLIF(trim(c.smtp_email), ''), NULL) IS NOT NULL
        AND COALESCE(NULLIF(trim(c.smtp_apikey), ''), NULL) IS NOT NULL
      ) AS smtp_configurado,
      CASE
        WHEN COALESCE(NULLIF(trim(c.smtp_host), ''), NULL) IS NOT NULL
          AND COALESCE(NULLIF(trim(c.smtp_user), ''), NULL) IS NOT NULL
          AND COALESCE(NULLIF(trim(c.smtp_email), ''), NULL) IS NOT NULL
          AND COALESCE(NULLIF(trim(c.smtp_apikey), ''), NULL) IS NOT NULL
        THEN NULLIF(trim(c.smtp_email), '')
        ELSE NULL
      END AS smtp_email
    FROM public."SAAS_Config_Emails" c
    WHERE c.id = 1
    LIMIT 1;
  $$;

  GRANT EXECUTE ON FUNCTION public.obter_status_smtp() TO authenticated;

