  -- Expõe apenas app_id e config_id para o front de conexões (sem app_secret)
  CREATE OR REPLACE FUNCTION public.get_config_api_oficial_sdk()
  RETURNS JSON
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path = public
  STABLE
  AS $$
    SELECT CASE
      WHEN c.app_id IS NOT NULL AND btrim(c.app_id) <> ''
      AND c.config_id IS NOT NULL AND btrim(c.config_id) <> ''
      AND (c.visivel = true OR public.is_super_admin())
      THEN json_build_object('app_id', c.app_id, 'config_id', c.config_id, 'visivel', c.visivel)
      ELSE NULL
    END
    FROM public."SAAS_Config_ApiOficial" c
    WHERE c.id = 1;
  $$;

  GRANT EXECUTE ON FUNCTION public.get_config_api_oficial_sdk() TO authenticated;

