  -- Integração de pagamento (painel admin): webhook por plano, mapeamento nome/e-mail/telefone, conta vinculada
  CREATE TABLE IF NOT EXISTS public."SAAS_IntegracaoPagamento" (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    nome TEXT,
    "planoId" BIGINT REFERENCES public."SAAS_Planos"(id) ON UPDATE CASCADE ON DELETE SET NULL,
    "tokenWebhook" UUID DEFAULT gen_random_uuid(),
    mapeamento JSONB,
    "ultimoPayload" JSONB,
    teste BOOLEAN DEFAULT false,
    status BOOLEAN DEFAULT true
  );
  CREATE INDEX IF NOT EXISTS idx_integ_pag_plano ON public."SAAS_IntegracaoPagamento"("planoId");
  CREATE INDEX IF NOT EXISTS idx_integ_pag_token ON public."SAAS_IntegracaoPagamento"("tokenWebhook");
  ALTER TABLE public."SAAS_IntegracaoPagamento" ENABLE ROW LEVEL SECURITY;

  -- Migrar a validade legada para o plano vinculado (integração mais recente por plano).
  -- Planos que já possuem validade configurada mantêm seu valor.
  DO $$
  BEGIN
    IF EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_IntegracaoPagamento' AND column_name = 'diasValidade'
    ) THEN
      UPDATE public."SAAS_Planos" p
      SET "diasValidade" = origem."diasValidade"
      FROM (
        SELECT DISTINCT ON ("planoId") "planoId", "diasValidade"
        FROM public."SAAS_IntegracaoPagamento"
        WHERE "planoId" IS NOT NULL AND "diasValidade" > 0
        ORDER BY "planoId", created_at DESC, id DESC
      ) origem
      WHERE p.id = origem."planoId" AND p."diasValidade" IS NULL;
      ALTER TABLE public."SAAS_IntegracaoPagamento" DROP COLUMN "diasValidade";
    END IF;
  END$$;

  -- Completar planos antigos sem validade após aproveitar os valores das integrações.
  UPDATE public."SAAS_Planos"
  SET "diasValidade" = 30
  WHERE "diasValidade" IS NULL OR "diasValidade" <= 0;
  ALTER TABLE public."SAAS_Planos" ALTER COLUMN "diasValidade" SET DEFAULT 30;
  ALTER TABLE public."SAAS_Planos" ALTER COLUMN "diasValidade" SET NOT NULL;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_IntegracaoPagamento"') IS NULL THEN RETURN; END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_IntegracaoPagamento' AND column_name = 'conexaoId') THEN
      ALTER TABLE public."SAAS_IntegracaoPagamento" DROP COLUMN "conexaoId";
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_IntegracaoPagamento' AND column_name = 'idAgente') THEN
      ALTER TABLE public."SAAS_IntegracaoPagamento" DROP COLUMN "idAgente";
    END IF;
    -- (não remover "contaId" aqui; se precisar, ajustar no migration própria)
  END$$;

  -- RLS: só super_admin (após a tabela existir)
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_IntegracaoPagamento"') IS NULL THEN RETURN; END IF;
    DROP POLICY IF EXISTS "select_integracao_pagamento" ON public."SAAS_IntegracaoPagamento";
    DROP POLICY IF EXISTS "insert_integracao_pagamento" ON public."SAAS_IntegracaoPagamento";
