    CREATE POLICY "select_integracao_pagamento" ON public."SAAS_IntegracaoPagamento" FOR SELECT TO authenticated USING ((SELECT public.rls_eh_super_admin()));
    CREATE POLICY "insert_integracao_pagamento" ON public."SAAS_IntegracaoPagamento" FOR INSERT TO authenticated WITH CHECK ((SELECT public.rls_eh_super_admin()));
    CREATE POLICY "update_integracao_pagamento" ON public."SAAS_IntegracaoPagamento" FOR UPDATE TO authenticated USING ((SELECT public.rls_eh_super_admin())) WITH CHECK ((SELECT public.rls_eh_super_admin()));
    CREATE POLICY "delete_integracao_pagamento" ON public."SAAS_IntegracaoPagamento" FOR DELETE TO authenticated USING ((SELECT public.rls_eh_super_admin()));
