  CREATE UNIQUE INDEX IF NOT EXISTS uq_modelo_etapa_tipo_agendamento
    ON public."SAAS_Modelos_Etapas" ("modeloId") WHERE "tipoEtapa" = 'agendamento';

  GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_Modelos" TO authenticated;
