    CREATE POLICY "select_modelos" ON public."SAAS_Modelos" FOR SELECT TO authenticated USING (true);
    CREATE POLICY "insert_modelos" ON public."SAAS_Modelos" FOR INSERT TO authenticated WITH CHECK ((SELECT public.rls_eh_super_admin()));
    CREATE POLICY "update_modelos" ON public."SAAS_Modelos" FOR UPDATE TO authenticated USING ((SELECT public.rls_eh_super_admin())) WITH CHECK ((SELECT public.rls_eh_super_admin()));
    CREATE POLICY "delete_modelos" ON public."SAAS_Modelos" FOR DELETE TO authenticated USING ((SELECT public.rls_eh_super_admin()));
