    DROP POLICY IF EXISTS "delete_modelos_etapas" ON public."SAAS_Modelos_Etapas";
    CREATE POLICY "select_modelos_etapas" ON public."SAAS_Modelos_Etapas" FOR SELECT TO authenticated USING (true);
    CREATE POLICY "insert_modelos_etapas" ON public."SAAS_Modelos_Etapas" FOR INSERT TO authenticated WITH CHECK ((SELECT public.rls_eh_super_admin()));
    CREATE POLICY "update_modelos_etapas" ON public."SAAS_Modelos_Etapas" FOR UPDATE TO authenticated USING ((SELECT public.rls_eh_super_admin())) WITH CHECK ((SELECT public.rls_eh_super_admin()));
    CREATE POLICY "delete_modelos_etapas" ON public."SAAS_Modelos_Etapas" FOR DELETE TO authenticated USING ((SELECT public.rls_eh_super_admin()));
