    END IF;
    IF to_regprocedure('public.edit_disparo_grupo(jsonb)') IS NOT NULL THEN
      GRANT EXECUTE ON FUNCTION public.edit_disparo_grupo(jsonb) TO authenticated;
    END IF;
  END $$;
  GRANT EXECUTE ON FUNCTION public.swap_connection(bigint, bigint) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.resume_disparo(bigint, uuid) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.pause_disparo(bigint, uuid) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.delete_disparo(bigint, uuid) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.add_connections_disparo(bigint, bigint[], uuid) TO authenticated;

  -- Dashboard, listas, quadros, tokens, expiração
  GRANT EXECUTE ON FUNCTION public.get_dashboard(UUID, TIMESTAMPTZ, TIMESTAMPTZ, BIGINT[], BIGINT) TO authenticated, anon;
  GRANT EXECUTE ON FUNCTION public.get_dashboard_crm(UUID, BIGINT) TO authenticated, anon;
  GRANT EXECUTE ON FUNCTION public.get_dashboard_vendas(UUID, TIMESTAMPTZ, TIMESTAMPTZ, BIGINT) TO authenticated, anon;
  GRANT EXECUTE ON FUNCTION public.get_dashboard_agendamentos(UUID, TIMESTAMPTZ, TIMESTAMPTZ, BIGINT) TO authenticated, anon;
  GRANT EXECUTE ON FUNCTION public.get_crm_resumo_metricas(UUID) TO authenticated, anon;
  GRANT EXECUTE ON FUNCTION public.f_add_tokens_usuario_por_agente(jsonb) TO authenticated;
  DO $$ BEGIN
    IF to_regprocedure('public.f_add_tokens_conta(uuid, numeric)') IS NOT NULL THEN
