    END IF;
  END $$;
  GRANT EXECUTE ON FUNCTION public.f_pausar_atendimento_por_mensagem(BIGINT) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.f_resetar_creditos_agentes_mes() TO authenticated;
  GRANT EXECUTE ON FUNCTION public.f_ingestao_mensagem(jsonb) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.f_avaliar_fluxo_agente_ia(bigint, uuid, bigint, bigint, text, text, boolean, text, text, boolean) TO authenticated, service_role;
  GRANT EXECUTE ON FUNCTION public.f_vincular_contatos_conversas_por_telefone() TO authenticated;
  GRANT EXECUTE ON FUNCTION public.p_expire_contas_daily() TO authenticated;
  GRANT EXECUTE ON FUNCTION public.p_expire_contas_now() TO authenticated;
  DO $$ BEGIN IF to_regproc('public.get_contatos_by_lista(bigint)') IS NOT NULL THEN GRANT EXECUTE ON FUNCTION public.get_contatos_by_lista(bigint) TO authenticated; END IF; IF to_regproc('public.get_grupos_by_lista(bigint)') IS NOT NULL THEN GRANT EXECUTE ON FUNCTION public.get_grupos_by_lista(bigint) TO authenticated; END IF; END $$;
  GRANT EXECUTE ON FUNCTION public.f_contas_com_plano() TO authenticated;

  -- =========================
  -- Planos padrão (Ilimitado, Free) e linha de versão
  -- =========================
  -- Remover qntListas de planos existentes (etiquetas não são limitadas)
  DO $$ BEGIN
    IF to_regclass('public."SAAS_Planos"') IS NOT NULL AND EXISTS (
      SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='SAAS_Planos' AND column_name='qntListas'
    ) THEN
      ALTER TABLE public."SAAS_Planos" DROP COLUMN "qntListas";
    END IF;
  END $$;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Planos"') IS NOT NULL THEN
      BEGIN
        CREATE UNIQUE INDEX IF NOT EXISTS uq_SAAS_Planos_nome ON public."SAAS_Planos"(nome);
      EXCEPTION
        WHEN OTHERS THEN
          RAISE NOTICE 'Erro ao criar índice uq_SAAS_Planos_nome: %', SQLERRM;
      END;

      INSERT INTO public."SAAS_Planos"(nome, preco, "qntConexoes", "qntContatos", "qntDisparos", "qntUsuarios", "qntQuadros", "qntAgentesIa", "qntCreditosIa")
      VALUES
        ('Ilimitado', 0, 999999999999, 999999999999, 999999999999, 999999999999, 999999999999, 999999999999, 999999999999),
        ('Free',      0, 1, 10, 100, 1, 2, 1, 1000)
      ON CONFLICT (nome) DO UPDATE SET
        preco = EXCLUDED.preco,
        "qntConexoes" = EXCLUDED."qntConexoes",
        "qntContatos" = EXCLUDED."qntContatos",
        "qntDisparos" = EXCLUDED."qntDisparos",
        "qntUsuarios" = EXCLUDED."qntUsuarios",
        "qntQuadros" = EXCLUDED."qntQuadros",
        "qntAgentesIa" = EXCLUDED."qntAgentesIa",
        "qntCreditosIa" = EXCLUDED."qntCreditosIa";
    END IF;
  END$$;

  -- Garantia explícita de limite de usuários nos planos padrão
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Planos"') IS NOT NULL THEN
      UPDATE public."SAAS_Planos"
      SET "qntUsuarios" = 1
      WHERE nome = 'Free';

      UPDATE public."SAAS_Planos"
      SET "qntUsuarios" = 999999999999
      WHERE nome = 'Ilimitado';
    END IF;
  END$$;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Versao"') IS NOT NULL THEN
      IF NOT EXISTS (SELECT 1 FROM public."SAAS_Versao" LIMIT 1) THEN
        INSERT INTO public."SAAS_Versao" ("versaoAtual", "ultimaAtualizacao")
        VALUES ('V8.0.0', now());
      END IF;
    END IF;
  END$$;

  -- Atribuir plano Ilimitado às contas sem plano
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Planos"') IS NOT NULL AND to_regclass('public."SAAS_Contas"') IS NOT NULL THEN
      WITH il AS (SELECT id FROM public."SAAS_Planos" WHERE nome='Ilimitado' LIMIT 1)
      UPDATE public."SAAS_Contas" c SET plano = (SELECT id FROM il) WHERE c.plano IS NULL;
    END IF;
  END$$;

  -- =========================
  -- Bucket 'arquivos' (Storage)
  -- =========================
  DO $$
  BEGIN
    IF to_regnamespace('storage') IS NOT NULL AND to_regclass('storage.buckets') IS NOT NULL THEN
      IF NOT EXISTS (SELECT 1 FROM storage.buckets WHERE id = 'arquivos') THEN
        INSERT INTO storage.buckets (id, name, public)
        VALUES ('arquivos', 'arquivos', true);
      END IF;
    ELSE
      RAISE NOTICE 'Schema storage/tabela buckets não existem neste banco. Pulando criação do bucket.';
    END IF;
  END$$;

  -- =========================
  -- Storage RLS do bucket 'arquivos' (logo/favicon)
  -- =========================
  DO $$
  BEGIN
    IF to_regnamespace('storage') IS NOT NULL AND to_regclass('storage.objects') IS NOT NULL THEN
      BEGIN
        -- Em alguns projetos managed, este ALTER exige owner de storage.objects.
        ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY;
      EXCEPTION
        WHEN insufficient_privilege THEN
          RAISE NOTICE 'Sem permissão para ALTER TABLE storage.objects. Prosseguindo sem alterar RLS.';
      END;

      BEGIN
        DROP POLICY IF EXISTS "arquivos_public_read" ON storage.objects;
        DROP POLICY IF EXISTS "arquivos_auth_insert" ON storage.objects;
        DROP POLICY IF EXISTS "arquivos_auth_update" ON storage.objects;
        DROP POLICY IF EXISTS "arquivos_auth_delete" ON storage.objects;

        -- Leitura pública dos arquivos do bucket (bucket público).
        CREATE POLICY "arquivos_public_read"
          ON storage.objects
          FOR SELECT
          TO public
          USING (bucket_id = 'arquivos');

        -- Escrita autenticada restrita aos arquivos de branding usados pelo admin.
        -- Nomes aceitos: logo, favicon (atual) e LOGO PRINCIPAL.* / FAVICON.* / logo.* / favicon.* (legado).
        CREATE POLICY "arquivos_auth_insert"
          ON storage.objects
          FOR INSERT
          TO authenticated
          WITH CHECK (
            bucket_id = 'arquivos'
            AND (
              name ~* '^(logo|favicon|LOGO PRINCIPAL|FAVICON)(\.[a-z0-9]+)?$'
              OR name LIKE 'personalizacao/%'
            )
          );

        CREATE POLICY "arquivos_auth_update"
          ON storage.objects
          FOR UPDATE
          TO authenticated
          USING (
            bucket_id = 'arquivos'
            AND (
              name ~* '^(logo|favicon|LOGO PRINCIPAL|FAVICON)(\.[a-z0-9]+)?$'
              OR name LIKE 'personalizacao/%'
            )
          )
          WITH CHECK (
            bucket_id = 'arquivos'
            AND (
              name ~* '^(logo|favicon|LOGO PRINCIPAL|FAVICON)(\.[a-z0-9]+)?$'
              OR name LIKE 'personalizacao/%'
            )
          );

        CREATE POLICY "arquivos_auth_delete"
          ON storage.objects
          FOR DELETE
          TO authenticated
          USING (
            bucket_id = 'arquivos'
            AND (
              name ~* '^(logo|favicon|LOGO PRINCIPAL|FAVICON)(\.[a-z0-9]+)?$'
              OR name LIKE 'personalizacao/%'
            )
          );
      EXCEPTION
        WHEN insufficient_privilege THEN
          RAISE NOTICE 'Sem permissão para criar policies em storage.objects. Configure pelo Dashboard > Storage > Policies.';
      END;
    END IF;
  END$$;

  -- =========================
  -- pg_cron: agendar expiração diária de contas (p_expire_contas_daily)
  -- =========================
  DO $$
  BEGIN
    IF EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'pg_cron') THEN
      BEGIN
        CREATE EXTENSION IF NOT EXISTS pg_cron;
      EXCEPTION
        WHEN insufficient_privilege THEN
          RAISE NOTICE 'Sem privilégio para criar extensão pg_cron';
        WHEN OTHERS THEN
          RAISE NOTICE 'Falha ao criar extensão pg_cron: %', SQLERRM;
      END;
    ELSE
      RAISE NOTICE 'Extensão pg_cron não disponível neste servidor';
    END IF;
  END$$;

  DO $$
  BEGIN
    IF to_regnamespace('cron') IS NOT NULL AND to_regclass('cron.job') IS NOT NULL THEN
      BEGIN
        PERFORM cron.unschedule(jobid) FROM cron.job WHERE jobname = 'expire_contas_daily';
      EXCEPTION
        WHEN OTHERS THEN
          RAISE NOTICE 'Erro ao remover job expire_contas_daily: %', SQLERRM;
      END;

      BEGIN
        PERFORM cron.schedule(
          'expire_contas_daily',
          '1 3 * * *',
          'SELECT public.p_expire_contas_daily();'
        );
      EXCEPTION
        WHEN OTHERS THEN
          RAISE NOTICE 'Erro ao criar job expire_contas_daily: %', SQLERRM;
      END;
    ELSE
      RAISE NOTICE 'pg_cron não disponível. Pulando criação de jobs cron.';
    END IF;
  END$$;

  -- Cron: resetar créditos de agentes mensalmente
  DO $$
  BEGIN
    IF to_regnamespace('cron') IS NOT NULL AND to_regclass('cron.job') IS NOT NULL THEN
      BEGIN
        PERFORM cron.unschedule(jobid) FROM cron.job WHERE jobname = 'resetar_creditos_agentes_mes';
      EXCEPTION WHEN OTHERS THEN RAISE NOTICE 'Erro ao remover job resetar_creditos_agentes_mes: %', SQLERRM; END;
      BEGIN
        PERFORM cron.schedule('resetar_creditos_agentes_mes', '5 0 1 * *', 'SELECT public.f_resetar_creditos_agentes_mes();');
      EXCEPTION WHEN OTHERS THEN RAISE NOTICE 'Erro ao criar job resetar_creditos_agentes_mes: %', SQLERRM; END;
    END IF;
  END;
  $$;

  -- =========================
  -- Auto-vincular contatos se existem conversas sem contatoId
  -- =========================
  DO $$
  DECLARE
    v_resultado jsonb;
  BEGIN
    IF EXISTS (
      SELECT 1 FROM public."SAAS_Conversas_Agentes"
      WHERE "contatoId" IS NULL
      LIMIT 1
    ) THEN
      RAISE NOTICE 'Conversas com contatoId vazio encontradas — executando f_vincular_contatos_conversas_por_telefone...';
      v_resultado := public.f_vincular_contatos_conversas_por_telefone();
      RAISE NOTICE 'Resultado: %', v_resultado::text;
    ELSE
      RAISE NOTICE 'Todas as conversas já possuem contatoId — pulando vinculação automática.';
    END IF;
  END;
  $$;

  -- =============================================================================
  -- MIGRAÇÃO: Listas → Etiquetas | Grupos → Contatos | Contatos únicos
  -- =============================================================================
  -- Se SAAS_Etiquetas e SAAS_Contatos_Etiquetas já existem: pula migração, só alterações (funções, RLS, etc.)
  -- Caso contrário: executa migração completa
  -- =============================================================================

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Etiquetas"') IS NOT NULL AND to_regclass('public."SAAS_Contatos_Etiquetas"') IS NOT NULL THEN
      RAISE NOTICE 'SAAS_Etiquetas e SAAS_Contatos_Etiquetas já existem. Pulando migração, executando apenas alterações.';
    ELSIF to_regclass('public."SAAS_Listas"') IS NULL THEN
      RAISE NOTICE 'SAAS_Listas não existe. Pulando migração (estrutura já nova ou vazia).';
    ELSE
      RAISE NOTICE 'Executando migração Listas→Etiquetas...';
    END IF;
  END$$;

  -- Bloco de migração: só executa quando SAAS_Contatos_Etiquetas NÃO existe
  -- 1. Renomear SAAS_Listas → SAAS_Etiquetas
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Contatos_Etiquetas"') IS NOT NULL THEN RETURN; END IF;
    IF to_regclass('public."SAAS_Listas"') IS NOT NULL AND to_regclass('public."SAAS_Etiquetas"') IS NULL THEN
      ALTER TABLE public."SAAS_Listas" RENAME TO "SAAS_Etiquetas";
      RAISE NOTICE 'SAAS_Listas renomeada para SAAS_Etiquetas';
    END IF;
  END$$;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Contatos_Etiquetas"') IS NOT NULL THEN RETURN; END IF;
    IF to_regclass('public."SAAS_Etiquetas"') IS NOT NULL THEN
      ALTER TABLE public."SAAS_Etiquetas" DROP COLUMN IF EXISTS tipo;
      ALTER TABLE public."SAAS_Etiquetas" DROP COLUMN IF EXISTS campos;
      ALTER TABLE public."SAAS_Etiquetas" DROP COLUMN IF EXISTS "idConexao";
    END IF;
  END$$;

  DO $$ BEGIN
    IF to_regclass('public."SAAS_Etiquetas"') IS NOT NULL THEN
      ALTER TABLE public."SAAS_Etiquetas" ADD COLUMN IF NOT EXISTS cor TEXT;
    END IF;
  END $$;

  -- 2. SAAS_Contatos: adicionar tipo, email, lid; atributos → variaveis (idempotente)
  ALTER TABLE public."SAAS_Contatos" ADD COLUMN IF NOT EXISTS tipo TEXT NOT NULL DEFAULT 'contato' CHECK (tipo IN ('contato','grupo'));
  ALTER TABLE public."SAAS_Contatos" ADD COLUMN IF NOT EXISTS email TEXT;
  ALTER TABLE public."SAAS_Contatos" ADD COLUMN IF NOT EXISTS lid TEXT;
  ALTER TABLE public."SAAS_Contatos" ADD COLUMN IF NOT EXISTS "fotoPerfil" TEXT;
  ALTER TABLE public."SAAS_Contatos" ADD COLUMN IF NOT EXISTS validado BOOLEAN NOT NULL DEFAULT false;
  DO $$ BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns c WHERE c.table_schema='public' AND c.table_name='SAAS_Contatos' AND c.column_name='lid' AND c.data_type='boolean') THEN
      ALTER TABLE public."SAAS_Contatos" ALTER COLUMN lid TYPE TEXT USING CASE WHEN lid THEN 'true' ELSE 'false' END;
    END IF;
  END $$;
  ALTER TABLE public."SAAS_Contatos" ALTER COLUMN lid DROP NOT NULL;

  DO $$ BEGIN
    IF to_regclass('public."SAAS_Contatos_Etiquetas"') IS NOT NULL THEN RETURN; END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='SAAS_Contatos' AND column_name='atributos')
      AND NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='SAAS_Contatos' AND column_name='variaveis') THEN
      ALTER TABLE public."SAAS_Contatos" RENAME COLUMN atributos TO variaveis;
    END IF;
  END $$;
  ALTER TABLE public."SAAS_Contatos" ADD COLUMN IF NOT EXISTS variaveis JSONB NOT NULL DEFAULT '{}';

  DO $$ BEGIN
    IF to_regclass('public."SAAS_Contatos_Etiquetas"') IS NOT NULL THEN RETURN; END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='SAAS_Contatos' AND column_name='idLista') THEN
      ALTER TABLE public."SAAS_Contatos" ALTER COLUMN "idLista" DROP NOT NULL;
    END IF;
  END $$;

  -- 3. Migrar SAAS_Grupos → SAAS_Contatos (tipo='grupo')
  CREATE TEMP TABLE IF NOT EXISTS _map_grupo_contato (grupo_id BIGINT PRIMARY KEY, contato_id BIGINT);

  DO $$
  DECLARE rec RECORD; novo_id BIGINT; v_variaveis JSONB;
  BEGIN
    IF to_regclass('public."SAAS_Contatos_Etiquetas"') IS NOT NULL THEN RETURN; END IF;
    IF to_regclass('public."SAAS_Grupos"') IS NULL THEN RETURN; END IF;
    FOR rec IN SELECT id, created_at, nome, "WhatsAppId", "idLista", atributos, "contaId" FROM public."SAAS_Grupos"
    LOOP
      v_variaveis := COALESCE(rec.atributos, '{}'::jsonb) || jsonb_build_object('whatsappId', rec."WhatsAppId");
      INSERT INTO public."SAAS_Contatos" (created_at, nome, telefone, tipo, variaveis, "contaId", "idLista")
      VALUES (rec.created_at, rec.nome, NULL, 'grupo', v_variaveis, rec."contaId", rec."idLista")
      RETURNING id INTO novo_id;
      INSERT INTO _map_grupo_contato (grupo_id, contato_id) VALUES (rec.id, novo_id) ON CONFLICT (grupo_id) DO UPDATE SET contato_id = EXCLUDED.contato_id;
    END LOOP;
    RAISE NOTICE 'Grupos migrados para SAAS_Contatos (tipo=grupo)';
  END$$;

  -- Remover crédito por agente: créditos são controlados na conta (SAAS_Contas.tokens)
  DO $$
  BEGIN
    IF EXISTS (
      SELECT 1
      FROM information_schema.columns
      WHERE table_schema = 'public'
        AND table_name = 'SAAS_AgentesIA'
        AND column_name = 'creditosGasto'
    ) THEN
      ALTER TABLE public."SAAS_AgentesIA" DROP COLUMN "creditosGasto";
    END IF;
  END$$;

  -- 4. SAAS_Detalhes_Disparos: idGrupo → idContato
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Contatos_Etiquetas"') IS NOT NULL THEN RETURN; END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='SAAS_Detalhes_Disparos' AND column_name='idGrupo') THEN
      DROP VIEW IF EXISTS public."vw_Detalhes_Completo" CASCADE;
      UPDATE public."SAAS_Detalhes_Disparos" d SET "idContato" = m.contato_id, "idGrupo" = NULL
      FROM _map_grupo_contato m WHERE d."idGrupo" = m.grupo_id;
      ALTER TABLE public."SAAS_Detalhes_Disparos" DROP COLUMN IF EXISTS "idGrupo";
      RAISE NOTICE 'SAAS_Detalhes_Disparos: idGrupo migrado para idContato';
    END IF;
  END$$;

  -- 5. Garantir SAAS_Etiquetas (clientes sem SAAS_Listas / já no modelo novo)
  CREATE TABLE IF NOT EXISTS public."SAAS_Etiquetas" (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    nome TEXT NOT NULL,
    descricao TEXT,
    cor TEXT,
    "contaId" UUID NOT NULL REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE
  );
  CREATE INDEX IF NOT EXISTS "idx_Etiquetas_contaId" ON public."SAAS_Etiquetas"("contaId");

  -- 5b. Criar SAAS_Contatos_Etiquetas (N:N)
  CREATE TABLE IF NOT EXISTS public."SAAS_Contatos_Etiquetas" (
    "contatoId" BIGINT NOT NULL REFERENCES public."SAAS_Contatos"(id) ON DELETE CASCADE,
    "etiquetaId" BIGINT NOT NULL REFERENCES public."SAAS_Etiquetas"(id) ON DELETE CASCADE,
    "contaId" UUID NOT NULL REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE,
    PRIMARY KEY ("contatoId", "etiquetaId")
  );
  CREATE INDEX IF NOT EXISTS idx_contatos_etiquetas_contato ON public."SAAS_Contatos_Etiquetas"("contatoId");
  CREATE INDEX IF NOT EXISTS idx_contatos_etiquetas_etiqueta ON public."SAAS_Contatos_Etiquetas"("etiquetaId");
  CREATE INDEX IF NOT EXISTS idx_contatos_etiquetas_conta ON public."SAAS_Contatos_Etiquetas"("contaId");

  -- Campos personalizados por conta (nome, tipo, contaId; descricao opcional)
  CREATE TABLE IF NOT EXISTS public."SAAS_Campos_Personalizados" (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    "nome" TEXT NOT NULL,
    "descricao" TEXT,
    "tipo" TEXT NOT NULL CHECK ("tipo" IN ('texto', 'numero', 'data', 'boolean')),
    "contaId" UUID NOT NULL REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE
  );
  CREATE INDEX IF NOT EXISTS idx_campos_personalizados_conta ON public."SAAS_Campos_Personalizados"("contaId");

  -- Valores dos campos personalizados por contato (contatoId = idContato, campoId = idCampo)
  CREATE TABLE IF NOT EXISTS public."SAAS_Valores_Campos_Personalizados" (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    "idCampo" BIGINT NOT NULL REFERENCES public."SAAS_Campos_Personalizados"(id) ON DELETE CASCADE,
    "idContato" BIGINT NOT NULL REFERENCES public."SAAS_Contatos"(id) ON DELETE CASCADE,
    "contaId" UUID NOT NULL REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE,
    "valor" TEXT,
    UNIQUE ("idCampo", "idContato")
  );
  CREATE INDEX IF NOT EXISTS idx_valores_campos_personalizados_campo ON public."SAAS_Valores_Campos_Personalizados"("idCampo");
  CREATE INDEX IF NOT EXISTS idx_valores_campos_personalizados_contato ON public."SAAS_Valores_Campos_Personalizados"("idContato");
  CREATE INDEX IF NOT EXISTS idx_valores_campos_personalizados_conta ON public."SAAS_Valores_Campos_Personalizados"("contaId");

  -- Migração idempotente: estender CHECK de tipo (boolean); preencher contaId em valores
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Campos_Personalizados"') IS NOT NULL THEN
      ALTER TABLE public."SAAS_Campos_Personalizados" ADD COLUMN IF NOT EXISTS "descricao" TEXT;
      ALTER TABLE public."SAAS_Campos_Personalizados" DROP CONSTRAINT IF EXISTS "SAAS_Campos_Personalizados_tipo_check";
      ALTER TABLE public."SAAS_Campos_Personalizados" ADD CONSTRAINT "SAAS_Campos_Personalizados_tipo_check"
        CHECK ("tipo" IN ('texto', 'numero', 'data', 'boolean'));
    END IF;
    IF to_regclass('public."SAAS_Valores_Campos_Personalizados"') IS NOT NULL THEN
      ALTER TABLE public."SAAS_Valores_Campos_Personalizados" ADD COLUMN IF NOT EXISTS "contaId" UUID REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE;
      UPDATE public."SAAS_Valores_Campos_Personalizados" v
      SET "contaId" = c."contaId"
      FROM public."SAAS_Contatos" c
      WHERE v."idContato" = c.id AND (v."contaId" IS DISTINCT FROM c."contaId");
      UPDATE public."SAAS_Valores_Campos_Personalizados" v
      SET "contaId" = cp."contaId"
      FROM public."SAAS_Campos_Personalizados" cp
      WHERE v."idCampo" = cp.id AND v."contaId" IS NULL;
      DELETE FROM public."SAAS_Valores_Campos_Personalizados" WHERE "contaId" IS NULL;
      ALTER TABLE public."SAAS_Valores_Campos_Personalizados" ALTER COLUMN "contaId" SET NOT NULL;
    END IF;
  END $$;

  -- Garantir no máximo um valor por par (idCampo, idContato)
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Valores_Campos_Personalizados"') IS NULL THEN RETURN; END IF;
    DELETE FROM public."SAAS_Valores_Campos_Personalizados" a
    USING public."SAAS_Valores_Campos_Personalizados" b
    WHERE a.ctid > b.ctid
      AND a."idCampo" = b."idCampo"
      AND a."idContato" = b."idContato";
    IF NOT EXISTS (
      SELECT 1
      FROM pg_constraint
      WHERE conrelid = 'public."SAAS_Valores_Campos_Personalizados"'::regclass
        AND conname = 'uq_valores_campos_idCampo_idContato'
    ) THEN
      BEGIN
        ALTER TABLE public."SAAS_Valores_Campos_Personalizados"
          ADD CONSTRAINT "uq_valores_campos_idCampo_idContato" UNIQUE ("idCampo", "idContato");
      EXCEPTION
        WHEN duplicate_object OR duplicate_table THEN NULL;
      END;
    END IF;
  END $$;

  DO $$
  BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='SAAS_Contatos' AND column_name='idLista') THEN
      INSERT INTO public."SAAS_Contatos_Etiquetas" ("contatoId", "etiquetaId", "contaId")
      SELECT c.id, c."idLista", c."contaId" FROM public."SAAS_Contatos" c
      WHERE c."idLista" IS NOT NULL AND c.tipo = 'contato'
        AND EXISTS (SELECT 1 FROM public."SAAS_Etiquetas" e WHERE e.id = c."idLista")
      ON CONFLICT ("contatoId", "etiquetaId") DO NOTHING;
      INSERT INTO public."SAAS_Contatos_Etiquetas" ("contatoId", "etiquetaId", "contaId")
      SELECT c.id, c."idLista", c."contaId" FROM public."SAAS_Contatos" c
      WHERE c."idLista" IS NOT NULL AND c.tipo = 'grupo'
        AND EXISTS (SELECT 1 FROM public."SAAS_Etiquetas" e WHERE e.id = c."idLista")
      ON CONFLICT ("contatoId", "etiquetaId") DO NOTHING;
    END IF;
  END$$;

  -- 6. Tratar contatos duplicados (contaId + telefone)
  DO $$
  DECLARE
    v_duplicados bigint := 0;
    v_job record;
  BEGIN
    SELECT COALESCE(SUM(qtd - 1), 0)
    INTO v_duplicados
    FROM (
      SELECT COUNT(*) AS qtd
      FROM public."SAAS_Contatos"
      WHERE tipo = 'contato'
        AND telefone IS NOT NULL
        AND btrim(telefone) <> ''
      GROUP BY "contaId", btrim(telefone)
      HAVING COUNT(*) > 1
    ) t;

    IF v_duplicados > 0 THEN
      CREATE EXTENSION IF NOT EXISTS pg_cron;

      CREATE OR REPLACE FUNCTION public.excluir_contatos_duplicados_lote(p_lote integer DEFAULT 5000)
      RETURNS integer
      LANGUAGE plpgsql
      SECURITY DEFINER
      SET search_path = public
      AS $function$
      DECLARE
        v_removidos integer := 0;
      BEGIN
        -- Evita timeout no trigger de bloqueio durante limpeza técnica em lote
        SET LOCAL session_replication_role = replica;

        WITH alvo AS (
          SELECT id
          FROM (
            SELECT
              c.id,
              row_number() OVER (
                PARTITION BY c."contaId", btrim(c.telefone)
                ORDER BY c.id
              ) AS rn
            FROM public."SAAS_Contatos" c
            WHERE c.tipo = 'contato'
              AND c.telefone IS NOT NULL
              AND btrim(c.telefone) <> ''
          ) t
          WHERE t.rn > 1
          LIMIT p_lote
        )
        DELETE FROM public."SAAS_Conversas_Agentes" ca
        USING alvo
        WHERE ca."contatoId" = alvo.id;

        WITH alvo AS (
          SELECT id
          FROM (
            SELECT
              c.id,
              row_number() OVER (
                PARTITION BY c."contaId", btrim(c.telefone)
                ORDER BY c.id
              ) AS rn
            FROM public."SAAS_Contatos" c
            WHERE c.tipo = 'contato'
              AND c.telefone IS NOT NULL
              AND btrim(c.telefone) <> ''
          ) t
          WHERE t.rn > 1
          LIMIT p_lote
        )
        DELETE FROM public."SAAS_Contatos" c
        USING alvo
        WHERE c.id = alvo.id;

        GET DIAGNOSTICS v_removidos = ROW_COUNT;
        RETURN v_removidos;
      END;
      $function$;

      CREATE OR REPLACE FUNCTION public.worker_limpeza_contatos_duplicados()
      RETURNS void
      LANGUAGE plpgsql
      SECURITY DEFINER
      SET search_path = public
      AS $function$
      DECLARE
        v_removidos integer := 0;
        v_job record;
      BEGIN
        v_removidos := public.excluir_contatos_duplicados_lote(5000);

        IF v_removidos = 0 THEN
          CREATE OR REPLACE FUNCTION public.f_block_duplicate_contato()
          RETURNS trigger
          LANGUAGE plpgsql
          AS $inner$
          BEGIN
            IF NEW.tipo <> 'contato' THEN
              RETURN NEW;
            END IF;

            IF NEW.telefone IS NULL OR btrim(NEW.telefone) = '' THEN
              RETURN NEW;
            END IF;

            NEW.telefone := btrim(NEW.telefone);

            IF EXISTS (
              SELECT 1
              FROM public."SAAS_Contatos" c
              WHERE c."contaId" = NEW."contaId"
                AND btrim(c.telefone) = NEW.telefone
                AND c.tipo = 'contato'
                AND c.id <> COALESCE(NEW.id, -1)
            ) THEN
              RAISE EXCEPTION 'Contato duplicado para contaId % e telefone %', NEW."contaId", NEW.telefone;
            END IF;

            RETURN NEW;
          END;
          $inner$;

          DROP TRIGGER IF EXISTS trg_block_duplicate_contato ON public."SAAS_Contatos";
          CREATE TRIGGER trg_block_duplicate_contato
          BEFORE INSERT OR UPDATE OF "contaId", telefone, tipo ON public."SAAS_Contatos"
          FOR EACH ROW EXECUTE FUNCTION public.f_block_duplicate_contato();

          CREATE UNIQUE INDEX IF NOT EXISTS uq_saas_contatos_conta_telefone
          ON public."SAAS_Contatos"("contaId", telefone)
          WHERE telefone IS NOT NULL AND telefone != '';

          FOR v_job IN
            SELECT jobid
            FROM cron.job
            WHERE jobname = 'limpeza_contatos_duplicados_1min'
          LOOP
            PERFORM cron.unschedule(v_job.jobid);
          END LOOP;
        END IF;
      END;
      $function$;

      FOR v_job IN
        SELECT jobid FROM cron.job WHERE jobname = 'limpeza_contatos_duplicados_1min'
      LOOP
        PERFORM cron.unschedule(v_job.jobid);
      END LOOP;

      PERFORM cron.schedule(
        'limpeza_contatos_duplicados_1min',
        '* * * * *',
        $cron$SELECT public.worker_limpeza_contatos_duplicados();$cron$
      );

      RAISE NOTICE 'Foram encontrados % contatos duplicados. Cron agendado para remover 5000/min. SQL manual: SELECT public.excluir_contatos_duplicados_lote(5000);', v_duplicados;
    ELSE
      CREATE OR REPLACE FUNCTION public.f_block_duplicate_contato()
      RETURNS trigger
      LANGUAGE plpgsql
      AS $function$
      BEGIN
        IF NEW.tipo <> 'contato' THEN
          RETURN NEW;
        END IF;

        IF NEW.telefone IS NULL OR btrim(NEW.telefone) = '' THEN
          RETURN NEW;
        END IF;

        NEW.telefone := btrim(NEW.telefone);

        IF EXISTS (
          SELECT 1
          FROM public."SAAS_Contatos" c
          WHERE c."contaId" = NEW."contaId"
            AND btrim(c.telefone) = NEW.telefone
            AND c.tipo = 'contato'
            AND c.id <> COALESCE(NEW.id, -1)
        ) THEN
          RAISE EXCEPTION 'Contato duplicado para contaId % e telefone %', NEW."contaId", NEW.telefone;
        END IF;

        RETURN NEW;
      END;
      $function$;

      DROP TRIGGER IF EXISTS trg_block_duplicate_contato ON public."SAAS_Contatos";
      CREATE TRIGGER trg_block_duplicate_contato
      BEFORE INSERT OR UPDATE OF "contaId", telefone, tipo ON public."SAAS_Contatos"
      FOR EACH ROW EXECUTE FUNCTION public.f_block_duplicate_contato();

      CREATE UNIQUE INDEX IF NOT EXISTS uq_saas_contatos_conta_telefone
      ON public."SAAS_Contatos"("contaId", telefone)
      WHERE telefone IS NOT NULL AND telefone != '';
    END IF;
  END$$;

  -- 7. Remover idLista e colunas antigas
  DO $$ BEGIN IF to_regclass('public."SAAS_Contatos_Etiquetas"') IS NULL THEN ALTER TABLE public."SAAS_Contatos" DROP COLUMN IF EXISTS "idLista"; END IF; END $$;
  ALTER TABLE public."SAAS_Contatos" DROP COLUMN IF EXISTS "whatsappId";
  ALTER TABLE public."SAAS_Contatos" DROP COLUMN IF EXISTS "idConexao";
  ALTER TABLE public."SAAS_Contatos" DROP COLUMN IF EXISTS participantes;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Conversas_Agentes"') IS NOT NULL THEN
      ALTER TABLE public."SAAS_Conversas_Agentes"
        ALTER COLUMN "statusAtendimento" SET DEFAULT 'aguardando';
    END IF;
  END$$;

  -- 8. SAAS_Disparos: idListas → idEtiquetas
  ALTER TABLE public."SAAS_Disparos" ADD COLUMN IF NOT EXISTS "idEtiquetas" BIGINT[];
  ALTER TABLE public."SAAS_Disparos" ADD COLUMN IF NOT EXISTS "NomeDisparo" TEXT;
  ALTER TABLE public."SAAS_Disparos" ADD COLUMN IF NOT EXISTS "mostrarMensagem" BOOLEAN NOT NULL DEFAULT true;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Contatos_Etiquetas"') IS NOT NULL THEN RETURN; END IF;
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='SAAS_Disparos' AND column_name='idListas') THEN
      UPDATE public."SAAS_Disparos" SET "idEtiquetas" = "idListas" WHERE "idListas" IS NOT NULL;
      ALTER TABLE public."SAAS_Disparos" DROP COLUMN "idListas";
      RAISE NOTICE 'SAAS_Disparos: idListas migrado para idEtiquetas';
    END IF;
  END$$;

  -- 9. Remover SAAS_Grupos
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Grupos"') IS NULL THEN RETURN; END IF;
    DROP TRIGGER IF EXISTS trg_block_delete_grupo_if_active ON public."SAAS_Grupos";
    DROP TABLE IF EXISTS public."SAAS_Grupos" CASCADE;
  END $$;

  -- 10. Funções, trigger, RLS e GRANTs (etiquetas)
  CREATE OR REPLACE FUNCTION public.get_contatos_by_etiqueta(p_id_etiqueta bigint)
  RETURNS SETOF public."SAAS_Contatos" LANGUAGE sql STABLE AS $$
    SELECT c.* FROM public."SAAS_Contatos" c JOIN public."SAAS_Contatos_Etiquetas" ce ON ce."contatoId" = c.id
    WHERE ce."etiquetaId" = p_id_etiqueta AND c.tipo = 'contato';
  $$;

  CREATE OR REPLACE FUNCTION public.get_grupos_by_etiqueta(p_id_etiqueta bigint)
  RETURNS SETOF public."SAAS_Contatos" LANGUAGE sql STABLE AS $$
    SELECT c.* FROM public."SAAS_Contatos" c JOIN public."SAAS_Contatos_Etiquetas" ce ON ce."contatoId" = c.id
    WHERE ce."etiquetaId" = p_id_etiqueta AND c.tipo = 'grupo';
  $$;

  -- Exclusão de etiqueta: remove vínculos em lotes e depois a etiqueta (evita timeout em contas grandes).
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Etiquetas"') IS NULL THEN RETURN; END IF;
    DROP TRIGGER IF EXISTS trg_block_delete_lista_if_active ON public."SAAS_Etiquetas";
    DROP TRIGGER IF EXISTS trg_block_delete_etiqueta_if_active ON public."SAAS_Etiquetas";
  END$$;
  DROP FUNCTION IF EXISTS public.f_block_delete_etiqueta_if_active();

  CREATE OR REPLACE FUNCTION public.f_excluir_etiqueta(p_etiqueta_id bigint, p_conta_id uuid)
  RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
  DECLARE
    v_deleted int;
    v_lote constant int := 5000;
  BEGIN
    IF NOT public.is_admin(p_conta_id) AND NOT public.is_super_admin() THEN
      RETURN false;
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM public."SAAS_Etiquetas"
      WHERE id = p_etiqueta_id AND "contaId" = p_conta_id
    ) THEN
      RETURN false;
    END IF;

    LOOP
      DELETE FROM public."SAAS_Contatos_Etiquetas" ce
      WHERE ce.ctid IN (
        SELECT c.ctid
        FROM public."SAAS_Contatos_Etiquetas" c
        WHERE c."etiquetaId" = p_etiqueta_id AND c."contaId" = p_conta_id
        LIMIT v_lote
      );
      GET DIAGNOSTICS v_deleted = ROW_COUNT;
      EXIT WHEN v_deleted = 0;
    END LOOP;

    DELETE FROM public."SAAS_Etiquetas"
    WHERE id = p_etiqueta_id AND "contaId" = p_conta_id;

    RETURN true;
  END;
  $$;

  GRANT EXECUTE ON FUNCTION public.f_excluir_etiqueta(bigint, uuid) TO authenticated;

  -- create_disparo e create_disparo_grupo (modelo etiquetas)
  CREATE OR REPLACE FUNCTION public.create_disparo(p_payload jsonb)
  RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $function$
  DECLARE
    v_conta_id uuid := (p_payload ->> 'userId')::uuid;
    v_nome_disparo text := NULLIF(COALESCE(p_payload->>'nomeCampanha', p_payload->>'nomeDisparo', ''), '');
    v_fake_call boolean := COALESCE((p_payload #>> '{settings,fakecall}')::boolean, false);
    v_messages jsonb[] := ARRAY(SELECT m FROM jsonb_array_elements(COALESCE(p_payload->'mensagens','[]'::jsonb)) m);
    v_msg_count int := COALESCE(array_length(v_messages, 1), 0);
    v_conn_ids bigint[] := COALESCE(ARRAY(SELECT (c->>'id')::bigint FROM jsonb_array_elements(COALESCE(p_payload->'connections','[]'::jsonb)) c WHERE (c->>'id') ~ '^\d+$'), array[]::bigint[]);
    v_conn_count int := COALESCE(array_length(v_conn_ids,1),0);
    v_etiqueta_ids bigint[] := COALESCE(ARRAY(SELECT (x)::bigint FROM jsonb_array_elements_text(COALESCE(p_payload->'idLista', p_payload->'idEtiqueta','[]'::jsonb)) x), array[]::bigint[]);
    v_stage_ids bigint[] := COALESCE(
      ARRAY(
        SELECT DISTINCT (f->>'stageId')::bigint
        FROM jsonb_array_elements(COALESCE(p_payload->'settings'->'crmFilters','[]'::jsonb)) f
        WHERE (f->>'stageId') ~ '^\d+$'
      ),
      ARRAY(
        SELECT DISTINCT (x)::bigint
        FROM jsonb_array_elements_text(COALESCE(p_payload->'settings'->'crmStageIds','[]'::jsonb)) x
        WHERE x ~ '^\d+$'
      ),
      array[]::bigint[]
    );
    v_interval_min int := COALESCE((p_payload #>> '{settings,intervalMin}')::int, 30);
    v_interval_max int := COALESCE((p_payload #>> '{settings,intervalMax}')::int, 60);
    v_pause_after int := COALESCE((p_payload #>> '{settings,pauseAfterMessages}')::int, 0);
    v_pause_minutes int := COALESCE((p_payload #>> '{settings,pauseMinutes}')::int, 0);
    v_start_time time := COALESCE((p_payload #>> '{settings,startTime}')::time, time '08:00');
    v_end_time time := COALESCE((p_payload #>> '{settings,endTime}')::time, time '18:00');
    v_days int[] := COALESCE(ARRAY(SELECT CASE WHEN dtxt='0' THEN 7 ELSE dtxt::int END FROM jsonb_array_elements_text(COALESCE(p_payload->'settings'->'selectedDays','[]'::jsonb)) WITH ORDINALITY AS t(dtxt,ord) WHERE dtxt ~ '^\d+$' ORDER BY ord), array[]::int[]);
    v_schedule_base timestamptz := COALESCE((p_payload #>> '{settings,scheduleData}')::timestamptz, now() + interval '2 minutes');
    v_mostrar_mensagem boolean := COALESCE((p_payload #>> '{settings,mostrarMensagem}')::boolean, true);
    v_cur_ts timestamptz; v_disparo_id bigint; v_first_ts timestamptz; v_total int := 0; v_idx_msg int := 1; v_idx_conn int := 1; v_counter int := 0; v_gap int;
    v_msg_obj jsonb; v_template text; v_media_hash text; v_conn_id bigint; v_rendered text; rec_cont record;
    v_limit_plan bigint; v_used_month bigint; v_to_send bigint; v_total_after bigint;
    v_month_start timestamptz := (date_trunc('month', now() AT TIME ZONE 'America/Sao_Paulo') AT TIME ZONE 'America/Sao_Paulo');
    v_next_month timestamptz := ((date_trunc('month', now() AT TIME ZONE 'America/Sao_Paulo') + interval '1 month') AT TIME ZONE 'America/Sao_Paulo');
  BEGIN
    v_cur_ts := f_next_valid_time(v_schedule_base, v_start_time, v_end_time, v_days);
    SELECT p."qntDisparos"::bigint INTO v_limit_plan FROM public."SAAS_Contas" conta LEFT JOIN public."SAAS_Planos" p ON p.id = conta.plano WHERE conta.id = v_conta_id;
    IF v_limit_plan IS NOT NULL THEN
      SELECT COALESCE(COUNT(*),0)::bigint INTO v_used_month FROM public."SAAS_Detalhes_Disparos" d JOIN public."SAAS_Disparos" h ON h.id = d."idDisparo" WHERE h."contaId" = v_conta_id AND d."dataEnvio" >= v_month_start AND d."dataEnvio" < v_next_month;
      WITH etiqueta_contatos AS (
        SELECT DISTINCT c.id, c.telefone
        FROM public."SAAS_Contatos" c
        JOIN public."SAAS_Contatos_Etiquetas" ce ON ce."contatoId" = c.id
        WHERE c."contaId" = v_conta_id
          AND c.tipo = 'contato'
          AND c.telefone IS NOT NULL
          AND btrim(c.telefone) <> ''
          AND ce."etiquetaId" = ANY(v_etiqueta_ids)
      ),
      crm_contatos AS (
        SELECT DISTINCT c.id, c.telefone
        FROM public."SAAS_Contatos" c
        JOIN public."SAAS_Cards_Quadros" cq ON cq."contatoId" = c.id
        WHERE c."contaId" = v_conta_id
          AND c.tipo = 'contato'
          AND c.telefone IS NOT NULL
          AND btrim(c.telefone) <> ''
          AND cq."etapaQuadroId" = ANY(v_stage_ids)
      ),
      all_contatos AS (
        SELECT DISTINCT c.id, c.telefone
        FROM public."SAAS_Contatos" c
        WHERE c."contaId" = v_conta_id
          AND c.tipo = 'contato'
          AND c.telefone IS NOT NULL
          AND btrim(c.telefone) <> ''
          AND COALESCE(cardinality(v_etiqueta_ids),0) = 0
          AND COALESCE(cardinality(v_stage_ids),0) = 0
      ),
      base AS (
        SELECT telefone FROM etiqueta_contatos
        UNION
        SELECT telefone FROM crm_contatos
        UNION
        SELECT telefone FROM all_contatos
      )
      SELECT COALESCE(COUNT(*),0)::bigint INTO v_to_send FROM base;
      v_total_after := v_used_month + v_to_send;
      IF v_total_after > v_limit_plan THEN RAISE EXCEPTION 'limite atingido: % usados + % a enviar = %, limite = %', v_used_month, v_to_send, v_total_after, v_limit_plan USING ERRCODE='P0001'; END IF;
    END IF;
    INSERT INTO public."SAAS_Disparos" ("NomeDisparo","Mensagens","TipoDisparo","TotalDisparos","MensagensDisparadas","StatusDisparo","contaId","idEtiquetas","idConexoes","intervaloMin","intervaloMax","PausaAposMensagens","PausaMinutos","StartTime","EndTime","DiasSelecionados","DataAgendamento","mostrarMensagem")
    VALUES (v_nome_disparo,v_messages,'Individual',0,0,'Aguardando',v_conta_id,v_etiqueta_ids,v_conn_ids,v_interval_min,v_interval_max,v_pause_after,v_pause_minutes,v_start_time,v_end_time,v_days::smallint[],CASE WHEN p_payload #>> '{settings,scheduleData}' IS NOT NULL THEN v_schedule_base ELSE NULL END,v_mostrar_mensagem)
    RETURNING id INTO v_disparo_id;
    FOR rec_cont IN
      WITH etiqueta_contatos AS (
        SELECT DISTINCT c.id, c.telefone, c.nome, COALESCE(c.variaveis,'{}'::jsonb) AS base_variaveis
        FROM public."SAAS_Contatos" c
        JOIN public."SAAS_Contatos_Etiquetas" ce ON ce."contatoId" = c.id
        WHERE c."contaId" = v_conta_id
          AND c.tipo = 'contato'
          AND c.telefone IS NOT NULL
          AND btrim(c.telefone) <> ''
          AND ce."etiquetaId" = ANY(v_etiqueta_ids)
      ),
      crm_contatos AS (
        SELECT DISTINCT c.id, c.telefone, c.nome, COALESCE(c.variaveis,'{}'::jsonb) AS base_variaveis
        FROM public."SAAS_Contatos" c
        JOIN public."SAAS_Cards_Quadros" cq ON cq."contatoId" = c.id
        WHERE c."contaId" = v_conta_id
          AND c.tipo = 'contato'
          AND c.telefone IS NOT NULL
          AND btrim(c.telefone) <> ''
          AND cq."etapaQuadroId" = ANY(v_stage_ids)
      ),
      all_contatos AS (
        SELECT DISTINCT c.id, c.telefone, c.nome, COALESCE(c.variaveis,'{}'::jsonb) AS base_variaveis
        FROM public."SAAS_Contatos" c
        WHERE c."contaId" = v_conta_id
          AND c.tipo = 'contato'
          AND c.telefone IS NOT NULL
          AND btrim(c.telefone) <> ''
          AND COALESCE(cardinality(v_etiqueta_ids),0) = 0
          AND COALESCE(cardinality(v_stage_ids),0) = 0
      ),
      base AS (
        SELECT * FROM etiqueta_contatos
        UNION
        SELECT * FROM crm_contatos
        UNION
        SELECT * FROM all_contatos
      ),
      contato_custom_fields AS (
        SELECT
          b.id AS contato_id,
          COALESCE(
            jsonb_object_agg(
              lower(regexp_replace(cp."nome", '\s+', '_', 'g')),
              COALESCE(vcp."valor",'')
            ) FILTER (WHERE cp.id IS NOT NULL),
            '{}'::jsonb
          ) AS custom_variaveis
        FROM base b
        LEFT JOIN public."SAAS_Valores_Campos_Personalizados" vcp ON vcp."idContato" = b.id AND vcp."contaId" = v_conta_id
        LEFT JOIN public."SAAS_Campos_Personalizados" cp ON cp.id = vcp."idCampo" AND cp."contaId" = v_conta_id
        GROUP BY b.id
      )
      SELECT DISTINCT ON (b.telefone)
        b.id,
        b.telefone,
        b.nome,
        (COALESCE(b.base_variaveis,'{}'::jsonb) || COALESCE(ccf.custom_variaveis,'{}'::jsonb)) AS variaveis
      FROM base b
      LEFT JOIN contato_custom_fields ccf ON ccf.contato_id = b.id
      ORDER BY b.telefone, b.id
    LOOP
      v_msg_obj := v_messages[v_idx_msg]; v_idx_msg := (v_idx_msg % v_msg_count) + 1;
      v_template := v_msg_obj->>'text'; v_media_hash := NULLIF(COALESCE(v_msg_obj->'media'->>'link', v_msg_obj->'media'->>'hashredis',''),'');
      v_conn_id := CASE WHEN v_conn_count > 0 THEN v_conn_ids[v_idx_conn] END;
      IF v_conn_count > 0 THEN v_idx_conn := (v_idx_conn % v_conn_count) + 1; END IF;
      IF v_pause_after > 0 AND v_counter > 0 AND v_counter % v_pause_after = 0 THEN v_cur_ts := f_next_valid_time(v_cur_ts + make_interval(mins => v_pause_minutes), v_start_time, v_end_time, v_days); END IF;
      v_rendered := f_render_message(v_template, rec_cont.nome, COALESCE(rec_cont.variaveis,'{}'::jsonb), v_cur_ts);
      INSERT INTO public."SAAS_Detalhes_Disparos" ("idDisparo","idContato","Mensagem","idConexao","dataEnvio","Status","KeyRedis","FakeCall")
      VALUES (v_disparo_id, rec_cont.id, v_rendered, v_conn_id, v_cur_ts, 'pending', v_media_hash, v_fake_call);
      IF v_total = 0 THEN v_first_ts := v_cur_ts; END IF;
      v_total := v_total + 1; v_counter := v_counter + 1;
      v_gap := v_interval_min + floor(random() * (v_interval_max - v_interval_min + 1))::int;
      v_cur_ts := f_next_valid_time(v_cur_ts + make_interval(secs => v_gap), v_start_time, v_end_time, v_days);
    END LOOP;
    UPDATE public."SAAS_Disparos" SET "TotalDisparos"=v_total, "StatusDisparo"=CASE WHEN v_first_ts > now() THEN 'Aguardando' ELSE 'Em andamento' END WHERE id=v_disparo_id;
    RETURN v_disparo_id;
  END $function$;

  CREATE OR REPLACE FUNCTION public.edit_disparo(p_payload jsonb)
  RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $function$
  DECLARE
    v_disparo_id bigint := (p_payload->>'idDisparo')::bigint;
    v_conta_id uuid := (p_payload->>'userId')::uuid;
    v_nome_disparo text := NULLIF(COALESCE(p_payload->>'nomeCampanha', p_payload->>'nomeDisparo', ''), '');
    v_messages jsonb[] := ARRAY(SELECT m FROM jsonb_array_elements(COALESCE(p_payload->'mensagens','[]'::jsonb)) m);
    v_msg_count int := coalesce(array_length(v_messages,1),0);
    v_conn_ids bigint[] := COALESCE(ARRAY(SELECT (c->>'id')::bigint FROM jsonb_array_elements(COALESCE(p_payload->'connections','[]'::jsonb)) c WHERE (c->>'id') ~ '^\d+$'), array[]::bigint[]);
    v_conn_count int := coalesce(array_length(v_conn_ids,1),0);
    v_etiqueta_ids bigint[] := COALESCE(ARRAY(SELECT (x)::bigint FROM jsonb_array_elements_text(COALESCE(p_payload->'idLista', p_payload->'idEtiqueta', '[]'::jsonb)) x), array[]::bigint[]);
    v_stage_ids bigint[] := COALESCE(
      ARRAY(
        SELECT DISTINCT (f->>'stageId')::bigint
        FROM jsonb_array_elements(COALESCE(p_payload->'settings'->'crmFilters', '[]'::jsonb)) f
        WHERE (f->>'stageId') ~ '^\d+$'
      ),
      ARRAY(
        SELECT DISTINCT (x)::bigint
        FROM jsonb_array_elements_text(COALESCE(p_payload->'settings'->'crmStageIds','[]'::jsonb)) x
        WHERE x ~ '^\d+$'
      ),
      array[]::bigint[]
    );
    v_interval_min int := COALESCE((p_payload #>> '{settings,intervalMin}')::int, 30);
    v_interval_max int := COALESCE((p_payload #>> '{settings,intervalMax}')::int, 60);
    v_pause_after int := COALESCE((p_payload #>> '{settings,pauseAfterMessages}')::int, 20);
    v_pause_minutes int := COALESCE((p_payload #>> '{settings,pauseMinutes}')::int, 10);
    v_start_time time := COALESCE((p_payload #>> '{settings,startTime}')::time, time '08:00');
    v_end_time time := COALESCE((p_payload #>> '{settings,endTime}')::time, time '18:00');
    v_days int[] := COALESCE(ARRAY(
      SELECT CASE WHEN dtxt='0' THEN 7 ELSE dtxt::int END
      FROM jsonb_array_elements_text(COALESCE(p_payload->'settings'->'selectedDays','[]'::jsonb)) WITH ORDINALITY AS t(dtxt,ord)
      WHERE dtxt ~ '^\d+$'
      ORDER BY ord
    ), array[]::int[]);
    v_schedule_base timestamptz := COALESCE((p_payload#>>'{settings,scheduleData}')::timestamptz, now() + interval '2 minutes');
    v_cur_ts timestamptz;
    v_idx_msg int := 1;
    v_idx_conn int := 1;
    v_counter int := 0;
    v_gap int;
    v_msg_obj jsonb;
    v_template text;
    v_media_hash text;
    v_conn_id bigint;
    v_rendered text;
    rec_cont record;
    v_pending_total int := 0;
    v_first_pending_ts timestamptz := NULL;
    v_old_status text := NULL;
  BEGIN
    IF v_disparo_id IS NULL OR v_conta_id IS NULL THEN
      RAISE EXCEPTION 'idDisparo e userId são obrigatórios' USING ERRCODE='P0001';
    END IF;
    IF v_msg_count = 0 THEN
      RAISE EXCEPTION 'mensagens não pode ser vazio' USING ERRCODE='P0001';
    END IF;

    PERFORM 1
    FROM public."SAAS_Disparos" d
    WHERE d.id = v_disparo_id
      AND d."contaId" = v_conta_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'disparo % não encontrado para a conta', v_disparo_id USING ERRCODE='P0001';
    END IF;

    IF COALESCE(cardinality(v_conn_ids), 0) > 0 THEN
      v_conn_ids := COALESCE(ARRAY(
        SELECT c.id
        FROM unnest(v_conn_ids) AS uid(id)
        INNER JOIN public."SAAS_Conexões" c ON c.id = uid.id AND c."contaId" = v_conta_id
        ORDER BY c.id
      ), ARRAY[]::bigint[]);
      v_conn_count := COALESCE(array_length(v_conn_ids, 1), 0);
    END IF;
    IF COALESCE(jsonb_array_length(COALESCE(p_payload->'connections', '[]'::jsonb)), 0) > 0 AND v_conn_count = 0 THEN
      RAISE EXCEPTION 'Nenhuma conexão válida encontrada para esta conta' USING ERRCODE='P0001';
    END IF;

    IF v_interval_min <= 0 THEN v_interval_min := 30; END IF;
    IF v_interval_max <= 0 THEN v_interval_max := 60; END IF;
    IF v_interval_max < v_interval_min THEN v_interval_max := v_interval_min; END IF;
    IF v_pause_after < 0 THEN v_pause_after := 0; END IF;
    IF v_pause_minutes < 0 THEN v_pause_minutes := 0; END IF;
    IF COALESCE(cardinality(v_days),0) = 0 THEN v_days := ARRAY[1,2,3,4,5,6,7]; END IF;
    v_cur_ts := f_next_valid_time(v_schedule_base, v_start_time, v_end_time, v_days);

    CREATE TEMP TABLE IF NOT EXISTS _tmp_edit_disparo_targets (
      "idContato" bigint PRIMARY KEY,
      "Mensagem" text,
      "idConexao" bigint,
      "dataEnvio" timestamptz,
      "KeyRedis" text
    ) ON COMMIT DROP;
    TRUNCATE _tmp_edit_disparo_targets;
    CREATE TEMP TABLE IF NOT EXISTS _tmp_edit_disparo_pending_keep (
      id bigint PRIMARY KEY,
      "idContato" bigint UNIQUE
    ) ON COMMIT DROP;
    TRUNCATE _tmp_edit_disparo_pending_keep;
    CREATE TEMP TABLE IF NOT EXISTS _tmp_edit_disparo_done_contacts (
      "idContato" bigint PRIMARY KEY
    ) ON COMMIT DROP;
    TRUNCATE _tmp_edit_disparo_done_contacts;
    INSERT INTO _tmp_edit_disparo_done_contacts ("idContato")
    SELECT DISTINCT d."idContato"
    FROM public."SAAS_Detalhes_Disparos" d
    WHERE d."idDisparo" = v_disparo_id
      AND d."idContato" IS NOT NULL
      AND lower(COALESCE(d."Status",'')) <> 'pending';

    FOR rec_cont IN
      WITH etiqueta_contatos AS (
        SELECT DISTINCT c.id, c.telefone, c.nome, COALESCE(c.variaveis,'{}'::jsonb) AS base_variaveis
        FROM public."SAAS_Contatos" c
        JOIN public."SAAS_Contatos_Etiquetas" ce ON ce."contatoId" = c.id
        WHERE c."contaId" = v_conta_id
          AND c.tipo = 'contato'
          AND c.telefone IS NOT NULL
          AND btrim(c.telefone) <> ''
          AND ce."etiquetaId" = ANY(v_etiqueta_ids)
      ),
      crm_contatos AS (
        SELECT DISTINCT c.id, c.telefone, c.nome, COALESCE(c.variaveis,'{}'::jsonb) AS base_variaveis
        FROM public."SAAS_Contatos" c
        JOIN public."SAAS_Cards_Quadros" cq ON cq."contatoId" = c.id
        WHERE c."contaId" = v_conta_id
          AND c.tipo = 'contato'
          AND c.telefone IS NOT NULL
          AND btrim(c.telefone) <> ''
          AND cq."etapaQuadroId" = ANY(v_stage_ids)
      ),
      all_contatos AS (
        SELECT DISTINCT c.id, c.telefone, c.nome, COALESCE(c.variaveis,'{}'::jsonb) AS base_variaveis
        FROM public."SAAS_Contatos" c
        WHERE c."contaId" = v_conta_id
          AND c.tipo = 'contato'
          AND c.telefone IS NOT NULL
          AND btrim(c.telefone) <> ''
          AND COALESCE(cardinality(v_etiqueta_ids),0) = 0
          AND COALESCE(cardinality(v_stage_ids),0) = 0
      ),
      base AS (
        SELECT * FROM etiqueta_contatos
        UNION
        SELECT * FROM crm_contatos
        UNION
        SELECT * FROM all_contatos
      ),
      contato_custom_fields AS (
        SELECT
          b.id AS contato_id,
          COALESCE(
            jsonb_object_agg(
              lower(regexp_replace(cp."nome", '\s+', '_', 'g')),
              COALESCE(vcp."valor",'')
            ) FILTER (WHERE cp.id IS NOT NULL),
            '{}'::jsonb
          ) AS custom_variaveis
        FROM base b
        LEFT JOIN public."SAAS_Valores_Campos_Personalizados" vcp ON vcp."idContato" = b.id AND vcp."contaId" = v_conta_id
        LEFT JOIN public."SAAS_Campos_Personalizados" cp ON cp.id = vcp."idCampo" AND cp."contaId" = v_conta_id
        GROUP BY b.id
      )
      SELECT DISTINCT ON (b.telefone)
        b.id,
        b.telefone,
        b.nome,
        (COALESCE(b.base_variaveis,'{}'::jsonb) || COALESCE(ccf.custom_variaveis,'{}'::jsonb)) AS variaveis
      FROM base b
      LEFT JOIN contato_custom_fields ccf ON ccf.contato_id = b.id
      WHERE NOT EXISTS (
        SELECT 1 FROM _tmp_edit_disparo_done_contacts dc WHERE dc."idContato" = b.id
      )
      ORDER BY b.telefone, b.id
    LOOP
      v_msg_obj := v_messages[v_idx_msg];
      v_idx_msg := (v_idx_msg % v_msg_count) + 1;
      v_template := v_msg_obj->>'text';
      v_media_hash := NULLIF(COALESCE(v_msg_obj->'media'->>'link', v_msg_obj->'media'->>'hashredis',''),'');
      v_conn_id := CASE WHEN v_conn_count > 0 THEN v_conn_ids[v_idx_conn] END;
      IF v_conn_count > 0 THEN v_idx_conn := (v_idx_conn % v_conn_count) + 1; END IF;

      IF v_pause_after > 0 AND v_counter > 0 AND v_counter % v_pause_after = 0 THEN
        v_cur_ts := f_next_valid_time(v_cur_ts + make_interval(mins => v_pause_minutes), v_start_time, v_end_time, v_days);
      END IF;

      v_rendered := f_render_message(v_template, rec_cont.nome, COALESCE(rec_cont.variaveis,'{}'::jsonb), v_cur_ts);
      INSERT INTO _tmp_edit_disparo_targets ("idContato","Mensagem","idConexao","dataEnvio","KeyRedis")
      VALUES (rec_cont.id, v_rendered, v_conn_id, v_cur_ts, v_media_hash)
      ON CONFLICT ("idContato") DO UPDATE
        SET "Mensagem" = EXCLUDED."Mensagem",
            "idConexao" = EXCLUDED."idConexao",
            "dataEnvio" = EXCLUDED."dataEnvio",
            "KeyRedis" = EXCLUDED."KeyRedis";

      IF v_first_pending_ts IS NULL THEN v_first_pending_ts := v_cur_ts; END IF;
      v_counter := v_counter + 1;
      v_gap := v_interval_min + floor(random() * (v_interval_max - v_interval_min + 1))::int;
      v_cur_ts := f_next_valid_time(v_cur_ts + make_interval(secs => v_gap), v_start_time, v_end_time, v_days);
    END LOOP;

    INSERT INTO _tmp_edit_disparo_pending_keep (id, "idContato")
    SELECT DISTINCT ON (d."idContato")
      d.id, d."idContato"
    FROM public."SAAS_Detalhes_Disparos" d
    WHERE d."idDisparo" = v_disparo_id
      AND lower(COALESCE(d."Status",'')) = 'pending'
      AND d."idContato" IS NOT NULL
    ORDER BY d."idContato", d.id DESC;

    DELETE FROM public."SAAS_Detalhes_Disparos" d
    WHERE d."idDisparo" = v_disparo_id
      AND lower(COALESCE(d."Status",'')) = 'pending'
      AND (
        d.id NOT IN (SELECT k.id FROM _tmp_edit_disparo_pending_keep k)
        OR NOT EXISTS (
          SELECT 1
          FROM _tmp_edit_disparo_targets t
          WHERE t."idContato" = d."idContato"
        )
      );

    UPDATE public."SAAS_Detalhes_Disparos" d
    SET "Mensagem" = t."Mensagem",
        "idConexao" = t."idConexao",
        "dataEnvio" = t."dataEnvio",
        "KeyRedis" = t."KeyRedis"
    FROM _tmp_edit_disparo_targets t
    WHERE d."idDisparo" = v_disparo_id
      AND lower(COALESCE(d."Status",'')) = 'pending'
      AND d."idContato" = t."idContato";

    INSERT INTO public."SAAS_Detalhes_Disparos" ("idDisparo","idContato","Mensagem","idConexao","dataEnvio","Status","KeyRedis","FakeCall")
    SELECT v_disparo_id, t."idContato", t."Mensagem", t."idConexao", t."dataEnvio", 'pending', t."KeyRedis", false
    FROM _tmp_edit_disparo_targets t
    WHERE NOT EXISTS (
      SELECT 1
      FROM public."SAAS_Detalhes_Disparos" d
      WHERE d."idDisparo" = v_disparo_id
        AND d."idContato" = t."idContato"
    );

    SELECT COALESCE(COUNT(*),0)::int INTO v_pending_total
    FROM public."SAAS_Detalhes_Disparos" d
    WHERE d."idDisparo" = v_disparo_id
      AND lower(COALESCE(d."Status",'')) = 'pending';

    SELECT "StatusDisparo" INTO v_old_status FROM public."SAAS_Disparos" WHERE id = v_disparo_id;

    UPDATE public."SAAS_Disparos"
    SET "NomeDisparo" = COALESCE(v_nome_disparo, "NomeDisparo"),
        "Mensagens" = v_messages,
        "idEtiquetas" = v_etiqueta_ids,
        "idConexoes" = CASE WHEN v_conn_count > 0 THEN v_conn_ids ELSE NULL END,
        "intervaloMin" = v_interval_min,
        "intervaloMax" = v_interval_max,
        "PausaAposMensagens" = v_pause_after,
        "PausaMinutos" = v_pause_minutes,
        "StartTime" = v_start_time,
        "EndTime" = v_end_time,
        "DiasSelecionados" = v_days::smallint[],
        "DataAgendamento" = CASE WHEN p_payload #>> '{settings,scheduleData}' IS NOT NULL THEN v_schedule_base ELSE NULL END,
        "TotalDisparos" = (
          SELECT COUNT(*)::int
          FROM public."SAAS_Detalhes_Disparos" dd
          WHERE dd."idDisparo" = v_disparo_id
        ),
        "StatusDisparo" = CASE
          WHEN lower(COALESCE(v_old_status,'')) = 'pausado' THEN 'Pausado'
          WHEN v_pending_total = 0 THEN COALESCE(v_old_status, 'Finalizado')
          WHEN v_first_pending_ts > now() THEN 'Aguardando'
          ELSE 'Em andamento'
        END
    WHERE id = v_disparo_id
      AND "contaId" = v_conta_id;

    RETURN v_disparo_id;
  END $function$;

  CREATE OR REPLACE FUNCTION public.edit_disparo_grupo(p_payload jsonb)
  RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $function$
  DECLARE
    v_disparo_id bigint := (p_payload->>'idDisparo')::bigint;
    v_conta_id uuid := (p_payload->>'userId')::uuid;
    v_nome_disparo text := NULLIF(COALESCE(p_payload->>'nomeCampanha', p_payload->>'nomeDisparo', ''), '');
    v_mention_all boolean := coalesce((p_payload#>>'{settings,mencionarTodos}')::boolean,false);
    v_messages jsonb[] := ARRAY(SELECT m FROM jsonb_array_elements(COALESCE(p_payload->'mensagens','[]'::jsonb)) m);
    v_msg_count int := coalesce(array_length(v_messages,1),0);
    v_conn_id bigint := (SELECT (c->>'id')::bigint FROM jsonb_array_elements(COALESCE(p_payload->'connections','[]'::jsonb)) c WHERE (c->>'id') ~ '^\d+$' ORDER BY 1 LIMIT 1);
    v_etiqueta_ids bigint[] := COALESCE(ARRAY(SELECT (x)::bigint FROM jsonb_array_elements_text(COALESCE(p_payload->'idLista', p_payload->'idEtiqueta','[]'::jsonb)) x), array[]::bigint[]);
    v_stage_ids bigint[] := COALESCE(
      ARRAY(
        SELECT DISTINCT (f->>'stageId')::bigint
        FROM jsonb_array_elements(COALESCE(p_payload->'settings'->'crmFilters','[]'::jsonb)) f
        WHERE (f->>'stageId') ~ '^\d+$'
      ),
      ARRAY(
        SELECT DISTINCT (x)::bigint
        FROM jsonb_array_elements_text(COALESCE(p_payload->'settings'->'crmStageIds','[]'::jsonb)) x
        WHERE x ~ '^\d+$'
      ),
      array[]::bigint[]
    );
    v_interval_min int := COALESCE((p_payload #>> '{settings,intervalMin}')::int, 30);
    v_interval_max int := COALESCE((p_payload #>> '{settings,intervalMax}')::int, 60);
    v_pause_after int := COALESCE((p_payload #>> '{settings,pauseAfterMessages}')::int, 20);
    v_pause_minutes int := COALESCE((p_payload #>> '{settings,pauseMinutes}')::int, 10);
    v_start_time time := COALESCE((p_payload #>> '{settings,startTime}')::time, time '08:00');
    v_end_time time := COALESCE((p_payload #>> '{settings,endTime}')::time, time '18:00');
    v_days int[] := COALESCE(ARRAY(
      SELECT CASE WHEN dtxt='0' THEN 7 ELSE dtxt::int END
      FROM jsonb_array_elements_text(COALESCE(p_payload->'settings'->'selectedDays','[]'::jsonb)) WITH ORDINALITY AS t(dtxt,ord)
      WHERE dtxt ~ '^\d+$'
      ORDER BY ord
    ), array[]::int[]);
    v_schedule_base timestamptz := COALESCE((p_payload#>>'{settings,scheduleData}')::timestamptz, now() + interval '2 minutes');
    v_cur_ts timestamptz;
    v_idx_msg int := 1;
    v_counter int := 0;
    v_gap int;
    v_msg_obj jsonb;
    v_template text;
    v_media_hash text;
    v_rendered text;
    rec_cont record;
    v_pending_total int := 0;
    v_first_pending_ts timestamptz := NULL;
    v_old_status text := NULL;
  BEGIN
    IF v_disparo_id IS NULL OR v_conta_id IS NULL THEN
      RAISE EXCEPTION 'idDisparo e userId são obrigatórios' USING ERRCODE='P0001';
    END IF;
    IF v_msg_count = 0 THEN
      RAISE EXCEPTION 'mensagens não pode ser vazio' USING ERRCODE='P0001';
    END IF;

    PERFORM 1
    FROM public."SAAS_Disparos" d
    WHERE d.id = v_disparo_id
      AND d."contaId" = v_conta_id
      AND lower(coalesce(d."TipoDisparo",'')) = 'grupos';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'disparo de grupos % não encontrado para a conta', v_disparo_id USING ERRCODE='P0001';
    END IF;

    IF v_conn_id IS NOT NULL THEN
      SELECT c.id INTO v_conn_id
      FROM public."SAAS_Conexões" c
      WHERE c.id = v_conn_id AND c."contaId" = v_conta_id
      LIMIT 1;
    END IF;
    IF COALESCE(jsonb_array_length(COALESCE(p_payload->'connections', '[]'::jsonb)), 0) > 0 AND v_conn_id IS NULL THEN
      RAISE EXCEPTION 'Nenhuma conexão válida encontrada para esta conta' USING ERRCODE='P0001';
    END IF;

    IF v_interval_min <= 0 THEN v_interval_min := 30; END IF;
    IF v_interval_max <= 0 THEN v_interval_max := 60; END IF;
    IF v_interval_max < v_interval_min THEN v_interval_max := v_interval_min; END IF;
    IF v_pause_after < 0 THEN v_pause_after := 0; END IF;
    IF v_pause_minutes < 0 THEN v_pause_minutes := 0; END IF;
    IF COALESCE(cardinality(v_days),0) = 0 THEN v_days := ARRAY[1,2,3,4,5,6,7]; END IF;
    v_cur_ts := f_next_valid_time(v_schedule_base, v_start_time, v_end_time, v_days);

    CREATE TEMP TABLE IF NOT EXISTS _tmp_edit_disparo_grupo_targets (
      "idContato" bigint PRIMARY KEY,
      "whatsappId" text,
      "Mensagem" text,
      "dataEnvio" timestamptz,
      "KeyRedis" text
    ) ON COMMIT DROP;
    TRUNCATE _tmp_edit_disparo_grupo_targets;
    CREATE TEMP TABLE IF NOT EXISTS _tmp_edit_disparo_grupo_pending_keep (
      id bigint PRIMARY KEY,
      "idContato" bigint UNIQUE
    ) ON COMMIT DROP;
    TRUNCATE _tmp_edit_disparo_grupo_pending_keep;
    CREATE TEMP TABLE IF NOT EXISTS _tmp_edit_disparo_grupo_done_contacts (
      "idContato" bigint PRIMARY KEY
    ) ON COMMIT DROP;
    TRUNCATE _tmp_edit_disparo_grupo_done_contacts;
    INSERT INTO _tmp_edit_disparo_grupo_done_contacts ("idContato")
    SELECT DISTINCT d."idContato"
    FROM public."SAAS_Detalhes_Disparos" d
    WHERE d."idDisparo" = v_disparo_id
      AND d."idContato" IS NOT NULL
      AND lower(COALESCE(d."Status",'')) <> 'pending';

    FOR rec_cont IN
      WITH etiqueta_grupos AS (
        SELECT DISTINCT c.id, c.nome, COALESCE(c.variaveis,'{}'::jsonb) AS base_variaveis
        FROM public."SAAS_Contatos" c
        JOIN public."SAAS_Contatos_Etiquetas" ce ON ce."contatoId" = c.id
        WHERE c."contaId" = v_conta_id
          AND c.tipo = 'grupo'
          AND ce."etiquetaId" = ANY(v_etiqueta_ids)
          AND NULLIF(btrim(c.variaveis->>'whatsappId'),'') IS NOT NULL
      ),
      crm_grupos AS (
        SELECT DISTINCT c.id, c.nome, COALESCE(c.variaveis,'{}'::jsonb) AS base_variaveis
        FROM public."SAAS_Contatos" c
        JOIN public."SAAS_Cards_Quadros" cq ON cq."contatoId" = c.id
        WHERE c."contaId" = v_conta_id
          AND c.tipo = 'grupo'
          AND cq."etapaQuadroId" = ANY(v_stage_ids)
          AND NULLIF(btrim(c.variaveis->>'whatsappId'),'') IS NOT NULL
      ),
      all_grupos AS (
        SELECT DISTINCT c.id, c.nome, COALESCE(c.variaveis,'{}'::jsonb) AS base_variaveis
        FROM public."SAAS_Contatos" c
        WHERE c."contaId" = v_conta_id
          AND c.tipo = 'grupo'
          AND NULLIF(btrim(c.variaveis->>'whatsappId'),'') IS NOT NULL
          AND COALESCE(cardinality(v_etiqueta_ids),0) = 0
          AND COALESCE(cardinality(v_stage_ids),0) = 0
      ),
      base AS (
        SELECT * FROM etiqueta_grupos
        UNION
        SELECT * FROM crm_grupos
        UNION
        SELECT * FROM all_grupos
      ),
      contato_custom_fields AS (
        SELECT
          b.id AS contato_id,
          COALESCE(
            jsonb_object_agg(
              lower(regexp_replace(cp."nome", '\s+', '_', 'g')),
              COALESCE(vcp."valor",'')
            ) FILTER (WHERE cp.id IS NOT NULL),
            '{}'::jsonb
          ) AS custom_variaveis
        FROM base b
        LEFT JOIN public."SAAS_Valores_Campos_Personalizados" vcp ON vcp."idContato" = b.id AND vcp."contaId" = v_conta_id
        LEFT JOIN public."SAAS_Campos_Personalizados" cp ON cp.id = vcp."idCampo" AND cp."contaId" = v_conta_id
        GROUP BY b.id
      )
      SELECT DISTINCT ON ((coalesce(b.base_variaveis->>'whatsappId','')))
        b.id,
        coalesce(b.base_variaveis->>'whatsappId','') AS "whatsappId",
        b.nome,
        (COALESCE(b.base_variaveis,'{}'::jsonb) || COALESCE(ccf.custom_variaveis,'{}'::jsonb)) AS variaveis
      FROM base b
      LEFT JOIN contato_custom_fields ccf ON ccf.contato_id = b.id
      WHERE NOT EXISTS (
        SELECT 1 FROM _tmp_edit_disparo_grupo_done_contacts dc WHERE dc."idContato" = b.id
      )
      ORDER BY (coalesce(b.base_variaveis->>'whatsappId','')), b.id
    LOOP
      v_msg_obj := v_messages[v_idx_msg];
      v_idx_msg := (v_idx_msg % v_msg_count) + 1;
      v_template := v_msg_obj->>'text';
      v_media_hash := NULLIF(COALESCE(v_msg_obj->'media'->>'link', v_msg_obj->'media'->>'hashredis',''),'');

      IF v_pause_after > 0 AND v_counter > 0 AND v_counter % v_pause_after = 0 THEN
        v_cur_ts := f_next_valid_time(v_cur_ts + make_interval(mins => v_pause_minutes), v_start_time, v_end_time, v_days);
      END IF;

      v_rendered := public.f_render_message(v_template, rec_cont.nome, COALESCE(rec_cont.variaveis,'{}'::jsonb), v_cur_ts);
      INSERT INTO _tmp_edit_disparo_grupo_targets ("idContato","whatsappId","Mensagem","dataEnvio","KeyRedis")
      VALUES (rec_cont.id, rec_cont."whatsappId", v_rendered, v_cur_ts, v_media_hash)
      ON CONFLICT ("idContato") DO UPDATE
        SET "whatsappId" = EXCLUDED."whatsappId",
            "Mensagem" = EXCLUDED."Mensagem",
            "dataEnvio" = EXCLUDED."dataEnvio",
            "KeyRedis" = EXCLUDED."KeyRedis";

      IF v_first_pending_ts IS NULL THEN v_first_pending_ts := v_cur_ts; END IF;
      v_counter := v_counter + 1;
      v_gap := v_interval_min + floor(random() * (v_interval_max - v_interval_min + 1))::int;
      v_cur_ts := f_next_valid_time(v_cur_ts + make_interval(secs => v_gap), v_start_time, v_end_time, v_days);
    END LOOP;

    INSERT INTO _tmp_edit_disparo_grupo_pending_keep (id, "idContato")
    SELECT DISTINCT ON (d."idContato")
      d.id, d."idContato"
    FROM public."SAAS_Detalhes_Disparos" d
    WHERE d."idDisparo" = v_disparo_id
      AND lower(COALESCE(d."Status",'')) = 'pending'
      AND d."idContato" IS NOT NULL
    ORDER BY d."idContato", d.id DESC;

    DELETE FROM public."SAAS_Detalhes_Disparos" d
    WHERE d."idDisparo" = v_disparo_id
      AND lower(COALESCE(d."Status",'')) = 'pending'
      AND (
        d.id NOT IN (SELECT k.id FROM _tmp_edit_disparo_grupo_pending_keep k)
        OR NOT EXISTS (
          SELECT 1
          FROM _tmp_edit_disparo_grupo_targets t
          WHERE t."idContato" = d."idContato"
        )
      );

    UPDATE public."SAAS_Detalhes_Disparos" d
    SET "Mensagem" = t."Mensagem",
        "idConexao" = v_conn_id,
        "dataEnvio" = t."dataEnvio",
        "KeyRedis" = t."KeyRedis",
        "FakeCall" = v_mention_all
    FROM _tmp_edit_disparo_grupo_targets t
    WHERE d."idDisparo" = v_disparo_id
      AND lower(COALESCE(d."Status",'')) = 'pending'
      AND d."idContato" = t."idContato";

    INSERT INTO public."SAAS_Detalhes_Disparos" ("idDisparo","idContato","Mensagem","idConexao","dataEnvio","Status","KeyRedis","FakeCall")
    SELECT v_disparo_id, t."idContato", t."Mensagem", v_conn_id, t."dataEnvio", 'pending', t."KeyRedis", v_mention_all
    FROM _tmp_edit_disparo_grupo_targets t
    WHERE NOT EXISTS (
      SELECT 1
      FROM public."SAAS_Detalhes_Disparos" d
      WHERE d."idDisparo" = v_disparo_id
        AND d."idContato" = t."idContato"
    );

    SELECT COALESCE(COUNT(*),0)::int INTO v_pending_total
    FROM public."SAAS_Detalhes_Disparos" d
    WHERE d."idDisparo" = v_disparo_id
      AND lower(COALESCE(d."Status",'')) = 'pending';

    SELECT "StatusDisparo" INTO v_old_status FROM public."SAAS_Disparos" WHERE id = v_disparo_id;

    UPDATE public."SAAS_Disparos"
    SET "NomeDisparo" = COALESCE(v_nome_disparo, "NomeDisparo"),
        "Mensagens" = v_messages,
        "idEtiquetas" = v_etiqueta_ids,
        "idConexoes" = CASE WHEN v_conn_id IS NOT NULL THEN ARRAY[v_conn_id] ELSE NULL END,
        "intervaloMin" = v_interval_min,
        "intervaloMax" = v_interval_max,
        "PausaAposMensagens" = v_pause_after,
        "PausaMinutos" = v_pause_minutes,
        "StartTime" = v_start_time,
        "EndTime" = v_end_time,
        "DiasSelecionados" = v_days::smallint[],
        "DataAgendamento" = CASE WHEN p_payload #>> '{settings,scheduleData}' IS NOT NULL THEN v_schedule_base ELSE NULL END,
        "TotalDisparos" = (
          SELECT COUNT(*)::int
          FROM public."SAAS_Detalhes_Disparos" dd
          WHERE dd."idDisparo" = v_disparo_id
        ),
        "StatusDisparo" = CASE
          WHEN lower(COALESCE(v_old_status,'')) = 'pausado' THEN 'Pausado'
          WHEN v_pending_total = 0 THEN COALESCE(v_old_status, 'Finalizado')
          WHEN v_first_pending_ts > now() THEN 'Aguardando'
          ELSE 'Em andamento'
        END
    WHERE id = v_disparo_id
      AND "contaId" = v_conta_id;

    RETURN v_disparo_id;
  END $function$;

  CREATE OR REPLACE FUNCTION public.create_disparo_grupo(p_payload jsonb)
  RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $function$
  DECLARE
    v_conta_id uuid := (p_payload->>'userId')::uuid;
    v_nome_disparo text := NULLIF(COALESCE(p_payload->>'nomeCampanha', p_payload->>'nomeDisparo', ''), '');
    v_mention_all boolean := coalesce((p_payload#>>'{settings,mencionarTodos}')::boolean,false);
    v_messages jsonb[] := ARRAY(SELECT m FROM jsonb_array_elements(COALESCE(p_payload->'mensagens','[]'::jsonb)) m);
    v_msg_count int := coalesce(array_length(v_messages,1),0);
    v_conn_id bigint := (SELECT (c->>'id')::bigint FROM jsonb_array_elements(COALESCE(p_payload->'connections','[]'::jsonb)) c WHERE (c->>'id') ~ '^\d+$' ORDER BY 1 LIMIT 1);
    v_etiqueta_ids bigint[] := COALESCE(ARRAY(SELECT (x)::bigint FROM jsonb_array_elements_text(COALESCE(p_payload->'idLista', p_payload->'idEtiqueta','[]'::jsonb)) x), array[]::bigint[]);
    v_stage_ids bigint[] := COALESCE(
      ARRAY(
        SELECT DISTINCT (f->>'stageId')::bigint
        FROM jsonb_array_elements(COALESCE(p_payload->'settings'->'crmFilters','[]'::jsonb)) f
        WHERE (f->>'stageId') ~ '^\d+$'
      ),
      ARRAY(
        SELECT DISTINCT (x)::bigint
        FROM jsonb_array_elements_text(COALESCE(p_payload->'settings'->'crmStageIds','[]'::jsonb)) x
        WHERE x ~ '^\d+$'
      ),
      array[]::bigint[]
    );
    v_month_start timestamptz := (date_trunc('month', now() AT TIME ZONE 'America/Sao_Paulo') AT TIME ZONE 'America/Sao_Paulo');
    v_next_month timestamptz := ((date_trunc('month', now() AT TIME ZONE 'America/Sao_Paulo') + interval '1 month') AT TIME ZONE 'America/Sao_Paulo');
    v_limit_plan bigint; v_used_month bigint; v_to_send bigint; v_total_after bigint;
    v_interval_min int := COALESCE((p_payload #>> '{settings,intervalMin}')::int, 30);
    v_interval_max int := COALESCE((p_payload #>> '{settings,intervalMax}')::int, 60);
    v_pause_after int := COALESCE((p_payload #>> '{settings,pauseAfterMessages}')::int, 20);
    v_pause_minutes int := COALESCE((p_payload #>> '{settings,pauseMinutes}')::int, 10);
    v_start_time time := COALESCE((p_payload #>> '{settings,startTime}')::time, time '08:00');
    v_end_time time := COALESCE((p_payload #>> '{settings,endTime}')::time, time '18:00');
    v_days int[] := COALESCE(ARRAY(SELECT CASE WHEN dtxt='0' THEN 7 ELSE dtxt::int END FROM jsonb_array_elements_text(COALESCE(p_payload->'settings'->'selectedDays','[]'::jsonb)) WITH ORDINALITY AS t(dtxt,ord) WHERE dtxt ~ '^\d+$' ORDER BY ord), array[]::int[]);
    v_schedule_base timestamptz := COALESCE((p_payload#>>'{settings,scheduleData}')::timestamptz, now() + interval '2 minutes');
    v_mostrar_mensagem boolean := COALESCE((p_payload #>> '{settings,mostrarMensagem}')::boolean, true);
    v_cur_ts timestamptz; v_disparo_id bigint; v_first_ts timestamptz; v_total int := 0; v_idx_msg int := 1; v_counter int := 0; v_gap int;
    v_msg_obj jsonb; v_template text; v_media_hash text; v_rendered text; rec_cont record;
  BEGIN
    IF v_interval_min <= 0 THEN v_interval_min := 30; END IF;
    IF v_interval_max <= 0 THEN v_interval_max := 60; END IF;
    IF v_interval_max < v_interval_min THEN v_interval_max := v_interval_min; END IF;
    IF v_pause_after < 0 THEN v_pause_after := 0; END IF;
    IF v_pause_minutes < 0 THEN v_pause_minutes := 0; END IF;
    IF COALESCE(cardinality(v_days),0) = 0 THEN v_days := ARRAY[1,2,3,4,5,6,7]; END IF;
    v_cur_ts := f_next_valid_time(v_schedule_base, v_start_time, v_end_time, v_days);

    SELECT p."qntDisparos"::bigint INTO v_limit_plan FROM public."SAAS_Contas" conta LEFT JOIN public."SAAS_Planos" p ON p.id = conta.plano WHERE conta.id = v_conta_id;
    IF v_limit_plan IS NOT NULL THEN
      SELECT COALESCE(COUNT(*),0)::bigint INTO v_used_month FROM public."SAAS_Detalhes_Disparos" d JOIN public."SAAS_Disparos" h ON h.id = d."idDisparo" WHERE h."contaId" = v_conta_id AND d."dataEnvio" >= v_month_start AND d."dataEnvio" < v_next_month;
      WITH etiqueta_grupos AS (
        SELECT DISTINCT c.id, (c.variaveis->>'whatsappId') AS wid
        FROM public."SAAS_Contatos" c
        JOIN public."SAAS_Contatos_Etiquetas" ce ON ce."contatoId" = c.id
        WHERE c."contaId" = v_conta_id
          AND c.tipo = 'grupo'
          AND ce."etiquetaId" = ANY(v_etiqueta_ids)
          AND NULLIF(btrim(c.variaveis->>'whatsappId'),'') IS NOT NULL
      ),
      crm_grupos AS (
        SELECT DISTINCT c.id, (c.variaveis->>'whatsappId') AS wid
        FROM public."SAAS_Contatos" c
        JOIN public."SAAS_Cards_Quadros" cq ON cq."contatoId" = c.id
        WHERE c."contaId" = v_conta_id
          AND c.tipo = 'grupo'
          AND cq."etapaQuadroId" = ANY(v_stage_ids)
          AND NULLIF(btrim(c.variaveis->>'whatsappId'),'') IS NOT NULL
      ),
      all_grupos AS (
        SELECT DISTINCT c.id, (c.variaveis->>'whatsappId') AS wid
        FROM public."SAAS_Contatos" c
        WHERE c."contaId" = v_conta_id
          AND c.tipo = 'grupo'
          AND NULLIF(btrim(c.variaveis->>'whatsappId'),'') IS NOT NULL
          AND COALESCE(cardinality(v_etiqueta_ids),0) = 0
          AND COALESCE(cardinality(v_stage_ids),0) = 0
      ),
      base AS (
        SELECT wid FROM etiqueta_grupos
        UNION
        SELECT wid FROM crm_grupos
        UNION
        SELECT wid FROM all_grupos
      )
      SELECT COALESCE(COUNT(*),0)::bigint INTO v_to_send FROM base;
      v_total_after := v_used_month + v_to_send;
      IF v_total_after > v_limit_plan THEN RAISE EXCEPTION 'limite atingido: % usados + % a enviar = %', v_used_month, v_to_send, v_total_after USING ERRCODE='P0001'; END IF;
    END IF;
    INSERT INTO public."SAAS_Disparos" ("NomeDisparo","Mensagens","TipoDisparo","TotalDisparos","MensagensDisparadas","StatusDisparo","contaId","idEtiquetas","idConexoes","DataAgendamento","mostrarMensagem")
    VALUES (v_nome_disparo,v_messages,'Grupos',0,0,'Aguardando',v_conta_id,v_etiqueta_ids,CASE WHEN v_conn_id IS NOT NULL THEN ARRAY[v_conn_id] ELSE NULL END,CASE WHEN p_payload #>> '{settings,scheduleData}' IS NOT NULL THEN v_schedule_base ELSE NULL END,v_mostrar_mensagem)
    RETURNING id INTO v_disparo_id;
    FOR rec_cont IN
      WITH etiqueta_grupos AS (
        SELECT DISTINCT c.id, c.nome, COALESCE(c.variaveis,'{}'::jsonb) AS base_variaveis
        FROM public."SAAS_Contatos" c
        JOIN public."SAAS_Contatos_Etiquetas" ce ON ce."contatoId" = c.id
        WHERE c."contaId" = v_conta_id
          AND c.tipo = 'grupo'
          AND ce."etiquetaId" = ANY(v_etiqueta_ids)
          AND NULLIF(btrim(c.variaveis->>'whatsappId'),'') IS NOT NULL
      ),
      crm_grupos AS (
        SELECT DISTINCT c.id, c.nome, COALESCE(c.variaveis,'{}'::jsonb) AS base_variaveis
        FROM public."SAAS_Contatos" c
        JOIN public."SAAS_Cards_Quadros" cq ON cq."contatoId" = c.id
        WHERE c."contaId" = v_conta_id
          AND c.tipo = 'grupo'
          AND cq."etapaQuadroId" = ANY(v_stage_ids)
          AND NULLIF(btrim(c.variaveis->>'whatsappId'),'') IS NOT NULL
      ),
      all_grupos AS (
        SELECT DISTINCT c.id, c.nome, COALESCE(c.variaveis,'{}'::jsonb) AS base_variaveis
        FROM public."SAAS_Contatos" c
        WHERE c."contaId" = v_conta_id
          AND c.tipo = 'grupo'
          AND NULLIF(btrim(c.variaveis->>'whatsappId'),'') IS NOT NULL
          AND COALESCE(cardinality(v_etiqueta_ids),0) = 0
          AND COALESCE(cardinality(v_stage_ids),0) = 0
      ),
      base AS (
        SELECT * FROM etiqueta_grupos
        UNION
        SELECT * FROM crm_grupos
        UNION
        SELECT * FROM all_grupos
      ),
      contato_custom_fields AS (
        SELECT
          b.id AS contato_id,
          COALESCE(
            jsonb_object_agg(
              lower(regexp_replace(cp."nome", '\s+', '_', 'g')),
              COALESCE(vcp."valor",'')
            ) FILTER (WHERE cp.id IS NOT NULL),
            '{}'::jsonb
          ) AS custom_variaveis
        FROM base b
        LEFT JOIN public."SAAS_Valores_Campos_Personalizados" vcp ON vcp."idContato" = b.id AND vcp."contaId" = v_conta_id
        LEFT JOIN public."SAAS_Campos_Personalizados" cp ON cp.id = vcp."idCampo" AND cp."contaId" = v_conta_id
        GROUP BY b.id
      )
      SELECT DISTINCT ON ((coalesce(b.base_variaveis->>'whatsappId','')))
        b.id,
        coalesce(b.base_variaveis->>'whatsappId','') AS "whatsappId",
        b.nome,
        (COALESCE(b.base_variaveis,'{}'::jsonb) || COALESCE(ccf.custom_variaveis,'{}'::jsonb)) AS variaveis
      FROM base b
      LEFT JOIN contato_custom_fields ccf ON ccf.contato_id = b.id
      ORDER BY (coalesce(b.base_variaveis->>'whatsappId','')), b.id
    LOOP
      v_msg_obj := v_messages[v_idx_msg]; v_idx_msg := (v_idx_msg % v_msg_count) + 1;
      v_template := v_msg_obj->>'text'; v_media_hash := NULLIF(COALESCE(v_msg_obj->'media'->>'link', v_msg_obj->'media'->>'hashredis',''),'');
      IF v_pause_after > 0 AND v_counter > 0 AND v_counter % v_pause_after = 0 THEN v_cur_ts := f_next_valid_time(v_cur_ts + make_interval(mins => v_pause_minutes), v_start_time, v_end_time, v_days); END IF;
      v_rendered := public.f_render_message(v_template, rec_cont.nome, COALESCE(rec_cont.variaveis,'{}'::jsonb), v_cur_ts);
      INSERT INTO public."SAAS_Detalhes_Disparos" ("idDisparo","idContato","Mensagem","idConexao","dataEnvio","Status","KeyRedis","FakeCall")
      VALUES (v_disparo_id, rec_cont.id, v_rendered, v_conn_id, v_cur_ts, 'pending', v_media_hash, v_mention_all);
      IF v_total = 0 THEN v_first_ts := v_cur_ts; END IF;
      v_total := v_total + 1; v_counter := v_counter + 1;
      v_gap := v_interval_min + floor(random() * (v_interval_max - v_interval_min + 1))::int;
      v_cur_ts := f_next_valid_time(v_cur_ts + make_interval(secs => v_gap), v_start_time, v_end_time, v_days);
    END LOOP;
    UPDATE public."SAAS_Disparos" SET "TotalDisparos"=v_total, "StatusDisparo"=CASE WHEN v_first_ts > now() THEN 'Aguardando' ELSE 'Em andamento' END WHERE id=v_disparo_id;
    RETURN v_disparo_id;
  END $function$;

  CREATE OR REPLACE FUNCTION public.f_limpar_etiquetas(p_conta_id uuid)
  RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
  BEGIN
    IF NOT public.is_admin(p_conta_id) AND NOT public.is_super_admin() THEN RETURN false; END IF;
    DELETE FROM public."SAAS_Contatos_Etiquetas" WHERE "contaId" = p_conta_id;
    DELETE FROM public."SAAS_Contatos" WHERE "contaId" = p_conta_id;
    DELETE FROM public."SAAS_Etiquetas" WHERE "contaId" = p_conta_id;
    RETURN true;
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_resetar_conta(p_conta_id uuid)
  RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
  DECLARE conv_ids bigint[]; disp_ids bigint[]; quadro_ids bigint[];
  BEGIN
    IF NOT public.is_admin(p_conta_id) AND NOT public.is_super_admin() THEN RETURN false; END IF;
    SELECT array_agg(id) INTO conv_ids FROM public."SAAS_Conversas_Agentes" WHERE "contaId" = p_conta_id;
    IF conv_ids IS NOT NULL AND array_length(conv_ids, 1) > 0 THEN DELETE FROM public."SAAS_Mensagens" WHERE "conversaId" = ANY(conv_ids); END IF;
    DELETE FROM public."SAAS_Conversas_Agentes" WHERE "contaId" = p_conta_id;
    SELECT array_agg(id) INTO disp_ids FROM public."SAAS_Disparos" WHERE "contaId" = p_conta_id;
    IF disp_ids IS NOT NULL AND array_length(disp_ids, 1) > 0 THEN DELETE FROM public."SAAS_Detalhes_Disparos" WHERE "idDisparo" = ANY(disp_ids); END IF;
    DELETE FROM public."SAAS_Disparos" WHERE "contaId" = p_conta_id;
    DELETE FROM public."SAAS_Contatos_Etiquetas" WHERE "contaId" = p_conta_id;
    DELETE FROM public."SAAS_Contatos" WHERE "contaId" = p_conta_id;
    DELETE FROM public."SAAS_Etiquetas" WHERE "contaId" = p_conta_id;
    SELECT array_agg(id) INTO quadro_ids FROM public."SAAS_Quadros" WHERE "contaId" = p_conta_id;
    IF quadro_ids IS NOT NULL AND array_length(quadro_ids, 1) > 0 THEN DELETE FROM public."SAAS_Cards_Quadros" WHERE "quadroId" = ANY(quadro_ids); END IF;
    DELETE FROM public."SAAS_Etapas_Quadros" WHERE "contaId" = p_conta_id;
    DELETE FROM public."SAAS_Quadros" WHERE "contaId" = p_conta_id;
    DELETE FROM public."SAAS_Conexões" WHERE "contaId" = p_conta_id;
    DELETE FROM public."SAAS_AgentesIA" WHERE "contaId" = p_conta_id;
    DELETE FROM public."SAAS_Webhook" WHERE "contaId" = p_conta_id;
    IF to_regclass('public."SAAS_IntegracaoPagamento"') IS NOT NULL THEN DELETE FROM public."SAAS_IntegracaoPagamento"; END IF;
    DELETE FROM public."SAAS_Resposta_Rapidas" WHERE "contaId" = p_conta_id;
    RETURN true;
  END;
  $$;

  -- Aliases compatibilidade
  DROP FUNCTION IF EXISTS public.get_contatos_by_lista(bigint);
  DROP FUNCTION IF EXISTS public.get_grupos_by_lista(bigint);
  CREATE OR REPLACE FUNCTION public.get_contatos_by_lista(p_id bigint) RETURNS SETOF public."SAAS_Contatos" AS $$ SELECT * FROM public.get_contatos_by_etiqueta(p_id); $$ LANGUAGE sql STABLE;
  CREATE OR REPLACE FUNCTION public.get_grupos_by_lista(p_id bigint) RETURNS SETOF public."SAAS_Contatos" AS $$ SELECT * FROM public.get_grupos_by_etiqueta(p_id); $$ LANGUAGE sql STABLE;
  CREATE OR REPLACE FUNCTION public.f_limpar_listas(p_conta_id uuid) RETURNS boolean AS $$ SELECT public.f_limpar_etiquetas(p_conta_id); $$ LANGUAGE sql SECURITY DEFINER SET search_path = public;

  DO $$ BEGIN
    IF to_regprocedure('public.create_disparo(jsonb)') IS NOT NULL THEN
      GRANT EXECUTE ON FUNCTION public.create_disparo(jsonb) TO authenticated;
    END IF;
    IF to_regprocedure('public.create_disparo_grupo(jsonb)') IS NOT NULL THEN
      GRANT EXECUTE ON FUNCTION public.create_disparo_grupo(jsonb) TO authenticated;
    END IF;
    IF to_regprocedure('public.create_disparo_email(jsonb)') IS NOT NULL THEN
      GRANT EXECUTE ON FUNCTION public.create_disparo_email(jsonb) TO authenticated;
    END IF;
    IF to_regprocedure('public.edit_disparo(jsonb)') IS NOT NULL THEN
      GRANT EXECUTE ON FUNCTION public.edit_disparo(jsonb) TO authenticated;
    END IF;
    IF to_regprocedure('public.edit_disparo_grupo(jsonb)') IS NOT NULL THEN
      GRANT EXECUTE ON FUNCTION public.edit_disparo_grupo(jsonb) TO authenticated;
    END IF;
  END $$;

  -- RLS e GRANTs etiquetas
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Etiquetas"') IS NOT NULL THEN
      ALTER TABLE public."SAAS_Etiquetas" ENABLE ROW LEVEL SECURITY;
      DROP POLICY IF EXISTS "select_listas" ON public."SAAS_Etiquetas";
      DROP POLICY IF EXISTS "insert_listas" ON public."SAAS_Etiquetas";
      DROP POLICY IF EXISTS "update_listas" ON public."SAAS_Etiquetas";
      DROP POLICY IF EXISTS "delete_listas_admin" ON public."SAAS_Etiquetas";
      DROP POLICY IF EXISTS "select_etiquetas" ON public."SAAS_Etiquetas";
      DROP POLICY IF EXISTS "insert_etiquetas" ON public."SAAS_Etiquetas";
      DROP POLICY IF EXISTS "update_etiquetas" ON public."SAAS_Etiquetas";
      DROP POLICY IF EXISTS "delete_etiquetas_admin" ON public."SAAS_Etiquetas";
      CREATE POLICY "select_etiquetas" ON public."SAAS_Etiquetas" FOR SELECT TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
      CREATE POLICY "insert_etiquetas" ON public."SAAS_Etiquetas" FOR INSERT TO authenticated WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
      CREATE POLICY "update_etiquetas" ON public."SAAS_Etiquetas" FOR UPDATE TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin())) WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
      CREATE POLICY "delete_etiquetas_admin" ON public."SAAS_Etiquetas" FOR DELETE TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids_admin()) OR (SELECT public.rls_eh_super_admin()));
    END IF;
    IF to_regclass('public."SAAS_Contatos_Etiquetas"') IS NOT NULL THEN
      ALTER TABLE public."SAAS_Contatos_Etiquetas" ENABLE ROW LEVEL SECURITY;
      DROP POLICY IF EXISTS "select_contatos_etiquetas" ON public."SAAS_Contatos_Etiquetas";
      DROP POLICY IF EXISTS "insert_contatos_etiquetas" ON public."SAAS_Contatos_Etiquetas";
      DROP POLICY IF EXISTS "delete_contatos_etiquetas" ON public."SAAS_Contatos_Etiquetas";
      DROP POLICY IF EXISTS "delete_contatos_etiquetas_admin" ON public."SAAS_Contatos_Etiquetas";
      CREATE POLICY "select_contatos_etiquetas" ON public."SAAS_Contatos_Etiquetas" FOR SELECT TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
      CREATE POLICY "insert_contatos_etiquetas" ON public."SAAS_Contatos_Etiquetas" FOR INSERT TO authenticated WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
      CREATE POLICY "delete_contatos_etiquetas_admin" ON public."SAAS_Contatos_Etiquetas" FOR DELETE TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids_admin()) OR (SELECT public.rls_eh_super_admin()));
    END IF;
    IF to_regclass('public."SAAS_Campos_Personalizados"') IS NOT NULL THEN
      ALTER TABLE public."SAAS_Campos_Personalizados" ENABLE ROW LEVEL SECURITY;
      DROP POLICY IF EXISTS "select_campos_personalizados" ON public."SAAS_Campos_Personalizados";
      DROP POLICY IF EXISTS "insert_campos_personalizados" ON public."SAAS_Campos_Personalizados";
      DROP POLICY IF EXISTS "update_campos_personalizados" ON public."SAAS_Campos_Personalizados";
      DROP POLICY IF EXISTS "delete_campos_personalizados_admin" ON public."SAAS_Campos_Personalizados";
      CREATE POLICY "select_campos_personalizados" ON public."SAAS_Campos_Personalizados" FOR SELECT TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
      CREATE POLICY "insert_campos_personalizados" ON public."SAAS_Campos_Personalizados" FOR INSERT TO authenticated WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
      CREATE POLICY "update_campos_personalizados" ON public."SAAS_Campos_Personalizados" FOR UPDATE TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin())) WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
      CREATE POLICY "delete_campos_personalizados_admin" ON public."SAAS_Campos_Personalizados" FOR DELETE TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids_admin()));
    END IF;
    IF to_regclass('public."SAAS_Valores_Campos_Personalizados"') IS NOT NULL THEN
      ALTER TABLE public."SAAS_Valores_Campos_Personalizados" ENABLE ROW LEVEL SECURITY;
      DROP POLICY IF EXISTS "select_valores_campos_personalizados" ON public."SAAS_Valores_Campos_Personalizados";
      DROP POLICY IF EXISTS "insert_valores_campos_personalizados" ON public."SAAS_Valores_Campos_Personalizados";
      DROP POLICY IF EXISTS "update_valores_campos_personalizados" ON public."SAAS_Valores_Campos_Personalizados";
      DROP POLICY IF EXISTS "delete_valores_campos_personalizados_admin" ON public."SAAS_Valores_Campos_Personalizados";
      CREATE POLICY "select_valores_campos_personalizados" ON public."SAAS_Valores_Campos_Personalizados" FOR SELECT TO authenticated
        USING (
          EXISTS (
            SELECT 1
            FROM public."SAAS_Campos_Personalizados" cp
            WHERE cp.id = "SAAS_Valores_Campos_Personalizados"."idCampo"
              AND (cp."contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()))
          )
        );
      CREATE POLICY "insert_valores_campos_personalizados" ON public."SAAS_Valores_Campos_Personalizados" FOR INSERT TO authenticated
        WITH CHECK (
          EXISTS (
            SELECT 1
            FROM public."SAAS_Campos_Personalizados" cp
            JOIN public."SAAS_Contatos" c ON c.id = "SAAS_Valores_Campos_Personalizados"."idContato"
            WHERE cp.id = "SAAS_Valores_Campos_Personalizados"."idCampo"
              AND cp."contaId" = c."contaId"
              AND "SAAS_Valores_Campos_Personalizados"."contaId" = cp."contaId"
              AND "SAAS_Valores_Campos_Personalizados"."contaId" = c."contaId"
              AND (cp."contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()))
          )
        );
      CREATE POLICY "update_valores_campos_personalizados" ON public."SAAS_Valores_Campos_Personalizados" FOR UPDATE TO authenticated
        USING (
          EXISTS (
            SELECT 1
            FROM public."SAAS_Campos_Personalizados" cp
            WHERE cp.id = "SAAS_Valores_Campos_Personalizados"."idCampo"
              AND (cp."contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()))
          )
        )
        WITH CHECK (
          EXISTS (
            SELECT 1
            FROM public."SAAS_Campos_Personalizados" cp
            JOIN public."SAAS_Contatos" c ON c.id = "SAAS_Valores_Campos_Personalizados"."idContato"
            WHERE cp.id = "SAAS_Valores_Campos_Personalizados"."idCampo"
              AND cp."contaId" = c."contaId"
              AND "SAAS_Valores_Campos_Personalizados"."contaId" = cp."contaId"
              AND "SAAS_Valores_Campos_Personalizados"."contaId" = c."contaId"
              AND (cp."contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()))
          )
        );
      CREATE POLICY "delete_valores_campos_personalizados_admin" ON public."SAAS_Valores_Campos_Personalizados" FOR DELETE TO authenticated
        USING (
          EXISTS (
            SELECT 1
            FROM public."SAAS_Campos_Personalizados" cp
            WHERE cp.id = "SAAS_Valores_Campos_Personalizados"."idCampo"
              AND (cp."contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()))
          )
        );
    END IF;
  END$$;

  GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_Etiquetas" TO authenticated;
  GRANT SELECT, INSERT, DELETE ON public."SAAS_Contatos_Etiquetas" TO authenticated;
  GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_Campos_Personalizados" TO authenticated;
  GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_Valores_Campos_Personalizados" TO authenticated;
  GRANT EXECUTE ON FUNCTION public.get_contatos_by_etiqueta(bigint) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.get_grupos_by_etiqueta(bigint) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.f_limpar_etiquetas(uuid) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.f_webhook_sincronizar_contato(uuid, text, text, jsonb, bigint[]) TO authenticated, service_role;

  -- View vw_Detalhes_Completo
  CREATE OR REPLACE VIEW public."vw_Detalhes_Completo" WITH (security_invoker = true) AS
  SELECT d.id, d."idDisparo", d."idContato", d."Mensagem", d."idConexao", d."dataEnvio", d."Status", d."statusHttp", d."mensagemErro", d."respostaHttp", d."Payload", d."KeyRedis", d."FakeCall",
    disp."StatusDisparo",
    CASE WHEN c.tipo = 'contato' THEN c.telefone ELSE NULL END AS "TelefoneContato",
    c.variaveis->>'whatsappId' AS "WhatsAppIdGrupo",
    c.nome AS "NomeGrupo",
    cx."instanceName" AS "InstanceName", cx."Apikey" AS "ApikeyConexao",
    COALESCE(cx."provedorApi", 'evolution') AS "provedorApi",
    cx."urlApi" AS "urlApi",
    disp."contaId" AS "UserId", cx."NomeConexao", disp."TipoDisparo"
  FROM public."SAAS_Detalhes_Disparos" d
  LEFT JOIN public."SAAS_Disparos" disp ON disp.id = d."idDisparo"
  LEFT JOIN public."SAAS_Contatos" c ON c.id = d."idContato"
  LEFT JOIN public."SAAS_Conexões" cx ON cx.id = d."idConexao";

  -- =============================================================================
  -- Meta WhatsApp API Oficial: templates, colunas de conexão/mensagens, RPC webhooks
  -- =============================================================================

  CREATE TABLE IF NOT EXISTS public."SAAS_Templates_Meta" (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    "conexaoId" BIGINT REFERENCES public."SAAS_Conexões"(id) ON UPDATE CASCADE ON DELETE CASCADE,
    "wabaId" TEXT,
    "metaTemplateId" TEXT,
    nome TEXT NOT NULL,
    idioma TEXT NOT NULL DEFAULT 'pt_BR',
    categoria TEXT,
    status TEXT,
    qualidade TEXT,
    "motivoRejeicao" TEXT,
    componentes JSONB,
    "statusUpdatedAt" TIMESTAMPTZ,
    "qualidadeUpdatedAt" TIMESTAMPTZ,
    "categoriaUpdatedAt" TIMESTAMPTZ
  );

  CREATE UNIQUE INDEX IF NOT EXISTS saas_templates_meta_conexao_nome_idioma_unique
    ON public."SAAS_Templates_Meta"("conexaoId", nome, idioma);

  CREATE INDEX IF NOT EXISTS saas_templates_meta_conexao_idx
    ON public."SAAS_Templates_Meta"("conexaoId");

  CREATE INDEX IF NOT EXISTS saas_templates_meta_waba_idx
    ON public."SAAS_Templates_Meta"("wabaId");

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Conexões"') IS NULL THEN RETURN; END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'expires_at') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN expires_at TIMESTAMPTZ;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaPhoneQualityEvent') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaPhoneQualityEvent" TEXT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaPhoneQualityLimit') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaPhoneQualityLimit" TEXT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaPhoneQualityUpdatedAt') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaPhoneQualityUpdatedAt" TIMESTAMPTZ;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaMessagingLimit') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaMessagingLimit" TEXT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaMaxPhoneNumbers') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaMaxPhoneNumbers" INTEGER;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaBusinessCapabilityUpdatedAt') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaBusinessCapabilityUpdatedAt" TIMESTAMPTZ;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaAccountEvent') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaAccountEvent" TEXT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaAccountUpdate') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaAccountUpdate" JSONB;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaAccountUpdatedAt') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaAccountUpdatedAt" TIMESTAMPTZ;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaUltimoAlerta') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaUltimoAlerta" JSONB;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaAlertasUpdatedAt') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaAlertasUpdatedAt" TIMESTAMPTZ;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaPagamento') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaPagamento" JSONB NOT NULL DEFAULT '[]'::jsonb;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaPagamentoUpdatedAt') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaPagamentoUpdatedAt" TIMESTAMPTZ;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaNameStatus') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaNameStatus" TEXT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaNewDisplayName') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaNewDisplayName" TEXT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaNewNameStatus') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaNewNameStatus" TEXT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaPrimaryFundingId') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaPrimaryFundingId" TEXT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaWabaStatus') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaWabaStatus" TEXT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaWabaName') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaWabaName" TEXT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaWabaCurrency') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaWabaCurrency" TEXT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaWabaTimezoneId') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaWabaTimezoneId" TEXT;
    END IF;
  END$$;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Mensagens"') IS NULL THEN RETURN; END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Mensagens' AND column_name = 'metaMessageId') THEN
      ALTER TABLE public."SAAS_Mensagens" ADD COLUMN "metaMessageId" TEXT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Mensagens' AND column_name = 'metaStatus') THEN
      ALTER TABLE public."SAAS_Mensagens" ADD COLUMN "metaStatus" TEXT;
    END IF;
    -- Motivo da recusa da Meta (ex.: "(#132012) ..."), gravado pelo backend quando o envio falha.
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Mensagens' AND column_name = 'metaErro') THEN
      ALTER TABLE public."SAAS_Mensagens" ADD COLUMN "metaErro" TEXT;
    END IF;
  END$$;

  CREATE UNIQUE INDEX IF NOT EXISTS saas_mensagens_conversa_meta_message_unique
    ON public."SAAS_Mensagens"("conversaId", "metaMessageId")
    WHERE "metaMessageId" IS NOT NULL;

  CREATE INDEX IF NOT EXISTS saas_mensagens_meta_message_id_idx
    ON public."SAAS_Mensagens"("metaMessageId")
    WHERE "metaMessageId" IS NOT NULL;

  CREATE OR REPLACE FUNCTION public.f_meta_templates_touch_updated_at()
  RETURNS trigger
  LANGUAGE plpgsql
  AS $$
  BEGIN
    NEW.updated_at := now();
    RETURN NEW;
  END;
  $$;

  DROP TRIGGER IF EXISTS trg_saas_templates_meta_updated_at ON public."SAAS_Templates_Meta";
  CREATE TRIGGER trg_saas_templates_meta_updated_at
    BEFORE UPDATE ON public."SAAS_Templates_Meta"
    FOR EACH ROW EXECUTE FUNCTION public.f_meta_templates_touch_updated_at();

  CREATE OR REPLACE FUNCTION public.f_meta_resolver_conexao(
    p_waba_id text,
    p_phone_number_id text DEFAULT NULL
  )
  RETURNS public."SAAS_Conexões"
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path = public
  AS $$
  DECLARE
    v_row public."SAAS_Conexões"%ROWTYPE;
  BEGIN
    IF NULLIF(trim(p_phone_number_id), '') IS NOT NULL THEN
      SELECT * INTO v_row
      FROM public."SAAS_Conexões"
      WHERE "phone_number_id" = trim(p_phone_number_id)
        AND COALESCE("apiOficial", false) = true
      ORDER BY id
      LIMIT 1;
      IF FOUND THEN RETURN v_row; END IF;
    END IF;

    IF NULLIF(trim(p_waba_id), '') IS NOT NULL THEN
      SELECT * INTO v_row
      FROM public."SAAS_Conexões"
      WHERE "waba_id" = trim(p_waba_id)
        AND COALESCE("apiOficial", false) = true
      ORDER BY id
      LIMIT 1;
      IF FOUND THEN RETURN v_row; END IF;
    END IF;

    RETURN NULL;
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_meta_upsert_pagamento(
    p_conexao_id bigint,
    p_config jsonb
  )
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
  DECLARE
    v_name text;
    v_atual jsonb;
    v_novo jsonb := '[]'::jsonb;
    v_elem jsonb;
  BEGIN
    v_name := NULLIF(trim(p_config->>'configuration_name'), '');
    IF v_name IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'configuration_name obrigatorio');
    END IF;

    SELECT COALESCE("metaPagamento", '[]'::jsonb) INTO v_atual
    FROM public."SAAS_Conexões"
    WHERE id = p_conexao_id;

    IF jsonb_typeof(v_atual) <> 'array' THEN
      v_atual := '[]'::jsonb;
    END IF;

    FOR v_elem IN SELECT value FROM jsonb_array_elements(v_atual)
    LOOP
      IF COALESCE(v_elem->>'configuration_name', '') <> v_name THEN
        v_novo := v_novo || jsonb_build_array(v_elem);
      END IF;
    END LOOP;

    v_novo := v_novo || jsonb_build_array(p_config);

    UPDATE public."SAAS_Conexões"
    SET "metaPagamento" = v_novo,
        "metaPagamentoUpdatedAt" = now()
    WHERE id = p_conexao_id;

    RETURN jsonb_build_object('ok', true, 'metaPagamento', v_novo);
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_meta_normalizar_tipo_mensagem(p_tipo text)
  RETURNS text
  LANGUAGE sql
  IMMUTABLE
  AS $$
    SELECT CASE lower(trim(COALESCE(p_tipo, '')))
      WHEN 'text' THEN 'conversation'
      WHEN 'conversation' THEN 'conversation'
      WHEN 'template' THEN 'conversation'
      WHEN 'image' THEN 'imageMessage'
      WHEN 'imagemessage' THEN 'imageMessage'
      WHEN 'video' THEN 'videoMessage'
      WHEN 'videomessage' THEN 'videoMessage'
      WHEN 'audio' THEN 'audioMessage'
      WHEN 'audiomessage' THEN 'audioMessage'
      WHEN 'sticker' THEN 'stickerMessage'
      WHEN 'stickermessage' THEN 'stickerMessage'
      WHEN 'document' THEN 'documentMessage'
      WHEN 'documentmessage' THEN 'documentMessage'
      ELSE COALESCE(NULLIF(trim(p_tipo), ''), 'conversation')
    END;
  $$;

  DROP FUNCTION IF EXISTS public.f_meta_salvar_mensagem_chat(bigint, uuid, text, text, text, boolean, text, text, text, text);

  CREATE OR REPLACE FUNCTION public.f_meta_salvar_mensagem_chat(
    p_conexao_id bigint,
    p_conta_id uuid,
    p_telefone text,
    p_mensagem text,
    p_tipo_mensagem text,
    p_from_me boolean,
    p_meta_message_id text,
    p_meta_status text DEFAULT NULL,
    p_arquivo_url text DEFAULT NULL,
    p_nome_contato text DEFAULT NULL,
    p_mensagem_respondida text DEFAULT NULL
  )
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
  DECLARE
    v_conversa_id bigint;
    v_mensagem_id bigint;
    v_contato_id bigint;
    v_contato_telefone text;
    v_telefone text;
    v_telefone_whatsapp text;
    v_telefone_alt text;
    v_candidatos_telefone text[];
    v_tipo text;
    v_fluxo jsonb;
    v_eh_primeira_mensagem boolean := false;
    v_contato_criado boolean := false;
  BEGIN
    v_telefone := regexp_replace(COALESCE(p_telefone, ''), '\D', '', 'g');
    IF v_telefone = '' OR p_conexao_id IS NULL OR p_conta_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'telefone, conexaoId e contaId obrigatorios');
    END IF;

    v_telefone_whatsapp := v_telefone || '@s.whatsapp.net';
    v_telefone_alt := public.f_meta_alternar_telefone_br(v_telefone);
    v_candidatos_telefone := array_remove(ARRAY[
      v_telefone,
      v_telefone_whatsapp,
      v_telefone_alt,
      CASE WHEN v_telefone_alt IS NOT NULL THEN v_telefone_alt || '@s.whatsapp.net' END
    ], NULL);
    v_tipo := public.f_meta_normalizar_tipo_mensagem(p_tipo_mensagem);

    -- Buscar contato por telefone (digitos, @s.whatsapp.net e variante BR com/sem 9)
    SELECT c.id, c.telefone
      INTO v_contato_id, v_contato_telefone
      FROM public."SAAS_Contatos" c
    WHERE c."contaId" = p_conta_id
      AND c.telefone = ANY (v_candidatos_telefone)
    ORDER BY CASE c.telefone
      WHEN v_telefone THEN 1
      WHEN v_telefone_whatsapp THEN 2
      WHEN v_telefone_alt THEN 3
      ELSE 4
    END
    LIMIT 1;

    IF v_contato_id IS NULL THEN
      INSERT INTO public."SAAS_Contatos" (nome, telefone, tipo, variaveis, "contaId")
      VALUES (
        NULLIF(trim(COALESCE(p_nome_contato, '')), ''),
        v_telefone,
        'contato',
        '{}'::jsonb,
        p_conta_id
      )
      RETURNING id, telefone INTO v_contato_id, v_contato_telefone;
      v_contato_criado := true;
    ELSIF NULLIF(trim(COALESCE(p_nome_contato, '')), '') IS NOT NULL THEN
      UPDATE public."SAAS_Contatos"
        SET nome = COALESCE(NULLIF(trim(nome), ''), trim(p_nome_contato))
      WHERE id = v_contato_id
        AND NULLIF(trim(nome), '') IS NULL;
    END IF;

    -- 3) Buscar conversa por idContato + idConexao
    SELECT id INTO v_conversa_id
    FROM public."SAAS_Conversas_Agentes"
    WHERE "contatoId" = v_contato_id
      AND "idConexao" = p_conexao_id
    LIMIT 1;

    -- 4) Criar conversa vinculada ao contato se nao existir
    IF v_conversa_id IS NULL THEN
      BEGIN
        INSERT INTO public."SAAS_Conversas_Agentes" (
          telefone, "idConexao", "contaId", "contatoId", "nomeConversa", "statusAtendimento", lida
        ) VALUES (
          COALESCE(v_contato_telefone, v_telefone),
          p_conexao_id,
          p_conta_id,
          v_contato_id,
          NULLIF(trim(COALESCE(p_nome_contato, '')), ''),
          CASE WHEN p_from_me THEN 'aberto' ELSE 'aguardando' END,
          p_from_me
        )
        RETURNING id INTO v_conversa_id;
      EXCEPTION
        WHEN unique_violation THEN
          SELECT id INTO v_conversa_id
          FROM public."SAAS_Conversas_Agentes"
          WHERE "contatoId" = v_contato_id
            AND "idConexao" = p_conexao_id
          LIMIT 1;
      END;
    END IF;

    IF NULLIF(trim(COALESCE(p_meta_message_id, '')), '') IS NOT NULL THEN
      SELECT id INTO v_mensagem_id
      FROM public."SAAS_Mensagens"
      WHERE "conversaId" = v_conversa_id
        AND (
          "metaMessageId" = trim(p_meta_message_id)
          OR "messageEvolutionId" = trim(p_meta_message_id)
        )
      LIMIT 1;

      IF v_mensagem_id IS NOT NULL THEN
        UPDATE public."SAAS_Mensagens"
        SET "metaStatus" = COALESCE(NULLIF(trim(COALESCE(p_meta_status, '')), ''), "metaStatus"),
            enviada = CASE
              WHEN NULLIF(trim(COALESCE(p_meta_status, '')), '') IN ('sent', 'delivered', 'read') THEN true
              ELSE enviada
            END,
            -- Se a linha nasceu sem texto (preview falhou) e agora temos o body do template, preenche.
            mensagem = CASE
              WHEN NULLIF(trim(COALESCE(mensagem, '')), '') IS NULL
                AND NULLIF(trim(COALESCE(p_mensagem, '')), '') IS NOT NULL
              THEN NULLIF(trim(p_mensagem), '')
              ELSE mensagem
            END,
            "arquivoUrl" = CASE
              WHEN NULLIF(trim(COALESCE("arquivoUrl", '')), '') IS NULL
                AND NULLIF(trim(COALESCE(p_arquivo_url, '')), '') IS NOT NULL
              THEN NULLIF(trim(p_arquivo_url), '')
              ELSE "arquivoUrl"
            END,
            "tipoMensagem" = CASE
              WHEN NULLIF(trim(COALESCE(mensagem, '')), '') IS NULL
                AND NULLIF(trim(COALESCE(p_mensagem, '')), '') IS NOT NULL
              THEN v_tipo
              ELSE "tipoMensagem"
            END
        WHERE id = v_mensagem_id;

        -- Mensagem já existia (retry webhook): ainda avalia fluxo do agente no inbound.
        IF COALESCE(p_from_me, false) IS NOT TRUE
          AND lower(trim(COALESCE(v_tipo, ''))) NOT IN ('reaction', 'reactionmessage')
          AND lower(trim(COALESCE(p_tipo_mensagem, ''))) <> 'reaction'
        THEN
          SELECT COUNT(*) <= 1 INTO v_eh_primeira_mensagem
            FROM public."SAAS_Mensagens" m
          WHERE m."conversaId" = v_conversa_id
            AND m."fromMe" = false
            AND COALESCE(m.apagada, false) = false;

          v_fluxo := public.f_avaliar_fluxo_agente_ia(
            p_conexao_id,
            p_conta_id,
            v_conversa_id,
            v_contato_id,
            v_contato_telefone,
            v_telefone,
            false,
            p_nome_contato,
            NULLIF(trim(COALESCE(p_mensagem, '')), ''),
            v_eh_primeira_mensagem
          );
        ELSE
          v_fluxo := jsonb_build_object('segueFluxoIA', false);
        END IF;

        RETURN jsonb_build_object(
          'ok', true,
          'skipped', true,
          'fromMe', COALESCE(p_from_me, false),
          'conversaId', v_conversa_id,
          'mensagemId', v_mensagem_id,
          'contatoId', v_contato_id,
          'contatoCriado', v_contato_criado,
          'contaId', p_conta_id,
          'conexaoId', p_conexao_id,
          'tipoMensagem', v_tipo,
          'telefone', v_telefone
        ) || COALESCE(v_fluxo - 'ok', '{}'::jsonb);
      END IF;
    END IF;

    INSERT INTO public."SAAS_Mensagens" (
      "contaId", "conexaoId", "conversaId", mensagem, "tipoMensagem", "arquivoUrl",
      "fromMe", apagada, "messageEvolutionId", "metaMessageId", "metaStatus", "mensagemRespondida", enviada, "IA"
    ) VALUES (
      p_conta_id,
      p_conexao_id,
      v_conversa_id,
      NULLIF(trim(COALESCE(p_mensagem, '')), ''),
      v_tipo,
      NULLIF(trim(COALESCE(p_arquivo_url, '')), ''),
      COALESCE(p_from_me, false),
      false,
      NULLIF(trim(COALESCE(p_meta_message_id, '')), ''),
      NULLIF(trim(COALESCE(p_meta_message_id, '')), ''),
      NULLIF(trim(COALESCE(p_meta_status, '')), ''),
      NULLIF(trim(COALESCE(p_mensagem_respondida, '')), ''),
      CASE
        WHEN p_from_me AND COALESCE(NULLIF(trim(p_meta_status), ''), 'sent') IN ('sent', 'delivered', 'read') THEN true
        WHEN p_from_me THEN true
        ELSE NULL
      END,
      false
    )
    RETURNING id INTO v_mensagem_id;

    UPDATE public."SAAS_Conversas_Agentes"
    SET "ultimaMensagem" = now(),
        lida = CASE WHEN p_from_me THEN true ELSE false END,
        "nomeConversa" = COALESCE(NULLIF(trim("nomeConversa"), ''), NULLIF(trim(COALESCE(p_nome_contato, '')), ''))
    WHERE id = v_conversa_id;

    IF COALESCE(p_from_me, false) IS NOT TRUE
      AND lower(trim(COALESCE(v_tipo, ''))) NOT IN ('reaction', 'reactionmessage')
      AND lower(trim(COALESCE(p_tipo_mensagem, ''))) <> 'reaction'
    THEN
      SELECT COUNT(*) <= 1 INTO v_eh_primeira_mensagem
        FROM public."SAAS_Mensagens" m
      WHERE m."conversaId" = v_conversa_id
        AND m."fromMe" = false
        AND COALESCE(m.apagada, false) = false;

      v_fluxo := public.f_avaliar_fluxo_agente_ia(
        p_conexao_id,
        p_conta_id,
        v_conversa_id,
        v_contato_id,
        v_contato_telefone,
        v_telefone,
        false,
        p_nome_contato,
        NULLIF(trim(COALESCE(p_mensagem, '')), ''),
        v_eh_primeira_mensagem
      );
    ELSE
      v_fluxo := public.f_avaliar_fluxo_agente_ia(
        p_conexao_id,
        p_conta_id,
        v_conversa_id,
        v_contato_id,
        v_contato_telefone,
        v_telefone,
        true,
        p_nome_contato,
        NULLIF(trim(COALESCE(p_mensagem, '')), ''),
        false
      );
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'fromMe', COALESCE(p_from_me, false),
      'conversaId', v_conversa_id,
      'mensagemId', v_mensagem_id,
      'contatoId', v_contato_id,
      'contatoCriado', v_contato_criado,
      'contaId', p_conta_id,
      'conexaoId', p_conexao_id,
      'tipoMensagem', v_tipo,
      'telefone', v_telefone
    ) || COALESCE(v_fluxo - 'ok', '{}'::jsonb);
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
  END;
  $$;

  -- Alterna telefone BR (insere ou remove nono dígito) para retry após webhook failed 131026
  CREATE OR REPLACE FUNCTION public.f_meta_alternar_telefone_br(p_digits text)
  RETURNS text
  LANGUAGE plpgsql
  IMMUTABLE
  AS $$
  DECLARE
    v text;
  BEGIN
    v := regexp_replace(COALESCE(p_digits, ''), '\D', '', 'g');
    IF v = '' OR v NOT LIKE '55%' THEN
      RETURN NULL;
    END IF;
    IF length(v) = 12 THEN
      RETURN substring(v FROM 1 FOR 4) || '9' || substring(v FROM 5);
    END IF;
    IF length(v) = 13 AND substring(v FROM 5 FOR 1) = '9' THEN
      RETURN substring(v FROM 1 FOR 4) || substring(v FROM 6);
    END IF;
    RETURN NULL;
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_meta_erro_pagamento_webhook(p_status jsonb)
  RETURNS boolean
  LANGUAGE sql
  IMMUTABLE
  AS $$
    SELECT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(COALESCE(p_status->'errors', '[]'::jsonb)) e
      WHERE (e->>'code')::int IN (131042, 134011)
        OR lower(COALESCE(e->>'title', '')) LIKE '%payment%'
        OR lower(COALESCE(e->>'message', '')) LIKE '%payment method%'
        OR lower(COALESCE(e->>'error_data', '')) LIKE '%payment%'
    );
  $$;

  CREATE OR REPLACE FUNCTION public.f_meta_patch_pagamento_por_webhook(
    p_conexao_id bigint,
    p_evento text,
    p_status jsonb DEFAULT NULL
  )
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
  DECLARE
    v_atual jsonb;
    v_novo jsonb := '[]'::jsonb;
    v_elem jsonb;
    v_billing jsonb;
    v_now timestamptz := now();
    v_waba_status text;
  BEGIN
    IF p_conexao_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'conexaoId obrigatorio');
    END IF;

    SELECT COALESCE("metaPagamento", '[]'::jsonb), "metaWabaStatus"
      INTO v_atual, v_waba_status
    FROM public."SAAS_Conexões"
    WHERE id = p_conexao_id;

    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'error', 'conexao nao encontrada');
    END IF;

    IF jsonb_typeof(v_atual) <> 'array' THEN
      v_atual := '[]'::jsonb;
    END IF;

    SELECT elem INTO v_billing
    FROM jsonb_array_elements(v_atual) elem
    WHERE COALESCE(elem->>'configuration_name', '') = 'billing_meta_api'
    LIMIT 1;

    v_billing := COALESCE(v_billing, jsonb_build_object('configuration_name', 'billing_meta_api'));

    IF p_evento = 'delivered' THEN
      v_billing := v_billing
        || jsonb_build_object(
          'source', 'webhook_delivery',
          'has_payment_method', true,
          'pending_valid_payment_method', false,
          'status', 'active',
          'credit_line_status', 'active',
          'confirmed_by_delivery_webhook', true,
          'delivery_webhook_at', v_now,
          'last_payment_webhook_at', v_now
        );
      IF COALESCE(v_billing->>'waba_status', v_waba_status, '') = 'PENDING_VALID_PAYMENT_METHOD' THEN
        v_billing := v_billing || jsonb_build_object('waba_status', NULL);
        v_waba_status := NULL;
      END IF;
    ELSIF p_evento = 'payment_error' THEN
      v_billing := v_billing
        || jsonb_build_object(
          'source', 'webhook_failed_payment',
          'has_payment_method', false,
          'pending_valid_payment_method', true,
          'status', 'pending_valid_payment_method',
          'credit_line_status', 'needs_update',
          'waba_status', 'PENDING_VALID_PAYMENT_METHOD',
          'primary_funding_id', NULL,
          'funding', NULL,
          'payment_webhook_error', COALESCE(p_status->'errors', '[]'::jsonb),
          'last_payment_webhook_at', v_now
        );
      v_waba_status := 'PENDING_VALID_PAYMENT_METHOD';
    ELSE
      RETURN jsonb_build_object('ok', false, 'error', 'evento invalido', 'evento', p_evento);
    END IF;

    FOR v_elem IN SELECT value FROM jsonb_array_elements(v_atual)
    LOOP
      IF COALESCE(v_elem->>'configuration_name', '') <> 'billing_meta_api' THEN
        v_novo := v_novo || jsonb_build_array(v_elem);
      END IF;
    END LOOP;

    v_novo := v_novo || jsonb_build_array(v_billing);

    UPDATE public."SAAS_Conexões"
    SET "metaPagamento" = v_novo,
        "metaPagamentoUpdatedAt" = v_now,
        "metaWabaStatus" = v_waba_status
    WHERE id = p_conexao_id;

    RETURN jsonb_build_object('ok', true, 'evento', p_evento, 'metaPagamento', v_novo);
  END;
  $$;

  -- Webhook Meta status failed (131026): sent → pending com telefone alternativo para o disparador
  CREATE OR REPLACE FUNCTION public.f_meta_retry_detalhe_telefone_webhook(p_wamid text, p_status jsonb)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
  DECLARE
    v_detail public."SAAS_Detalhes_Disparos"%ROWTYPE;
    v_disparo public."SAAS_Disparos"%ROWTYPE;
    v_phone_base text;
    v_phone_override text;
    v_recipient text;
    v_now timestamptz := now();
  BEGIN
    IF NULLIF(trim(COALESCE(p_wamid, '')), '') IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'wamid vazio');
    END IF;

    SELECT d.* INTO v_detail
    FROM public."SAAS_Detalhes_Disparos" d
    WHERE d."Status" = 'sent'
      AND (
        d."respostaHttp"#>>'{messages,0,id}' = p_wamid
        OR d."respostaHttp"->>'metaMessageId' = p_wamid
      )
    ORDER BY d.id DESC
    LIMIT 1;

    IF v_detail.id IS NULL THEN
      RETURN jsonb_build_object('ok', true, 'action', 'detalhe_nao_encontrado', 'wamid', p_wamid);
    END IF;

    SELECT h.* INTO v_disparo
    FROM public."SAAS_Disparos" h
    WHERE h.id = v_detail."idDisparo";

    IF v_disparo.id IS NULL OR lower(COALESCE(v_disparo."TipoDisparo", '')) <> 'apioficial' THEN
      RETURN jsonb_build_object('ok', true, 'action', 'ignorado_nao_apioficial', 'detalheId', v_detail.id);
    END IF;

    IF COALESCE(v_detail."respostaHttp"->>'_webhookPhoneRetry', 'false') = 'true' THEN
      UPDATE public."SAAS_Detalhes_Disparos"
      SET "Status" = 'failed',
          "mensagemErro" = 'Message undeliverable (131026) após retry de telefone',
          "respostaHttp" = COALESCE(v_detail."respostaHttp", '{}'::jsonb)
            || jsonb_build_object(
              '_webhookFailedFinalAt', v_now,
              '_webhookFailedWamid', p_wamid
            )
      WHERE id = v_detail.id;

      RETURN jsonb_build_object(
        'ok', true,
        'action', 'marked_failed_after_retry',
        'detalheId', v_detail.id,
        'wamid', p_wamid
      );
    END IF;

    v_recipient := NULLIF(regexp_replace(COALESCE(p_status->>'recipient_id', ''), '\D', '', 'g'), '');
    v_phone_base := NULLIF(regexp_replace(COALESCE(v_detail."respostaHttp"->>'_phoneUsed', v_recipient, ''), '\D', '', 'g'), '');
    v_phone_override := public.f_meta_alternar_telefone_br(v_phone_base);

    IF v_phone_override IS NULL OR v_phone_override = v_phone_base THEN
      UPDATE public."SAAS_Detalhes_Disparos"
      SET "Status" = 'failed',
          "mensagemErro" = 'Message undeliverable (131026) — sem variante de telefone BR',
          "respostaHttp" = COALESCE(v_detail."respostaHttp", '{}'::jsonb)
            || jsonb_build_object('_webhookFailedFinalAt', v_now, '_webhookFailedWamid', p_wamid)
      WHERE id = v_detail.id;

      RETURN jsonb_build_object(
        'ok', true,
        'action', 'marked_failed_sem_alternativa',
        'detalheId', v_detail.id,
        'telefoneBase', v_phone_base
      );
    END IF;

    UPDATE public."SAAS_Detalhes_Disparos"
    SET "Status" = 'pending',
        "dataEnvio" = NULL,
        "statusHttp" = NULL,
        "mensagemErro" = NULL,
        "respostaHttp" = COALESCE(v_detail."respostaHttp", '{}'::jsonb)
          || jsonb_build_object(
            '_webhookPhoneRetry', true,
            '_phoneOverride', v_phone_override,
            '_phoneUsedBeforeRetry', v_phone_base,
            '_webhookFailedWamid', p_wamid,
            '_webhookFailedAt', v_now
          )
    WHERE id = v_detail.id;

    UPDATE public."SAAS_Disparos"
    SET "MensagensDisparadas" = GREATEST(COALESCE("MensagensDisparadas", 0) - 1, 0),
        "StatusDisparo" = CASE
          WHEN "StatusDisparo" = 'Finalizado' THEN 'Em andamento'
          ELSE "StatusDisparo"
        END
    WHERE id = v_detail."idDisparo";

    RETURN jsonb_build_object(
      'ok', true,
      'action', 'retry_pending',
      'detalheId', v_detail.id,
      'wamid', p_wamid,
      'telefoneAnterior', v_phone_base,
      'telefoneOverride', v_phone_override
    );
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'error', SQLERRM, 'wamid', p_wamid);
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_meta_processar_evento(p_evento jsonb)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
  DECLARE
    v_field text;
    v_waba_id text;
    v_value jsonb;
    v_conexao public."SAAS_Conexões"%ROWTYPE;
    v_phone_number_id text;
    v_msg jsonb;
    v_status jsonb;
    v_telefone text;
    v_wamid text;
    v_texto text;
    v_tipo text;
    v_arquivo text;
    v_nome text;
    v_limit text;
    v_template_nome text;
    v_template_idioma text;
    v_motivo text;
    v_mensagem_respondida text;
    v_now timestamptz := now();
    v_retry_result jsonb;
    v_chat_result jsonb;
    v_agente_fluxo jsonb;
  BEGIN
    IF p_evento IS NULL OR p_evento = 'null'::jsonb THEN
      RETURN jsonb_build_object('ok', false, 'error', 'evento vazio');
    END IF;

    v_field := NULLIF(trim(p_evento->>'field'), '');
    v_waba_id := NULLIF(trim(p_evento->>'waba_id'), '');
    v_value := COALESCE(p_evento->'value', '{}'::jsonb);

    v_phone_number_id := NULLIF(trim(v_value#>>'{metadata,phone_number_id}'), '');
    v_conexao := public.f_meta_resolver_conexao(v_waba_id, v_phone_number_id);

    IF v_conexao.id IS NULL AND v_field NOT IN ('messages', 'smb_message_echoes') THEN
      RETURN jsonb_build_object('ok', false, 'error', 'conexao nao encontrada', 'field', v_field, 'waba_id', v_waba_id);
    END IF;

    IF v_field = 'messages' THEN
      IF v_conexao.id IS NULL THEN
        RETURN jsonb_build_object('ok', false, 'error', 'conexao nao encontrada para messages');
      END IF;

      IF jsonb_typeof(v_value->'contacts') = 'array' AND jsonb_array_length(v_value->'contacts') > 0 THEN
        v_nome := v_value->'contacts'->0#>>'{profile,name}';
      END IF;

      IF jsonb_typeof(v_value->'messages') = 'array' THEN
        FOR v_msg IN SELECT value FROM jsonb_array_elements(v_value->'messages')
        LOOP
          v_telefone := v_msg->>'from';
          v_wamid := v_msg->>'id';
          v_tipo := COALESCE(NULLIF(trim(v_msg->>'type'), ''), 'unsupported');
          v_texto := NULL;
          v_arquivo := NULL;
          v_mensagem_respondida := NULLIF(trim(v_msg#>>'{context,id}'), '');

          -- Midias (image/audio/video/document/sticker) sao tratadas no n8n: download Meta + S3 + arquivoUrl
          IF v_tipo IN ('image', 'audio', 'video', 'document', 'sticker') THEN
            CONTINUE;
          END IF;

          CASE v_tipo
            WHEN 'text' THEN
              v_tipo := 'conversation';
              v_texto := v_msg#>>'{text,body}';
            WHEN 'location' THEN
              v_texto := COALESCE(v_msg#>>'{location,name}', v_msg#>>'{location,address}', '[localizacao]');
            WHEN 'contacts' THEN
              v_texto := '[contato]';
            WHEN 'interactive' THEN
              v_texto := COALESCE(
                v_msg#>>'{interactive,button_reply,title}',
                v_msg#>>'{interactive,list_reply,title}',
                '[interativo]'
              );
            WHEN 'button' THEN
              v_texto := v_msg#>>'{button,text}';
            WHEN 'reaction' THEN
              v_texto := v_msg#>>'{reaction,emoji}';
            ELSE
              v_texto := COALESCE(v_msg->>'type', '[mensagem]');
          END CASE;

          IF v_tipo = 'reaction' THEN
            CONTINUE;
          END IF;

          v_chat_result := public.f_meta_salvar_mensagem_chat(
            v_conexao.id,
            v_conexao."contaId",
            v_telefone,
            v_texto,
            v_tipo,
            false,
            v_wamid,
            NULL,
            v_arquivo,
            v_nome,
            v_mensagem_respondida
          );

          -- Sempre propaga o resultado do chat (mesmo se segueFluxoIA=false),
          -- para o inbound logar conversaId/agenteId/motivo reais.
          IF v_chat_result IS NOT NULL THEN
            v_agente_fluxo := COALESCE(v_chat_result, '{}'::jsonb)
              || jsonb_build_object(
                'canal', 'meta',
                'metaMessageId', v_wamid,
                'telefone', v_telefone,
                'tipoMensagem', v_tipo,
                'mensagem', v_texto,
                'nomeContato', v_nome
              );
          END IF;
        END LOOP;
      END IF;

      IF jsonb_typeof(v_value->'statuses') = 'array' THEN
        FOR v_status IN SELECT value FROM jsonb_array_elements(v_value->'statuses')
        LOOP
          v_wamid := v_status->>'id';
          IF NULLIF(trim(COALESCE(v_wamid, '')), '') IS NULL THEN
            CONTINUE;
          END IF;

          UPDATE public."SAAS_Mensagens"
          SET "metaStatus" = v_status->>'status',
              enviada = CASE WHEN v_status->>'status' IN ('sent', 'delivered', 'read') THEN true ELSE enviada END,
              "metaMessageId" = CASE
                WHEN NULLIF(trim(COALESCE("metaMessageId", '')), '') IS NULL THEN v_wamid
                ELSE "metaMessageId"
              END
          WHERE "metaMessageId" = v_wamid
             OR "messageEvolutionId" = v_wamid;

          IF v_status->>'status' = 'read' THEN
            UPDATE public."SAAS_Detalhes_Disparos" d
            SET "mensagemLida" = true,
                "dataMensagemLida" = COALESCE(d."dataMensagemLida", now())
            WHERE (
                d."respostaHttp"#>>'{messages,0,id}' = v_wamid
                OR d."respostaHttp"->>'metaMessageId' = v_wamid
              )
              AND COALESCE(d."mensagemLida", false) = false;
          END IF;

          IF v_status->>'status' = 'delivered' AND v_conexao.id IS NOT NULL THEN
            PERFORM public.f_meta_patch_pagamento_por_webhook(v_conexao.id, 'delivered', v_status);
          END IF;

          IF v_status->>'status' = 'failed' THEN
            IF public.f_meta_erro_pagamento_webhook(v_status) AND v_conexao.id IS NOT NULL THEN
              PERFORM public.f_meta_patch_pagamento_por_webhook(v_conexao.id, 'payment_error', v_status);
            ELSIF EXISTS (
              SELECT 1
              FROM jsonb_array_elements(COALESCE(v_status->'errors', '[]'::jsonb)) e
              WHERE (e->>'code')::int = 131026
            ) THEN
              v_retry_result := public.f_meta_retry_detalhe_telefone_webhook(v_wamid, v_status);
            END IF;
          END IF;
        END LOOP;
      END IF;

      RETURN jsonb_build_object(
        'ok', true,
        'field', v_field,
        'conexaoId', v_conexao.id,
        'retryDetalhe', v_retry_result
      ) || CASE
        WHEN v_agente_fluxo IS NOT NULL THEN v_agente_fluxo
        ELSE '{}'::jsonb
      END;
    END IF;

    -- Coexistencia: mensagens enviadas pelo WhatsApp Business App (celular/dispositivo vinculado).
    IF v_field = 'smb_message_echoes' THEN
      IF v_conexao.id IS NULL THEN
        RETURN jsonb_build_object('ok', false, 'error', 'conexao nao encontrada para smb_message_echoes');
      END IF;

      v_nome := NULL;

      IF jsonb_typeof(v_value->'message_echoes') = 'array' THEN
        FOR v_msg IN SELECT value FROM jsonb_array_elements(v_value->'message_echoes')
        LOOP
          v_telefone := COALESCE(
            NULLIF(trim(v_msg->>'to'), ''),
            NULLIF(trim(v_msg->>'to_user_id'), ''),
            NULLIF(trim(v_msg->>'to_parent_user_id'), '')
          );
          v_wamid := v_msg->>'id';
          v_tipo := COALESCE(NULLIF(trim(v_msg->>'type'), ''), 'unsupported');
          v_texto := NULL;
          v_arquivo := NULL;
          v_mensagem_respondida := NULLIF(trim(v_msg#>>'{context,id}'), '');

          IF v_tipo IN ('image', 'audio', 'video', 'document', 'sticker') THEN
            CONTINUE;
          END IF;

          IF v_tipo = 'revoke' THEN
            v_mensagem_respondida := NULLIF(trim(COALESCE(
              v_msg#>>'{revoke,original_message_id}',
              v_msg->>'original_message_id'
            )), '');
            IF v_mensagem_respondida IS NOT NULL THEN
              UPDATE public."SAAS_Mensagens"
              SET apagada = true
              WHERE "metaMessageId" = v_mensagem_respondida
                AND "conexaoId" = v_conexao.id;
            END IF;
            CONTINUE;
          END IF;

          IF v_tipo = 'edit' THEN
            v_mensagem_respondida := NULLIF(trim(COALESCE(
              v_msg#>>'{edit,original_message_id}',
              v_msg->>'original_message_id'
            )), '');
            v_texto := COALESCE(
              v_msg#>>'{edit,message,text,body}',
              v_msg#>>'{edit,text,body}',
              v_msg#>>'{text,body}'
            );
            IF v_mensagem_respondida IS NOT NULL AND NULLIF(trim(COALESCE(v_texto, '')), '') IS NOT NULL THEN
              UPDATE public."SAAS_Mensagens"
              SET mensagem = trim(v_texto)
              WHERE "metaMessageId" = v_mensagem_respondida
                AND "conexaoId" = v_conexao.id;
            END IF;
            CONTINUE;
          END IF;

          CASE v_tipo
            WHEN 'text' THEN
              v_tipo := 'conversation';
              v_texto := v_msg#>>'{text,body}';
            WHEN 'location' THEN
              v_texto := COALESCE(v_msg#>>'{location,name}', v_msg#>>'{location,address}', '[localizacao]');
            WHEN 'contacts' THEN
              v_texto := '[contato]';
            WHEN 'interactive' THEN
              v_texto := COALESCE(
                v_msg#>>'{interactive,button_reply,title}',
                v_msg#>>'{interactive,list_reply,title}',
                '[interativo]'
              );
            WHEN 'button' THEN
              v_texto := v_msg#>>'{button,text}';
            WHEN 'reaction' THEN
              v_texto := v_msg#>>'{reaction,emoji}';
            ELSE
              v_texto := COALESCE(v_msg->>'type', '[mensagem]');
          END CASE;

          IF v_tipo = 'reaction' THEN
            CONTINUE;
          END IF;

          v_chat_result := public.f_meta_salvar_mensagem_chat(
            v_conexao.id,
            v_conexao."contaId",
            v_telefone,
            v_texto,
            v_tipo,
            true,
            v_wamid,
            'sent',
            v_arquivo,
            v_nome,
            NULLIF(trim(COALESCE(v_msg#>>'{context,id}', '')), '')
          );

          IF v_chat_result IS NOT NULL THEN
            v_agente_fluxo := COALESCE(v_chat_result, '{}'::jsonb)
              || jsonb_build_object(
                'canal', 'meta',
                'fromMe', true,
                'echo', true,
                'metaMessageId', v_wamid,
                'telefone', v_telefone,
                'tipoMensagem', v_tipo,
                'mensagem', v_texto,
                'nomeContato', v_nome
              );
          END IF;
        END LOOP;
      END IF;

      RETURN jsonb_build_object(
        'ok', true,
        'field', v_field,
        'conexaoId', v_conexao.id
      ) || CASE
        WHEN v_agente_fluxo IS NOT NULL THEN v_agente_fluxo
        ELSE '{}'::jsonb
      END;
    END IF;

    IF v_field = 'message_template_status_update' THEN
      v_template_nome := v_value->>'message_template_name';
      v_template_idioma := COALESCE(v_value->>'message_template_language', 'pt_BR');
      v_motivo := COALESCE(v_value->>'reason', v_value#>>'{rejection_info,reason}');

      INSERT INTO public."SAAS_Templates_Meta" (
        "conexaoId", "wabaId", "metaTemplateId", nome, idioma, categoria, status,
        "motivoRejeicao", "statusUpdatedAt"
      ) VALUES (
        v_conexao.id,
        v_waba_id,
        COALESCE(v_value->>'message_template_id', NULL),
        v_template_nome,
        v_template_idioma,
        v_value->>'message_template_category',
        v_value->>'event',
        NULLIF(v_motivo, 'NONE'),
        v_now
      )
      ON CONFLICT ("conexaoId", nome, idioma) DO UPDATE SET
        "metaTemplateId" = COALESCE(EXCLUDED."metaTemplateId", public."SAAS_Templates_Meta"."metaTemplateId"),
        categoria = COALESCE(EXCLUDED.categoria, public."SAAS_Templates_Meta".categoria),
        status = EXCLUDED.status,
        "motivoRejeicao" = EXCLUDED."motivoRejeicao",
        "statusUpdatedAt" = EXCLUDED."statusUpdatedAt",
        updated_at = v_now;

      RETURN jsonb_build_object('ok', true, 'field', v_field, 'conexaoId', v_conexao.id, 'template', v_template_nome);
    END IF;

    IF v_field = 'message_template_quality_update' THEN
      v_template_nome := v_value->>'message_template_name';
      v_template_idioma := COALESCE(v_value->>'message_template_language', 'pt_BR');

      INSERT INTO public."SAAS_Templates_Meta" (
        "conexaoId", "wabaId", "metaTemplateId", nome, idioma, qualidade, "qualidadeUpdatedAt"
      ) VALUES (
        v_conexao.id,
        v_waba_id,
        COALESCE(v_value->>'message_template_id', NULL),
        v_template_nome,
        v_template_idioma,
        v_value->>'new_quality_score',
        v_now
      )
      ON CONFLICT ("conexaoId", nome, idioma) DO UPDATE SET
        "metaTemplateId" = COALESCE(EXCLUDED."metaTemplateId", public."SAAS_Templates_Meta"."metaTemplateId"),
        qualidade = EXCLUDED.qualidade,
        "qualidadeUpdatedAt" = EXCLUDED."qualidadeUpdatedAt",
        updated_at = v_now;

      RETURN jsonb_build_object('ok', true, 'field', v_field, 'conexaoId', v_conexao.id, 'template', v_template_nome);
    END IF;

    IF v_field = 'template_category_update' THEN
      v_template_nome := v_value->>'message_template_name';
      v_template_idioma := COALESCE(v_value->>'message_template_language', 'pt_BR');

      INSERT INTO public."SAAS_Templates_Meta" (
        "conexaoId", "wabaId", "metaTemplateId", nome, idioma, categoria, "categoriaUpdatedAt"
      ) VALUES (
        v_conexao.id,
        v_waba_id,
        COALESCE(v_value->>'message_template_id', NULL),
        v_template_nome,
        v_template_idioma,
        COALESCE(v_value->>'new_category', v_value->>'message_template_category'),
        v_now
      )
      ON CONFLICT ("conexaoId", nome, idioma) DO UPDATE SET
        categoria = EXCLUDED.categoria,
        "categoriaUpdatedAt" = EXCLUDED."categoriaUpdatedAt",
        updated_at = v_now;

      RETURN jsonb_build_object('ok', true, 'field', v_field, 'conexaoId', v_conexao.id, 'template', v_template_nome);
    END IF;

    IF v_field = 'phone_number_quality_update' THEN
      UPDATE public."SAAS_Conexões"
      SET "metaPhoneQualityEvent" = v_value->>'event',
          "metaPhoneQualityLimit" = v_value->>'current_limit',
          "metaPhoneQualityUpdatedAt" = v_now,
          "Telefone" = COALESCE(NULLIF(trim("Telefone"), ''), NULLIF(regexp_replace(COALESCE(v_value->>'display_phone_number', ''), '\D', '', 'g'), ''))
      WHERE id = v_conexao.id;

      RETURN jsonb_build_object('ok', true, 'field', v_field, 'conexaoId', v_conexao.id);
    END IF;

    IF v_field = 'business_capability_update' THEN
      v_limit := COALESCE(
        v_value->>'max_daily_conversations_per_business',
        v_value->>'max_daily_conversation_per_business',
        CASE
          WHEN (v_value->>'max_daily_conversation_per_phone') IS NOT NULL THEN
            'TIER_' || (v_value->>'max_daily_conversation_per_phone')
          ELSE NULL
        END
      );

      UPDATE public."SAAS_Conexões"
      SET "metaMessagingLimit" = v_limit,
          "metaMaxPhoneNumbers" = COALESCE(
            NULLIF(v_value->>'max_phone_numbers_per_business', '')::integer,
            NULLIF(v_value->>'max_phone_numbers_per_waba', '')::integer,
            "metaMaxPhoneNumbers"
          ),
          "metaBusinessCapabilityUpdatedAt" = v_now
      WHERE id = v_conexao.id;

      RETURN jsonb_build_object('ok', true, 'field', v_field, 'conexaoId', v_conexao.id);
    END IF;

    IF v_field = 'account_update' THEN
      UPDATE public."SAAS_Conexões"
      SET "metaAccountEvent" = v_value->>'event',
          "metaAccountUpdate" = v_value,
          "metaAccountUpdatedAt" = v_now
      WHERE id = v_conexao.id;

      RETURN jsonb_build_object('ok', true, 'field', v_field, 'conexaoId', v_conexao.id, 'event', v_value->>'event');
    END IF;

    IF v_field = 'account_alerts' THEN
      UPDATE public."SAAS_Conexões"
      SET "metaUltimoAlerta" = v_value,
          "metaAlertasUpdatedAt" = v_now
      WHERE id = v_conexao.id;

      RETURN jsonb_build_object('ok', true, 'field', v_field, 'conexaoId', v_conexao.id);
    END IF;

    IF v_field = 'payment_configuration_update' THEN
      RETURN public.f_meta_upsert_pagamento(v_conexao.id, v_value)
        || jsonb_build_object('field', v_field, 'conexaoId', v_conexao.id);
    END IF;

    RETURN jsonb_build_object('ok', true, 'ignored', true, 'field', v_field);
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'error', SQLERRM, 'field', v_field);
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_meta_salvar_mensagem_midia_job(p_job jsonb)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
  BEGIN
    RETURN public.f_meta_salvar_mensagem_chat(
      NULLIF(p_job->>'conexaoId', '')::bigint,
      NULLIF(p_job->>'contaId', '')::uuid,
      p_job->>'telefone',
      NULLIF(p_job->>'mensagem', ''),
      COALESCE(NULLIF(p_job->>'tipo_mensagem', ''), 'image'),
      lower(COALESCE(p_job->>'from_me', p_job->>'fromMe', 'false')) IN ('true', 't', '1'),
      p_job->>'meta_message_id',
      CASE
        WHEN lower(COALESCE(p_job->>'from_me', p_job->>'fromMe', 'false')) IN ('true', 't', '1') THEN 'sent'
        ELSE NULL
      END,
      NULLIF(p_job->>'link', ''),
      NULLIF(p_job->>'nome_contato', ''),
      NULLIF(COALESCE(p_job->>'mensagemRespondida', p_job->>'mensagem_respondida'), '')
    );
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_meta_preparar_envio_template(p_payload jsonb)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
  DECLARE
    v_id_conexao bigint;
    v_id_contato bigint;
    v_template_id bigint;
    v_id_mensagem bigint;
    v_conexao jsonb;
    v_template jsonb;
    v_contato jsonb;
    v_conta_id uuid;
  BEGIN
    v_id_conexao := NULLIF(trim(COALESCE(p_payload->>'idConexao', p_payload->>'id_conexao', '')), '')::bigint;
    v_id_contato := NULLIF(trim(COALESCE(p_payload->>'idContato', p_payload->>'id_contato', '')), '')::bigint;
    v_template_id := NULLIF(trim(COALESCE(p_payload->>'templateId', p_payload->>'template_id', '')), '')::bigint;
    v_id_mensagem := NULLIF(trim(COALESCE(p_payload->>'idMensagem', p_payload->>'id_mensagem', '')), '')::bigint;

    IF v_id_conexao IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Campo idConexao obrigatorio.');
    END IF;
    IF v_id_contato IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Campo idContato obrigatorio.');
    END IF;
    IF v_template_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Campo templateId obrigatorio.');
    END IF;
    IF v_id_mensagem IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Campo idMensagem obrigatorio.');
    END IF;

    SELECT to_jsonb(c) INTO v_conexao
    FROM public."SAAS_Conexões" c
    WHERE c.id = v_id_conexao
    LIMIT 1;

    IF v_conexao IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Conexao nao encontrada.');
    END IF;

    IF COALESCE((v_conexao->>'apiOficial')::boolean, false) IS NOT TRUE THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Envio de template exige conexao com apiOficial=true.');
    END IF;

    IF NULLIF(v_conexao->>'access_token', '') IS NULL OR NULLIF(v_conexao->>'phone_number_id', '') IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Conexao sem access_token ou phone_number_id.');
    END IF;

    SELECT to_jsonb(t) INTO v_template
    FROM public."SAAS_Templates_Meta" t
    WHERE t.id = v_template_id
    LIMIT 1;

    IF v_template IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Template nao encontrado em SAAS_Templates_Meta.');
    END IF;

    IF (v_template->>'conexaoId')::bigint IS DISTINCT FROM v_id_conexao THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Template nao pertence a esta conexao.');
    END IF;

    IF NULLIF(v_template->>'status', '') IS NOT NULL
      AND upper(v_template->>'status') <> 'APPROVED' THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', format('Template com status %s; apenas aprovados podem ser enviados.', v_template->>'status')
      );
    END IF;

    SELECT to_jsonb(ct) INTO v_contato
    FROM public."SAAS_Contatos" ct
    WHERE ct.id = v_id_contato
    LIMIT 1;

    IF v_contato IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Contato nao encontrado.');
    END IF;

    IF NULLIF(regexp_replace(COALESCE(v_contato->>'telefone', ''), '\D', '', 'g'), '') IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Contato sem telefone valido.');
    END IF;

    v_conta_id := NULLIF(v_contato->>'contaId', '')::uuid;

    RETURN jsonb_build_object(
      'ok', true,
      'idMensagem', v_id_mensagem,
      'conexao', jsonb_build_object(
        'id', v_conexao->>'id',
        'apiOficial', v_conexao->>'apiOficial',
        'access_token', v_conexao->>'access_token',
        'phone_number_id', v_conexao->>'phone_number_id',
        'contaId', v_conexao->>'contaId'
      ),
      'template', jsonb_build_object(
        'id', v_template->>'id',
        'nome', v_template->>'nome',
        'idioma', v_template->>'idioma',
        'status', v_template->>'status',
        'conexaoId', v_template->>'conexaoId',
        'componentes', COALESCE(v_template->'componentes', 'null'::jsonb),
        'variaveisCampos', v_template->'variaveisCampos'
      ),
      'contato', jsonb_build_object(
        'id', v_contato->>'id',
        'telefone', v_contato->>'telefone',
        'nome', v_contato->>'nome',
        'variaveis', COALESCE(v_contato->'variaveis', '{}'::jsonb),
        'contaId', v_contato->>'contaId'
      ),
      'valoresCampos', COALESCE((
        SELECT jsonb_agg(jsonb_build_object('idCampo', v."idCampo", 'valor', v.valor) ORDER BY v."idCampo")
        FROM public."SAAS_Valores_Campos_Personalizados" v
        WHERE v."idContato" = v_id_contato
      ), '[]'::jsonb),
      'camposPersonalizados', COALESCE((
        SELECT jsonb_agg(jsonb_build_object('id', cp.id, 'nome', cp.nome, 'tipo', cp.tipo) ORDER BY cp.id)
        FROM public."SAAS_Campos_Personalizados" cp
        WHERE cp."contaId" = v_conta_id
      ), '[]'::jsonb)
    );
  END;
  $$;

  GRANT EXECUTE ON FUNCTION public.f_meta_salvar_mensagem_midia_job(jsonb) TO authenticated, service_role;
  GRANT EXECUTE ON FUNCTION public.f_meta_preparar_envio_template(jsonb) TO authenticated, service_role;

  GRANT EXECUTE ON FUNCTION public.f_meta_resolver_conexao(text, text) TO authenticated, service_role;
  GRANT EXECUTE ON FUNCTION public.f_meta_upsert_pagamento(bigint, jsonb) TO authenticated, service_role;
  GRANT EXECUTE ON FUNCTION public.f_meta_salvar_mensagem_chat(bigint, uuid, text, text, text, boolean, text, text, text, text, text) TO authenticated, service_role;
  GRANT EXECUTE ON FUNCTION public.f_meta_normalizar_tipo_mensagem(text) TO authenticated, service_role;
  GRANT EXECUTE ON FUNCTION public.f_meta_processar_evento(jsonb) TO authenticated, service_role;
  GRANT EXECUTE ON FUNCTION public.f_meta_alternar_telefone_br(text) TO authenticated, service_role;
  GRANT EXECUTE ON FUNCTION public.f_meta_erro_pagamento_webhook(jsonb) TO authenticated, service_role;
  GRANT EXECUTE ON FUNCTION public.f_meta_patch_pagamento_por_webhook(bigint, text, jsonb) TO authenticated, service_role;
  GRANT EXECUTE ON FUNCTION public.f_meta_retry_detalhe_telefone_webhook(text, jsonb) TO authenticated, service_role;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Templates_Meta"') IS NULL THEN RETURN; END IF;
    ALTER TABLE public."SAAS_Templates_Meta" ENABLE ROW LEVEL SECURITY;
    DROP POLICY IF EXISTS "service_role_full_access" ON public."SAAS_Templates_Meta";
    DROP POLICY IF EXISTS "select_templates_meta" ON public."SAAS_Templates_Meta";
    DROP POLICY IF EXISTS "insert_templates_meta" ON public."SAAS_Templates_Meta";
    DROP POLICY IF EXISTS "update_templates_meta" ON public."SAAS_Templates_Meta";
    DROP POLICY IF EXISTS "delete_templates_meta" ON public."SAAS_Templates_Meta";
    CREATE POLICY "service_role_full_access" ON public."SAAS_Templates_Meta" TO service_role USING (true) WITH CHECK (true);
    CREATE POLICY "select_templates_meta" ON public."SAAS_Templates_Meta" FOR SELECT TO authenticated
      USING (
        EXISTS (
          SELECT 1 FROM public."SAAS_Conexões" c
          WHERE c.id = "SAAS_Templates_Meta"."conexaoId"
            AND (c."contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()))
        )
      );
    CREATE POLICY "insert_templates_meta" ON public."SAAS_Templates_Meta" FOR INSERT TO authenticated
      WITH CHECK (
        EXISTS (
          SELECT 1 FROM public."SAAS_Conexões" c
          WHERE c.id = "SAAS_Templates_Meta"."conexaoId"
            AND (c."contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()))
        )
      );
    CREATE POLICY "update_templates_meta" ON public."SAAS_Templates_Meta" FOR UPDATE TO authenticated
      USING (
        EXISTS (
          SELECT 1 FROM public."SAAS_Conexões" c
          WHERE c.id = "SAAS_Templates_Meta"."conexaoId"
            AND (c."contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()))
        )
      );
    CREATE POLICY "delete_templates_meta" ON public."SAAS_Templates_Meta" FOR DELETE TO authenticated
      USING (
        EXISTS (
          SELECT 1 FROM public."SAAS_Conexões" c
          WHERE c.id = "SAAS_Templates_Meta"."conexaoId"
            AND (c."contaId" IN (SELECT public.rls_conta_ids_admin()) OR (SELECT public.rls_eh_super_admin()))
        )
      );
    GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_Templates_Meta" TO authenticated;
  END$$;

  -- Meta WhatsApp: cache de perfil e metadados da conexao (tela de dados da conexao)
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Conexões"') IS NULL THEN RETURN; END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaPerfil') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaPerfil" JSONB;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaPerfilUpdatedAt') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaPerfilUpdatedAt" TIMESTAMPTZ;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaVerifiedName') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaVerifiedName" TEXT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaPhoneStatus') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaPhoneStatus" TEXT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaQualityRating') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaQualityRating" TEXT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaBusinessVerificationStatus') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaBusinessVerificationStatus" TEXT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaAccountReviewStatus') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaAccountReviewStatus" TEXT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaDadosUpdatedAt') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaDadosUpdatedAt" TIMESTAMPTZ;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'SAAS_Conexões' AND column_name = 'metaPinVerificacao') THEN
      ALTER TABLE public."SAAS_Conexões" ADD COLUMN "metaPinVerificacao" TEXT;
    END IF;
  END$$;

  -- =============================================================================
  -- Disparo API Oficial: colunas, mapeamento de variáveis e create_disparo_oficial
  -- =============================================================================

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Disparos"') IS NOT NULL THEN
      IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'SAAS_Disparos' AND column_name = 'apiOficial'
      ) THEN
        ALTER TABLE public."SAAS_Disparos" ADD COLUMN "apiOficial" BOOLEAN NOT NULL DEFAULT false;
      END IF;
    END IF;

    IF to_regclass('public."SAAS_Templates_Meta"') IS NOT NULL THEN
      IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'SAAS_Templates_Meta' AND column_name = 'variaveisCampos'
      ) THEN
        ALTER TABLE public."SAAS_Templates_Meta" ADD COLUMN "variaveisCampos" JSONB NOT NULL DEFAULT '{}'::jsonb;
      END IF;
    END IF;

    -- Métrica de leitura (webhook Meta status=read → eventsmeta)
    IF to_regclass('public."SAAS_Detalhes_Disparos"') IS NOT NULL THEN
      IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'SAAS_Detalhes_Disparos' AND column_name = 'mensagemLida'
      ) THEN
        ALTER TABLE public."SAAS_Detalhes_Disparos"
          ADD COLUMN "mensagemLida" BOOLEAN NOT NULL DEFAULT false;
      END IF;
      IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'SAAS_Detalhes_Disparos' AND column_name = 'dataMensagemLida'
      ) THEN
        ALTER TABLE public."SAAS_Detalhes_Disparos"
          ADD COLUMN "dataMensagemLida" TIMESTAMPTZ;
      END IF;
    END IF;
  END$$;

  CREATE OR REPLACE FUNCTION public.f_meta_tier_to_limit(p_tier text)
  RETURNS bigint
  LANGUAGE plpgsql
  IMMUTABLE
  AS $$
  DECLARE
    v_raw text := upper(trim(COALESCE(p_tier, '')));
    v_match text[];
    v_num bigint;
  BEGIN
    IF v_raw = '' THEN RETURN NULL; END IF;
    IF v_raw LIKE '%UNLIMITED%' THEN RETURN NULL; END IF;
    v_match := regexp_match(v_raw, 'TIER_(\d+)(K|M)?');
    IF v_match IS NULL THEN RETURN NULL; END IF;
    v_num := v_match[1]::bigint;
    IF v_match[2] = 'K' THEN v_num := v_num * 1000;
    ELSIF v_match[2] = 'M' THEN v_num := v_num * 1000000;
    END IF;
    RETURN v_num;
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_meta_campo_valor_contato(
    p_contato_id bigint,
    p_campo_id bigint,
    p_conta_id uuid
  )
  RETURNS text
  LANGUAGE sql
  STABLE
  AS $$
    SELECT COALESCE(v."valor", '')
    FROM public."SAAS_Valores_Campos_Personalizados" v
    WHERE v."idContato" = p_contato_id
      AND v."idCampo" = p_campo_id
      AND v."contaId" = p_conta_id
    LIMIT 1;
  $$;

  CREATE OR REPLACE FUNCTION public.f_meta_build_disparo_payload(
    p_template_id bigint,
    p_contato_id bigint,
    p_conta_id uuid
  )
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path = public
  AS $$
  DECLARE
    v_tpl record;
    v_map jsonb;
    v_payload jsonb := '{}'::jsonb;
    v_body jsonb := '[]'::jsonb;
    v_header jsonb;
    v_buttons jsonb := '[]'::jsonb;
    v_comp jsonb;
    v_idx int;
    v_campo_id bigint;
    v_campo_raw text;
    v_valor text;
    v_btn jsonb;
    v_btn_out jsonb;
    v_header_midia jsonb;
  BEGIN
    SELECT id, componentes, "variaveisCampos"
    INTO v_tpl
    FROM public."SAAS_Templates_Meta"
    WHERE id = p_template_id;

    IF NOT FOUND THEN
      RETURN '{}'::jsonb;
    END IF;

    v_map := COALESCE(v_tpl."variaveisCampos", '{}'::jsonb);

    IF jsonb_typeof(v_map->'body') = 'object' THEN
      FOR v_idx IN
        SELECT (key)::int
        FROM jsonb_each(v_map->'body')
        ORDER BY (key)::int
      LOOP
        v_campo_raw := NULLIF(v_map->'body'->>v_idx::text, '');
        IF v_campo_raw IN ('nome', 'email') THEN
          SELECT CASE v_campo_raw
            WHEN 'nome' THEN COALESCE(c.nome, '')
            WHEN 'email' THEN COALESCE(c.email, '')
          END
          INTO v_valor
          FROM public."SAAS_Contatos" c
          WHERE c.id = p_contato_id
            AND c."contaId" = p_conta_id
          LIMIT 1;
          v_valor := COALESCE(v_valor, '');
        ELSE
          v_campo_id := v_campo_raw::bigint;
          v_valor := COALESCE(public.f_meta_campo_valor_contato(p_contato_id, v_campo_id, p_conta_id), '');
        END IF;
        v_body := v_body || jsonb_build_array(v_valor);
      END LOOP;
    END IF;

    IF jsonb_array_length(v_body) > 0 THEN
      v_payload := v_payload || jsonb_build_object('body', v_body);
    END IF;

    v_header_midia := v_map->'headerMidia';
    IF v_header_midia IS NOT NULL AND jsonb_typeof(v_header_midia) = 'object' AND NULLIF(v_header_midia->>'link', '') IS NOT NULL THEN
      v_payload := v_payload || jsonb_build_object(
        'header',
        jsonb_build_object(
          'type', COALESCE(NULLIF(lower(v_header_midia->>'type'), ''), 'image'),
          'link', v_header_midia->>'link'
        )
      );
    ELSIF jsonb_typeof(v_tpl.componentes) = 'array' THEN
      FOR v_comp IN SELECT value FROM jsonb_array_elements(v_tpl.componentes)
      LOOP
        IF upper(COALESCE(v_comp->>'type', '')) = 'HEADER'
          AND upper(COALESCE(v_comp->>'format', '')) IN ('IMAGE', 'VIDEO', 'DOCUMENT')
          AND NULLIF(v_comp->>'link', '') IS NOT NULL THEN
          v_payload := v_payload || jsonb_build_object(
            'header',
            jsonb_build_object(
              'type', lower(v_comp->>'format'),
              'link', v_comp->>'link'
            )
          );
          EXIT;
        END IF;
      END LOOP;
    END IF;

    IF jsonb_typeof(v_map->'buttons') = 'array' THEN
      FOR v_btn IN SELECT value FROM jsonb_array_elements(v_map->'buttons')
      LOOP
        v_btn_out := jsonb_build_object(
          'type', COALESCE(v_btn->>'type', 'url'),
          'index', COALESCE((v_btn->>'index')::int, 0)
        );
        IF NULLIF(v_btn->>'payload', '') IS NOT NULL THEN
          v_btn_out := v_btn_out || jsonb_build_object('payload', v_btn->>'payload');
        ELSIF NULLIF(v_btn->>'campoPadrao', '') IN ('nome', 'email') THEN
          v_campo_raw := v_btn->>'campoPadrao';
          SELECT CASE v_campo_raw
            WHEN 'nome' THEN COALESCE(c.nome, '')
            WHEN 'email' THEN COALESCE(c.email, '')
          END
          INTO v_valor
          FROM public."SAAS_Contatos" c
          WHERE c.id = p_contato_id
            AND c."contaId" = p_conta_id
          LIMIT 1;
          v_btn_out := v_btn_out || jsonb_build_object('payload', COALESCE(v_valor, ''));
        ELSIF NULLIF(v_btn->>'campoId', '') IS NOT NULL THEN
          v_campo_id := (v_btn->>'campoId')::bigint;
          v_valor := COALESCE(public.f_meta_campo_valor_contato(p_contato_id, v_campo_id, p_conta_id), '');
          v_btn_out := v_btn_out || jsonb_build_object('payload', v_valor);
        END IF;
        v_buttons := v_buttons || jsonb_build_array(v_btn_out);
      END LOOP;
    END IF;

    IF jsonb_array_length(v_buttons) > 0 THEN
      v_payload := v_payload || jsonb_build_object('buttons', v_buttons);
    END IF;

    RETURN v_payload;
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_meta_payload_key_redis(p_payload jsonb)
  RETURNS text
  LANGUAGE sql
  IMMUTABLE
  AS $$
    SELECT NULLIF(p_payload #>> '{header,link}', '');
  $$;

  CREATE OR REPLACE FUNCTION public.create_disparo_oficial(p_payload jsonb)
  RETURNS bigint
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $function$
  DECLARE
    v_conta_id uuid := (p_payload ->> 'userId')::uuid;
    v_nome_disparo text := NULLIF(COALESCE(p_payload->>'nomeCampanha', p_payload->>'nomeDisparo', ''), '');
    v_template_id bigint := NULLIF(COALESCE(p_payload->>'templateId', ''), '')::bigint;
    v_conn_id bigint := NULLIF(COALESCE(p_payload->>'connectionId', ''), '')::bigint;
    v_etiqueta_ids bigint[] := COALESCE(
      ARRAY(SELECT (x)::bigint FROM jsonb_array_elements_text(COALESCE(p_payload->'idLista', p_payload->'idEtiqueta', '[]'::jsonb)) x),
      array[]::bigint[]
    );
    v_stage_ids bigint[] := COALESCE(
      ARRAY(
        SELECT DISTINCT (f->>'stageId')::bigint
        FROM jsonb_array_elements(COALESCE(p_payload->'settings'->'crmFilters', '[]'::jsonb)) f
        WHERE (f->>'stageId') ~ '^\d+$'
      ),
      ARRAY(
        SELECT DISTINCT (x)::bigint
        FROM jsonb_array_elements_text(COALESCE(p_payload->'settings'->'crmStageIds', '[]'::jsonb)) x
        WHERE x ~ '^\d+$'
      ),
      array[]::bigint[]
    );
    v_schedule_base timestamptz := COALESCE(
      (p_payload #>> '{settings,scheduleData}')::timestamptz,
      now() + interval '2 minutes'
    );
    v_mostrar_mensagem boolean := COALESCE((p_payload #>> '{settings,mostrarMensagem}')::boolean, true);
    v_avancado boolean := COALESCE((p_payload #>> '{settings,avancado}')::boolean, false);
    v_pause_after int := 0;
    v_pause_minutes int := 0;
    v_interval_min int := 0;
    v_interval_max int := 0;
    v_start_time time := NULL;
    v_end_time time := NULL;
    v_days int[] := array[]::int[];
    v_gap int;
    v_cur_ts timestamptz;
    v_counter int := 0;
    v_disparo_id bigint;
    v_total int := 0;
    v_first_ts timestamptz;
    v_conn record;
    v_tpl record;
    v_tier_limit bigint;
    v_limit_plan bigint;
    v_used_month bigint;
    v_to_send bigint;
    v_total_after bigint;
    v_month_start timestamptz := (date_trunc('month', now() AT TIME ZONE 'America/Sao_Paulo') AT TIME ZONE 'America/Sao_Paulo');
    v_next_month timestamptz := ((date_trunc('month', now() AT TIME ZONE 'America/Sao_Paulo') + interval '1 month') AT TIME ZONE 'America/Sao_Paulo');
    rec_cont record;
    v_payload jsonb;
    v_key_redis text;
  BEGIN
    IF v_conta_id IS NULL THEN
      RAISE EXCEPTION 'userId é obrigatório' USING ERRCODE = 'P0001';
    END IF;
    IF v_template_id IS NULL THEN
      RAISE EXCEPTION 'templateId é obrigatório' USING ERRCODE = 'P0001';
    END IF;
    IF v_conn_id IS NULL THEN
      RAISE EXCEPTION 'connectionId é obrigatório' USING ERRCODE = 'P0001';
    END IF;

    SELECT c.* INTO v_conn
    FROM public."SAAS_Conexões" c
    WHERE c.id = v_conn_id
      AND c."contaId" = v_conta_id
      AND COALESCE(c."apiOficial", false) = true;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Conexão API Oficial inválida para esta conta' USING ERRCODE = 'P0001';
    END IF;

    IF NULLIF(trim(COALESCE(v_conn."metaMessagingLimit", '')), '') IS NULL THEN
      RAISE EXCEPTION 'Sincronize os dados da conexão API Oficial antes de criar o disparo' USING ERRCODE = 'P0001';
    END IF;

    v_tier_limit := public.f_meta_tier_to_limit(v_conn."metaMessagingLimit");

    SELECT t.* INTO v_tpl
    FROM public."SAAS_Templates_Meta" t
    WHERE t.id = v_template_id
      AND t."conexaoId" = v_conn_id
      AND upper(COALESCE(t.status, '')) = 'APPROVED';

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Template não encontrado, não aprovado ou não pertence à conexão selecionada' USING ERRCODE = 'P0001';
    END IF;

    WITH etiqueta_contatos AS (
      SELECT DISTINCT c.id, c.telefone
      FROM public."SAAS_Contatos" c
      JOIN public."SAAS_Contatos_Etiquetas" ce ON ce."contatoId" = c.id
      WHERE c."contaId" = v_conta_id
        AND c.tipo = 'contato'
        AND c.telefone IS NOT NULL
        AND btrim(c.telefone) <> ''
        AND ce."etiquetaId" = ANY(v_etiqueta_ids)
    ),
    crm_contatos AS (
      SELECT DISTINCT c.id, c.telefone
      FROM public."SAAS_Contatos" c
      JOIN public."SAAS_Cards_Quadros" cq ON cq."contatoId" = c.id
      WHERE c."contaId" = v_conta_id
        AND c.tipo = 'contato'
        AND c.telefone IS NOT NULL
        AND btrim(c.telefone) <> ''
        AND cq."etapaQuadroId" = ANY(v_stage_ids)
    ),
    all_contatos AS (
      SELECT DISTINCT c.id, c.telefone
      FROM public."SAAS_Contatos" c
      WHERE c."contaId" = v_conta_id
        AND c.tipo = 'contato'
        AND c.telefone IS NOT NULL
        AND btrim(c.telefone) <> ''
        AND COALESCE(cardinality(v_etiqueta_ids), 0) = 0
        AND COALESCE(cardinality(v_stage_ids), 0) = 0
    ),
    base AS (
      SELECT id, telefone FROM etiqueta_contatos
      UNION
      SELECT id, telefone FROM crm_contatos
      UNION
      SELECT id, telefone FROM all_contatos
    )
    SELECT COALESCE(COUNT(*), 0)::bigint INTO v_to_send FROM base;

    IF v_to_send = 0 THEN
      RAISE EXCEPTION 'Nenhum contato elegível para o disparo' USING ERRCODE = 'P0001';
    END IF;

    IF v_tier_limit IS NOT NULL AND v_to_send > v_tier_limit THEN
      RAISE EXCEPTION 'tier excedido: máximo % contatos a cada 24h para esta conexão, selecionados %', v_tier_limit, v_to_send
        USING ERRCODE = 'P0001';
    END IF;

    SELECT p."qntDisparos"::bigint INTO v_limit_plan
    FROM public."SAAS_Contas" conta
    LEFT JOIN public."SAAS_Planos" p ON p.id = conta.plano
    WHERE conta.id = v_conta_id;

    IF v_limit_plan IS NOT NULL THEN
      SELECT COALESCE(COUNT(*), 0)::bigint INTO v_used_month
      FROM public."SAAS_Detalhes_Disparos" d
      JOIN public."SAAS_Disparos" h ON h.id = d."idDisparo"
      WHERE h."contaId" = v_conta_id
        AND d."dataEnvio" >= v_month_start
        AND d."dataEnvio" < v_next_month;

      v_total_after := v_used_month + v_to_send;
      IF v_total_after > v_limit_plan THEN
        RAISE EXCEPTION 'limite atingido: % usados + % a enviar = %, limite = %', v_used_month, v_to_send, v_total_after, v_limit_plan
          USING ERRCODE = 'P0001';
      END IF;
    END IF;

    IF v_avancado THEN
      v_interval_min := COALESCE((p_payload #>> '{settings,intervalMin}')::int, 30);
      v_interval_max := COALESCE((p_payload #>> '{settings,intervalMax}')::int, 60);
      v_pause_after := GREATEST(COALESCE((p_payload #>> '{settings,pauseAfterMessages}')::int, 0), 0);
      v_pause_minutes := GREATEST(COALESCE((p_payload #>> '{settings,pauseMinutes}')::int, 0), 0);
      v_start_time := COALESCE((p_payload #>> '{settings,startTime}')::time, time '08:00');
      v_end_time := COALESCE((p_payload #>> '{settings,endTime}')::time, time '18:00');
      v_days := COALESCE(
        ARRAY(
          SELECT CASE WHEN dtxt = '0' THEN 7 ELSE dtxt::int END
          FROM jsonb_array_elements_text(COALESCE(p_payload->'settings'->'selectedDays', '[]'::jsonb)) WITH ORDINALITY AS t(dtxt, ord)
          WHERE dtxt ~ '^\d+$'
          ORDER BY ord
        ),
        array[]::int[]
      );
      IF v_interval_min <= 0 THEN v_interval_min := 30; END IF;
      IF v_interval_max <= 0 THEN v_interval_max := 60; END IF;
      IF v_interval_max < v_interval_min THEN v_interval_max := v_interval_min; END IF;
      IF v_pause_after < 1 OR v_pause_minutes < 1 THEN
        RAISE EXCEPTION 'Informe mensagens e minutos válidos para a pausa automática' USING ERRCODE = 'P0001';
      END IF;
      IF COALESCE(array_length(v_days, 1), 0) = 0 THEN
        RAISE EXCEPTION 'Selecione pelo menos um dia da semana' USING ERRCODE = 'P0001';
      END IF;
      v_cur_ts := public.f_next_valid_time(v_schedule_base, v_start_time, v_end_time, v_days);
    ELSE
      v_cur_ts := v_schedule_base;
    END IF;

    INSERT INTO public."SAAS_Disparos" (
      "NomeDisparo", "Mensagens", "TipoDisparo", "TotalDisparos", "MensagensDisparadas",
      "StatusDisparo", "contaId", "idEtiquetas", "idConexoes", "DataAgendamento", "apiOficial", "mostrarMensagem",
      "intervaloMin", "intervaloMax", "PausaAposMensagens", "PausaMinutos", "StartTime", "EndTime", "DiasSelecionados"
    ) VALUES (
      v_nome_disparo, NULL, 'apioficial', 0, 0, 'Aguardando', v_conta_id,
      v_etiqueta_ids, ARRAY[v_conn_id],
      CASE WHEN p_payload #>> '{settings,scheduleData}' IS NOT NULL THEN v_schedule_base ELSE NULL END,
      true, v_mostrar_mensagem,
      CASE WHEN v_avancado THEN v_interval_min ELSE NULL END,
      CASE WHEN v_avancado THEN v_interval_max ELSE NULL END,
      CASE WHEN v_avancado THEN v_pause_after ELSE NULL END,
      CASE WHEN v_avancado THEN v_pause_minutes ELSE NULL END,
      CASE WHEN v_avancado THEN v_start_time ELSE NULL END,
      CASE WHEN v_avancado THEN v_end_time ELSE NULL END,
      CASE WHEN v_avancado THEN v_days::smallint[] ELSE NULL END
    )
    RETURNING id INTO v_disparo_id;

    FOR rec_cont IN
      WITH etiqueta_contatos AS (
        SELECT DISTINCT c.id, c.telefone
        FROM public."SAAS_Contatos" c
        JOIN public."SAAS_Contatos_Etiquetas" ce ON ce."contatoId" = c.id
        WHERE c."contaId" = v_conta_id
          AND c.tipo = 'contato'
          AND c.telefone IS NOT NULL
          AND btrim(c.telefone) <> ''
          AND ce."etiquetaId" = ANY(v_etiqueta_ids)
      ),
      crm_contatos AS (
        SELECT DISTINCT c.id, c.telefone
        FROM public."SAAS_Contatos" c
        JOIN public."SAAS_Cards_Quadros" cq ON cq."contatoId" = c.id
        WHERE c."contaId" = v_conta_id
          AND c.tipo = 'contato'
          AND c.telefone IS NOT NULL
          AND btrim(c.telefone) <> ''
          AND cq."etapaQuadroId" = ANY(v_stage_ids)
      ),
      all_contatos AS (
        SELECT DISTINCT c.id, c.telefone
        FROM public."SAAS_Contatos" c
        WHERE c."contaId" = v_conta_id
          AND c.tipo = 'contato'
          AND c.telefone IS NOT NULL
          AND btrim(c.telefone) <> ''
          AND COALESCE(cardinality(v_etiqueta_ids), 0) = 0
          AND COALESCE(cardinality(v_stage_ids), 0) = 0
      ),
      base AS (
        SELECT id, telefone FROM etiqueta_contatos
        UNION
        SELECT id, telefone FROM crm_contatos
        UNION
        SELECT id, telefone FROM all_contatos
      )
      SELECT DISTINCT ON (telefone) id, telefone
      FROM base
      ORDER BY telefone, id
    LOOP
      v_payload := public.f_meta_build_disparo_payload(v_template_id, rec_cont.id, v_conta_id);
      v_key_redis := public.f_meta_payload_key_redis(v_payload);

      IF v_avancado AND v_pause_after > 0 AND v_counter > 0 AND v_counter % v_pause_after = 0 THEN
        v_cur_ts := public.f_next_valid_time(v_cur_ts + make_interval(mins => v_pause_minutes), v_start_time, v_end_time, v_days);
      END IF;

      INSERT INTO public."SAAS_Detalhes_Disparos" (
        "idDisparo", "idContato", "Mensagem", "idConexao", "dataEnvio", "Status", "Payload", "KeyRedis"
      ) VALUES (
        v_disparo_id,
        rec_cont.id,
        v_template_id::text,
        v_conn_id,
        v_cur_ts,
        'pending',
        v_payload,
        v_key_redis
      );

      IF v_total = 0 THEN
        v_first_ts := v_cur_ts;
      END IF;
      v_total := v_total + 1;
      v_counter := v_counter + 1;

      IF v_avancado THEN
        v_gap := v_interval_min + floor(random() * (v_interval_max - v_interval_min + 1))::int;
        v_cur_ts := public.f_next_valid_time(v_cur_ts + make_interval(secs => v_gap), v_start_time, v_end_time, v_days);
      END IF;
    END LOOP;

    UPDATE public."SAAS_Disparos"
    SET "TotalDisparos" = v_total,
        "StatusDisparo" = CASE WHEN v_first_ts > now() THEN 'Aguardando' ELSE 'Em andamento' END
    WHERE id = v_disparo_id;

    RETURN v_disparo_id;
  END;
  $function$;

  GRANT EXECUTE ON FUNCTION public.f_meta_tier_to_limit(text) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.f_meta_campo_valor_contato(bigint, bigint, uuid) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.f_meta_build_disparo_payload(bigint, bigint, uuid) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.f_meta_payload_key_redis(jsonb) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.create_disparo_oficial(jsonb) TO authenticated;

  CREATE OR REPLACE FUNCTION public.f_render_variaveis_email(
    p_template TEXT,
    p_nome TEXT,
    p_email TEXT,
    p_attrs JSONB,
    p_send_ts timestamptz
  ) RETURNS TEXT
  LANGUAGE plpgsql
  IMMUTABLE
  AS $$
  DECLARE
    v_msg TEXT := COALESCE(p_template, '');
    v_token TEXT;
    v_val TEXT;
    v_dia TEXT;
  BEGIN
    v_dia := lower(to_char(p_send_ts AT TIME ZONE 'America/Sao_Paulo', 'TMDay'));
    v_dia := replace(replace(replace(replace(replace(replace(replace(
      v_dia, 'monday', 'segunda-feira'), 'tuesday', 'terça-feira'),
      'wednesday', 'quarta-feira'), 'thursday', 'quinta-feira'),
      'friday', 'sexta-feira'), 'saturday', 'sábado'), 'sunday', 'domingo');

    v_msg := replace(v_msg, '<nome>', COALESCE(p_nome, COALESCE(p_attrs->>'nome', '')));
    v_msg := replace(v_msg, '<email>', COALESCE(p_email, COALESCE(p_attrs->>'email', '')));
    v_msg := replace(v_msg, '<telefone>', COALESCE(p_attrs->>'telefone', ''));
    v_msg := replace(v_msg, '<data>', to_char(p_send_ts AT TIME ZONE 'America/Sao_Paulo', 'DD/MM/YYYY'));
    v_msg := replace(v_msg, '<diadasemana>', v_dia);
    v_msg := replace(v_msg, '<hora>', to_char(p_send_ts AT TIME ZONE 'America/Sao_Paulo', 'HH24:MI'));
    v_msg := replace(v_msg, '<mes>', lower(to_char(p_send_ts AT TIME ZONE 'America/Sao_Paulo', 'TMMonth')));
    v_msg := replace(v_msg, '<saudacao>', public.f_saudacao(p_send_ts));

    IF p_attrs IS NOT NULL THEN
      FOR v_token IN SELECT jsonb_object_keys(p_attrs)
      LOOP
        IF v_token NOT IN ('nome', 'email', 'telefone', 'data', 'diadasemana', 'hora', 'mes', 'saudacao') THEN
          v_val := COALESCE(p_attrs ->> v_token, '');
          v_msg := replace(v_msg, '<' || v_token || '>', v_val);
        END IF;
      END LOOP;
    END IF;
    RETURN v_msg;
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.create_disparo_email(p_payload jsonb)
  RETURNS bigint
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $function$
  DECLARE
    v_conta_id uuid := (p_payload ->> 'userId')::uuid;
    v_nome_disparo text := NULLIF(COALESCE(p_payload->>'nomeCampanha', p_payload->>'nomeDisparo', ''), '');
    v_remetente_id bigint := NULLIF(COALESCE(p_payload->>'remetenteId', ''), '')::bigint;
    v_assunto text := NULLIF(trim(COALESCE(p_payload->'mensagens'->0->>'assunto', p_payload->>'assunto', '')), '');
    v_html text := NULLIF(trim(COALESCE(p_payload->'mensagens'->0->>'html', p_payload->>'html', '')), '');
    v_etiqueta_ids bigint[] := COALESCE(
      ARRAY(SELECT (x)::bigint FROM jsonb_array_elements_text(COALESCE(p_payload->'idLista', p_payload->'idEtiqueta', '[]'::jsonb)) x),
      array[]::bigint[]
    );
    v_stage_ids bigint[] := COALESCE(
      ARRAY(
        SELECT DISTINCT (f->>'stageId')::bigint
        FROM jsonb_array_elements(COALESCE(p_payload->'settings'->'crmFilters', '[]'::jsonb)) f
        WHERE (f->>'stageId') ~ '^\d+$'
      ),
      ARRAY(
        SELECT DISTINCT (x)::bigint
        FROM jsonb_array_elements_text(COALESCE(p_payload->'settings'->'crmStageIds', '[]'::jsonb)) x
        WHERE x ~ '^\d+$'
      ),
      array[]::bigint[]
    );
    v_schedule_base timestamptz := COALESCE(
      (p_payload #>> '{settings,scheduleData}')::timestamptz,
      now() + interval '2 minutes'
    );
    v_disparo_id bigint;
    v_total int := 0;
    v_first_ts timestamptz;
    v_remetente record;
    v_libera_email boolean := false;
    v_limit_plan bigint;
    v_used_month bigint;
    v_to_send bigint;
    v_total_after bigint;
    v_month_start timestamptz := (date_trunc('month', now() AT TIME ZONE 'America/Sao_Paulo') AT TIME ZONE 'America/Sao_Paulo');
    v_next_month timestamptz := ((date_trunc('month', now() AT TIME ZONE 'America/Sao_Paulo') + interval '1 month') AT TIME ZONE 'America/Sao_Paulo');
    rec_cont record;
    v_assunto_ok text;
    v_html_ok text;
    v_messages jsonb[];
  BEGIN
    IF v_conta_id IS NULL THEN
      RAISE EXCEPTION 'userId é obrigatório' USING ERRCODE = 'P0001';
    END IF;
    IF NOT (public.can_access_conta(v_conta_id) OR public.is_super_admin()) THEN
      RAISE EXCEPTION 'sem permissão para esta conta' USING ERRCODE = 'P0001';
    END IF;
    IF v_remetente_id IS NULL THEN
      RAISE EXCEPTION 'remetenteId é obrigatório' USING ERRCODE = 'P0001';
    END IF;
    IF v_assunto IS NULL THEN
      RAISE EXCEPTION 'assunto é obrigatório' USING ERRCODE = 'P0001';
    END IF;
    IF v_html IS NULL THEN
      RAISE EXCEPTION 'html é obrigatório' USING ERRCODE = 'P0001';
    END IF;

    SELECT COALESCE(p."liberarEmail", false) INTO v_libera_email
    FROM public."SAAS_Contas" conta
    LEFT JOIN public."SAAS_Planos" p ON p.id = conta.plano
    WHERE conta.id = v_conta_id;
    IF v_libera_email IS NOT TRUE THEN
      RAISE EXCEPTION 'Plano sem disparo de e-mail' USING ERRCODE = 'P0001';
    END IF;

    SELECT r.* INTO v_remetente
    FROM public."SAAS_RemetentesEmails" r
    WHERE r.id = v_remetente_id
      AND r."contaId" = v_conta_id
      AND NULLIF(btrim(COALESCE(r.smtp_host, '')), '') IS NOT NULL
      AND NULLIF(btrim(COALESCE(r.smtp_user, '')), '') IS NOT NULL
      AND NULLIF(btrim(COALESCE(r.smtp_email, '')), '') IS NOT NULL
      AND NULLIF(btrim(COALESCE(r.smtp_apikey, '')), '') IS NOT NULL;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Remetente SMTP inválido ou incompleto para esta conta' USING ERRCODE = 'P0001';
    END IF;

    WITH etiqueta_contatos AS (
      SELECT DISTINCT c.id, c.email
      FROM public."SAAS_Contatos" c
      JOIN public."SAAS_Contatos_Etiquetas" ce ON ce."contatoId" = c.id
      WHERE c."contaId" = v_conta_id
        AND c.tipo = 'contato'
        AND c.email IS NOT NULL
        AND btrim(c.email) <> ''
        AND ce."etiquetaId" = ANY(v_etiqueta_ids)
    ),
    crm_contatos AS (
      SELECT DISTINCT c.id, c.email
      FROM public."SAAS_Contatos" c
      JOIN public."SAAS_Cards_Quadros" cq ON cq."contatoId" = c.id
      WHERE c."contaId" = v_conta_id
        AND c.tipo = 'contato'
        AND c.email IS NOT NULL
        AND btrim(c.email) <> ''
        AND cq."etapaQuadroId" = ANY(v_stage_ids)
    ),
    all_contatos AS (
      SELECT DISTINCT c.id, c.email
      FROM public."SAAS_Contatos" c
      WHERE c."contaId" = v_conta_id
        AND c.tipo = 'contato'
        AND c.email IS NOT NULL
        AND btrim(c.email) <> ''
        AND COALESCE(cardinality(v_etiqueta_ids), 0) = 0
        AND COALESCE(cardinality(v_stage_ids), 0) = 0
    ),
    base AS (
      SELECT id, email FROM etiqueta_contatos
      UNION
      SELECT id, email FROM crm_contatos
      UNION
      SELECT id, email FROM all_contatos
    )
    SELECT COALESCE(COUNT(DISTINCT lower(btrim(email))), 0)::bigint INTO v_to_send FROM base;

    IF v_to_send = 0 THEN
      RAISE EXCEPTION 'Nenhum contato com e-mail elegível para o disparo' USING ERRCODE = 'P0001';
    END IF;

    SELECT p."qntDisparos"::bigint INTO v_limit_plan
    FROM public."SAAS_Contas" conta
    LEFT JOIN public."SAAS_Planos" p ON p.id = conta.plano
    WHERE conta.id = v_conta_id;

    IF v_limit_plan IS NOT NULL THEN
      SELECT COALESCE(COUNT(*), 0)::bigint INTO v_used_month
      FROM public."SAAS_Detalhes_Disparos" d
      JOIN public."SAAS_Disparos" h ON h.id = d."idDisparo"
      WHERE h."contaId" = v_conta_id
        AND d."dataEnvio" >= v_month_start
        AND d."dataEnvio" < v_next_month;

      v_total_after := v_used_month + v_to_send;
      IF v_total_after > v_limit_plan THEN
        RAISE EXCEPTION 'limite atingido: % usados + % a enviar = %, limite = %', v_used_month, v_to_send, v_total_after, v_limit_plan
          USING ERRCODE = 'P0001';
      END IF;
    END IF;

    v_messages := ARRAY[
      jsonb_build_object(
        'tipo', 'email',
        'assunto', v_assunto,
        'html', v_html,
        'remetenteId', v_remetente_id
      )
    ];

    INSERT INTO public."SAAS_Disparos" (
      "NomeDisparo", "Mensagens", "TipoDisparo", "TotalDisparos", "MensagensDisparadas",
      "StatusDisparo", "contaId", "idEtiquetas", "idConexoes", "DataAgendamento", "mostrarMensagem"
    ) VALUES (
      v_nome_disparo, v_messages, 'Email', 0, 0, 'Aguardando', v_conta_id,
      v_etiqueta_ids, NULL,
      CASE WHEN p_payload #>> '{settings,scheduleData}' IS NOT NULL THEN v_schedule_base ELSE NULL END,
      false
    )
    RETURNING id INTO v_disparo_id;

    FOR rec_cont IN
      WITH etiqueta_contatos AS (
        SELECT DISTINCT c.id, c.email, c.nome, c.telefone, COALESCE(c.variaveis, '{}'::jsonb) AS base_variaveis
        FROM public."SAAS_Contatos" c
        JOIN public."SAAS_Contatos_Etiquetas" ce ON ce."contatoId" = c.id
        WHERE c."contaId" = v_conta_id
          AND c.tipo = 'contato'
          AND c.email IS NOT NULL
          AND btrim(c.email) <> ''
          AND ce."etiquetaId" = ANY(v_etiqueta_ids)
      ),
      crm_contatos AS (
        SELECT DISTINCT c.id, c.email, c.nome, c.telefone, COALESCE(c.variaveis, '{}'::jsonb) AS base_variaveis
        FROM public."SAAS_Contatos" c
        JOIN public."SAAS_Cards_Quadros" cq ON cq."contatoId" = c.id
        WHERE c."contaId" = v_conta_id
          AND c.tipo = 'contato'
          AND c.email IS NOT NULL
          AND btrim(c.email) <> ''
          AND cq."etapaQuadroId" = ANY(v_stage_ids)
      ),
      all_contatos AS (
        SELECT DISTINCT c.id, c.email, c.nome, c.telefone, COALESCE(c.variaveis, '{}'::jsonb) AS base_variaveis
        FROM public."SAAS_Contatos" c
        WHERE c."contaId" = v_conta_id
          AND c.tipo = 'contato'
          AND c.email IS NOT NULL
          AND btrim(c.email) <> ''
          AND COALESCE(cardinality(v_etiqueta_ids), 0) = 0
          AND COALESCE(cardinality(v_stage_ids), 0) = 0
      ),
      base AS (
        SELECT * FROM etiqueta_contatos
        UNION
        SELECT * FROM crm_contatos
        UNION
        SELECT * FROM all_contatos
      ),
      contato_custom_fields AS (
        SELECT
          b.id AS contato_id,
          COALESCE(
            jsonb_object_agg(
              lower(regexp_replace(cp."nome", '\s+', '_', 'g')),
              COALESCE(vcp."valor", '')
            ) FILTER (WHERE cp.id IS NOT NULL),
            '{}'::jsonb
          ) AS custom_variaveis
        FROM base b
        LEFT JOIN public."SAAS_Valores_Campos_Personalizados" vcp ON vcp."idContato" = b.id AND vcp."contaId" = v_conta_id
        LEFT JOIN public."SAAS_Campos_Personalizados" cp ON cp.id = vcp."idCampo" AND cp."contaId" = v_conta_id
        GROUP BY b.id
      )
      SELECT DISTINCT ON (lower(btrim(b.email)))
        b.id,
        b.email,
        b.nome,
        b.telefone,
        (COALESCE(b.base_variaveis, '{}'::jsonb) || COALESCE(ccf.custom_variaveis, '{}'::jsonb) || jsonb_build_object(
          'nome', COALESCE(b.nome, ''),
          'email', b.email,
          'telefone', COALESCE(b.telefone, '')
        )) AS variaveis
      FROM base b
      LEFT JOIN contato_custom_fields ccf ON ccf.contato_id = b.id
      ORDER BY lower(btrim(b.email)), b.id
    LOOP
      v_assunto_ok := public.f_render_variaveis_email(v_assunto, rec_cont.nome, rec_cont.email, rec_cont.variaveis, v_schedule_base);
      v_html_ok := public.f_render_variaveis_email(v_html, rec_cont.nome, rec_cont.email, rec_cont.variaveis, v_schedule_base);

      INSERT INTO public."SAAS_Detalhes_Disparos" (
        "idDisparo", "idContato", "Mensagem", "idConexao", "dataEnvio", "Status", "Payload"
      ) VALUES (
        v_disparo_id,
        rec_cont.id,
        v_html_ok,
        NULL,
        v_schedule_base,
        'pending',
        jsonb_build_object(
          'tipo', 'email',
          'assunto', v_assunto_ok,
          'html', v_html_ok,
          'email', rec_cont.email,
          'remetenteId', v_remetente_id
        )
      );

      IF v_total = 0 THEN
        v_first_ts := v_schedule_base;
      END IF;
      v_total := v_total + 1;
    END LOOP;

    UPDATE public."SAAS_Disparos"
    SET "TotalDisparos" = v_total,
        "StatusDisparo" = CASE WHEN v_first_ts > now() THEN 'Aguardando' ELSE 'Em andamento' END
    WHERE id = v_disparo_id;

    RETURN v_disparo_id;
  END;
  $function$;

  GRANT EXECUTE ON FUNCTION public.f_render_variaveis_email(text, text, text, jsonb, timestamptz) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.create_disparo_email(jsonb) TO authenticated;

  -- =========================
  -- Setores (equipe) + visibilidade de conversas por setor/atendente
  -- =========================
  CREATE TABLE IF NOT EXISTS public."SAAS_Setores" (
    id BIGSERIAL PRIMARY KEY,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    nome TEXT NOT NULL,
    cor TEXT,
    "contaId" UUID NOT NULL REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE
  );
  CREATE INDEX IF NOT EXISTS saas_setores_conta_idx ON public."SAAS_Setores"("contaId");

  CREATE TABLE IF NOT EXISTS public."SAAS_Setores_Usuarios" (
    id BIGSERIAL PRIMARY KEY,
    "setorId" BIGINT NOT NULL REFERENCES public."SAAS_Setores"(id) ON UPDATE CASCADE ON DELETE CASCADE,
    "usuarioId" UUID NOT NULL REFERENCES public."SAAS_Usuarios"(id) ON UPDATE CASCADE ON DELETE CASCADE,
    "contaId" UUID NOT NULL REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE,
    UNIQUE ("setorId", "usuarioId")
  );
  CREATE INDEX IF NOT EXISTS saas_setores_usuarios_setor_idx ON public."SAAS_Setores_Usuarios"("setorId");
  CREATE INDEX IF NOT EXISTS saas_setores_usuarios_usuario_idx ON public."SAAS_Setores_Usuarios"("usuarioId");
  CREATE INDEX IF NOT EXISTS saas_setores_usuarios_conta_idx ON public."SAAS_Setores_Usuarios"("contaId");

  CREATE TABLE IF NOT EXISTS public."SAAS_Setores_Gerentes" (
    id BIGSERIAL PRIMARY KEY,
    "setorId" BIGINT NOT NULL REFERENCES public."SAAS_Setores"(id) ON UPDATE CASCADE ON DELETE CASCADE,
    "usuarioId" UUID NOT NULL REFERENCES public."SAAS_Usuarios"(id) ON UPDATE CASCADE ON DELETE CASCADE,
    "contaId" UUID NOT NULL REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE,
    UNIQUE ("setorId", "usuarioId")
  );
  CREATE INDEX IF NOT EXISTS saas_setores_gerentes_setor_idx ON public."SAAS_Setores_Gerentes"("setorId");
  CREATE INDEX IF NOT EXISTS saas_setores_gerentes_usuario_idx ON public."SAAS_Setores_Gerentes"("usuarioId");
  CREATE INDEX IF NOT EXISTS saas_setores_gerentes_conta_idx ON public."SAAS_Setores_Gerentes"("contaId");

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Conversas_Agentes"') IS NOT NULL
      AND to_regclass('public."SAAS_Setores"') IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'SAAS_Conversas_Agentes' AND column_name = 'setorId'
      ) THEN
      ALTER TABLE public."SAAS_Conversas_Agentes"
        ADD COLUMN "setorId" BIGINT DEFAULT NULL REFERENCES public."SAAS_Setores"(id) ON UPDATE CASCADE ON DELETE SET NULL;
      CREATE INDEX IF NOT EXISTS saas_conversas_agentes_setor_idx ON public."SAAS_Conversas_Agentes"("setorId");
    END IF;
  END$$;

  CREATE OR REPLACE FUNCTION public.usuario_pertence_setor(p_setor_id bigint)
  RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
    SELECT p_setor_id IS NOT NULL AND EXISTS (
      SELECT 1
      FROM public."SAAS_Setores_Usuarios" su
      JOIN public."SAAS_Usuarios" u ON u.id = su."usuarioId"
      WHERE su."setorId" = p_setor_id AND u.auth_user_id = auth.uid()
    );
  $$;

  CREATE OR REPLACE FUNCTION public.usuario_gerencia_setor(p_setor_id bigint)
  RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
    SELECT p_setor_id IS NOT NULL AND EXISTS (
      SELECT 1
      FROM public."SAAS_Setores_Gerentes" sg
      JOIN public."SAAS_Usuarios" u ON u.id = sg."usuarioId"
      WHERE sg."setorId" = p_setor_id AND u.auth_user_id = auth.uid()
    );
  $$;

  CREATE OR REPLACE FUNCTION public.usuario_gerencia_atendente(p_atendente uuid)
  RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
    SELECT p_atendente IS NOT NULL AND EXISTS (
      SELECT 1
      FROM public."SAAS_Setores_Gerentes" sg
      JOIN public."SAAS_Usuarios" u ON u.id = sg."usuarioId"
      JOIN public."SAAS_Setores_Usuarios" su ON su."setorId" = sg."setorId"
      WHERE u.auth_user_id = auth.uid()
        AND su."usuarioId" = p_atendente
    );
  $$;

  CREATE OR REPLACE FUNCTION public.can_see_conversa(p_conta_id uuid, p_atendente uuid, p_setor_id bigint)
  RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
    SELECT public.is_admin(p_conta_id)
      OR (
        p_atendente IS NOT NULL
        AND EXISTS (
          SELECT 1 FROM public."SAAS_Usuarios" u
          WHERE u.auth_user_id = auth.uid() AND u.id = p_atendente
        )
      )
      OR (
        p_atendente IS NULL
        AND p_setor_id IS NOT NULL
        AND public.usuario_pertence_setor(p_setor_id)
      )
      OR public.usuario_gerencia_setor(p_setor_id)
      OR public.usuario_gerencia_atendente(p_atendente)
      OR (
        p_atendente IS NULL
        AND p_setor_id IS NULL
        AND public.can_access_conta(p_conta_id)
      );
  $$;

  CREATE OR REPLACE FUNCTION public.can_see_mensagem(p_conta_id uuid, p_conversa_id bigint, p_conexao_id bigint)
  RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
  DECLARE
    v_conv_conta_id uuid;
    v_conv_atendente uuid;
    v_conv_setor_id bigint;
  BEGIN
    SELECT c."contaId", c.atendente, c."setorId"
      INTO v_conv_conta_id, v_conv_atendente, v_conv_setor_id
      FROM public."SAAS_Conversas_Agentes" c
    WHERE c.id = p_conversa_id;

    IF v_conv_conta_id IS NULL THEN
      RETURN false;
    END IF;

    IF public.can_see_conversa(v_conv_conta_id, v_conv_atendente, v_conv_setor_id) THEN
      RETURN true;
    END IF;

    IF p_conexao_id IS NOT NULL
      AND public.can_access_conta(p_conta_id)
      AND EXISTS (
        SELECT 1
          FROM public."SAAS_Conexões" co
          WHERE co.id = p_conexao_id
            AND co."contaId" = p_conta_id
      ) THEN
      RETURN true;
    END IF;

    RETURN false;
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_transferir_setor_conversa(
    p_conversa_id bigint,
    p_novo_setor_id bigint
  )
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
  DECLARE
    v_conta uuid;
    v_atendente uuid;
    v_setor bigint;
  BEGIN
    IF p_conversa_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'conversa_id obrigatório');
    END IF;

    SELECT c."contaId", c.atendente, c."setorId"
      INTO v_conta, v_atendente, v_setor
      FROM public."SAAS_Conversas_Agentes" c
    WHERE c.id = p_conversa_id
    FOR UPDATE;

    IF v_conta IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Conversa não encontrada');
    END IF;

    IF NOT (
      public.is_admin(v_conta)
      OR (
        v_atendente IS NOT NULL
        AND EXISTS (
          SELECT 1 FROM public."SAAS_Usuarios" u
          WHERE u.id = v_atendente AND u.auth_user_id = auth.uid()
        )
      )
      OR (
        v_atendente IS NULL
        AND v_setor IS NOT NULL
        AND public.usuario_pertence_setor(v_setor)
      )
    ) THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Sem permissão para transferir setor desta conversa');
    END IF;

    IF p_novo_setor_id IS NULL THEN
      IF NOT public.is_admin(v_conta) THEN
        RETURN jsonb_build_object('ok', false, 'erro', 'Apenas administradores podem remover o setor');
      END IF;
    ELSE
      IF NOT EXISTS (
        SELECT 1 FROM public."SAAS_Setores" s
        WHERE s.id = p_novo_setor_id AND s."contaId" = v_conta
      ) THEN
        RETURN jsonb_build_object('ok', false, 'erro', 'Setor não pertence a esta conta');
      END IF;
    END IF;

    UPDATE public."SAAS_Conversas_Agentes"
    SET "setorId" = p_novo_setor_id,
        atendente = NULL
    WHERE id = p_conversa_id;

    RETURN jsonb_build_object('ok', true);
  END;
  $$;

  GRANT EXECUTE ON FUNCTION public.usuario_pertence_setor(bigint) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.usuario_gerencia_setor(bigint) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.usuario_gerencia_atendente(uuid) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.f_transferir_setor_conversa(bigint, bigint) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.f_transferir_setor_conversa(bigint, bigint) TO service_role;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Setores"') IS NOT NULL THEN
      ALTER TABLE public."SAAS_Setores" ENABLE ROW LEVEL SECURITY;
      DROP POLICY IF EXISTS "select_setores" ON public."SAAS_Setores";
      DROP POLICY IF EXISTS "insert_setores" ON public."SAAS_Setores";
      DROP POLICY IF EXISTS "update_setores" ON public."SAAS_Setores";
      DROP POLICY IF EXISTS "delete_setores_admin" ON public."SAAS_Setores";
      CREATE POLICY "select_setores" ON public."SAAS_Setores" FOR SELECT TO authenticated
        USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
      CREATE POLICY "insert_setores" ON public."SAAS_Setores" FOR INSERT TO authenticated
        WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
      CREATE POLICY "update_setores" ON public."SAAS_Setores" FOR UPDATE TO authenticated
        USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()))
        WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
      CREATE POLICY "delete_setores_admin" ON public."SAAS_Setores" FOR DELETE TO authenticated
        USING ("contaId" IN (SELECT public.rls_conta_ids_admin()) OR (SELECT public.rls_eh_super_admin()));
      GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_Setores" TO authenticated;
    END IF;

    IF to_regclass('public."SAAS_Setores_Usuarios"') IS NOT NULL THEN
      ALTER TABLE public."SAAS_Setores_Usuarios" ENABLE ROW LEVEL SECURITY;
      DROP POLICY IF EXISTS "select_setores_usuarios" ON public."SAAS_Setores_Usuarios";
      DROP POLICY IF EXISTS "insert_setores_usuarios" ON public."SAAS_Setores_Usuarios";
      DROP POLICY IF EXISTS "update_setores_usuarios" ON public."SAAS_Setores_Usuarios";
      DROP POLICY IF EXISTS "delete_setores_usuarios" ON public."SAAS_Setores_Usuarios";
      CREATE POLICY "select_setores_usuarios" ON public."SAAS_Setores_Usuarios" FOR SELECT TO authenticated
        USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
      CREATE POLICY "insert_setores_usuarios" ON public."SAAS_Setores_Usuarios" FOR INSERT TO authenticated
        WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
      CREATE POLICY "update_setores_usuarios" ON public."SAAS_Setores_Usuarios" FOR UPDATE TO authenticated
        USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()))
        WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
      CREATE POLICY "delete_setores_usuarios" ON public."SAAS_Setores_Usuarios" FOR DELETE TO authenticated
        USING ("contaId" IN (SELECT public.rls_conta_ids_admin()) OR (SELECT public.rls_eh_super_admin()));
      GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_Setores_Usuarios" TO authenticated;
    END IF;

    IF to_regclass('public."SAAS_Setores_Gerentes"') IS NOT NULL THEN
      ALTER TABLE public."SAAS_Setores_Gerentes" ENABLE ROW LEVEL SECURITY;
      DROP POLICY IF EXISTS "select_setores_gerentes" ON public."SAAS_Setores_Gerentes";
      DROP POLICY IF EXISTS "insert_setores_gerentes" ON public."SAAS_Setores_Gerentes";
      DROP POLICY IF EXISTS "update_setores_gerentes" ON public."SAAS_Setores_Gerentes";
      DROP POLICY IF EXISTS "delete_setores_gerentes" ON public."SAAS_Setores_Gerentes";
      CREATE POLICY "select_setores_gerentes" ON public."SAAS_Setores_Gerentes" FOR SELECT TO authenticated
        USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
      CREATE POLICY "insert_setores_gerentes" ON public."SAAS_Setores_Gerentes" FOR INSERT TO authenticated
        WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
      CREATE POLICY "update_setores_gerentes" ON public."SAAS_Setores_Gerentes" FOR UPDATE TO authenticated
        USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()))
        WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
      CREATE POLICY "delete_setores_gerentes" ON public."SAAS_Setores_Gerentes" FOR DELETE TO authenticated
        USING ("contaId" IN (SELECT public.rls_conta_ids_admin()) OR (SELECT public.rls_eh_super_admin()));
      GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_Setores_Gerentes" TO authenticated;
      IF pg_get_serial_sequence('public."SAAS_Setores_Gerentes"', 'id') IS NOT NULL THEN
        EXECUTE format(
          'GRANT USAGE, SELECT ON SEQUENCE %s TO authenticated',
          pg_get_serial_sequence('public."SAAS_Setores_Gerentes"', 'id')
        );
      END IF;
    END IF;

    IF to_regclass('public."SAAS_Conversas_Agentes"') IS NULL THEN RETURN; END IF;
    ALTER TABLE public."SAAS_Conversas_Agentes" ENABLE ROW LEVEL SECURITY;
    DROP POLICY IF EXISTS "select_conversas" ON public."SAAS_Conversas_Agentes";
    DROP POLICY IF EXISTS "update_conversas" ON public."SAAS_Conversas_Agentes";
    -- RLS set-based: mesma regra de can_see_conversa (admin, atendente, setor sem dono, gerente de setor, gerente do atendente, membro em fila livre).
    CREATE POLICY "select_conversas" ON public."SAAS_Conversas_Agentes" FOR SELECT TO authenticated
      USING (
        "contaId" IN (
          SELECT u."contaId" FROM public."SAAS_Usuarios" u
          WHERE u.auth_user_id = (SELECT auth.uid()) AND u.funcao = 'admin'
        )
        OR atendente IN (
          SELECT u.id FROM public."SAAS_Usuarios" u
          WHERE u.auth_user_id = (SELECT auth.uid())
        )
        OR (
          atendente IS NULL
          AND "setorId" IN (
            SELECT su."setorId" FROM public."SAAS_Setores_Usuarios" su
            JOIN public."SAAS_Usuarios" u ON u.id = su."usuarioId"
            WHERE u.auth_user_id = (SELECT auth.uid())
          )
        )
        OR "setorId" IN (
          SELECT sg."setorId" FROM public."SAAS_Setores_Gerentes" sg
          JOIN public."SAAS_Usuarios" u ON u.id = sg."usuarioId"
          WHERE u.auth_user_id = (SELECT auth.uid())
        )
        OR atendente IN (
          SELECT su."usuarioId" FROM public."SAAS_Setores_Usuarios" su
          JOIN public."SAAS_Setores_Gerentes" sg ON sg."setorId" = su."setorId"
          JOIN public."SAAS_Usuarios" u ON u.id = sg."usuarioId"
          WHERE u.auth_user_id = (SELECT auth.uid())
        )
        OR (
          atendente IS NULL
          AND "setorId" IS NULL
          AND "contaId" IN (
            SELECT u."contaId" FROM public."SAAS_Usuarios" u
            WHERE u.auth_user_id = (SELECT auth.uid())
          )
        )
      );
    CREATE POLICY "update_conversas" ON public."SAAS_Conversas_Agentes" FOR UPDATE TO authenticated
      USING (
        "contaId" IN (
          SELECT u."contaId" FROM public."SAAS_Usuarios" u
          WHERE u.auth_user_id = (SELECT auth.uid()) AND u.funcao = 'admin'
        )
        OR atendente IN (
          SELECT u.id FROM public."SAAS_Usuarios" u
          WHERE u.auth_user_id = (SELECT auth.uid())
        )
        OR (
          atendente IS NULL
          AND "setorId" IN (
            SELECT su."setorId" FROM public."SAAS_Setores_Usuarios" su
            JOIN public."SAAS_Usuarios" u ON u.id = su."usuarioId"
            WHERE u.auth_user_id = (SELECT auth.uid())
          )
        )
        OR "setorId" IN (
          SELECT sg."setorId" FROM public."SAAS_Setores_Gerentes" sg
          JOIN public."SAAS_Usuarios" u ON u.id = sg."usuarioId"
          WHERE u.auth_user_id = (SELECT auth.uid())
        )
        OR atendente IN (
          SELECT su."usuarioId" FROM public."SAAS_Setores_Usuarios" su
          JOIN public."SAAS_Setores_Gerentes" sg ON sg."setorId" = su."setorId"
          JOIN public."SAAS_Usuarios" u ON u.id = sg."usuarioId"
          WHERE u.auth_user_id = (SELECT auth.uid())
        )
        OR (
          atendente IS NULL
          AND "setorId" IS NULL
          AND "contaId" IN (
            SELECT u."contaId" FROM public."SAAS_Usuarios" u
            WHERE u.auth_user_id = (SELECT auth.uid())
          )
        )
      )
      WITH CHECK (
        "contaId" IN (
          SELECT u."contaId" FROM public."SAAS_Usuarios" u
          WHERE u.auth_user_id = (SELECT auth.uid()) AND u.funcao = 'admin'
        )
        OR atendente IN (
          SELECT u.id FROM public."SAAS_Usuarios" u
          WHERE u.auth_user_id = (SELECT auth.uid())
        )
        OR (
          atendente IS NULL
          AND "setorId" IN (
            SELECT su."setorId" FROM public."SAAS_Setores_Usuarios" su
            JOIN public."SAAS_Usuarios" u ON u.id = su."usuarioId"
            WHERE u.auth_user_id = (SELECT auth.uid())
          )
        )
        OR "setorId" IN (
          SELECT sg."setorId" FROM public."SAAS_Setores_Gerentes" sg
          JOIN public."SAAS_Usuarios" u ON u.id = sg."usuarioId"
          WHERE u.auth_user_id = (SELECT auth.uid())
        )
        OR atendente IN (
          SELECT su."usuarioId" FROM public."SAAS_Setores_Usuarios" su
          JOIN public."SAAS_Setores_Gerentes" sg ON sg."setorId" = su."setorId"
          JOIN public."SAAS_Usuarios" u ON u.id = sg."usuarioId"
          WHERE u.auth_user_id = (SELECT auth.uid())
        )
        OR (
          atendente IS NULL
          AND "setorId" IS NULL
          AND "contaId" IN (
            SELECT u."contaId" FROM public."SAAS_Usuarios" u
            WHERE u.auth_user_id = (SELECT auth.uid())
          )
        )
      );

    IF to_regclass('public."SAAS_Mensagens"') IS NOT NULL THEN
      DROP POLICY IF EXISTS "select_mensagens" ON public."SAAS_Mensagens";
      DROP POLICY IF EXISTS "update_mensagens" ON public."SAAS_Mensagens";
      CREATE POLICY "select_mensagens" ON public."SAAS_Mensagens" FOR SELECT TO authenticated
        USING (EXISTS (
          SELECT 1 FROM public."SAAS_Conversas_Agentes" c
          WHERE c.id = "SAAS_Mensagens"."conversaId"
            AND (
              c."contaId" IN (
                SELECT u."contaId" FROM public."SAAS_Usuarios" u
                WHERE u.auth_user_id = (SELECT auth.uid()) AND u.funcao = 'admin'
              )
              OR c.atendente IN (
                SELECT u.id FROM public."SAAS_Usuarios" u
                WHERE u.auth_user_id = (SELECT auth.uid())
              )
              OR (
                c.atendente IS NULL
                AND c."setorId" IN (
                  SELECT su."setorId" FROM public."SAAS_Setores_Usuarios" su
                  JOIN public."SAAS_Usuarios" u ON u.id = su."usuarioId"
                  WHERE u.auth_user_id = (SELECT auth.uid())
                )
              )
              OR c."setorId" IN (
                SELECT sg."setorId" FROM public."SAAS_Setores_Gerentes" sg
                JOIN public."SAAS_Usuarios" u ON u.id = sg."usuarioId"
                WHERE u.auth_user_id = (SELECT auth.uid())
              )
              OR c.atendente IN (
                SELECT su."usuarioId" FROM public."SAAS_Setores_Usuarios" su
                JOIN public."SAAS_Setores_Gerentes" sg ON sg."setorId" = su."setorId"
                JOIN public."SAAS_Usuarios" u ON u.id = sg."usuarioId"
                WHERE u.auth_user_id = (SELECT auth.uid())
              )
              OR (
                c.atendente IS NULL
                AND c."setorId" IS NULL
                AND c."contaId" IN (
                  SELECT u."contaId" FROM public."SAAS_Usuarios" u
                  WHERE u.auth_user_id = (SELECT auth.uid())
                )
              )
            )
        ));
      CREATE POLICY "update_mensagens" ON public."SAAS_Mensagens" FOR UPDATE TO authenticated
        USING (EXISTS (
          SELECT 1 FROM public."SAAS_Conversas_Agentes" c
          WHERE c.id = "SAAS_Mensagens"."conversaId"
            AND (
              c."contaId" IN (
                SELECT u."contaId" FROM public."SAAS_Usuarios" u
                WHERE u.auth_user_id = (SELECT auth.uid()) AND u.funcao = 'admin'
              )
              OR c.atendente IN (
                SELECT u.id FROM public."SAAS_Usuarios" u
                WHERE u.auth_user_id = (SELECT auth.uid())
              )
              OR (
                c.atendente IS NULL
                AND c."setorId" IN (
                  SELECT su."setorId" FROM public."SAAS_Setores_Usuarios" su
                  JOIN public."SAAS_Usuarios" u ON u.id = su."usuarioId"
                  WHERE u.auth_user_id = (SELECT auth.uid())
                )
              )
              OR c."setorId" IN (
                SELECT sg."setorId" FROM public."SAAS_Setores_Gerentes" sg
                JOIN public."SAAS_Usuarios" u ON u.id = sg."usuarioId"
                WHERE u.auth_user_id = (SELECT auth.uid())
              )
              OR c.atendente IN (
                SELECT su."usuarioId" FROM public."SAAS_Setores_Usuarios" su
                JOIN public."SAAS_Setores_Gerentes" sg ON sg."setorId" = su."setorId"
                JOIN public."SAAS_Usuarios" u ON u.id = sg."usuarioId"
                WHERE u.auth_user_id = (SELECT auth.uid())
              )
              OR (
                c.atendente IS NULL
                AND c."setorId" IS NULL
                AND c."contaId" IN (
                  SELECT u."contaId" FROM public."SAAS_Usuarios" u
                  WHERE u.auth_user_id = (SELECT auth.uid())
                )
              )
            )
        ));
    END IF;
  END$$;

  -- Coluna produtos em SAAS_AgentesIA + RLS conhecimentos vinculados a produtos
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_AgentesIA"') IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'SAAS_AgentesIA' AND column_name = 'produtos'
      ) THEN
      ALTER TABLE public."SAAS_AgentesIA" ADD COLUMN produtos JSONB DEFAULT '[]'::jsonb;
    END IF;

    IF to_regclass('public."SAAS_Conhecimentos"') IS NOT NULL
      AND to_regclass('public."SAAS_AgentesIA"') IS NOT NULL THEN
      DROP POLICY IF EXISTS delete_knowledge_linked_to_own_agents ON public."SAAS_Conhecimentos";
      CREATE POLICY delete_knowledge_linked_to_own_agents
      ON public."SAAS_Conhecimentos"
      FOR DELETE
      TO authenticated
      USING (
        EXISTS (
          SELECT 1
          FROM public."SAAS_AgentesIA" a
          WHERE a."contaId" = ((current_setting('request.jwt.claims', true)::jsonb->>'contaId')::uuid)
            AND (
              EXISTS (
                SELECT 1
                FROM jsonb_array_elements(COALESCE(a.conhecimento, '[]'::jsonb)) AS c(elem)
                WHERE c.elem->>'idUnico' = metadata->>'idUnico'
              )
              OR EXISTS (
                SELECT 1
                FROM jsonb_array_elements(COALESCE(a.produtos, '[]'::jsonb)) AS pr(elem)
                WHERE pr.elem->>'idUnico' = metadata->>'idUnico'
              )
            )
        )
      );
    END IF;
  END$$;

  -- =========================
  -- Ativação / roteamento multi-agentes
  -- =========================
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Contas"') IS NOT NULL
      AND to_regclass('public."SAAS_AgentesIA"') IS NOT NULL THEN
      IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'SAAS_Contas' AND column_name = 'idAgentePadrao'
      ) THEN
        ALTER TABLE public."SAAS_Contas" ADD COLUMN "idAgentePadrao" BIGINT;
      END IF;
      IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Contas_idAgentePadrao_fkey') THEN
        ALTER TABLE public."SAAS_Contas"
          ADD CONSTRAINT "SAAS_Contas_idAgentePadrao_fkey"
          FOREIGN KEY ("idAgentePadrao") REFERENCES public."SAAS_AgentesIA"(id) ON UPDATE CASCADE ON DELETE SET NULL;
      END IF;
    END IF;

    IF to_regclass('public."SAAS_AgentesIA_Ativacao"') IS NULL
      AND to_regclass('public."SAAS_AgentesIA"') IS NOT NULL THEN
      CREATE TABLE public."SAAS_AgentesIA_Ativacao" (
        id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
        created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
        "contaId" UUID NOT NULL REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE,
        "idAgente" BIGINT NOT NULL REFERENCES public."SAAS_AgentesIA"(id) ON UPDATE CASCADE ON DELETE CASCADE,
        tipo TEXT NOT NULL CHECK (tipo IN (
          'palavra_chave', 'etiqueta', 'crm', 'setor', 'horario'
        )),
        prioridade INTEGER NOT NULL DEFAULT 0,
        "conexoesModo" TEXT NOT NULL DEFAULT 'todas'
          CHECK ("conexoesModo" IN ('todas', 'incluir', 'excluir')),
        "conexoesIds" JSONB NOT NULL DEFAULT '[]'::jsonb,
        condicao JSONB NOT NULL DEFAULT '{}'::jsonb,
        "apenasPrimeiraMensagem" BOOLEAN NOT NULL DEFAULT false,
        exclusivo BOOLEAN NOT NULL DEFAULT false,
        ativo BOOLEAN NOT NULL DEFAULT true
      );
      CREATE INDEX IF NOT EXISTS idx_agentes_ia_ativacao_conta ON public."SAAS_AgentesIA_Ativacao"("contaId");
      CREATE INDEX IF NOT EXISTS idx_agentes_ia_ativacao_agente ON public."SAAS_AgentesIA_Ativacao"("idAgente");
      CREATE INDEX IF NOT EXISTS idx_agentes_ia_ativacao_tipo ON public."SAAS_AgentesIA_Ativacao"(tipo, ativo);
    END IF;

    IF to_regclass('public."SAAS_AgentesIA_Ativacao"') IS NOT NULL THEN
      UPDATE public."SAAS_AgentesIA_Ativacao"
      SET "apenasPrimeiraMensagem" = false
      WHERE "apenasPrimeiraMensagem" IS DISTINCT FROM false;
      ALTER TABLE public."SAAS_AgentesIA_Ativacao"
        ALTER COLUMN "apenasPrimeiraMensagem" SET DEFAULT false;
      UPDATE public."SAAS_AgentesIA_Ativacao"
      SET tipo = 'horario'
      WHERE tipo IN ('horario_comercial', 'horario_intervalo');
      ALTER TABLE public."SAAS_AgentesIA_Ativacao"
        DROP CONSTRAINT IF EXISTS "SAAS_AgentesIA_Ativacao_tipo_check";
      ALTER TABLE public."SAAS_AgentesIA_Ativacao"
        ADD CONSTRAINT "SAAS_AgentesIA_Ativacao_tipo_check"
        CHECK (tipo IN ('palavra_chave', 'etiqueta', 'crm', 'setor', 'horario'));

      ALTER TABLE public."SAAS_AgentesIA_Ativacao" ENABLE ROW LEVEL SECURITY;
      DROP POLICY IF EXISTS "select_agentes_ia_ativacao" ON public."SAAS_AgentesIA_Ativacao";
      DROP POLICY IF EXISTS "insert_agentes_ia_ativacao" ON public."SAAS_AgentesIA_Ativacao";
      DROP POLICY IF EXISTS "update_agentes_ia_ativacao" ON public."SAAS_AgentesIA_Ativacao";
      DROP POLICY IF EXISTS "delete_agentes_ia_ativacao" ON public."SAAS_AgentesIA_Ativacao";
      CREATE POLICY "select_agentes_ia_ativacao" ON public."SAAS_AgentesIA_Ativacao"
        FOR SELECT TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
      CREATE POLICY "insert_agentes_ia_ativacao" ON public."SAAS_AgentesIA_Ativacao"
        FOR INSERT TO authenticated WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
      CREATE POLICY "update_agentes_ia_ativacao" ON public."SAAS_AgentesIA_Ativacao"
        FOR UPDATE TO authenticated
        USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()))
        WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
      CREATE POLICY "delete_agentes_ia_ativacao" ON public."SAAS_AgentesIA_Ativacao"
        FOR DELETE TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
      GRANT SELECT, INSERT, UPDATE, DELETE ON public."SAAS_AgentesIA_Ativacao" TO authenticated;
      GRANT USAGE, SELECT ON SEQUENCE public."SAAS_AgentesIA_Ativacao_id_seq" TO authenticated;
    END IF;
  END$$;

  CREATE OR REPLACE FUNCTION public.f_regra_ativacao_conexao_ok(
    p_conexoes_modo text,
    p_conexoes_ids jsonb,
    p_conexao_id bigint
  ) RETURNS boolean
  LANGUAGE plpgsql IMMUTABLE AS $$
  BEGIN
    IF COALESCE(p_conexoes_modo, 'todas') = 'todas' THEN RETURN true; END IF;
    IF p_conexao_id IS NULL THEN RETURN false; END IF;
    IF p_conexoes_modo = 'incluir' THEN
      RETURN COALESCE(p_conexoes_ids, '[]'::jsonb) @> to_jsonb(p_conexao_id);
    END IF;
    IF p_conexoes_modo = 'excluir' THEN
      RETURN NOT (COALESCE(p_conexoes_ids, '[]'::jsonb) @> to_jsonb(p_conexao_id));
    END IF;
    RETURN true;
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_regra_horario_ativacao_ok(p_condicao jsonb)
  RETURNS boolean
  LANGUAGE plpgsql STABLE AS $$
  DECLARE
    v_tz text;
    v_local timestamp;
    v_dow int;
    v_time time;
    v_inicio time;
    v_fim time;
    v_dias jsonb;
  BEGIN
    v_tz := COALESCE(NULLIF(p_condicao->>'fuso', ''), 'America/Sao_Paulo');
    v_local := (now() AT TIME ZONE v_tz)::timestamp;
    v_dow := EXTRACT(ISODOW FROM v_local)::int;
    v_time := v_local::time;
    v_dias := COALESCE(p_condicao->'diasSemana', '[1,2,3,4,5]'::jsonb);
    IF NOT (v_dias @> to_jsonb(v_dow)) THEN RETURN false; END IF;
    BEGIN
      v_inicio := NULLIF(p_condicao->>'horaInicio', '')::time;
      v_fim := NULLIF(p_condicao->>'horaFim', '')::time;
    EXCEPTION WHEN OTHERS THEN
      RETURN false;
    END;
    IF v_inicio IS NULL OR v_fim IS NULL THEN RETURN true; END IF;
    IF v_inicio <= v_fim THEN
      RETURN v_time >= v_inicio AND v_time <= v_fim;
    END IF;
    RETURN v_time >= v_inicio OR v_time <= v_fim;
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_regra_ativacao_condicao_ok(
    p_tipo text,
    p_condicao jsonb,
    p_mensagem text,
    p_contato_id bigint,
    p_setor_id bigint
  ) RETURNS boolean
  LANGUAGE plpgsql STABLE AS $$
  DECLARE
    v_palavra text;
    v_modo text;
    v_match boolean := false;
    v_todas_ok boolean := true;
    v_crm_modo text;
  BEGIN
    IF p_tipo IN ('horario', 'horario_comercial', 'horario_intervalo') THEN
      RETURN public.f_regra_horario_ativacao_ok(p_condicao);
    END IF;

    IF p_tipo = 'palavra_chave' THEN
      IF COALESCE(trim(p_mensagem), '') = '' THEN RETURN false; END IF;
      v_modo := COALESCE(p_condicao->>'modo', 'qualquer');
      FOR v_palavra IN SELECT jsonb_array_elements_text(COALESCE(p_condicao->'palavras', '[]'::jsonb))
      LOOP
        IF v_palavra IS NULL OR trim(v_palavra) = '' THEN CONTINUE; END IF;
        IF position(lower(trim(v_palavra)) IN lower(p_mensagem)) > 0 THEN
          v_match := true;
          IF v_modo = 'qualquer' THEN RETURN true; END IF;
        ELSE
          v_todas_ok := false;
        END IF;
      END LOOP;
      IF v_modo = 'todas' THEN RETURN v_todas_ok AND v_match; END IF;
      RETURN v_match;
    END IF;

    IF p_tipo = 'etiqueta' THEN
      IF p_contato_id IS NULL OR to_regclass('public."SAAS_Contatos_Etiquetas"') IS NULL THEN RETURN false; END IF;
      IF NULLIF(p_condicao->>'etiquetaId', '') IS NULL THEN RETURN false; END IF;
      v_modo := COALESCE(NULLIF(trim(p_condicao->>'modo'), ''), 'tem');
      IF v_modo IN ('nao_tem', 'sem_etiqueta', 'nao') THEN
        RETURN NOT EXISTS (
          SELECT 1 FROM public."SAAS_Contatos_Etiquetas" ce
          WHERE ce."contatoId" = p_contato_id
            AND ce."etiquetaId" = NULLIF(p_condicao->>'etiquetaId', '')::bigint
        );
      END IF;
      RETURN EXISTS (
        SELECT 1 FROM public."SAAS_Contatos_Etiquetas" ce
        WHERE ce."contatoId" = p_contato_id
          AND ce."etiquetaId" = NULLIF(p_condicao->>'etiquetaId', '')::bigint
      );
    END IF;

    IF p_tipo = 'crm' THEN
      IF p_contato_id IS NULL OR to_regclass('public."SAAS_Cards_Quadros"') IS NULL THEN RETURN false; END IF;
      v_crm_modo := COALESCE(NULLIF(trim(p_condicao->>'modo'), ''), 'na_etapa');
      -- Compat: "qualquer" / "todas" / vazio = sem filtro de etapa
      IF v_crm_modo IN ('na_etapa', 'tem_card')
         AND COALESCE(NULLIF(trim(p_condicao->>'etapaId'), ''), 'qualquer')
             IN ('qualquer', 'todas', '*', 'all') THEN
        v_crm_modo := 'tem_card';
      END IF;
      IF v_crm_modo = 'na_etapa' THEN
        RETURN EXISTS (
          SELECT 1 FROM public."SAAS_Cards_Quadros" cq
          WHERE cq."contatoId" = p_contato_id
            AND (NULLIF(trim(p_condicao->>'quadroId'), '') IS NULL
                 OR cq."quadroId" = NULLIF(trim(p_condicao->>'quadroId'), '')::bigint)
            AND cq."etapaQuadroId" = NULLIF(trim(p_condicao->>'etapaId'), '')::bigint
        );
      ELSIF v_crm_modo = 'tem_card' THEN
        RETURN EXISTS (
          SELECT 1 FROM public."SAAS_Cards_Quadros" cq
          WHERE cq."contatoId" = p_contato_id
            AND (NULLIF(trim(p_condicao->>'quadroId'), '') IS NULL
                 OR cq."quadroId" = NULLIF(trim(p_condicao->>'quadroId'), '')::bigint)
        );
      ELSIF v_crm_modo = 'sem_card' THEN
        -- Legado: regras antigas ainda validam
        RETURN NOT EXISTS (
          SELECT 1 FROM public."SAAS_Cards_Quadros" cq
          WHERE cq."contatoId" = p_contato_id
            AND (NULLIF(trim(p_condicao->>'quadroId'), '') IS NULL
                 OR cq."quadroId" = NULLIF(trim(p_condicao->>'quadroId'), '')::bigint)
        );
      END IF;
      RETURN false;
    END IF;

    IF p_tipo = 'setor' THEN
      RETURN p_setor_id IS NOT NULL
        AND p_setor_id = NULLIF(p_condicao->>'setorId', '')::bigint;
    END IF;

    RETURN false;
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_resolver_agente_ativacao(
    p_conta_id uuid,
    p_conexao_id bigint,
    p_conversa_id bigint DEFAULT NULL,
    p_mensagem text DEFAULT NULL,
    p_contato_id bigint DEFAULT NULL,
    p_setor_id bigint DEFAULT NULL,
    p_eh_primeira_mensagem boolean DEFAULT true
  ) RETURNS jsonb
  LANGUAGE plpgsql STABLE SECURITY DEFINER
  SET search_path = public
  AS $$
  DECLARE
    v_conversa record;
    v_agente_id bigint;
    v_regra record;
  BEGIN
    IF p_conta_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'contaId obrigatório');
    END IF;

    IF p_conversa_id IS NOT NULL AND to_regclass('public."SAAS_Conversas_Agentes"') IS NOT NULL THEN
      SELECT c."idAgente", c."setorId"
      INTO v_conversa
      FROM public."SAAS_Conversas_Agentes" c
      WHERE c.id = p_conversa_id AND c."contaId" = p_conta_id
      LIMIT 1;

      IF FOUND AND v_conversa."idAgente" IS NOT NULL THEN
        IF EXISTS (
          SELECT 1 FROM public."SAAS_AgentesIA" a
          WHERE a.id = v_conversa."idAgente" AND a.ativo IS NOT FALSE
        ) THEN
          RETURN jsonb_build_object(
            'ok', true, 'idAgente', v_conversa."idAgente", 'motivo', 'conversa_existente'
          );
        END IF;
      END IF;

      IF FOUND AND v_conversa."setorId" IS NOT NULL AND p_setor_id IS NULL THEN
        p_setor_id := v_conversa."setorId";
      END IF;
    END IF;

    IF to_regclass('public."SAAS_AgentesIA_Ativacao"') IS NOT NULL THEN
      FOR v_regra IN
        SELECT r.*
        FROM public."SAAS_AgentesIA_Ativacao" r
        JOIN public."SAAS_AgentesIA" a ON a.id = r."idAgente"
        WHERE r."contaId" = p_conta_id
          AND r.ativo IS TRUE
          AND a.ativo IS NOT FALSE
          AND public.f_regra_ativacao_conexao_ok(r."conexoesModo", r."conexoesIds", p_conexao_id)
          AND public.f_regra_ativacao_condicao_ok(
            r.tipo, r.condicao, p_mensagem, p_contato_id, p_setor_id
          )
        ORDER BY r.prioridade DESC, r.id ASC
      LOOP
        RETURN jsonb_build_object(
          'ok', true, 'idAgente', v_regra."idAgente",
          'motivo', 'regra_' || v_regra.tipo, 'regraId', v_regra.id
        );
      END LOOP;
    END IF;

    IF p_conexao_id IS NOT NULL AND to_regclass('public."SAAS_Conexões"') IS NOT NULL THEN
      SELECT cx."idAgente" INTO v_agente_id
      FROM public."SAAS_Conexões" cx
      JOIN public."SAAS_AgentesIA" a ON a.id = cx."idAgente"
      WHERE cx.id = p_conexao_id AND cx."contaId" = p_conta_id AND a.ativo IS NOT FALSE
      LIMIT 1;
      IF v_agente_id IS NOT NULL THEN
        RETURN jsonb_build_object('ok', true, 'idAgente', v_agente_id, 'motivo', 'padrao_conexao');
      END IF;
    END IF;

    IF to_regclass('public."SAAS_Contas"') IS NOT NULL THEN
      SELECT c."idAgentePadrao" INTO v_agente_id
      FROM public."SAAS_Contas" c
      JOIN public."SAAS_AgentesIA" a ON a.id = c."idAgentePadrao"
      WHERE c.id = p_conta_id AND a.ativo IS NOT FALSE
      LIMIT 1;
      IF v_agente_id IS NOT NULL THEN
        RETURN jsonb_build_object('ok', true, 'idAgente', v_agente_id, 'motivo', 'padrao_global');
      END IF;
    END IF;

    RETURN jsonb_build_object('ok', true, 'idAgente', NULL, 'motivo', 'nenhum');
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_salvar_agente_padrao_global(
    p_conta_id uuid,
    p_id_agente bigint DEFAULT NULL
  ) RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
  BEGIN
    IF p_conta_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'contaId obrigatório');
    END IF;

    IF NOT public.can_access_conta(p_conta_id) AND NOT public.is_super_admin() THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'sem_permissao');
    END IF;

    IF p_id_agente IS NOT NULL THEN
      IF NOT EXISTS (
        SELECT 1
        FROM public."SAAS_AgentesIA" a
        WHERE a.id = p_id_agente
          AND a."contaId" = p_conta_id
      ) THEN
        RETURN jsonb_build_object('ok', false, 'erro', 'agente_invalido');
      END IF;
    END IF;

    UPDATE public."SAAS_Contas"
    SET "idAgentePadrao" = p_id_agente
    WHERE id = p_conta_id;

    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'conta_nao_encontrada');
    END IF;

    RETURN jsonb_build_object('ok', true, 'idAgentePadrao', p_id_agente);
  END;
  $$;

  GRANT EXECUTE ON FUNCTION public.f_regra_ativacao_conexao_ok(text, jsonb, bigint) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.f_regra_horario_ativacao_ok(jsonb) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.f_regra_ativacao_condicao_ok(text, jsonb, text, bigint, bigint) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.f_resolver_agente_ativacao(uuid, bigint, bigint, text, bigint, bigint, boolean) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.f_resolver_agente_ativacao(uuid, bigint, bigint, text, bigint, bigint, boolean) TO service_role;
  GRANT EXECUTE ON FUNCTION public.f_salvar_agente_padrao_global(uuid, bigint) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.f_salvar_agente_padrao_global(uuid, bigint) TO service_role;

  -- Follow-up do agente IA: JSON no agente + uma linha por conversa/tipo
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_AgentesIA"') IS NOT NULL
       AND NOT EXISTS (
         SELECT 1 FROM information_schema.columns
         WHERE table_schema = 'public' AND table_name = 'SAAS_AgentesIA' AND column_name = 'followup'
       ) THEN
      ALTER TABLE public."SAAS_AgentesIA" ADD COLUMN followup JSONB NOT NULL DEFAULT '{}'::jsonb;
      COMMENT ON COLUMN public."SAAS_AgentesIA".followup IS
        'Follow-up: { ativo, pararSeHumano, respeitarHorario, etapas[{ slug, nome, criterio, perguntaPendente, passos }], passos, dinamico }';
    END IF;
  END$$;

  CREATE TABLE IF NOT EXISTS public."FollowupExecucao" (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "idConta" UUID NOT NULL,
    "idConversa" BIGINT NOT NULL REFERENCES public."SAAS_Conversas_Agentes"(id) ON UPDATE CASCADE ON DELETE CASCADE,
    "idAgente" BIGINT REFERENCES public."SAAS_AgentesIA"(id) ON UPDATE CASCADE ON DELETE SET NULL,
    "idContato" BIGINT,
    "idConexao" BIGINT,
    canal TEXT,
    telefone TEXT,
    tipo TEXT NOT NULL DEFAULT 'cadencia' CHECK (tipo IN ('cadencia', 'dinamico')),
    "passoAtual" INTEGER NOT NULL DEFAULT 0,
    "etapaAtual" TEXT,
    "progressoEtapas" JSONB NOT NULL DEFAULT '{}'::jsonb,
    "proximoEm" TIMESTAMPTZ NOT NULL,
    status TEXT NOT NULL DEFAULT 'agendado' CHECK (status IN ('agendado', 'enviado', 'parado', 'concluido')),
    "motivoParada" TEXT,
    "ultimoMenu" JSONB,
    "criadoEm" TIMESTAMPTZ NOT NULL DEFAULT now(),
    "atualizadoEm" TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE ("idConversa", tipo)
  );

  GRANT ALL ON TABLE public."FollowupExecucao" TO service_role;
  GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public."FollowupExecucao" TO authenticated;

  CREATE INDEX IF NOT EXISTS "FollowupExecucao_due_idx"
    ON public."FollowupExecucao" (status, "proximoEm");
  CREATE INDEX IF NOT EXISTS "FollowupExecucao_conta_idx"
    ON public."FollowupExecucao" ("idConta");

  ALTER TABLE public."FollowupExecucao" ENABLE ROW LEVEL SECURITY;

  ALTER TABLE public."FollowupExecucao"
    ADD COLUMN IF NOT EXISTS "etapaAtual" TEXT;
  ALTER TABLE public."FollowupExecucao"
    ADD COLUMN IF NOT EXISTS "progressoEtapas" JSONB NOT NULL DEFAULT '{}'::jsonb;
  COMMENT ON COLUMN public."FollowupExecucao"."etapaAtual" IS
    'Slug da etapa de follow-up em andamento (cadência por etapas).';
  COMMENT ON COLUMN public."FollowupExecucao"."progressoEtapas" IS
    'Mapa slug → próximo índice de passo daquela etapa.';

  -- Remetentes SMTP por conta (disparo de e-mail do cliente)
  CREATE TABLE IF NOT EXISTS public."SAAS_RemetentesEmails" (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    "contaId" UUID REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE,
    nome TEXT,
    smtp_email TEXT,
    smtp_name TEXT,
    smtp_host TEXT,
    smtp_port INT DEFAULT 587,
    smtp_user TEXT,
    smtp_apikey TEXT,
    padrao BOOLEAN NOT NULL DEFAULT false
  );

  CREATE INDEX IF NOT EXISTS "SAAS_RemetentesEmails_conta_idx"
    ON public."SAAS_RemetentesEmails" ("contaId");

  GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public."SAAS_RemetentesEmails" TO authenticated;
  GRANT ALL ON TABLE public."SAAS_RemetentesEmails" TO service_role;
  DO $$
  DECLARE
    v_seq text;
  BEGIN
    v_seq := pg_get_serial_sequence('public."SAAS_RemetentesEmails"', 'id');
    IF v_seq IS NOT NULL THEN
      EXECUTE format('GRANT USAGE, SELECT ON SEQUENCE %s TO authenticated', v_seq);
    END IF;
  END$$;

  ALTER TABLE public."SAAS_RemetentesEmails" ENABLE ROW LEVEL SECURITY;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_RemetentesEmails"') IS NULL THEN RETURN; END IF;
    DROP POLICY IF EXISTS "select_remetentes_emails" ON public."SAAS_RemetentesEmails";
    DROP POLICY IF EXISTS "insert_remetentes_emails" ON public."SAAS_RemetentesEmails";
    DROP POLICY IF EXISTS "update_remetentes_emails" ON public."SAAS_RemetentesEmails";
    DROP POLICY IF EXISTS "delete_remetentes_emails" ON public."SAAS_RemetentesEmails";
    CREATE POLICY "select_remetentes_emails" ON public."SAAS_RemetentesEmails"
      FOR SELECT TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
    CREATE POLICY "insert_remetentes_emails" ON public."SAAS_RemetentesEmails"
      FOR INSERT TO authenticated WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
    CREATE POLICY "update_remetentes_emails" ON public."SAAS_RemetentesEmails"
      FOR UPDATE TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()))
      WITH CHECK ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
    CREATE POLICY "delete_remetentes_emails" ON public."SAAS_RemetentesEmails"
      FOR DELETE TO authenticated USING ("contaId" IN (SELECT public.rls_conta_ids()) OR (SELECT public.rls_eh_super_admin()));
  END$$;

  -- =========================
  -- Atribuir contatos no CRM (novas conversas)
  -- =========================
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Contas"') IS NULL THEN
      RETURN;
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Contas' AND column_name = 'atribuirContatosCrm'
    ) THEN
      ALTER TABLE public."SAAS_Contas" ADD COLUMN "atribuirContatosCrm" BOOLEAN NOT NULL DEFAULT false;
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Contas' AND column_name = 'quadroIdAtribuicaoCrm'
    ) THEN
      ALTER TABLE public."SAAS_Contas" ADD COLUMN "quadroIdAtribuicaoCrm" BIGINT;
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Contas' AND column_name = 'etapaQuadroIdAtribuicaoCrm'
    ) THEN
      ALTER TABLE public."SAAS_Contas" ADD COLUMN "etapaQuadroIdAtribuicaoCrm" BIGINT;
    END IF;

    IF to_regclass('public."SAAS_Quadros"') IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Contas_quadroIdAtribuicaoCrm_fkey') THEN
      ALTER TABLE public."SAAS_Contas"
        ADD CONSTRAINT "SAAS_Contas_quadroIdAtribuicaoCrm_fkey"
        FOREIGN KEY ("quadroIdAtribuicaoCrm") REFERENCES public."SAAS_Quadros"(id) ON UPDATE CASCADE ON DELETE SET NULL;
    END IF;

    IF to_regclass('public."SAAS_Etapas_Quadros"') IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Contas_etapaQuadroIdAtribuicaoCrm_fkey') THEN
      ALTER TABLE public."SAAS_Contas"
        ADD CONSTRAINT "SAAS_Contas_etapaQuadroIdAtribuicaoCrm_fkey"
        FOREIGN KEY ("etapaQuadroIdAtribuicaoCrm") REFERENCES public."SAAS_Etapas_Quadros"(id) ON UPDATE CASCADE ON DELETE SET NULL;
    END IF;
  END$$;

  COMMENT ON COLUMN public."SAAS_Contas"."atribuirContatosCrm" IS
    'Se verdadeiro, novas conversas criam um card no CRM padrão da conta.';
  COMMENT ON COLUMN public."SAAS_Contas"."quadroIdAtribuicaoCrm" IS
    'Quadro de CRM usado para atribuir contatos de novas conversas.';
  COMMENT ON COLUMN public."SAAS_Contas"."etapaQuadroIdAtribuicaoCrm" IS
    'Etapa do CRM usada para atribuir contatos de novas conversas.';

  CREATE OR REPLACE FUNCTION public.f_salvar_atribuicao_contatos_crm(
    p_conta_id uuid,
    p_ativo boolean DEFAULT false,
    p_quadro_id bigint DEFAULT NULL,
    p_etapa_id bigint DEFAULT NULL
  ) RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
  BEGIN
    IF p_conta_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'contaId obrigatório');
    END IF;

    IF NOT public.can_access_conta(p_conta_id) AND NOT public.is_super_admin() THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'sem_permissao');
    END IF;

    IF p_quadro_id IS NOT NULL THEN
      IF NOT EXISTS (
        SELECT 1 FROM public."SAAS_Quadros" q
        WHERE q.id = p_quadro_id AND q."contaId" = p_conta_id
      ) THEN
        RETURN jsonb_build_object('ok', false, 'erro', 'CRM inválido');
      END IF;
    END IF;

    IF p_etapa_id IS NOT NULL THEN
      IF p_quadro_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM public."SAAS_Etapas_Quadros" e
        WHERE e.id = p_etapa_id
          AND e."quadroId" = p_quadro_id
          AND e."contaId" = p_conta_id
      ) THEN
        RETURN jsonb_build_object('ok', false, 'erro', 'Etapa inválida');
      END IF;
    END IF;

    IF COALESCE(p_ativo, false) AND (p_quadro_id IS NULL OR p_etapa_id IS NULL) THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Selecione um CRM e uma etapa.');
    END IF;

    UPDATE public."SAAS_Contas"
    SET
      "atribuirContatosCrm" = COALESCE(p_ativo, false),
      "quadroIdAtribuicaoCrm" = p_quadro_id,
      "etapaQuadroIdAtribuicaoCrm" = p_etapa_id
    WHERE id = p_conta_id;

    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Conta não encontrada');
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'atribuirContatosCrm', COALESCE(p_ativo, false),
      'quadroIdAtribuicaoCrm', p_quadro_id,
      'etapaQuadroIdAtribuicaoCrm', p_etapa_id
    );
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_atribuir_contato_crm_nova_conversa()
  RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
  DECLARE
    v_ativo boolean;
    v_quadro_id bigint;
    v_etapa_id bigint;
    v_ordem smallint;
    v_nome text;
    v_telefone text;
  BEGIN
    IF TG_OP = 'UPDATE' AND NEW."contatoId" IS NOT DISTINCT FROM OLD."contatoId" THEN
      RETURN NEW;
    END IF;

    IF NEW."contatoId" IS NULL OR NEW."contaId" IS NULL THEN
      RETURN NEW;
    END IF;

    SELECT c."atribuirContatosCrm", c."quadroIdAtribuicaoCrm", c."etapaQuadroIdAtribuicaoCrm"
      INTO v_ativo, v_quadro_id, v_etapa_id
    FROM public."SAAS_Contas" c
    WHERE c.id = NEW."contaId";

    IF NOT COALESCE(v_ativo, false) OR v_quadro_id IS NULL OR v_etapa_id IS NULL THEN
      RETURN NEW;
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public."SAAS_Quadros" q
      JOIN public."SAAS_Etapas_Quadros" e ON e.id = v_etapa_id AND e."quadroId" = q.id
      WHERE q.id = v_quadro_id
        AND q."contaId" = NEW."contaId"
        AND e."contaId" = NEW."contaId"
    ) THEN
      RETURN NEW;
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public."SAAS_Cards_Quadros" card
      WHERE card."contatoId" = NEW."contatoId"
        AND card."quadroId" = v_quadro_id
      LIMIT 1
    ) THEN
      RETURN NEW;
    END IF;

    SELECT c.nome, regexp_replace(COALESCE(c.telefone, NEW.telefone, ''), '[^0-9]', '', 'g')
      INTO v_nome, v_telefone
    FROM public."SAAS_Contatos" c
    WHERE c.id = NEW."contatoId";

    SELECT COALESCE(MAX(card.ordem), 0) + 1
      INTO v_ordem
    FROM public."SAAS_Cards_Quadros" card
    WHERE card."etapaQuadroId" = v_etapa_id;

    INSERT INTO public."SAAS_Cards_Quadros" (
      "quadroId",
      "etapaQuadroId",
      "contatoId",
      nome,
      contato,
      valor,
      observacoes,
      ordem
    ) VALUES (
      v_quadro_id,
      v_etapa_id,
      NEW."contatoId",
      COALESCE(NULLIF(btrim(v_nome), ''), NULLIF(v_telefone, ''), 'Contato'),
      NULLIF(v_telefone, ''),
      0,
      NULL,
      COALESCE(v_ordem, 1)
    );

    RETURN NEW;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'f_atribuir_contato_crm_nova_conversa: %', SQLERRM;
    RETURN NEW;
  END;
  $$;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Conversas_Agentes"') IS NULL THEN
      RETURN;
    END IF;
    DROP TRIGGER IF EXISTS trg_atribuir_contato_crm_nova_conversa ON public."SAAS_Conversas_Agentes";
    CREATE TRIGGER trg_atribuir_contato_crm_nova_conversa
      AFTER INSERT OR UPDATE OF "contatoId" ON public."SAAS_Conversas_Agentes"
      FOR EACH ROW
      EXECUTE FUNCTION public.f_atribuir_contato_crm_nova_conversa();
  END$$;

  GRANT EXECUTE ON FUNCTION public.f_salvar_atribuicao_contatos_crm(uuid, boolean, bigint, bigint) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.f_salvar_atribuicao_contatos_crm(uuid, boolean, bigint, bigint) TO service_role;

  -- =========================
  -- Distribuição / redistribuição automática de leads (chat)
  -- =========================
  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Contas"') IS NULL THEN
      RETURN;
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Contas' AND column_name = 'distribuicaoLeadsAtivo'
    ) THEN
      ALTER TABLE public."SAAS_Contas" ADD COLUMN "distribuicaoLeadsAtivo" BOOLEAN NOT NULL DEFAULT false;
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Contas' AND column_name = 'distribuicaoLeadsSetorId'
    ) THEN
      ALTER TABLE public."SAAS_Contas" ADD COLUMN "distribuicaoLeadsSetorId" BIGINT;
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Contas' AND column_name = 'distribuicaoLeadsModo'
    ) THEN
      ALTER TABLE public."SAAS_Contas" ADD COLUMN "distribuicaoLeadsModo" TEXT NOT NULL DEFAULT 'aleatorio';
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Contas' AND column_name = 'distribuicaoLeadsUsuarioFixoId'
    ) THEN
      ALTER TABLE public."SAAS_Contas" ADD COLUMN "distribuicaoLeadsUsuarioFixoId" UUID;
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Contas' AND column_name = 'distribuicaoLeadsUsuariosIds'
    ) THEN
      ALTER TABLE public."SAAS_Contas" ADD COLUMN "distribuicaoLeadsUsuariosIds" UUID[];
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Contas' AND column_name = 'redistribuicaoLeadsAtivo'
    ) THEN
      ALTER TABLE public."SAAS_Contas" ADD COLUMN "redistribuicaoLeadsAtivo" BOOLEAN NOT NULL DEFAULT false;
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Contas' AND column_name = 'redistribuicaoLeadsTempo'
    ) THEN
      ALTER TABLE public."SAAS_Contas" ADD COLUMN "redistribuicaoLeadsTempo" INTEGER NOT NULL DEFAULT 15;
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Contas' AND column_name = 'redistribuicaoLeadsUnidade'
    ) THEN
      ALTER TABLE public."SAAS_Contas" ADD COLUMN "redistribuicaoLeadsUnidade" TEXT NOT NULL DEFAULT 'minutos';
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Contas' AND column_name = 'redistribuicaoLeadsSetorId'
    ) THEN
      ALTER TABLE public."SAAS_Contas" ADD COLUMN "redistribuicaoLeadsSetorId" BIGINT;
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Contas' AND column_name = 'redistribuicaoLeadsModo'
    ) THEN
      ALTER TABLE public."SAAS_Contas" ADD COLUMN "redistribuicaoLeadsModo" TEXT NOT NULL DEFAULT 'aleatorio';
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Contas' AND column_name = 'redistribuicaoLeadsUsuarioFixoId'
    ) THEN
      ALTER TABLE public."SAAS_Contas" ADD COLUMN "redistribuicaoLeadsUsuarioFixoId" UUID;
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Contas' AND column_name = 'redistribuicaoLeadsUsuariosIds'
    ) THEN
      ALTER TABLE public."SAAS_Contas" ADD COLUMN "redistribuicaoLeadsUsuariosIds" UUID[];
    END IF;

    IF to_regclass('public."SAAS_Setores"') IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Contas_distribuicaoLeadsSetorId_fkey') THEN
      ALTER TABLE public."SAAS_Contas"
        ADD CONSTRAINT "SAAS_Contas_distribuicaoLeadsSetorId_fkey"
        FOREIGN KEY ("distribuicaoLeadsSetorId") REFERENCES public."SAAS_Setores"(id) ON UPDATE CASCADE ON DELETE SET NULL;
    END IF;

    IF to_regclass('public."SAAS_Setores"') IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SAAS_Contas_redistribuicaoLeadsSetorId_fkey') THEN
      ALTER TABLE public."SAAS_Contas"
        ADD CONSTRAINT "SAAS_Contas_redistribuicaoLeadsSetorId_fkey"
        FOREIGN KEY ("redistribuicaoLeadsSetorId") REFERENCES public."SAAS_Setores"(id) ON UPDATE CASCADE ON DELETE SET NULL;
    END IF;

    -- NÃO criar FKs Contas → Usuarios (distribuicao*/redistribuicao*UsuarioFixoId).
    -- Elas geram PGRST201 no embed SAAS_Usuarios → SAAS_Contas (login e status da conta).
    -- As colunas UUID continuam; a integridade fica na aplicação.
    BEGIN
      ALTER TABLE public."SAAS_Contas"
        DROP CONSTRAINT IF EXISTS "SAAS_Contas_distribuicaoLeadsUsuarioFixoId_fkey";
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'drop SAAS_Contas_distribuicaoLeadsUsuarioFixoId_fkey: %', SQLERRM;
    END;
    BEGIN
      ALTER TABLE public."SAAS_Contas"
        DROP CONSTRAINT IF EXISTS "SAAS_Contas_redistribuicaoLeadsUsuarioFixoId_fkey";
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'drop SAAS_Contas_redistribuicaoLeadsUsuarioFixoId_fkey: %', SQLERRM;
    END;
  END$$;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Conversas_Agentes"') IS NULL THEN
      RETURN;
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'SAAS_Conversas_Agentes' AND column_name = 'dataAtribuicaoAtendente'
    ) THEN
      ALTER TABLE public."SAAS_Conversas_Agentes" ADD COLUMN "dataAtribuicaoAtendente" TIMESTAMPTZ;
    END IF;
    CREATE INDEX IF NOT EXISTS saas_conversas_agentes_redistrib_idx
      ON public."SAAS_Conversas_Agentes" ("contaId", "statusAtendimento", "dataAtribuicaoAtendente");
  END$$;

  COMMENT ON COLUMN public."SAAS_Contas"."distribuicaoLeadsAtivo" IS
    'Se verdadeiro, novas conversas sem atendente são distribuídas automaticamente.';
  COMMENT ON COLUMN public."SAAS_Contas"."distribuicaoLeadsModo" IS
    'Modo: fixo | aleatorio | menos_ocupado.';
  COMMENT ON COLUMN public."SAAS_Contas"."redistribuicaoLeadsAtivo" IS
    'Se verdadeiro, leads em aguardando sem atendimento no prazo são redistribuídos.';
  COMMENT ON COLUMN public."SAAS_Conversas_Agentes"."dataAtribuicaoAtendente" IS
    'Momento da última atribuição de atendente (base do prazo de redistribuição).';

  CREATE OR REPLACE FUNCTION public.f_candidatos_distribuicao_leads(
    p_conta_id uuid,
    p_setor_id bigint DEFAULT NULL,
    p_usuarios_ids uuid[] DEFAULT NULL,
    p_excluir_usuario uuid DEFAULT NULL
  ) RETURNS TABLE(usuario_id uuid)
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path = public
  AS $$
    SELECT u.id
    FROM public."SAAS_Usuarios" u
    WHERE u."contaId" = p_conta_id
      AND (p_excluir_usuario IS NULL OR u.id IS DISTINCT FROM p_excluir_usuario)
      AND (
        p_setor_id IS NULL
        OR EXISTS (
          SELECT 1
          FROM public."SAAS_Setores_Usuarios" su
          WHERE su."setorId" = p_setor_id
            AND su."usuarioId" = u.id
            AND su."contaId" = p_conta_id
        )
      )
      AND (
        p_usuarios_ids IS NULL
        OR cardinality(p_usuarios_ids) = 0
        OR u.id = ANY (p_usuarios_ids)
      );
  $$;

  CREATE OR REPLACE FUNCTION public.f_escolher_atendente_distribuicao(
    p_conta_id uuid,
    p_modo text,
    p_setor_id bigint DEFAULT NULL,
    p_usuario_fixo uuid DEFAULT NULL,
    p_usuarios_ids uuid[] DEFAULT NULL,
    p_excluir_usuario uuid DEFAULT NULL
  ) RETURNS uuid
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path = public
  AS $$
  DECLARE
    v_modo text := lower(trim(COALESCE(p_modo, 'aleatorio')));
    v_escolhido uuid;
  BEGIN
    IF p_conta_id IS NULL THEN
      RETURN NULL;
    END IF;

    IF v_modo = 'fixo' THEN
      IF p_usuario_fixo IS NULL THEN
        RETURN NULL;
      END IF;
      IF p_excluir_usuario IS NOT NULL AND p_usuario_fixo = p_excluir_usuario THEN
        RETURN NULL;
      END IF;
      IF EXISTS (
        SELECT 1
        FROM public.f_candidatos_distribuicao_leads(p_conta_id, p_setor_id, ARRAY[p_usuario_fixo]::uuid[], NULL) c
        WHERE c.usuario_id = p_usuario_fixo
      ) THEN
        RETURN p_usuario_fixo;
      END IF;
      RETURN NULL;
    END IF;

    IF v_modo = 'menos_ocupado' THEN
      SELECT c.usuario_id
        INTO v_escolhido
      FROM public.f_candidatos_distribuicao_leads(p_conta_id, p_setor_id, p_usuarios_ids, p_excluir_usuario) c
      LEFT JOIN public."SAAS_Conversas_Agentes" conv
        ON conv.atendente = c.usuario_id
       AND conv."contaId" = p_conta_id
       AND lower(trim(COALESCE(conv."statusAtendimento", ''))) IN ('aberto', 'aguardando')
      GROUP BY c.usuario_id
      ORDER BY COUNT(conv.id) ASC, random()
      LIMIT 1;
      RETURN v_escolhido;
    END IF;

    -- aleatorio (padrão)
    SELECT c.usuario_id
      INTO v_escolhido
    FROM public.f_candidatos_distribuicao_leads(p_conta_id, p_setor_id, p_usuarios_ids, p_excluir_usuario) c
    ORDER BY random()
    LIMIT 1;
    RETURN v_escolhido;
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_validar_config_distribuicao_leads(
    p_conta_id uuid,
    p_ativo boolean,
    p_setor_id bigint,
    p_modo text,
    p_usuario_fixo uuid,
    p_usuarios_ids uuid[]
  ) RETURNS text
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path = public
  AS $$
  DECLARE
    v_modo text := lower(trim(COALESCE(p_modo, 'aleatorio')));
  BEGIN
    IF NOT COALESCE(p_ativo, false) THEN
      RETURN NULL;
    END IF;

    IF v_modo NOT IN ('fixo', 'aleatorio', 'menos_ocupado') THEN
      RETURN 'Modo de distribuição inválido.';
    END IF;

    IF p_setor_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public."SAAS_Setores" s
      WHERE s.id = p_setor_id AND s."contaId" = p_conta_id
    ) THEN
      RETURN 'Setor inválido.';
    END IF;

    IF v_modo = 'fixo' THEN
      IF p_usuario_fixo IS NULL THEN
        RETURN 'Selecione um atendente fixo.';
      END IF;
      IF public.f_escolher_atendente_distribuicao(
        p_conta_id, 'fixo', p_setor_id, p_usuario_fixo, NULL, NULL
      ) IS NULL THEN
        RETURN 'Atendente fixo inválido para o setor/conta.';
      END IF;
      RETURN NULL;
    END IF;

    IF p_usuarios_ids IS NULL OR cardinality(p_usuarios_ids) = 0 THEN
      RETURN 'Selecione ao menos um atendente.';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.f_candidatos_distribuicao_leads(p_conta_id, p_setor_id, p_usuarios_ids, NULL)
      LIMIT 1
    ) THEN
      RETURN 'Nenhum atendente válido na seleção.';
    END IF;

    RETURN NULL;
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_salvar_distribuicao_leads(
    p_conta_id uuid,
    p_distribuicao_ativo boolean DEFAULT false,
    p_distribuicao_setor_id bigint DEFAULT NULL,
    p_distribuicao_modo text DEFAULT 'aleatorio',
    p_distribuicao_usuario_fixo uuid DEFAULT NULL,
    p_distribuicao_usuarios_ids uuid[] DEFAULT NULL,
    p_redistribuicao_ativo boolean DEFAULT false,
    p_redistribuicao_tempo integer DEFAULT 15,
    p_redistribuicao_unidade text DEFAULT 'minutos',
    p_redistribuicao_setor_id bigint DEFAULT NULL,
    p_redistribuicao_modo text DEFAULT 'aleatorio',
    p_redistribuicao_usuario_fixo uuid DEFAULT NULL,
    p_redistribuicao_usuarios_ids uuid[] DEFAULT NULL
  ) RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
  DECLARE
    v_erro text;
    v_unidade text := lower(trim(COALESCE(p_redistribuicao_unidade, 'minutos')));
    v_tempo integer := COALESCE(p_redistribuicao_tempo, 15);
    v_dist_modo text := lower(trim(COALESCE(p_distribuicao_modo, 'aleatorio')));
    v_redist_modo text := lower(trim(COALESCE(p_redistribuicao_modo, 'aleatorio')));
  BEGIN
    IF p_conta_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'contaId obrigatório');
    END IF;

    IF NOT public.can_access_conta(p_conta_id) AND NOT public.is_super_admin() THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'sem_permissao');
    END IF;

    IF v_unidade NOT IN ('minutos', 'horas') THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Unidade de tempo inválida.');
    END IF;

    IF v_tempo IS NULL OR v_tempo < 1 THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Informe um tempo maior que zero.');
    END IF;

    v_erro := public.f_validar_config_distribuicao_leads(
      p_conta_id,
      p_distribuicao_ativo,
      p_distribuicao_setor_id,
      v_dist_modo,
      p_distribuicao_usuario_fixo,
      p_distribuicao_usuarios_ids
    );
    IF v_erro IS NOT NULL THEN
      RETURN jsonb_build_object('ok', false, 'erro', v_erro);
    END IF;

    v_erro := public.f_validar_config_distribuicao_leads(
      p_conta_id,
      p_redistribuicao_ativo,
      p_redistribuicao_setor_id,
      v_redist_modo,
      p_redistribuicao_usuario_fixo,
      p_redistribuicao_usuarios_ids
    );
    IF v_erro IS NOT NULL THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Redistribuição: ' || v_erro);
    END IF;

    IF v_dist_modo = 'fixo' THEN
      p_distribuicao_usuarios_ids := NULL;
    ELSE
      p_distribuicao_usuario_fixo := NULL;
    END IF;

    IF v_redist_modo = 'fixo' THEN
      p_redistribuicao_usuarios_ids := NULL;
    ELSE
      p_redistribuicao_usuario_fixo := NULL;
    END IF;

    IF NOT COALESCE(p_distribuicao_ativo, false) THEN
      p_distribuicao_setor_id := NULL;
      p_distribuicao_usuario_fixo := NULL;
      p_distribuicao_usuarios_ids := NULL;
      v_dist_modo := 'aleatorio';
    END IF;

    IF NOT COALESCE(p_redistribuicao_ativo, false) THEN
      p_redistribuicao_setor_id := NULL;
      p_redistribuicao_usuario_fixo := NULL;
      p_redistribuicao_usuarios_ids := NULL;
      v_redist_modo := 'aleatorio';
    END IF;

    UPDATE public."SAAS_Contas"
    SET
      "distribuicaoLeadsAtivo" = COALESCE(p_distribuicao_ativo, false),
      "distribuicaoLeadsSetorId" = p_distribuicao_setor_id,
      "distribuicaoLeadsModo" = v_dist_modo,
      "distribuicaoLeadsUsuarioFixoId" = p_distribuicao_usuario_fixo,
      "distribuicaoLeadsUsuariosIds" = p_distribuicao_usuarios_ids,
      "redistribuicaoLeadsAtivo" = COALESCE(p_redistribuicao_ativo, false),
      "redistribuicaoLeadsTempo" = v_tempo,
      "redistribuicaoLeadsUnidade" = v_unidade,
      "redistribuicaoLeadsSetorId" = p_redistribuicao_setor_id,
      "redistribuicaoLeadsModo" = v_redist_modo,
      "redistribuicaoLeadsUsuarioFixoId" = p_redistribuicao_usuario_fixo,
      "redistribuicaoLeadsUsuariosIds" = p_redistribuicao_usuarios_ids
    WHERE id = p_conta_id;

    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Conta não encontrada');
    END IF;

    RETURN jsonb_build_object('ok', true);
  END;
  $$;

  CREATE OR REPLACE FUNCTION public.f_distribuir_lead_nova_conversa()
  RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
  DECLARE
    v_ativo boolean;
    v_setor_id bigint;
    v_modo text;
    v_usuario_fixo uuid;
    v_usuarios_ids uuid[];
    v_escolhido uuid;
  BEGIN
    IF NEW."contaId" IS NULL THEN
      RETURN NEW;
    END IF;

    -- Marca horário sempre que o atendente muda (manual ou automático)
    IF TG_OP = 'INSERT' THEN
      IF NEW.atendente IS NOT NULL THEN
        NEW."dataAtribuicaoAtendente" := COALESCE(NEW."dataAtribuicaoAtendente", now());
      END IF;
    ELSIF TG_OP = 'UPDATE' THEN
      IF NEW.atendente IS DISTINCT FROM OLD.atendente THEN
        IF NEW.atendente IS NULL THEN
          NEW."dataAtribuicaoAtendente" := NULL;
        ELSE
          NEW."dataAtribuicaoAtendente" := now();
        END IF;
      END IF;
    END IF;

    IF TG_OP = 'UPDATE' THEN
      RETURN NEW;
    END IF;

    -- Distribuição automática: apenas INSERT sem atendente
    IF NEW.atendente IS NOT NULL THEN
      RETURN NEW;
    END IF;

    SELECT
      c."distribuicaoLeadsAtivo",
      c."distribuicaoLeadsSetorId",
      c."distribuicaoLeadsModo",
      c."distribuicaoLeadsUsuarioFixoId",
      c."distribuicaoLeadsUsuariosIds"
      INTO v_ativo, v_setor_id, v_modo, v_usuario_fixo, v_usuarios_ids
    FROM public."SAAS_Contas" c
    WHERE c.id = NEW."contaId";

    IF NOT COALESCE(v_ativo, false) THEN
      RETURN NEW;
    END IF;

    v_escolhido := public.f_escolher_atendente_distribuicao(
      NEW."contaId", v_modo, v_setor_id, v_usuario_fixo, v_usuarios_ids, NULL
    );

    IF v_escolhido IS NULL THEN
      RETURN NEW;
    END IF;

    NEW.atendente := v_escolhido;
    NEW."dataAtribuicaoAtendente" := now();
    IF v_setor_id IS NOT NULL AND NEW."setorId" IS NULL THEN
      NEW."setorId" := v_setor_id;
    END IF;

    RETURN NEW;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'f_distribuir_lead_nova_conversa: %', SQLERRM;
    RETURN NEW;
  END;
  $$;

  DO $$
  BEGIN
    IF to_regclass('public."SAAS_Conversas_Agentes"') IS NULL THEN
      RETURN;
    END IF;
    DROP TRIGGER IF EXISTS trg_distribuir_lead_nova_conversa ON public."SAAS_Conversas_Agentes";
    CREATE TRIGGER trg_distribuir_lead_nova_conversa
      BEFORE INSERT OR UPDATE OF atendente ON public."SAAS_Conversas_Agentes"
      FOR EACH ROW
      EXECUTE FUNCTION public.f_distribuir_lead_nova_conversa();
  END$$;

  CREATE OR REPLACE FUNCTION public.f_processar_redistribuicao_leads()
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
  DECLARE
    r RECORD;
    v_conv RECORD;
    v_escolhido uuid;
    v_minutos integer;
    v_qtd integer := 0;
  BEGIN
    FOR r IN
      SELECT
        c.id AS conta_id,
        c."redistribuicaoLeadsTempo" AS tempo,
        lower(trim(COALESCE(c."redistribuicaoLeadsUnidade", 'minutos'))) AS unidade,
        c."redistribuicaoLeadsSetorId" AS setor_id,
        c."redistribuicaoLeadsModo" AS modo,
        c."redistribuicaoLeadsUsuarioFixoId" AS usuario_fixo,
        c."redistribuicaoLeadsUsuariosIds" AS usuarios_ids
      FROM public."SAAS_Contas" c
      WHERE COALESCE(c."redistribuicaoLeadsAtivo", false) = true
        AND COALESCE(c."redistribuicaoLeadsTempo", 0) > 0
    LOOP
      v_minutos := CASE
        WHEN r.unidade = 'horas' THEN r.tempo * 60
        ELSE r.tempo
      END;

      FOR v_conv IN
        SELECT conv.id, conv.atendente
        FROM public."SAAS_Conversas_Agentes" conv
        WHERE conv."contaId" = r.conta_id
          AND lower(trim(COALESCE(conv."statusAtendimento", ''))) = 'aguardando'
          AND conv.atendente IS NOT NULL
          AND COALESCE(conv."dataAtribuicaoAtendente", conv.created_at) <= (now() - make_interval(mins => v_minutos))
        ORDER BY COALESCE(conv."dataAtribuicaoAtendente", conv.created_at) ASC
        LIMIT 200
      LOOP
        v_escolhido := public.f_escolher_atendente_distribuicao(
          r.conta_id,
          r.modo,
          r.setor_id,
          r.usuario_fixo,
          r.usuarios_ids,
          v_conv.atendente
        );

        IF v_escolhido IS NULL OR v_escolhido = v_conv.atendente THEN
          CONTINUE;
        END IF;

        UPDATE public."SAAS_Conversas_Agentes"
        SET
          atendente = v_escolhido,
          "dataAtribuicaoAtendente" = now(),
          "setorId" = COALESCE(r.setor_id, "setorId")
        WHERE id = v_conv.id
          AND lower(trim(COALESCE("statusAtendimento", ''))) = 'aguardando'
          AND atendente IS NOT DISTINCT FROM v_conv.atendente;

        IF FOUND THEN
          v_qtd := v_qtd + 1;
        END IF;
      END LOOP;
    END LOOP;

    RETURN v_qtd;
  END;
  $$;

  GRANT EXECUTE ON FUNCTION public.f_salvar_distribuicao_leads(
    uuid, boolean, bigint, text, uuid, uuid[], boolean, integer, text, bigint, text, uuid, uuid[]
  ) TO authenticated;
  GRANT EXECUTE ON FUNCTION public.f_salvar_distribuicao_leads(
    uuid, boolean, bigint, text, uuid, uuid[], boolean, integer, text, bigint, text, uuid, uuid[]
  ) TO service_role;
  GRANT EXECUTE ON FUNCTION public.f_processar_redistribuicao_leads() TO service_role;

  DO $$
  BEGIN
    IF to_regnamespace('cron') IS NOT NULL AND to_regclass('cron.job') IS NOT NULL THEN
      BEGIN
        PERFORM cron.unschedule(jobid) FROM cron.job WHERE jobname = 'redistribuir_leads_minuto';
      EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'Erro ao remover job redistribuir_leads_minuto: %', SQLERRM;
      END;
      BEGIN
        PERFORM cron.schedule(
          'redistribuir_leads_minuto',
          '* * * * *',
          'SELECT public.f_processar_redistribuicao_leads();'
        );
      EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'Erro ao criar job redistribuir_leads_minuto: %', SQLERRM;
      END;
    ELSE
      RAISE NOTICE 'pg_cron não disponível. Redistribuição de leads precisará de agendamento externo.';
    END IF;
  END$$;

  -- PGRST201: se a mesma coluna tiver 2 FKs para a mesma tabela, dropa a duplicata (nome minúsculo)
  DO $$
  DECLARE
    r RECORD;
    keep TEXT;
    drop_name TEXT;
  BEGIN
    FOR r IN
      SELECT
        c.conrelid,
        array_agg(c.conname ORDER BY c.conname) AS names
      FROM pg_constraint c
      JOIN pg_class t ON t.oid = c.conrelid
      JOIN pg_namespace n ON n.oid = t.relnamespace
      WHERE c.contype = 'f'
        AND n.nspname = 'public'
      GROUP BY c.conrelid, c.confrelid, c.conkey
      HAVING count(*) > 1
    LOOP
      SELECT x INTO keep
      FROM unnest(r.names) AS x
      WHERE x ~ '[A-Z]'
      LIMIT 1;
      IF keep IS NULL THEN
        keep := r.names[1];
      END IF;
      FOREACH drop_name IN ARRAY r.names LOOP
        IF drop_name IS DISTINCT FROM keep THEN
          EXECUTE format('ALTER TABLE %s DROP CONSTRAINT %I', r.conrelid::regclass, drop_name);
          RAISE NOTICE 'FK duplicada removida: %.%', r.conrelid::regclass, drop_name;
        END IF;
      END LOOP;
    END LOOP;
  END$$;
  NOTIFY pgrst, 'reload schema';


-- =============================================================================
-- 2. TELAS E AÇÕES (hublabel-disparador: scripts/migracao-n8n-telas-acoes.sql)
-- =============================================================================

-- =============================================================================
-- Migração n8n → código (telas + ações). Rode UMA vez no SQL Editor do Supabase.
-- Idempotente: pode rodar de novo sem quebrar nada.
-- =============================================================================

-- 1) Personalização white-label (linha única id=1).
--    Lida pelo servidor ao montar cada tela; editada pela aba Personalização do admin.
create table if not exists public."SAAS_Personalizacao" (
  id               bigint primary key default 1 check (id = 1),
  nome             text,
  cor              text,          -- hex sem '#', ex.: 25D366
  "telefoneSuporte" text,         -- só dígitos, ex.: 5511999998877
  "logoUrl"        text,          -- vazio = <SUPABASE_URL>/storage/v1/object/public/arquivos/LOGO%20PRINCIPAL.png
  "faviconUrl"     text,          -- vazio = <SUPABASE_URL>/storage/v1/object/public/arquivos/FAVICON.png
  updated_at       timestamptz not null default now()
);

insert into public."SAAS_Personalizacao" (id, nome, cor, "telefoneSuporte")
values (1, 'Disparamator', '25D366', '5511999998877')
on conflict (id) do nothing;

-- Só o backend (service_role) lê/escreve; o navegador não acessa a tabela.
alter table public."SAAS_Personalizacao" enable row level security;

-- 2) Página de vendas (/pv). Criada pelo botão "Criar" no admin a partir do
--    HTML padrão do repositório; as edições ficam salvas aqui.
create table if not exists public."SAAS_PaginaVendas" (
  id         bigint primary key default 1 check (id = 1),
  html       text not null,
  updated_at timestamptz not null default now()
);

alter table public."SAAS_PaginaVendas" enable row level security;

-- 3) Wrappers com parâmetros nomeados para as funções que o n8n chamava por
--    SQL posicional (o backend usa supabase.rpc, que exige nomes).
create or replace function public.f_hub_meta_preparar_envio_template(p_body jsonb)
returns jsonb
language sql
as $$
  select to_jsonb(public.f_meta_preparar_envio_template(p_body));
$$;

create or replace function public.f_hub_webhook_sincronizar_contato(
  p_conta_id  uuid,
  p_telefone  text,
  p_nome      text,
  p_campos    jsonb,
  p_etiquetas bigint[]
)
returns jsonb
language sql
as $$
  select to_jsonb(public.f_webhook_sincronizar_contato(p_conta_id, p_telefone, p_nome, p_campos, p_etiquetas));
$$;

create or replace function public.f_hub_conversa_ou_mensagem(
  p_telefone   text,
  p_id_conexao bigint,
  p_user_id    uuid,
  p_mensagem   text,
  p_message_id text,
  p_id_agente  bigint
)
returns jsonb
language sql
as $$
  select to_jsonb(public.f_conversa_ou_mensagem(p_telefone, p_id_conexao, p_user_id, p_mensagem, p_message_id, p_id_agente));
$$;

-- Wrappers só para o backend (não expõe nada novo para anon/authenticated).
revoke all on function public.f_hub_meta_preparar_envio_template(jsonb) from public, anon, authenticated;
revoke all on function public.f_hub_webhook_sincronizar_contato(uuid, text, text, jsonb, bigint[]) from public, anon, authenticated;
revoke all on function public.f_hub_conversa_ou_mensagem(text, bigint, uuid, text, text, bigint) from public, anon, authenticated;
grant execute on function public.f_hub_meta_preparar_envio_template(jsonb) to service_role;
grant execute on function public.f_hub_webhook_sincronizar_contato(uuid, text, text, jsonb, bigint[]) to service_role;
grant execute on function public.f_hub_conversa_ou_mensagem(text, bigint, uuid, text, text, bigint) to service_role;

-- Recarrega o cache de schema do PostgREST para as novas funções aparecerem no rpc().
notify pgrst, 'reload schema';


-- =============================================================================
-- 3. RODÍZIO DE CONEXÕES (hublabel-disparador: scripts/pause-dispatch-on-last-disconnected-connection.sql)
-- =============================================================================

-- Atualiza o rodízio de conexões: remove somente a conexão caída e pausa o
-- disparo quando não houver alternativa. Os detalhes pendentes permanecem
-- pendentes para retomada após reconexão e despausa.

CREATE OR REPLACE FUNCTION public.swap_connection(
  p_disparo_id bigint,
  p_blocked_conn_id bigint
)
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
  hdr record;
  v_conn_ids bigint[];
  v_new_conn_id bigint;
BEGIN
  SELECT * INTO hdr
  FROM public."SAAS_Disparos"
  WHERE id = p_disparo_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Disparo % não existe', p_disparo_id;
  END IF;

  v_conn_ids := array_remove(hdr."idConexoes", p_blocked_conn_id);

  IF v_conn_ids IS NULL OR COALESCE(array_length(v_conn_ids, 1), 0) = 0 THEN
    -- Mantém a referência da última conexão para permitir reconectar e despausar.
    UPDATE public."SAAS_Disparos"
    SET "StatusDisparo" = 'Pausado'
    WHERE id = p_disparo_id;
    RETURN;
  END IF;

  v_new_conn_id := v_conn_ids[1];

  UPDATE public."SAAS_Disparos"
  SET "idConexoes" = v_conn_ids
  WHERE id = p_disparo_id;

  UPDATE public."SAAS_Detalhes_Disparos"
  SET "idConexao" = v_new_conn_id
  WHERE "idDisparo" = p_disparo_id
    AND "Status" = 'pending'
    AND ("idConexao" = p_blocked_conn_id OR "idConexao" IS NULL);

  IF hdr."contaId" IS NOT NULL THEN
    PERFORM public.resume_disparo(p_disparo_id, hdr."contaId");
  END IF;
END;
$$;

-- =============================================================================
-- 4. Chat: lista de conversas numa chamada só (hublabel-disparador, chat.html)
-- =============================================================================
-- get_chat_lista: a página de conversas de uma aba + tudo que a lista mostra
-- (contagens das 4 abas, última mensagem, etiquetas, CRM e foto do contato).
-- Antes a tela fazia ~10 consultas por carga (lista, 4 contagens, última
-- mensagem, etiquetas x2, CRM x3, fotos). Mesmas regras das consultas da tela:
--   aberto     = statusAtendimento ILIKE 'aberto'
--   aguardando = ILIKE 'aguardando' e sem agente
--   fechado    = ILIKE 'fechado'
--   agente-ia  = com agente e status diferente de 'aberto'
-- SECURITY INVOKER: tudo passa pela RLS (membro vê as conversas dele, as do
-- setor dele sem atendente e as sem setor e sem atendente; admin vê todas).
-- Se a função não existir, a tela usa as consultas antigas.
CREATE OR REPLACE FUNCTION public.get_chat_lista(
  p_conta_id UUID,
  p_status TEXT DEFAULT 'aberto',
  p_limit INTEGER DEFAULT 20,
  p_offset INTEGER DEFAULT 0,
  p_conexao_ids BIGINT[] DEFAULT NULL,
  p_setor_ids BIGINT[] DEFAULT NULL,
  p_contato_ids BIGINT[] DEFAULT NULL,
  p_search TEXT DEFAULT NULL,
  p_somente_nao_lidas BOOLEAN DEFAULT false
)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path = public
AS $$
DECLARE
  v_status TEXT := LOWER(TRIM(COALESCE(p_status, 'aberto')));
  v_limit INTEGER := GREATEST(1, LEAST(COALESCE(p_limit, 20), 200));
  v_offset INTEGER := GREATEST(0, COALESCE(p_offset, 0));
  v_search TEXT := NULLIF(TRIM(COALESCE(p_search, '')), '');
  v_like TEXT;
  v_like_digitos TEXT;
  v_resultado JSONB;
BEGIN
  IF p_conta_id IS NULL THEN
    RETURN jsonb_build_object(
      'counts', jsonb_build_object('aberto', 0, 'aguardando', 0, 'fechado', 0, 'agente_ia', 0),
      'conversations', '[]'::jsonb, 'next_offset', 0, 'has_more', false
    );
  END IF;

  IF v_search IS NOT NULL THEN
    -- "contém", com % e _ digitados tratados como texto (igual à tela).
    v_like := '%' || replace(replace(replace(LOWER(v_search), '\', '\\'), '%', '\%'), '_', '\_') || '%';
    IF regexp_replace(v_search, '\D', '', 'g') <> '' THEN
      v_like_digitos := '%' || regexp_replace(v_search, '\D', '', 'g') || '%';
    END IF;
  END IF;

  WITH base AS MATERIALIZED (
    SELECT c.*
    FROM public."SAAS_Conversas_Agentes" c
    WHERE c."contaId" = p_conta_id
      AND (p_conexao_ids IS NULL OR cardinality(p_conexao_ids) = 0 OR c."idConexao" = ANY(p_conexao_ids))
      AND (p_setor_ids IS NULL OR cardinality(p_setor_ids) = 0 OR c."setorId" = ANY(p_setor_ids))
      AND (p_contato_ids IS NULL OR cardinality(p_contato_ids) = 0 OR c."contatoId" = ANY(p_contato_ids))
      AND (
        v_like IS NULL
        OR c.telefone ILIKE v_like
        OR (v_like_digitos IS NOT NULL AND c.telefone ILIKE v_like_digitos)
        OR c."contatoId" IN (
          SELECT ct.id FROM public."SAAS_Contatos" ct
          WHERE ct."contaId" = p_conta_id
            AND (
              ct.nome ILIKE v_like
              OR ct.telefone ILIKE v_like
              OR (v_like_digitos IS NOT NULL AND ct.telefone ILIKE v_like_digitos)
            )
        )
      )
  ),
  contagens AS (
    SELECT
      COUNT(*) FILTER (WHERE "statusAtendimento" ILIKE 'aberto') AS aberto,
      COUNT(*) FILTER (WHERE "statusAtendimento" ILIKE 'aguardando' AND "idAgente" IS NULL) AS aguardando,
      COUNT(*) FILTER (WHERE "statusAtendimento" ILIKE 'fechado') AS fechado,
      COUNT(*) FILTER (WHERE "idAgente" IS NOT NULL AND "statusAtendimento" NOT ILIKE 'aberto') AS agente_ia
    FROM base
  ),
  pagina AS (
    SELECT b.*
    FROM base b
    WHERE (
        CASE v_status
          WHEN 'aberto' THEN b."statusAtendimento" ILIKE 'aberto'
          WHEN 'aguardando' THEN b."statusAtendimento" ILIKE 'aguardando' AND b."idAgente" IS NULL
          WHEN 'agente-ia' THEN b."idAgente" IS NOT NULL AND b."statusAtendimento" NOT ILIKE 'aberto'
          ELSE b."statusAtendimento" ILIKE v_status
        END
      )
      AND (NOT COALESCE(p_somente_nao_lidas, false) OR b.lida = false)
    ORDER BY b."ultimaMensagem" DESC NULLS LAST, b.id DESC
    LIMIT v_limit + 1
    OFFSET v_offset
  ),
  itens AS (
    SELECT
      p.id,
      p."ultimaMensagem",
      to_jsonb(p) || jsonb_build_object(
        'atendente_usuario', (SELECT jsonb_build_object('nome', u.nome) FROM public."SAAS_Usuarios" u WHERE u.id = p.atendente),
        'setor', (SELECT jsonb_build_object('nome', s.nome, 'cor', s.cor) FROM public."SAAS_Setores" s WHERE s.id = p."setorId"),
        'contato', (SELECT jsonb_build_object('nome', ct.nome, 'fotoPerfil', ct."fotoPerfil") FROM public."SAAS_Contatos" ct WHERE ct.id = p."contatoId"),
        'SAAS_AgentesIA', (
          SELECT jsonb_build_object('id', a.id, 'nome', a.nome, 'pausarAtendimento', a."pausarAtendimento", 'ativo', a.ativo)
          FROM public."SAAS_AgentesIA" a WHERE a.id = p."idAgente"
        ),
        'SAAS_Conexões', (
          SELECT jsonb_build_object(
            'idAgente', cx."idAgente", 'NomeConexao', cx."NomeConexao", 'Telefone', cx."Telefone", 'apiOficial', cx."apiOficial",
            'SAAS_AgentesIA', (
              SELECT jsonb_build_object('nome', a2.nome, 'pausarAtendimento', a2."pausarAtendimento", 'ativo', a2.ativo)
              FROM public."SAAS_AgentesIA" a2 WHERE a2.id = cx."idAgente"
            )
          )
          FROM public."SAAS_Conexões" cx WHERE cx.id = p."idConexao"
        ),
        'ultimaMensagemTexto', lm.mensagem,
        'ultimaMensagemTipo', lm."tipoMensagem",
        'ultimaMensagemData', lm.created_at,
        'ultimaMensagemFromMe', lm."fromMe",
        'etiquetasPreview', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'nome', COALESCE(NULLIF(e.nome, ''), 'Sem nome'),
            'cor', CASE WHEN BTRIM(COALESCE(e.cor, '')) ~* '^#[0-9a-f]{6}$' THEN BTRIM(e.cor) ELSE '#6b7280' END
          ))
          FROM public."SAAS_Contatos_Etiquetas" ce
          JOIN public."SAAS_Etiquetas" e ON e.id = ce."etiquetaId" AND e."contaId" = p_conta_id
          WHERE ce."contaId" = p_conta_id AND ce."contatoId" = p."contatoId"
        ), '[]'::jsonb),
        'crmPreview', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'quadroNome', CASE WHEN q.id IS NULL THEN 'Quadro' ELSE COALESCE(NULLIF(q.nome, ''), 'Quadro ' || q.id) END,
            'etapaNome', CASE WHEN et.id IS NULL THEN 'Etapa' ELSE COALESCE(NULLIF(et.nome, ''), 'Etapa ' || et.id) END,
            'etapaTipo', CASE WHEN BTRIM(et."tipoEtapa") IN ('venda', 'agendamento', 'perda') THEN BTRIM(et."tipoEtapa") END
          ))
          FROM public."SAAS_Cards_Quadros" cq
          LEFT JOIN public."SAAS_Quadros" q ON q.id = cq."quadroId"
          LEFT JOIN public."SAAS_Etapas_Quadros" et ON et.id = cq."etapaQuadroId"
          WHERE cq."contatoId" = p."contatoId"
        ), '[]'::jsonb)
      ) AS item
    FROM pagina p
    LEFT JOIN LATERAL (
      SELECT m.mensagem, m."tipoMensagem", m.created_at, m."fromMe"
      FROM public."SAAS_Mensagens" m
      WHERE m."conversaId" = p.id AND m.apagada = false
      ORDER BY m.created_at DESC, m.id DESC
      LIMIT 1
    ) lm ON true
  )
  SELECT jsonb_build_object(
    'counts', (SELECT jsonb_build_object('aberto', aberto, 'aguardando', aguardando, 'fechado', fechado, 'agente_ia', agente_ia) FROM contagens),
    'conversations', COALESCE((
      SELECT jsonb_agg(i.item ORDER BY i."ultimaMensagem" DESC NULLS LAST, i.id DESC)
      FROM (SELECT * FROM itens ORDER BY "ultimaMensagem" DESC NULLS LAST, id DESC LIMIT v_limit) i
    ), '[]'::jsonb),
    'has_more', (SELECT COUNT(*) > v_limit FROM pagina),
    'next_offset', v_offset + LEAST(v_limit, (SELECT COUNT(*) FROM pagina)::INTEGER)
  )
  INTO v_resultado;

  RETURN v_resultado;
END;
$$;
REVOKE ALL ON FUNCTION public.get_chat_lista(UUID, TEXT, INTEGER, INTEGER, BIGINT[], BIGINT[], BIGINT[], TEXT, BOOLEAN) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_chat_lista(UUID, TEXT, INTEGER, INTEGER, BIGINT[], BIGINT[], BIGINT[], TEXT, BOOLEAN) TO authenticated;

-- Busca por telefone com "contém" nos contatos (chat e tela de contatos) e lista
-- paginada da tela de contatos (mais novos primeiro).
CREATE INDEX IF NOT EXISTS saas_contatos_telefone_trgm_idx
  ON public."SAAS_Contatos" USING gin (telefone gin_trgm_ops);
CREATE INDEX IF NOT EXISTS saas_contatos_conta_created_idx
  ON public."SAAS_Contatos" ("contaId", created_at DESC, id DESC);


-- =========================
-- Pixel da Meta (API de Conversões)
-- =========================
-- Configuração por conta (Configurações > Pixel). Só o backend (service_role) lê/grava:
-- a tela salva pela rota /pixel-meta/salvar e nunca recebe o token de volta.
CREATE TABLE IF NOT EXISTS public."SAAS_Contas_Pixel_Meta" (
  "contaId" UUID PRIMARY KEY REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE,
  "pixelId" TEXT,
  "accessToken" TEXT,
  "testEventCode" TEXT,
  ativo BOOLEAN NOT NULL DEFAULT true,
  "enviarVendaCrm" BOOLEAN NOT NULL DEFAULT true,
  "eventoVenda" TEXT NOT NULL DEFAULT 'Purchase',
  moeda TEXT NOT NULL DEFAULT 'BRL',
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE public."SAAS_Contas_Pixel_Meta" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public."SAAS_Contas_Pixel_Meta" FROM anon, authenticated;
DROP POLICY IF EXISTS "service_role_full_access" ON public."SAAS_Contas_Pixel_Meta";
CREATE POLICY "service_role_full_access" ON public."SAAS_Contas_Pixel_Meta" TO service_role USING (true) WITH CHECK (true);

-- Fila/histórico dos eventos enviados ao pixel. origem 'crm' = card entrou numa etapa de venda
-- (gravado pelo trigger abaixo); 'chat' = enviado à mão nos detalhes da conversa.
-- O backend pega os 'pendente', envia e marca 'enviado' ou 'erro'.
CREATE TABLE IF NOT EXISTS public."SAAS_Pixel_Eventos" (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  "contaId" UUID NOT NULL REFERENCES public."SAAS_Contas"(id) ON UPDATE CASCADE ON DELETE CASCADE,
  origem TEXT NOT NULL DEFAULT 'crm' CHECK (origem IN ('crm', 'chat')),
  evento TEXT NOT NULL,
  "eventId" TEXT NOT NULL,
  "cardId" BIGINT,
  "contatoId" BIGINT,
  "conversaId" BIGINT,
  "usuarioId" UUID,
  valor DOUBLE PRECISION,
  moeda TEXT,
  status TEXT NOT NULL DEFAULT 'pendente' CHECK (status IN ('pendente', 'enviando', 'enviado', 'erro', 'descartado')),
  tentativas INTEGER NOT NULL DEFAULT 0,
  "proximaTentativa" TIMESTAMPTZ NOT NULL DEFAULT now(),
  erro TEXT,
  resposta JSONB,
  "enviadoEm" TIMESTAMPTZ
);
CREATE UNIQUE INDEX IF NOT EXISTS saas_pixel_eventos_conta_event_id_idx
  ON public."SAAS_Pixel_Eventos" ("contaId", "eventId");
CREATE INDEX IF NOT EXISTS saas_pixel_eventos_fila_idx
  ON public."SAAS_Pixel_Eventos" ("proximaTentativa", id) WHERE status IN ('pendente', 'enviando');

ALTER TABLE public."SAAS_Pixel_Eventos" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public."SAAS_Pixel_Eventos" FROM anon, authenticated;
DROP POLICY IF EXISTS "service_role_full_access" ON public."SAAS_Pixel_Eventos";
CREATE POLICY "service_role_full_access" ON public."SAAS_Pixel_Eventos" TO service_role USING (true) WITH CHECK (true);

-- Card entrou numa etapa do tipo 'venda' (arrastar no Kanban, chat, contatos, agente IA, API):
-- se a conta tem pixel ativo com "enviarVendaCrm", enfileira o evento de venda.
-- Nunca impede a movimentação do card: qualquer erro aqui vira só um aviso.
CREATE OR REPLACE FUNCTION public.f_cards_pixel_venda()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_tipo TEXT; v_conta UUID; v_px public."SAAS_Contas_Pixel_Meta"%ROWTYPE;
BEGIN
  IF NEW."etapaQuadroId" IS NULL THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND NEW."etapaQuadroId" IS NOT DISTINCT FROM OLD."etapaQuadroId" THEN RETURN NEW; END IF;
  BEGIN
    SELECT e."tipoEtapa", COALESCE(e."contaId", q."contaId") INTO v_tipo, v_conta
    FROM public."SAAS_Etapas_Quadros" e
    LEFT JOIN public."SAAS_Quadros" q ON q.id = COALESCE(e."quadroId", NEW."quadroId")
    WHERE e.id = NEW."etapaQuadroId";
    IF v_tipo IS DISTINCT FROM 'venda' OR v_conta IS NULL THEN RETURN NEW; END IF;

    SELECT * INTO v_px FROM public."SAAS_Contas_Pixel_Meta" WHERE "contaId" = v_conta;
    IF NOT FOUND OR NOT v_px.ativo OR NOT v_px."enviarVendaCrm"
       OR COALESCE(v_px."pixelId", '') = '' OR COALESCE(v_px."accessToken", '') = '' THEN
      RETURN NEW;
    END IF;

    -- Sai 1 minuto depois: dá tempo de preencher o valor do card (o backend lê o valor atual)
    -- e, se o card sair da etapa de venda nesse meio-tempo, o evento é descartado.
    INSERT INTO public."SAAS_Pixel_Eventos" ("contaId", origem, evento, "eventId", "cardId", "contatoId", valor, moeda, "proximaTentativa")
    VALUES (
      v_conta, 'crm', COALESCE(NULLIF(v_px."eventoVenda", ''), 'Purchase'),
      'crm-' || NEW.id || '-' || NEW."etapaQuadroId" || '-' || floor(extract(epoch FROM clock_timestamp()))::BIGINT,
      NEW.id, NEW."contatoId", NEW.valor, COALESCE(NULLIF(v_px.moeda, ''), 'BRL'), now() + interval '1 minute'
    )
    ON CONFLICT DO NOTHING;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'f_cards_pixel_venda (card %): %', NEW.id, SQLERRM;
  END;
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.f_cards_pixel_venda() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS trg_cards_pixel_venda ON public."SAAS_Cards_Quadros";
CREATE TRIGGER trg_cards_pixel_venda AFTER INSERT OR UPDATE OF "etapaQuadroId" ON public."SAAS_Cards_Quadros"
FOR EACH ROW EXECUTE FUNCTION public.f_cards_pixel_venda();


NOTIFY pgrst, 'reload schema';
